pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: residuals too small for the minimum
    // plausible future item (<= 10) are unusable waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Residuals that cannot fit the lookahead item are semi-dead.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward leaving room for the lookahead item.
        score -= 15.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage opening new bins when few are open,
    // encourage spreading when many bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when few bins are open,
        // relax penalty as the stream matures and bins proliferate.
        score += 55.0 - 30.0 * progress - 2.0 * open_bins_count as f64;
    } else {
        // Mild preference for tighter (less residual) existing bins.
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
    }

    // Prefer bins whose residual deviates below the mean (tighter packing).
    score -= (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
