    if post_residual == 0 && bin_residual != bin_capacity {
        let crowd = ((open_bins_count as f64 - 4.0).max(0.0) / 12.0).min(1.0);
        score -= 5.0 * crowd * (0.5 + 0.5 * (1.0 - progress));
    }

    // MUTATION (gen 40): near-miss refusal — open bins that strand 1..=4
    // unusable units get a graded penalty so placements leaving reusable
    // tails are preferred, cutting dead space late in the stream.
    if post_residual >= 1 && post_residual <= 4 && bin_residual != bin_capacity {
        score += 3.0 * (1.0 - post_residual as f64 / 4.0) * (0.5 + 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
