                score -= 6.0 * (progress - 0.75) * 10.0;
            }
        }
        // Small items late: keep them out of fresh bins.
        if item_size < 15 && progress > 0.5 && fitting_bins_count >= 1 {
            score += 15.0;
        }
        // Mid-band fresh leftovers (30..=55) are reusable.
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left >= 30 && fresh_left <= 55 {
                score -= 2.5 * (1.0 - ((fresh_left as f64 - 42.5).abs() / 12.5).min(1.0)) * (1.0 - 0.4 * progress);
            } else if fresh_left > 65 {
                score += 0.06 * ((fresh_left - 65) as f64).min(35.0) * (0.5 + 0.5 * progress);
            }
        }
        // Scarcity-locked chain continuity for fresh bins.
        if fitting_bins_count <= 2 && next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left >= next_item_size {
                let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0);
                score -= 5.0 * scarcity * (0.5 + 0.5 * (1.0 - progress));
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = post * post / cap;                       // quadratic in post residual
    let progress_coupling = poly * (0.5 + progress);    // dead space penalized more later in stream
    let mut score = post + progress_coupling;

    // Reward tight fits (small post_residual) with smooth exponential shaping
    score -= 30.0 * (-(post / cap) * 4.0).exp();

    // Penalize when post_residual becomes too small to ever be useful (smooth sigmoid)
    let useless = 1.0 / (1.0 + (post / 10.0).exp());
    score += 20.0 * useless;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 12.0 * (1.0 - (post - next_item_size as f64) / cap);
    } else if next_item_size > 0 {
        score += 8.0;
    }

    // Mild preference for consolidating into fewer bins
    score += open_bins_count as f64 * 0.3;

    // Deviation from mean residual: prefer bins near/below mean (balance)
    score += 0.2 * (post - mean_residual).abs();

    // New-bin candidate: make it attractive only when item fits poorly everywhere else
    if bin_residual == bin_capacity {
        score = 40.0 + item * 0.5 - 10.0 * progress;
    }

    score
}

