    let resid_f = bin_residual as f64;
    if resid_f > mean_residual + 20.0 && item_size < 30 {
        // Don't waste a large-capacity bin on a tiny item when lookahead doesn't chain.
        if next_item_size == 0 || post_residual < next_item_size {
            score += 10.0;
        }
    } else if resid_f < mean_residual - 20.0 {
        // This bin is already tight; finishing it off is valuable.
        score -= 8.0;
    }

    // --- Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless post-residual is pure dead space). ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
        if post_residual >= 10 {
            score -= 10.0;
        }
    }

    // --- New-bin candidate handling: opening a fresh bin should only win when no
    // open bin offers a decent fit (post_residual would be large/awkward). ---
    if bin_residual == bin_capacity {
        // Neutral-ish baseline: slightly worse than a good fit, better than a bad one.
        score = 55.0 - 15.0 * progress;
        // If the next item chains perfectly into a fresh bin (e.g. item + next == C),
        // opening a new bin is attractive.
        if next_item_size > 0 && item_size + next_item_size >= bin_capacity {
            score -= 45.0;
        }
        // Late in the stream, avoid proliferating bins with big leftovers.
        if progress > 0.8 {
            score += 10.0;
        }
        // If many bins already fit the item, opening new is wasteful.
        if fitting_bins_count > 2 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score += tightness * 8.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Penalize dead space that no future item can use (items >= 10 in classic case,
    // but sizes unknown; penalize residual below half of smallest plausible item)
    if post_residual > 0 && post_residual < 12 {
        score += 30.0;
    }

    // Last chance: strongly favor using this bin rather than opening a new one
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
            // exact chain fit bonus
            if post_residual == next_item_size {
                score -= 15.0;
            }
        } else {
            // post-residual too small for next item: penalize proportionally
            let waste_ratio = (next_item_size - post_residual) as f64 / next_item_size as f64;
            score += waste_ratio * 15.0;
        }
    }

    // Prefer filling bins with larger residuals when many bins are open (consolidation)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (bin_residual as f64 / bin_capacity as f64) * (10.0 + 20.0 * progress);

    // Global pressure: when open bins are numerous, discourage new bins implicitly
    // by rewarding reuse of existing bins
    score -= (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is an outlier worth filling; if far above, keep it for future items
    let dev = bin_residual as f64 - mean_residual;
    if dev < 0.0 {
        score += dev * 0.3; // negative dev -> subtract -> favor
    } else {
        score += dev * 0.15;
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well
    if bin_residual == bin_capacity {
        // base penalty so open bins with decent fits win
        score += 45.0;
        // but if this is a last-chance situation nowhere else... fitting_bins_count==1
        // refers to open bins; new bin reduces future fragmentation when item is huge
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 30.0;
        }
        // late in stream, reusing is cheaper
        score += progress * 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear penalty for mid-range waste
    let mut score = pr * (1.0 + 0.8 * norm_pr * (1.0 - norm_pr));

    // Smooth polynomial coupling with stream progress:
    // early on, waste matters less (bins will fill later); late, waste is costly
    let progress_coupling = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 60.0 * progress_coupling * norm_pr * norm_pr;

    // Interaction with mean residual: penalize bins far below mean residual
    // (leaving them for other items), reward bins already tight
    let mr = mean_residual / cap;
    score += 25.0 * (mr - norm_pr).abs() * (0.3 + 0.7 * progress_coupling);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - norm_pr);
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_gap = (pr - nxt).abs();
        let fit_norm = fit_gap / cap;
        score -= 15.0 * (1.0 - fit_norm * fit_norm) * (1.0 - progress_coupling);
        // penalize leaving residual that is too small for the next item
        if pr < nxt {
            score += 20.0 * progress_coupling;
        }
    }

    // Slight penalty for proliferating bins early
    score += 2.0 * (open_bins_count as f64) * (1.0 - progress_coupling) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worse when it falls in
    // "useless" residue classes modulo common item sizes.
    let pr = post_residual;
    if pr > 0 {
        // Penalize residuals that cannot host any plausible future item (1..=100).
        // A residual r is "harmonically useful" if it lies in a wide residue band
        // reachable by sums of typical items. Reward classes divisible by 10/20/25.
        let mut class_penalty = 0.0;
        if pr % 10 == 0 { class_penalty -= 6.0; }
        if pr % 20 == 0 { class_penalty -= 3.0; }
        if pr % 25 == 0 { class_penalty -= 3.0; }
        if pr % 5 != 0 { class_penalty += 8.0; }        // awkward residue
        if pr < 10 { class_penalty += (10 - pr) as f64 * 1.5; } // tiny dead space
        score += class_penalty;
    } else {
        score -= 15.0; // perfect fill is excellent
    }

    // Lookahead coupling: harmonic class of next_item_size vs post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // If this bin could still host the next item, reward residual
            // compatibility (post_residual - next_item_size small => tight chain).
            let slack = post_residual - next_item_size;
            score -= 4.0;
            score += (slack as f64) * 0.15;
            if (post_residual % next_item_size.max(1)) == 0 {
                score -= 5.0; // exact harmonic division: chain of fits
            }
        } else {
            // Next item won't fit here; residual becomes stranded until something
            // smaller arrives. Penalize proportionally to how close-but-short it is.
            let miss = next_item_size - post_residual;
            score += (miss as f64) * 0.6;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin has full residual.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins are crowded
        // and the current fit is poor (large post_residual or awkward class).
        let poor_fit = (post_residual as f64) > 0.35 * bin_capacity as f64;
        let crowded = mean_residual < 0.25 * bin_capacity as f64;
        if poor_fit && crowded {
            score -= 10.0;
        } else {
            score += 20.0 + 3.0 * open_bins_count as f64;
        }
    }

    // Mild pressure to consolidate as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (mean_residual - post_residual as f64).abs() * 0.1;

    // Prefer tighter bins overall: deviation from mean residual.
    score += (post_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item size are pure waste.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 50.0; // perfect fit, no dead space
    } else if post_residual < 10 {
        // Tiny unusable gap -> heavy penalty scaled by gap smallness
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual < 20 {
        // Small gap, likely unusable for typical items
        score += 12.0;
    } else if post_residual <= 50 {
        // Mid-range residual: mildly desirable if it can host future items
        score -= 6.0;
    } else {
        // Large residual: flexible, slight bonus
        score -= 4.0;
    }

    // Reward tightness: fraction of bin used by this placement
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * tightness;

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 10.0 {
                score -= 20.0 * (1.0 - slack / 10.0);
            } else {
                score -= 5.0;
            }
        } else {
            // Next item won't fit here; penalize proportionally to wasted potential
            let waste = (next_item_size - post_residual) as f64;
            score += 8.0 * (waste / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when open bins fit well
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        score += 35.0 + 2.0 * pressure;
        // If mean residual across open bins is small, opening new bin is more acceptable
        score -= (mean_residual / bin_capacity as f64).clamp(0.0, 1.0) * 25.0;
    }

    // Open-bin pressure: consolidate when many bins are open
    score += 0.15 * open_bins_count as f64 * (1.0 - tightness);

    // Late-stream consolidation: near the end, prefer filling existing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins with residual close to item need
    let dev = (bin_residual as f64 - item_size as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: this bin will be closed by next item
        } else if next_item_size <= post_residual {
            // next item fits: bonus proportional to how well it matches
            let gap = (post_residual - next_item_size) as f64;
            score -= 30.0 - gap.min(30.0);
        } else {
            // next item does NOT fit here: penalize leaving space that strands it
            let overshoot = (next_item_size - post_residual) as f64;
            score += overshoot * 0.5;
        }
    }

    // Penalize small unusable dead space (fragmentation) more than large space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny dead slot is nearly useless
    }

    // Reward closing bins tightly: perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Compare against mean residual: prefer bins with residual below mean (tighter bins),
    // unless a perfect lookahead match exists.
    if bin_residual as f64 > mean_residual {
        score += 5.0;
    } else {
        score -= 3.0;
    }

    // New-bin candidate: prefer it only when no open bin offers a good lookahead fit.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 20.0;
        // late in the stream, opening new bins is cheaper than fragmenting
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
        // if many open bins fit the item, opening a new bin is wasteful
        score += 8.0 * (fitting_bins_count as f64).min(4.0);
        // if next item is large, a fresh bin gives flexibility
        if next_item_size > 50 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream: later, be more frugal with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Penalize large dead space more aggressively as stream progresses.
    score += 0.6 * (post_residual as f64).powi(2) / bin_capacity as f64 * (0.5 + progress);

    // Lookahead: reward bins whose post-residual can still hold the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 3.0 + 2.0 * (next_item_size as f64 / 100.0);
        } else {
            // Dead space the next item cannot use.
            score += 0.4 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Scarcity of fitting bins: mild extra reward when few alternatives.
    if fitting_bins_count >= 2 {
        score += 0.5 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: only attractive when item fits poorly everywhere
    // or global residuals are high (lots of wasted space already).
    if bin_residual == bin_capacity {
        let tight_fit = item_size as f64 / bin_capacity as f64;
        let global_waste = mean_residual / bin_capacity as f64;
        // Penalize opening new bins early or when open bins have room.
        score += 6.0 + 10.0 * (1.0 - progress);
        score -= 6.0 * global_waste * progress;
        // Large items justify new bins more than small ones.
        score -= 4.0 * tight_fit;
        if fitting_bins_count <= 1 {
            score -= 7.0; // no good alternative exists
        }
    }

    // Prefer bins tighter than the average residual (good fits).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Mild preference to keep many bins usable: avoid extreme small post-residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual (tight fit), with non-linear sharpening.
    let mut score = post * (1.0 + 1.5 * (post / cap).powi(2));

    // Smooth stream-progress coupling: early on, tolerate slack; late, demand tightness.
    score += 12.0 * progress * (post / cap);

    // Penalize large dead space non-linearly (quadratic waste), softened early.
    score += 0.02 * post * post / cap * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + post / cap);
    }

    // Lookahead: reward if next item fits into the resulting post_residual.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 8.0 * (1.0 - (next_item_size as f64) / cap);
    } else if next_item_size > 0 {
        // Next item cannot use leftover space: penalize proportional waste.
        score += 4.0 * (post / cap) * (next_item_size as f64 / cap);
    }

    // Mean-residual coupling: placing into a bin far from the mean residual
    // smooths the residual distribution — mildly reward that.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * progress;

    // Mild penalty for spreading across many open bins; encourage consolidation.
    score += 0.3 * open_bins_count as f64 * (post / cap);

    // New-bin candidate: empty bin should only win when fits elsewhere are bad.
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress;
        // But if item is large, opening a fresh bin is reasonable.
        score -= 0.15 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the gap left behind: small gaps are "dead space".
    if post_residual == 0 {
        score -= 30.0; // perfect closure
    } else if post_residual <= 10 {
        score += 12.0; // tiny unusable gap
    } else if post_residual <= 25 {
        score += 5.0;
    } else if post_residual <= 50 {
        score -= 3.0;
    }

    // Modulo-class coupling: does the leftover gap harmonize with the next item?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
            // exact harmonic match: gap is a multiple-class companion of next item
            if post_residual % next_item_size == 0 {
                score -= 6.0;
            }
        } else {
            score += 4.0;
            // next item shares a residue class with the gap -> likely future fit
            let g = post_residual % 10;
            let n = next_item_size % 10;
            if g == n {
                score -= 2.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize unless current bins are nearly full or item is huge.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 * (1.0 - pressure) * (1.0 - 0.5 * progress);
        if item_size >= 80 {
            score += 10.0;
        }
    }

    // Reward tight fits relative to item size.
    score -= 8.0 * (item_size as f64 / bin_capacity as f64);

    // Mild preference for bins below mean residual (balances load).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // minimum item size (1..100 stream => treat < 10 as near-dead) are
    // heavily penalized, since they can almost never be reused.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 50.0 * (dead_threshold - post_residual) as f64;
    }
    if post_residual == 0 {
        // Perfect fit is maximally rewarded.
        score -= 100.0;
    }

    // Reward tight fits: the smaller the waste fraction, the better.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * waste_frac * waste_frac;

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < dead_threshold {
            score -= 60.0; // chain fit with near-zero leftover
        } else {
            score -= 15.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Leftover cannot serve the next item: mild penalty.
        score += 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins; opening new bins gets progressively costlier.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_penalty = 30.0 + 0.5 * open_bins_count as f64 + 20.0 * progress;
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: base cost plus penalty for leaving the
        // current bin's residual stranded.
        score += new_bin_penalty;
        if bin_residual != bin_capacity {
            score += mean_residual * 0.2;
        }
        // Slight discount early in the stream when few bins exist.
        score -= 10.0 * (1.0 - progress);
    }

    // Mean residual coupling: if this bin is far below the mean residual,
    // it is already fragmented; prefer bins closer to the mean for reuse.
    score += ((mean_residual - bin_residual as f64).abs()) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit), but softly.
    score = post_residual as f64 * 0.9;

    // Aggressive 2-step lookahead: reward when post_residual exactly (or nearly) matches next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: strong reward (subtract).
        score -= 40.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        // If next item fits exactly after this placement, huge reward.
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // If next item cannot fit in post_residual, mild penalty for leaving dead space
        // relative to what a new bin could offer.
        if post_residual < next_item_size {
            score += 10.0;
        }
    } else {
        // Last item: just minimize waste.
        score = post_residual as f64;
    }

    // Penalize creating unusable dead space (very small post_residual that likely fits nothing).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when this bin's residual is far above mean
    // (i.e., current bin is a poor fit) or no lookahead match exists.
    if bin_residual == bin_capacity {
        // Slight default penalty so open bins win on ties.
        score += 5.0;
        // If the current bin leaves a large residual vs mean, opening new bin is better.
        if post_residual as f64 > mean_residual + 20.0 {
            score -= 15.0;
