        // If next item is large and post_residual too small anyway, new bin is attractive.
        if next_item_size > 0 && post_residual < next_item_size && next_item_size >= 50 {
            score -= 20.0;
        }
    }

    // Late in the stream, consolidate more aggressively (avoid leaving many open bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space non-linearly (small residuals are hard to reuse).
    let dead = post_residual as f64;
    score += 0.35 * (dead / 10.0).powi(2) * (dead > 0.0) as u8 as f64;

    // Reward tight fits (small post_residual) with a bonus.
    score -= 12.0 * ((bin_capacity as f64 - dead) / bin_capacity as f64).powi(3);

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize proportionally to wasted potential.
        score += 4.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Time horizon: early in the stream, keep bins open and flexible;
    // later, prioritize closing bins tightly.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - t) * 0.10 * dead;      // early: tolerate larger residuals
    score += t * 0.15 * dead;              // late: punish residual waste harder

    // Global state: many open bins -> discourage spreading, prefer filling.
    score += 0.05 * open_bins_count as f64 * (dead / bin_capacity as f64);

    // If this bin is far below the mean residual, it's a good filler target.
    score -= 0.08 * (mean_residual - bin_residual as f64).abs().signum()
        * (mean_residual - bin_residual as f64).abs();

    // New-bin candidate: penalize slightly unless current bin leaves terrible residue.
    if bin_residual == bin_capacity {
        score += 6.0;
        if post_residual > 40 {
            score -= 10.0; // big item, fine to open fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Non-linear coupling of post-residual with stream progress:
    // early on, waste matters less; late, strongly penalize large residuals.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score += progress_weight * 30.0 * norm_pr * norm_pr;

    // Reward tight fits: quadratic bonus when post_residual is small.
    score -= 40.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - progress);

    // Penalize dead space that no plausible future item (1..100) can use well:
    // residual far from typical item sizes is bad; smooth penalty via distance to mid-range.
    let dead = (norm_pr - 0.5).abs();
    score += 20.0 * dead * dead * (0.3 + progress);

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 25.0 * (1.0 - gap / cap) * (1.0 - gap / cap);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Mild pressure toward consolidation: bins with residuals below mean are attractive.
    score -= 8.0 * (mean_residual - pr) / cap;

    // Slight preference against opening new bins early, more tolerance later.
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) + 5.0 * norm_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class: partition residual space by capacity fractions (1/4 classes)
    let quarter = bin_capacity / 4; // 25
    let half = bin_capacity / 2;    // 50
    let class = |r: u32| -> u32 { r / quarter };
    let post_class = class(post_residual);

    // Reward landing in a low class (smaller residual) non-linearly
    score -= (4 - post_class) as f64 * (4 - post_class) as f64 * 6.0;

    // Dead-space penalty: residual too small for the minimum plausible item (1..100 range)
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Modulo arithmetic on post_residual: values near multiples of 25 are reusable
    let m = post_residual % quarter;
    score += (quarter as f64 - m as f64).abs() * 0.4;

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 500.0;
        } else {
            score -= 60.0 - slack as f64 * 0.5;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item can't use this bin's remainder: penalize proportionally
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's early or current bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = mean_residual / bin_capacity as f64;
        score += 120.0 * (1.0 - progress) + 200.0 * (1.0 - crowding);
        if post_class == 0 {
            score -= 50.0; // fresh bin keeps full harmonic flexibility
        }
    }

    // Mild preference for bins with residual close to item (tight fit) via integer division threshold
    if bin_residual / (item_size.max(1)) <= 1 {
        score -= 40.0;
    }

    // Small regularization toward mean residual alignment
    score += (post_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
