    }

    // NEW: two-item lookahead — if post_residual fits neither next item nor a
    // plausible follow-up (half of next), treat leftover as likely waste.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let half_next = next_item_size / 2;
        if post_residual < half_next {
