    // NEW: prefer bins whose residual is just above the item (near-exact capacity match)
    let slack = bin_residual as i64 - item_size as i64;
    if slack >= 0 && slack <= 4 {
        score -= 18.0;
    }

    // NEW: when many bins are open, amplify consolidation pressure on large-residual bins
    if open_bins_count > 8 {
        score += (bin_residual as f64 / bin_capacity as f64) * 6.0;
