        let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0);
        let adapt = 0.12 + 0.10 * scarcity.min(1.0);
        score += adapt * (post_residual as f64) * (0.6 + 0.8 * tightness);
    }

    // MUTATION (gen 8): chain-closure bonus — deepened with a sharp cutoff at
    // post_residual <= 12 so near-closures win decisively over moderate ones,
    // directly attacking the residual dead-space weakness.
    if post_residual > 0 && post_residual <= 24 && bin_residual != bin_capacity {
