        let sharp = if post_residual <= 12 { 1.6 } else { 1.0 };
        score -= 5.0 * nearness * sharp * (1.0 - 0.4 * progress);
    }

    // MUTATION (gen 8): open-bin load balancing guard
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && open_bins_count > 10 {
