        // bin when the two-item leftover lands in the reusable 25..=60 band
        // or closes perfectly; otherwise the fresh bin is a fragmentation risk.
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left > 0 && fresh_left < 25 && fresh_left < next_item_size {
                score += 10.0;
            }
        }
    }

    score
}

