    }

    // Exact-fill lookahead with early-stream bonus
    if next_item_size > 0 && post_residual == next_item_size && progress < 0.4 {
        score -= 6.0;
    }

    // Two-item lookahead chain — reward residuals that can absorb BOTH the
    // current and next item with a reusable remainder
    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let chain_left = bin_residual - item_size - next_item_size;
        if chain_left >= 15 && chain_left <= 55 {
            score -= 7.0 + 5.0 * (1.0 - progress);
        }
    }

    // Waste-shape gradient — graded penalty on post-fit dead space
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap > 8 && gap <= 20 {
            score += 1.5;
        } else if gap > 20 && gap <= 35 {
            score += 3.5;
        }
    }

    // Scarcity-weighted last-fit — tight fits under scarcity are decisive
    if fitting_bins_count <= 2 && bin_residual != bin_capacity && post_residual <= 12 {
        score -= 6.0 + 4.0 * (1.0 - progress);
    }

    // Consolidation gradient — many open bins: prefer tightest residual bins
    if open_bins_count > 12 && bin_residual != bin_capacity {
        score += 8.0 * (1.0 - resid_f / cap_f);
    }

    // Dead-space slope pressure — penalize unusable post-fit waste, scaled by
    // stream position so early bins absorb the risk
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unus = 1.0 - (post_residual as f64 / next_item_size as f64);
        score += 4.5 * unus * (1.0 - 0.3 * progress);
    }

    // Residual entropy guard — awkward 61..=99 band is hard to reuse
    if post_residual > 60 && post_residual < 100 {
        score += 2.5 + 2.0 * (1.0 - progress);
    }

    // Scarcity-weighted exact chain — few fitting bins AND exact next-item
    // match: lock in the pairing decisively
    if fitting_bins_count <= 2 && next_item_size > 0 && post_residual == next_item_size {
        score -= 8.0;
    }

    // Continuous tightness gradient — smooth penalty on every unit of dead
    // space, weighted by how tight the global bin population is
    if post_residual > 0 && bin_residual != bin_capacity {
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        score += 0.12 * (post_residual as f64) * (0.6 + 0.8 * tightness);
    }

    // Chain-closure bonus — when the current item nearly empties a bin
    // (post_residual small but nonzero), deepen the reward so bins get closed
    if post_residual > 0 && post_residual <= 20 && bin_residual != bin_capacity {
        score -= 5.0 * (1.0 - post_residual as f64 / 20.0) * (1.0 - 0.4 * progress);
    }

    // Open-bin load balancing guard — when many bins are open and this
    // placement strands space that no next item can use, add a mild
    // consolidation penalty scaled by open-bin count
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && open_bins_count > 10 {
        score += 1.5 * ((open_bins_count - 10) as f64).min(8.0) * 0.5;
    }

    // MUTATION (gen 8): dead-space divisibility probe — when the stranded
    // post-fit residual is an exact multiple of the next item size, the gap
    // will eventually be filled by one or more copies of that item, so the
    // "waste" is actually recoverable. Reward such residuals instead of
    // penalizing them, reducing false dead-space pressure.
    if post_residual > 0 && next_item_size > 1 && post_residual % next_item_size == 0 && post_residual >= next_item_size {
        let copies = post_residual / next_item_size;
        if copies <= 3 {
            score -= 4.0 + 2.0 * copies as f64;
        }
    }

    // MUTATION (gen 8): near-multiple recovery — when the stranded residual is
    // just above a multiple of the next item, the overflow sliver is tiny and
    // likely reusable later; soften the waste penalty proportionally.
    if post_residual > 0 && next_item_size > 1 {
        let m = post_residual / next_item_size;
        if m >= 1 {
            let over = post_residual - m * next_item_size;
            if over >= 1 && over <= 4 {
                score -= 3.0;
            }
        }
    }

    // MUTATION (gen 8): compaction gradient refinement — sharpen the
    // continuous dead-space slope for large residuals (>40) which historically
    // linger as fragmentation sources, while easing it for small residuals so
    // tight fits are not over-penalized.
    if post_residual > 0 && bin_residual != bin_capacity {
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        let slope = if post_residual > 40 { 0.06 } else { 0.03 };
        score += slope * (post_residual as f64) * (0.6 + 0.8 * tightness);
    }

    // MUTATION (gen 8): closure-anticipation — when the residual after this
    // fit is small (<= 20) AND the next item could not have used the bin
    // anyway, the bin is effectively sealed; reward the sealing so the
    // active-bin population shrinks faster.
    if post_residual > 0 && post_residual <= 20 && next_item_size > post_residual && bin_residual != bin_capacity {
        score -= 3.5 * (1.0 - 0.5 * progress);
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score = 55.0 - 15.0 * progress;
        if next_item_size > 0 && item_size + next_item_size >= bin_capacity {
            score -= 45.0;
        }
        if item_size as f64 > 0.6 * cap_f {
            score -= 30.0;
        }
        if progress > 0.8 {
            score += 10.0;
        }
        if fitting_bins_count > 2 {
            score += 20.0;
        }
        // When only one open bin barely fits, opening fresh is attractive
        if fitting_bins_count == 1 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover >= next_item_size {
                score -= 12.0;
            }
        }
        if next_item_size > 0 && item_size + next_item_size < bin_capacity {
            let leftover = bin_capacity - item_size - next_item_size;
            if leftover < 10 {
                score -= 8.0;
            } else if leftover < 25 {
                score -= 3.0;
            }
            // Leftover quality band
            if leftover >= 25 && leftover <= 60 {
                score -= 6.0;
            } else if leftover >= 1 && leftover <= 5 {
                score += 6.0;
            }
        }
        if open_bins_count < 4 && progress < 0.3 {
            score -= 12.0;
        }
        // Opening a fresh bin that leaves a large reusable residual is cheap
        if next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover >= next_item_size {
                score -= 10.0;
            }
        }
        // Avoid opening fresh bins for tiny items late in the stream
        if item_size < 15 && progress > 0.5 && fitting_bins_count >= 1 {
            score += 15.0;
        }
        // Penalize opening a fresh bin when an open bin absorbs with small waste
        if fitting_bins_count >= 1 && item_size <= bin_residual {
            let best_case_waste = bin_residual - item_size;
            if best_case_waste <= 5 {
                score += 25.0;
            } else if best_case_waste <= 15 {
                score += 8.0;
            }
        }
        // Late-stream discipline (steepened)
        if progress > 0.6 {
            score += 7.5 * (progress - 0.6) * 25.0;
        }
        // Mid-stream bin-count guard — suppress new bins when consolidation
        // headroom still exists
        if open_bins_count > 10 && progress > 0.35 && progress < 0.7 {
            let roomy = (mean_residual / cap_f).min(1.0);
            score += 6.0 * roomy;
        }
        // Big-item fresh-bin preference
        if item_size > 60 && next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 8.0;
        }
        // Fresh-bin chain quality — prefer opening a new bin when the two-item
        // leftover leaves a reusable band
        if next_item_size > 0 && item_size + next_item_size < bin_capacity {
            let leftover = bin_capacity - item_size - next_item_size;
            if leftover >= next_item_size {
                score -= 6.0;
            }
        }
        // Fresh-bin triple-chain check — only open a new bin if the leftover
        // after two items can still host a third meaningful chunk
        if next_item_size > 0 && fitting_bins_count >= 2 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover > 0 && leftover < 12 {
                score += 9.0;
            }
        }
        // Fresh-bin waste-floor coupling — when an open bin would leave
        // moderate (not tiny) waste, make fresh bins slightly more attractive
        // only if the fresh leftover is chainable; otherwise push toward
        // reusing open bins to keep the open-bin count low
        if fitting_bins_count >= 1 && item_size <= bin_residual {
            let open_waste = bin_residual - item_size;
            if open_waste > 15 && open_waste <= 35 {
                let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
                if next_item_size > 0 && fresh_left >= next_item_size {
                    score -= 4.0;
                } else {
                    score += 5.0;
                }
            }
        }
        // MUTATION (gen 8): fresh-bin exact-pair lock — when the fresh bin
        // would be consumed to exactly zero by item + next item (perfect
        // two-item bin), make opening it decisively cheap so perfect pairs
        // are never fragmented across open bins.
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 18.0;
        }
        // MUTATION (gen 8): fresh-bin divisibility chain — when the fresh
        // leftover is an exact multiple of the next item size, the bin can be
        // fully consumed by repeated next-item copies; reward this strongly.
        if next_item_size > 1 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover > 0 && leftover % next_item_size == 0 && leftover / next_item_size <= 3 {
                score -= 7.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap_f = bin_capacity as f64;
    let resid_f = bin_residual as f64;

    // Perfect fill reward
    if post_residual == 0 {
        score -= 65.0;
    }

    // Near-exact capacity match: residual just above item size
    let slack = bin_residual as i64 - item_size as i64;
    if slack >= 0 && slack <= 4 {
        score -= 20.0;
    }

    // --- 2-step lookahead core ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0 + 22.0 * (1.0 - progress);
        } else if post_residual > next_item_size {
            let slack_after_next = post_residual - next_item_size;
            score -= 25.0 - (slack_after_next as f64).min(40.0) * 0.3;
            if slack_after_next > 40 {
                score += (slack_after_next as f64 - 40.0) * 0.2;
            }
        } else {
            let shortfall = (next_item_size - post_residual) as f64;
            score += shortfall * 0.85;
            let half_next = next_item_size / 2;
            if post_residual > 0 && post_residual < half_next {
                score += 14.0;
            }
        }
    } else {
        score -= 10.0;
    }

    // Dead-space penalty: graded, fragmentation-aware waste pressure
    if post_residual > 0 {
        let waste_ratio = post_residual as f64 / cap_f;
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        let severity = 1.4 - 0.8 * tightness;
        if post_residual < next_item_size && next_item_size > 0 {
            let unusability = 1.0 - (post_residual as f64 / next_item_size as f64);
            score += 16.0 * unusability * (1.0 - 0.5 * progress) * severity;
            if post_residual < 10 {
                score += 9.0 * severity * (1.0 - 0.4 * progress);
            }
        } else if waste_ratio < 0.05 {
            score += 7.0 * (1.0 - progress) * severity;
        } else if waste_ratio < 0.10 && post_residual < 40 {
            score += 3.0 * (1.0 - progress) * severity;
        }
    }

    // Mean-residual coupling: fill tight bins, save roomy bins for big items
    if resid_f > mean_residual + 20.0 && item_size < 30 {
        if next_item_size == 0 || post_residual < next_item_size {
            score += 10.0;
        }
    } else if resid_f < mean_residual - 20.0 {
        score -= 8.0;
    }

    // Last-chance bonus: only bin that fits -> use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
        if post_residual >= 10 {
            score -= 10.0;
        }
    }

    // Consolidation pressure: prefer bins with larger residual when many bins open
    if open_bins_count > 8 {
        score += (resid_f / cap_f) * 6.0;
    }
    score -= (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Fragmentation-aware tiebreak: reward residuals likely reusable
    if post_residual >= 25 {
        score -= 4.0;
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 15 {
            score -= 6.0;
        }
    }

    // Triple-fit chain: scaled by remainder quality
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 20 {
            let sweet = if after_next <= 60 { 3.0 } else { 0.0 };
            score -= 5.0 + 5.0 * (1.0 - progress) + sweet;
        }
    }

    // Waste-ratio gradient: continuous pressure proportional to dead-space fraction
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 6.0 * (post_residual as f64 / cap_f) * 10.0;
    }

    // Dead-space anticipation weighted by scarcity
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let strandedness = 1.0 - (post_residual as f64 / next_item_size as f64);
        let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0);
        score += 9.0 * strandedness * scarcity;
    }

    // Residual-quality gradient — reusable band 20..=60
    if post_residual >= 20 && post_residual <= 60 {
        score -= 3.0 + 4.0 * (1.0 - progress);
    }

    // Avoid exact-dead residuals 1..=5
    if post_residual >= 1 && post_residual <= 5 {
        score += 5.0;
    }

    // Harmonic-anticipation — reward residuals that pair with the next item
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap > 0 && gap <= 8 {
            score -= 4.0 + 3.0 * (1.0 - progress);
        }
    }

    // Item-residual coupling — prefer bins whose residual is a tight multiple
    if item_size > 0 && bin_residual % item_size == 0 && bin_residual != bin_capacity {
        score -= 5.0;
        if post_residual == 0 {
            score -= 4.0;
        }
    }

    // Exact-fill lookahead with early-stream bonus
    if next_item_size > 0 && post_residual == next_item_size && progress < 0.4 {
        score -= 6.0;
    }

    // Two-item lookahead chain — absorb BOTH current and next item with reusable remainder
    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let chain_left = bin_residual - item_size - next_item_size;
        if chain_left >= 15 && chain_left <= 55 {
            score -= 7.0 + 5.0 * (1.0 - progress);
        }
    }

    // Waste-shape gradient — graded penalty on post-fit dead space
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap > 8 && gap <= 20 {
            score += 1.5;
        } else if gap > 20 && gap <= 35 {
            score += 3.5;
        }
    }

    // Scarcity-weighted last-fit — tight fits under scarcity are decisive
    if fitting_bins_count <= 2 && bin_residual != bin_capacity && post_residual <= 12 {
        score -= 6.0 + 4.0 * (1.0 - progress);
    }

    // Consolidation gradient — many open bins: prefer tightest residual bins
    if open_bins_count > 12 && bin_residual != bin_capacity {
        score += 8.0 * (1.0 - resid_f / cap_f);
    }

    // Dead-space slope pressure
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unus = 1.0 - (post_residual as f64 / next_item_size as f64);
        score += 4.5 * unus * (1.0 - 0.3 * progress);
    }

    // Residual entropy guard — awkward 61..=99 band is hard to reuse
    if post_residual > 60 && post_residual < 100 {
        score += 2.5 + 2.0 * (1.0 - progress);
    }

    // Scarcity-weighted exact chain
    if fitting_bins_count <= 2 && next_item_size > 0 && post_residual == next_item_size {
        score -= 8.0;
    }

    // MUTATION (gen 7): continuous tightness gradient — smooth penalty on
    // every unit of dead space, weighted by global bin tightness.
    if post_residual > 0 && bin_residual != bin_capacity {
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        score += 0.12 * (post_residual as f64) * (0.6 + 0.8 * tightness);
    }

    // MUTATION (gen 7): chain-closure bonus — deepen reward for near-emptying bins
    if post_residual > 0 && post_residual <= 20 && bin_residual != bin_capacity {
        score -= 5.0 * (1.0 - post_residual as f64 / 20.0) * (1.0 - 0.4 * progress);
    }

    // MUTATION (gen 7): open-bin load balancing guard
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && open_bins_count > 10 {
        score += 1.5 * ((open_bins_count - 10) as f64).min(8.0) * 0.5;
    }

    // MUTATION (gen 8): waste-floor refinement — replace the flat 0.12/unit
    // gradient with a convex (quadratic) waste cost so moderate gaps are
    // penalized super-linearly, sharpening residual compaction exactly where
    // the parent's dead-space weakness lies.
    if post_residual > 0 && bin_residual != bin_capacity {
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        let pr = post_residual as f64;
        score += (0.09 * pr + 0.0022 * pr * pr) * (0.6 + 0.8 * tightness);
    }

    // MUTATION (gen 8): post-fit chainability bonus — when the leftover after
    // this placement can still host the next item, reward proportionally to
    // how much slack remains after that hosting (keeps chains alive).
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let after_next = post_residual - next_item_size;
        if after_next >= 10 && after_next <= 45 {
            score -= 4.0 * (1.0 - after_next as f64 / 45.0) * (1.0 - 0.5 * progress);
        }
    }

    // MUTATION (gen 8): residual-mismatch guard — when post-fit residual is
    // just barely below the next item (near-miss), penalize extra since that
    // space is almost certainly stranded.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 6.0 {
            score += 10.0 * (1.0 - miss / 6.0) * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score = 55.0 - 15.0 * progress;
        if next_item_size > 0 && item_size + next_item_size >= bin_capacity {
            score -= 45.0;
        }
        if item_size as f64 > 0.6 * cap_f {
            score -= 30.0;
        }
        if progress > 0.8 {
            score += 10.0;
        }
        if fitting_bins_count > 2 {
            score += 20.0;
        }
        // When only one open bin barely fits, opening fresh is attractive
        if fitting_bins_count == 1 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover >= next_item_size {
                score -= 12.0;
            }
        }
        if next_item_size > 0 && item_size + next_item_size < bin_capacity {
            let leftover = bin_capacity - item_size - next_item_size;
            if leftover < 10 {
                score -= 8.0;
            } else if leftover < 25 {
                score -= 3.0;
            }
            // Leftover quality band
            if leftover >= 25 && leftover <= 60 {
                score -= 6.0;
            } else if leftover >= 1 && leftover <= 5 {
                score += 6.0;
            }
        }
        if open_bins_count < 4 && progress < 0.3 {
            score -= 12.0;
        }
        // Opening a fresh bin that leaves a large reusable residual is cheap
        if next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover >= next_item_size {
                score -= 10.0;
            }
        }
        // Avoid opening fresh bins for tiny items late in the stream
        if item_size < 15 && progress > 0.5 && fitting_bins_count >= 1 {
            score += 15.0;
        }
        // Penalize opening a fresh bin when an open bin absorbs with small waste
        if fitting_bins_count >= 1 && item_size <= bin_residual {
            let best_case_waste = bin_residual - item_size;
            if best_case_waste <= 5 {
                score += 25.0;
            } else if best_case_waste <= 15 {
                score += 8.0;
            }
        }
        // Late-stream discipline (steepened)
        if progress > 0.6 {
            score += 7.5 * (progress - 0.6) * 25.0;
        }
        // Mid-stream bin-count guard
        if open_bins_count > 10 && progress > 0.35 && progress < 0.7 {
            let roomy = (mean_residual / cap_f).min(1.0);
            score += 6.0 * roomy;
        }
        // Big-item fresh-bin preference
        if item_size > 60 && next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 8.0;
        }
        // Fresh-bin chain quality
        if next_item_size > 0 && item_size + next_item_size < bin_capacity {
            let leftover = bin_capacity - item_size - next_item_size;
            if leftover >= next_item_size {
                score -= 6.0;
            }
        }
        // Fresh-bin triple-chain check
        if next_item_size > 0 && fitting_bins_count >= 2 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover > 0 && leftover < 12 {
                score += 9.0;
            }
        }
        // Fresh-bin waste-floor coupling
        if fitting_bins_count >= 1 && item_size <= bin_residual {
            let open_waste = bin_residual - item_size;
            if open_waste > 15 && open_waste <= 35 {
                let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
                if next_item_size > 0 && fresh_left >= next_item_size {
                    score -= 4.0;
                } else {
                    score += 5.0;
                }
            }
        }
        // MUTATION (gen 8): fresh-bin convex-waste coupling — mirror the new
        // quadratic open-bin waste cost on the fresh-bin side so the choice
        // between reusing vs opening stays consistent under the sharpened
        // compaction pressure.
        if fitting_bins_count >= 1 && item_size <= bin_residual {
            let open_waste = bin_residual - item_size;
            if open_waste > 35 {
                score -= 3.0 + 0.05 * ((open_waste - 35) as f64).min(30.0);
            }
        }
        // MUTATION (gen 8): fresh-bin near-miss guard — if the fresh leftover
        // after placing this item sits just below the next item size, opening
        // a new bin strands nearly a full item's worth of space; discourage.
        if next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size);
            if leftover < next_item_size {
                let miss = (next_item_size - leftover) as f64;
                if miss <= 8.0 {
                    score += 12.0 * (1.0 - miss / 8.0);
                }
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
