    // now incur an accelerating cubic penalty, pushing the heuristic to prefer
    // placements that either nearly empty a bin or leave a compact remainder.
    if post_residual > 25 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        score += 0.00035 * pr * pr * pr * (1.0 - 0.3 * progress);
    }

    // MUTATION (gen 9): bin-differential tightness — compare this bin's
    // post-fit residual against the fleet mean; bins that end tighter than
