            score += 7.5 * (progress - 0.6) * 25.0;
        }
        // Mid-stream bin-count guard
        if open_bins_count > 10 && progress > 0.35 && progress < 0.7 {
            let roomy = (mean_residual / cap_f).min(1.0);
            score += 6.0 * roomy;
        }
        // Big-item fresh-bin preference
        if item_size > 60 && next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 8.0;
        }
        // Fresh-bin chain quality
        if next_item_size > 0 && item_size + next_item_size < bin_capacity {
            let leftover = bin_capacity - item_size - next_item_size;
            if leftover >= next_item_size {
                score -= 6.0;
            }
        }
        // Fresh-bin triple-chain check
        if next_item_size > 0 && fitting_bins_count >= 2 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover > 0 && leftover < 12 {
                score += 9.0;
            }
        }
        // Fresh-bin waste-floor coupling
        if fitting_bins_count >= 1 && item_size <= bin_residual {
            let open_waste = bin_residual - item_size;
            if open_waste > 15 && open_waste <= 35 {
                let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
                if next_item_size > 0 && fresh_left >= next_item_size {
                    score -= 4.0;
                } else {
                    score += 5.0;
                }
            }
        }
        // Fresh-bin convex-waste coupling — mirror the quadratic open-bin waste
        // cost on the fresh-bin side for consistent reuse-vs-open choices.
        if fitting_bins_count >= 1 && item_size <= bin_residual {
            let open_waste = bin_residual - item_size;
            if open_waste > 35 {
                score -= 3.0 + 0.05 * ((open_waste - 35) as f64).min(30.0);
            }
        }
        // Fresh-bin near-miss guard — opening a new bin that strands nearly a
        // full item's worth of space is discouraged.
        if next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size);
            if leftover < next_item_size {
                let miss = (next_item_size - leftover) as f64;
                if miss <= 8.0 {
                    score += 12.0 * (1.0 - miss / 8.0);
                }
            }
        }
        // MUTATION (gen 9): fresh-bin mean-residual alignment — when the fleet's
        // mean residual is already high (bins are fragmented), opening yet
        // another bin compounds fragmentation; penalize proportionally.
        if open_bins_count > 6 {
            let roomy = (mean_residual / cap_f).min(1.0);
            score += 4.0 * roomy * ((open_bins_count - 6) as f64).min(10.0) * 0.3;
        }
        // MUTATION (gen 9): fresh-bin compaction check — prefer opening a new
        // bin only when the fresh leftover is either tiny (<10, near-closed)
        // or comfortably reusable (>= next item); mid-range leftovers are
        // exactly the dead space that accumulates into wasted bins.
        if next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover >= 10 && leftover < next_item_size {
                score += 7.0 * (1.0 - leftover as f64 / next_item_size as f64);
            }
        }
    }

    score
}

