    // Scarcity-weighted exact chain
    if fitting_bins_count <= 2 && next_item_size > 0 && post_residual == next_item_size {
        score -= 8.0;
    }

    // MUTATION (gen 7): continuous tightness gradient — smooth penalty on
    // every unit of dead space, weighted by global bin tightness.
    if post_residual > 0 && bin_residual != bin_capacity {
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        score += 0.12 * (post_residual as f64) * (0.6 + 0.8 * tightness);
    }

    // MUTATION (gen 7): chain-closure bonus — deepen reward for near-emptying bins
    if post_residual > 0 && post_residual <= 20 && bin_residual != bin_capacity {
        score -= 5.0 * (1.0 - post_residual as f64 / 20.0) * (1.0 - 0.4 * progress);
    }

    // MUTATION (gen 7): open-bin load balancing guard
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && open_bins_count > 10 {
        score += 1.5 * ((open_bins_count - 10) as f64).min(8.0) * 0.5;
    }

    // MUTATION (gen 8): waste-floor refinement — convex (quadratic) waste cost
    if post_residual > 0 && bin_residual != bin_capacity {
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        let pr = post_residual as f64;
        score += (0.09 * pr + 0.0022 * pr * pr) * (0.6 + 0.8 * tightness);
    }

    // MUTATION (gen 8): post-fit chainability bonus
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let after_next = post_residual - next_item_size;
        if after_next >= 10 && after_next <= 45 {
            score -= 4.0 * (1.0 - after_next as f64 / 45.0) * (1.0 - 0.5 * progress);
        }
    }

    // MUTATION (gen 8): residual-mismatch guard — near-miss stranding penalty
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 6.0 {
            score += 10.0 * (1.0 - miss / 6.0) * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // MUTATION (gen 9): three-item lookahead — reward bins whose residual can
    // absorb the current item plus the next two items exactly or with minimal
    // waste; deep chains are the strongest compaction signal.
    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let after_two = bin_residual - item_size - next_item_size;
        if after_two > 0 && after_two <= 12 {
            score -= 6.0 * (1.0 - progress);
        }
    }

    // MUTATION (gen 9): waste-quadratic sharpening — steeper convex cost for
    // large dead-space gaps (>25 units) which the parent still tolerates.
    if post_residual > 25 && bin_residual != bin_capacity {
        let excess = (post_residual - 25) as f64;
        score += 0.06 * excess * (0.5 + 0.7 * progress);
    }

    // MUTATION (gen 9): exact-closure gradient — graded reward for leaving
    // post-fit residual in the 1..=8 range scaled by how close to zero it is,
    // refining the flat chain-closure bonus into a smooth gradient.
    if post_residual > 0 && post_residual <= 8 && bin_residual != bin_capacity {
        score -= 4.0 * (1.0 - post_residual as f64 / 8.0);
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score = 55.0 - 15.0 * progress;
        if next_item_size > 0 && item_size + next_item_size >= bin_capacity {
            score -= 45.0;
        }
        if item_size as f64 > 0.6 * cap_f {
            score -= 30.0;
        }
        if progress > 0.8 {
            score += 10.0;
        }
        if fitting_bins_count > 2 {
            score += 20.0;
        }
        // When only one open bin barely fits, opening fresh is attractive
        if fitting_bins_count == 1 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover >= next_item_size {
                score -= 12.0;
            }
        }
        if next_item_size > 0 && item_size + next_item_size < bin_capacity {
            let leftover = bin_capacity - item_size - next_item_size;
            if leftover < 10 {
                score -= 8.0;
            } else if leftover < 25 {
                score -= 3.0;
            }
            // Leftover quality band
            if leftover >= 25 && leftover <= 60 {
                score -= 6.0;
            } else if leftover >= 1 && leftover <= 5 {
                score += 6.0;
            }
        }
        if open_bins_count < 4 && progress < 0.3 {
            score -= 12.0;
        }
        // Opening a fresh bin that leaves a large reusable residual is cheap
        if next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover >= next_item_size {
                score -= 10.0;
            }
        }
        // Avoid opening fresh bins for tiny items late in the stream
        if item_size < 15 && progress > 0.5 && fitting_bins_count >= 1 {
            score += 15.0;
        }
        // Penalize opening a fresh bin when an open bin absorbs with small waste
        if fitting_bins_count >= 1 && item_size <= bin_residual {
            let best_case_waste = bin_residual - item_size;
            if best_case_waste <= 5 {
                score += 25.0;
            } else if best_case_waste <= 15 {
                score += 8.0;
            }
        }
        // Late-stream discipline (steepened)
        if progress > 0.6 {
            score += 7.5 * (progress - 0.6) * 25.0;
        }
        // Mid-stream bin-count guard
        if open_bins_count > 10 && progress > 0.35 && progress < 0.7 {
            let roomy = (mean_residual / cap_f).min(1.0);
            score += 6.0 * roomy;
        }
        // Big-item fresh-bin preference
        if item_size > 60 && next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 8.0;
        }
        // Fresh-bin chain quality
        if next_item_size > 0 && item_size + next_item_size < bin_capacity {
            let leftover = bin_capacity - item_size - next_item_size;
            if leftover >= next_item_size {
                score -= 6.0;
            }
        }
        // Fresh-bin triple-chain check
        if next_item_size > 0 && fitting_bins_count >= 2 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover > 0 && leftover < 12 {
                score += 9.0;
            }
        }
        // Fresh-bin waste-floor coupling
        if fitting_bins_count >= 1 && item_size <= bin_residual {
            let open_waste = bin_residual - item_size;
            if open_waste > 15 && open_waste <= 35 {
                let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
                if next_item_size > 0 && fresh_left >= next_item_size {
                    score -= 4.0;
                } else {
                    score += 5.0;
                }
            }
        }
        // MUTATION (gen 8): fresh-bin convex-waste coupling
        if fitting_bins_count >= 1 && item_size <= bin_residual {
            let open_waste = bin_residual - item_size;
            if open_waste > 35 {
                score -= 3.0 + 0.05 * ((open_waste - 35) as f64).min(30.0);
            }
        }
        // MUTATION (gen 8): fresh-bin near-miss guard
        if next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size);
            if leftover < next_item_size {
                let miss = (next_item_size - leftover) as f64;
                if miss <= 8.0 {
                    score += 12.0 * (1.0 - miss / 8.0);
                }
            }
        }
        // MUTATION (gen 9): fresh-bin waste-quadratic mirror — penalize fresh
        // openings whose implied leftover exceeds 25 units, keeping the
        // reuse-vs-open tradeoff consistent with the sharpened open-bin cost.
        if next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover > 25 {
                score += 0.05 * ((leftover - 25) as f64).min(40.0);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap_f = bin_capacity as f64;
    let resid_f = bin_residual as f64;

    // Perfect fill reward
    if post_residual == 0 {
        score -= 65.0;
    }

    // Near-exact capacity match: residual just above item size
    let slack = bin_residual as i64 - item_size as i64;
    if slack >= 0 && slack <= 4 {
        score -= 20.0;
    }

    // --- 2-step lookahead core ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0 + 22.0 * (1.0 - progress);
        } else if post_residual > next_item_size {
            let slack_after_next = post_residual - next_item_size;
            score -= 25.0 - (slack_after_next as f64).min(40.0) * 0.3;
            if slack_after_next > 40 {
                score += (slack_after_next as f64 - 40.0) * 0.2;
            }
        } else {
            let shortfall = (next_item_size - post_residual) as f64;
            score += shortfall * 0.85;
            let half_next = next_item_size / 2;
            if post_residual > 0 && post_residual < half_next {
                score += 14.0;
            }
        }
    } else {
        score -= 10.0;
    }

    // Dead-space penalty: graded, fragmentation-aware waste pressure
    if post_residual > 0 {
        let waste_ratio = post_residual as f64 / cap_f;
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        let severity = 1.4 - 0.8 * tightness;
        if post_residual < next_item_size && next_item_size > 0 {
            let unusability = 1.0 - (post_residual as f64 / next_item_size as f64);
            score += 16.0 * unusability * (1.0 - 0.5 * progress) * severity;
            if post_residual < 10 {
                score += 9.0 * severity * (1.0 - 0.4 * progress);
            }
        } else if waste_ratio < 0.05 {
            score += 7.0 * (1.0 - progress) * severity;
        } else if waste_ratio < 0.10 && post_residual < 40 {
            score += 3.0 * (1.0 - progress) * severity;
        }
    }

    // Mean-residual coupling: fill tight bins, save roomy bins for big items
    if resid_f > mean_residual + 20.0 && item_size < 30 {
        if next_item_size == 0 || post_residual < next_item_size {
            score += 10.0;
        }
    } else if resid_f < mean_residual - 20.0 {
        score -= 8.0;
    }

    // Last-chance bonus: only bin that fits -> use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
        if post_residual >= 10 {
            score -= 10.0;
        }
    }

    // Consolidation pressure: prefer bins with larger residual when many bins open
    if open_bins_count > 8 {
        score += (resid_f / cap_f) * 6.0;
    }
    score -= (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Fragmentation-aware tiebreak: reward residuals likely reusable
    if post_residual >= 25 {
        score -= 4.0;
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 15 {
            score -= 6.0;
        }
    }

    // Triple-fit chain: scaled by remainder quality
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 20 {
            let sweet = if after_next <= 60 { 3.0 } else { 0.0 };
            score -= 5.0 + 5.0 * (1.0 - progress) + sweet;
        }
    }

    // Waste-ratio gradient: continuous pressure proportional to dead-space fraction
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 6.0 * (post_residual as f64 / cap_f) * 10.0;
    }

    // Dead-space anticipation weighted by scarcity
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let strandedness = 1.0 - (post_residual as f64 / next_item_size as f64);
        let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0);
        score += 9.0 * strandedness * scarcity;
    }

    // Residual-quality gradient — reusable band 20..=60
    if post_residual >= 20 && post_residual <= 60 {
        score -= 3.0 + 4.0 * (1.0 - progress);
    }

    // Avoid exact-dead residuals 1..=5
    if post_residual >= 1 && post_residual <= 5 {
        score += 5.0;
    }

    // Harmonic-anticipation — reward residuals that pair with the next item
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap > 0 && gap <= 8 {
            score -= 4.0 + 3.0 * (1.0 - progress);
        }
    }

    // Item-residual coupling — prefer bins whose residual is a tight multiple
    if item_size > 0 && bin_residual % item_size == 0 && bin_residual != bin_capacity {
        score -= 5.0;
        if post_residual == 0 {
            score -= 4.0;
        }
    }

    // Exact-fill lookahead with early-stream bonus
    if next_item_size > 0 && post_residual == next_item_size && progress < 0.4 {
        score -= 6.0;
    }

    // Two-item lookahead chain — absorb BOTH current and next item with reusable remainder
    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let chain_left = bin_residual - item_size - next_item_size;
        if chain_left >= 15 && chain_left <= 55 {
