        score += 0.12 * (post_residual as f64) * (0.6 + 0.8 * tightness);
    }

    // Chain-closure bonus — deepen reward for near-emptying bins
    if post_residual > 0 && post_residual <= 20 && bin_residual != bin_capacity {
        score -= 5.0 * (1.0 - post_residual as f64 / 20.0) * (1.0 - 0.4 * progress);
    }

    // Open-bin load balancing guard
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && open_bins_count > 10 {
        score += 1.5 * ((open_bins_count - 10) as f64).min(8.0) * 0.5;
    }

    // Waste-floor refinement — convex (quadratic) waste cost
    if post_residual > 0 && bin_residual != bin_capacity {
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        let pr = post_residual as f64;
        score += (0.09 * pr + 0.0022 * pr * pr) * (0.6 + 0.8 * tightness);
    }

    // Post-fit chainability bonus
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let after_next = post_residual - next_item_size;
        if after_next >= 10 && after_next <= 45 {
            score -= 4.0 * (1.0 - after_next as f64 / 45.0) * (1.0 - 0.5 * progress);
        }
    }

    // Residual-mismatch guard — near-miss stranding penalty
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 6.0 {
            score += 10.0 * (1.0 - miss / 6.0) * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // Three-item lookahead — reward bins whose residual can absorb the current item plus the next item with minimal waste
    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let after_two = bin_residual - item_size - next_item_size;
        if after_two > 0 && after_two <= 12 {
            score -= 6.0 * (1.0 - progress);
        }
    }

    // Waste-quadratic sharpening — steeper convex cost for large dead-space gaps (>25 units)
    if post_residual > 25 && bin_residual != bin_capacity {
        let excess = (post_residual - 25) as f64;
        score += 0.06 * excess * (0.5 + 0.7 * progress);
    }

    // Exact-closure gradient — graded reward for leaving post-fit residual in the 1..=8 range
    if post_residual > 0 && post_residual <= 8 && bin_residual != bin_capacity {
        score -= 4.0 * (1.0 - post_residual as f64 / 8.0);
    }

    // MUTATION (gen 10): residual-harmony gradient — reward bins whose post-fit
    // residual lands in the empirically reusable 30..=55 band, scaled by how
    // centrally it sits in the band; refines the flat 20..=60 bonus.
    if post_residual >= 30 && post_residual <= 55 && bin_residual != bin_capacity {
        let center = 42.5;
        let d = ((post_residual as f64 - center).abs() / 12.5).min(1.0);
        score -= 5.0 * (1.0 - d) * (0.6 + 0.4 * (1.0 - progress));
    }

    // MUTATION (gen 10): adaptive waste coefficient — the quadratic waste cost
    // now scales with how many bins are competing; when few bins fit, dead
    // space is more forgivable (scarcity damping), when many fit, waste is
    // penalized harder. Sharpened convexity for the diagnosed weakness.
    if post_residual > 0 && bin_residual != bin_capacity {
        let scarcity_damp = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
        let pr = post_residual as f64;
        score += (0.05 * pr + 0.0018 * pr * pr) * scarcity_damp;
    }

    // MUTATION (gen 10): mid-band dead-space penalty — residual in 13..=29 is
    // too small to reliably fit mid-size items but too large to ignore; add a
    // graded pressure proportional to unusability against the next item.
    if post_residual >= 13 && post_residual <= 29 && next_item_size > 0 && post_residual < next_item_size && bin_residual != bin_capacity {
        let unus = 1.0 - (post_residual as f64 / next_item_size as f64);
        score += 7.0 * unus * (0.7 + 0.5 * progress);
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score = 55.0 - 15.0 * progress;
        if next_item_size > 0 && item_size + next_item_size >= bin_capacity {
            score -= 45.0;
        }
        if item_size as f64 > 0.6 * cap_f {
            score -= 30.0;
        }
        if progress > 0.8 {
            score += 10.0;
        }
        if fitting_bins_count > 2 {
