        } else if waste_ratio < 0.05 {
            score += 7.0 * (1.0 - progress) * severity;
        } else if waste_ratio < 0.10 && post_residual < 40 {
            score += 3.0 * (1.0 - progress) * severity;
        }
    }

    // Mean-residual coupling: fill tight bins, save roomy bins for big items
    if resid_f > mean_residual + 20.0 && item_size < 30 {
        if next_item_size == 0 || post_residual < next_item_size {
            score += 10.0;
        }
    } else if resid_f < mean_residual - 20.0 {
        score -= 8.0;
    }

    // Last-chance bonus: only bin that fits -> use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
        if post_residual >= 10 {
            score -= 10.0;
        }
    }

    // Consolidation pressure: prefer bins with larger residual when many bins open
    if open_bins_count > 8 {
        score += (resid_f / cap_f) * 6.0;
    }
    score -= (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Fragmentation-aware tiebreak: reward residuals likely reusable
    if post_residual >= 25 {
        score -= 4.0;
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 15 {
            score -= 6.0;
        }
    }

    // Triple-fit chain: scaled by remainder quality
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 20 {
            let sweet = if after_next <= 60 { 3.0 } else { 0.0 };
            score -= 5.0 + 5.0 * (1.0 - progress) + sweet;
        }
    }

    // Waste-ratio gradient: continuous pressure proportional to dead-space fraction
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 6.0 * (post_residual as f64 / cap_f) * 10.0;
    }

    // Dead-space anticipation weighted by scarcity
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let strandedness = 1.0 - (post_residual as f64 / next_item_size as f64);
        let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0);
        score += 9.0 * strandedness * scarcity;
    }

    // Residual-quality gradient — reusable band 20..=60
    if post_residual >= 20 && post_residual <= 60 {
        score -= 3.0 + 4.0 * (1.0 - progress);
    }

    // Avoid exact-dead residuals 1..=5
    if post_residual >= 1 && post_residual <= 5 {
        score += 5.0;
    }

    // Harmonic-anticipation — reward residuals that pair with the next item
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap > 0 && gap <= 8 {
            score -= 4.0 + 3.0 * (1.0 - progress);
        }
    }

    // Item-residual coupling — prefer bins whose residual is a tight multiple
    if item_size > 0 && bin_residual % item_size == 0 && bin_residual != bin_capacity {
        score -= 5.0;
        if post_residual == 0 {
            score -= 4.0;
        }
    }

    // Exact-fill lookahead with early-stream bonus
    if next_item_size > 0 && post_residual == next_item_size && progress < 0.4 {
        score -= 6.0;
    }

    // Two-item lookahead chain — absorb BOTH current and next item with reusable remainder
    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let chain_left = bin_residual - item_size - next_item_size;
        if chain_left >= 15 && chain_left <= 55 {
            score -= 7.0 + 5.0 * (1.0 - progress);
        }
    }

    // Waste-shape gradient — graded penalty on post-fit dead space
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap > 8 && gap <= 20 {
            score += 1.5;
        } else if gap > 20 && gap <= 35 {
            score += 3.5;
        }
    }

    // Scarcity-weighted last-fit — tight fits under scarcity are decisive
    if fitting_bins_count <= 2 && bin_residual != bin_capacity && post_residual <= 12 {
        score -= 6.0 + 4.0 * (1.0 - progress);
    }

    // Consolidation gradient — many open bins: prefer tightest residual bins
    if open_bins_count > 12 && bin_residual != bin_capacity {
        score += 8.0 * (1.0 - resid_f / cap_f);
    }

    // Dead-space slope pressure
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unus = 1.0 - (post_residual as f64 / next_item_size as f64);
        score += 4.5 * unus * (1.0 - 0.3 * progress);
    }

    // Residual entropy guard — awkward 61..=99 band is hard to reuse
    if post_residual > 60 && post_residual < 100 {
        score += 2.5 + 2.0 * (1.0 - progress);
    }

    // Scarcity-weighted exact chain
    if fitting_bins_count <= 2 && next_item_size > 0 && post_residual == next_item_size {
        score -= 8.0;
    }

    // Continuous tightness gradient — smooth penalty on dead space, weighted by global tightness
    if post_residual > 0 && bin_residual != bin_capacity {
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        score += 0.12 * (post_residual as f64) * (0.6 + 0.8 * tightness);
    }

    // Chain-closure bonus — deepen reward for near-emptying bins
    if post_residual > 0 && post_residual <= 20 && bin_residual != bin_capacity {
        score -= 5.0 * (1.0 - post_residual as f64 / 20.0) * (1.0 - 0.4 * progress);
    }

    // Open-bin load balancing guard
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && open_bins_count > 10 {
        score += 1.5 * ((open_bins_count - 10) as f64).min(8.0) * 0.5;
    }

    // Waste-floor refinement — convex (quadratic) waste cost
    if post_residual > 0 && bin_residual != bin_capacity {
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        let pr = post_residual as f64;
        score += (0.09 * pr + 0.0022 * pr * pr) * (0.6 + 0.8 * tightness);
    }

    // Post-fit chainability bonus
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let after_next = post_residual - next_item_size;
        if after_next >= 10 && after_next <= 45 {
            score -= 4.0 * (1.0 - after_next as f64 / 45.0) * (1.0 - 0.5 * progress);
        }
    }

    // Residual-mismatch guard — near-miss stranding penalty
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 6.0 {
            score += 10.0 * (1.0 - miss / 6.0) * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // MUTATION (gen 9): residual-harmony gradient — sharpen the reusable-band
    // reward around the empirically dense 30..=55 zone, weighted centrally.
    if post_residual >= 30 && post_residual <= 55 && bin_residual != bin_capacity {
        let d = ((post_residual as f64 - 42.5).abs() / 12.5).min(1.0);
        score -= 5.0 * (1.0 - d) * (0.6 + 0.4 * (1.0 - progress));
    }

    // MUTATION (gen 9): scarcity-damped adaptive waste cost — dead space is
    // forgivable when few bins fit, punished harder when many compete.
    if post_residual > 0 && bin_residual != bin_capacity {
        let scarcity_damp = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
        let pr = post_residual as f64;
        score += (0.05 * pr + 0.0018 * pr * pr) * scarcity_damp;
    }

    // MUTATION (gen 9): mid-band stranding penalty — residual in 13..=29 that
    // cannot host the next item is graded as unusable proportional to miss size.
    if post_residual >= 13 && post_residual <= 29 && next_item_size > 0 && post_residual < next_item_size && bin_residual != bin_capacity {
        let unus = 1.0 - (post_residual as f64 / next_item_size as f64);
        score += 7.0 * unus * (0.7 + 0.5 * progress);
    }

    // MUTATION (gen 10): dead-space ceiling guard — residuals that can host the
    // next item but leave an awkward tail (just above the reusable band) get a
    // graded penalty; residuals whose tail is exactly reusable get extra reward.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let tail = post_residual - next_item_size;
        if tail > 55 && tail < 100 {
            score += 3.0 * (1.0 - (tail as f64 - 55.0) / 45.0) * (0.5 + 0.5 * (1.0 - progress));
        } else if tail >= 60 {
            score += 2.0;
        }
    }

    // MUTATION (gen 10): exact two-item closure — reward bins where current +
    // next item leave exactly zero or a tiny (<=3) remainder, scaled by how
    // many competing bins exist (scarcity amplifies the payoff).
    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let chain_left = bin_residual - item_size - next_item_size;
        if chain_left <= 3 {
            score -= 10.0 + 6.0 * (1.0 - progress) + 3.0 / (fitting_bins_count as f64).max(1.0);
        }
    }

    // MUTATION (gen 10): item-size-aware waste gradient — large items (>50)
    // should tolerate generous residual hosts, small items should seek the
    // tightest possible fit; graded penalty scaled by item size mismatch.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let size_factor = (item_size as f64 / 100.0).powf(1.5);
        score += pr * 0.045 * (1.0 - size_factor) * (1.0 - 0.3 * progress);
    }

    // MUTATION (gen 10): residual-momentum coupling — when mean residual is
    // low (globally tight packing), tighten the reusable-band reward so bins
    // landing in the 20..=45 band get an extra scarcity-weighted discount.
    if post_residual >= 20 && post_residual <= 45 && bin_residual != bin_capacity {
        let tightness = (1.0 - (mean_residual / cap_f).min(1.0)).max(0.0);
        score -= 3.5 * tightness * (0.5 + 0.5 * (1.0 - progress));
    }

    // MUTATION (gen 11): next-item-fit anticipation — when the next item is
    // large and would be stranded by this placement, penalize proportionally
    // to how likely the next item is (large items late in stream are rare).
    if next_item_size > 35 && post_residual > 0 && post_residual < next_item_size && bin_residual != bin_capacity {
        let stranded = (next_item_size - post_residual) as f64 / next_item_size as f64;
        score += 5.0 * stranded * (1.0 - 0.4 * progress);
    }

    // MUTATION (gen 11): residual decay shaping — residuals in the awkward
    // 6..=12 band are nearly unusable for typical item sizes; apply a graded
    // penalty that grows with progress (late stream = fewer chances to fix).
    if post_residual >= 6 && post_residual <= 12 && bin_residual != bin_capacity {
        score += 2.5 + 3.0 * progress;
    }

    // MUTATION (gen 11): pair-closure lookahead — reward bins whose post-fit
    // residual equals a plausible sum of two future small items (<= 20), which
    // effectively empties the bin within two more placements.
    if post_residual > 0 && post_residual <= 20 && bin_residual != bin_capacity {
        score -= 3.0 * (1.0 - post_residual as f64 / 20.0) * (0.5 + 0.5 * progress);
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score = 55.0 - 15.0 * progress;
        if next_item_size > 0 && item_size + next_item_size >= bin_capacity {
            score -= 45.0;
        }
        if item_size as f64 > 0.6 * cap_f {
            score -= 30.0;
        }
        if progress > 0.8 {
            score += 10.0;
        }
        if fitting_bins_count > 2 {
            score += 20.0;
        }
        if fitting_bins_count == 1 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover >= next_item_size {
                score -= 12.0;
            }
        }
        if next_item_size > 0 && item_size + next_item_size < bin_capacity {
            let leftover = bin_capacity - item_size - next_item_size;
            if leftover < 10 {
                score -= 8.0;
            } else if leftover < 25 {
                score -= 3.0;
            }
            if leftover >= 25 && leftover <= 60 {
                score -= 6.0;
            } else if leftover >= 1 && leftover <= 5 {
                score += 6.0;
            }
        }
        if open_bins_count < 4 && progress < 0.3 {
            score -= 12.0;
        }
        if next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover >= next_item_size {
                score -= 10.0;
            }
        }
        if item_size < 15 && progress > 0.5 && fitting_bins_count >= 1 {
            score += 15.0;
        }
        if fitting_bins_count >= 1 && item_size <= bin_residual {
            let best_case_waste = bin_residual - item_size;
            if best_case_waste <= 5 {
                score += 25.0;
            } else if best_case_waste <= 15 {
                score += 8.0;
            }
        }
        if progress > 0.6 {
            score += 7.5 * (progress - 0.6) * 25.0;
        }
        if open_bins_count > 10 && progress > 0.35 && progress < 0.7 {
            let roomy = (mean_residual / cap_f).min(1.0);
            score += 6.0 * roomy;
        }
        if item_size > 60 && next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 8.0;
        }
        if next_item_size > 0 && item_size + next_item_size < bin_capacity {
            let leftover = bin_capacity - item_size - next_item_size;
            if leftover >= next_item_size {
                score -= 6.0;
            }
        }
        if next_item_size > 0 && fitting_bins_count >= 2 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover > 0 && leftover < 12 {
                score += 9.0;
            }
        }
        if fitting_bins_count >= 1 && item_size <= bin_residual {
            let open_waste = bin_residual - item_size;
            if open_waste > 15 && open_waste <= 35 {
                let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
                if next_item_size > 0 && fresh_left >= next_item_size {
                    score -= 4.0;
                } else {
                    score += 5.0;
                }
            }
        }
        // Fresh-bin convex-waste coupling
        if fitting_bins_count >= 1 && item_size <= bin_residual {
            let open_waste = bin_residual - item_size;
            if open_waste > 35 {
                score -= 3.0 + 0.05 * ((open_waste - 35) as f64).min(30.0);
            }
        }
        // Fresh-bin near-miss guard
        if next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size);
            if leftover < next_item_size {
                let miss = (next_item_size - leftover) as f64;
                if miss <= 8.0 {
                    score += 12.0 * (1.0 - miss / 8.0);
                }
            }
        }
        // Fresh-bin waste-quadratic mirror
        if next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover > 25 {
                score += 0.05 * ((leftover - 25) as f64).min(40.0);
            }
        }
        // MUTATION (gen 9): fresh-bin scarcity coupling — when only one open
        // bin fits and reusing it would strand a mid-band residual while a
        // fresh bin leaves a chainable leftover, prefer opening fresh.
        if fitting_bins_count == 1 && next_item_size > 0 {
            let open_waste = bin_residual.saturating_sub(item_size);
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if open_waste >= 13 && open_waste <= 29 && fresh_left >= next_item_size {
                score -= 9.0;
            }
        }
        // MUTATION (gen 9): fresh-bin late-stream waste floor — opening fresh
        // late in the stream must leave a genuinely usable leftover, otherwise
        // it is pure bin-count inflation; tighten the late discipline.
        if progress > 0.55 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover < 20 {
                score += 6.0 * (progress - 0.55) * 20.0;
            }
        }
        // MUTATION (gen 10): fresh-bin exact-closure preference — a fresh bin
        // is decisively better when current + next item close it exactly or
        // leave <=4 slack, but only mid-stream when open-bin waste would be
        // substantial; prevents fresh-bin inflation in trivial cases.
        if progress > 0.25 && progress < 0.85 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover <= 4 {
                if fitting_bins_count >= 1 && bin_residual.saturating_sub(item_size) > 12 {
                    score -= 14.0;
                }
            } else if leftover <= 12 && fitting_bins_count >= 1 {
                let open_waste = bin_residual.saturating_sub(item_size);
                if open_waste > leftover + 8 {
                    score -= 5.0;
                }
            }
        }
        // MUTATION (gen 10): fresh-bin large-item reserve — when the next item
        // is large (>45) and no open bin could host it after this item, a
        // fresh bin with enough room for both is strongly preferred.
        if next_item_size > 45 && fitting_bins_count >= 1 {
            let open_after = bin_residual.saturating_sub(item_size);
            let fresh_after = bin_capacity.saturating_sub(item_size);
            if open_after < next_item_size && fresh_after >= next_item_size {
                score -= 11.0;
            }
        }
        // MUTATION (gen 11): fresh-bin waste-parity guard — compare the fresh
        // bin's post-two-item leftover against the best open-bin waste; open
        // fresh only when its leftover is strictly more reusable than what
        // reusing an open bin would leave behind.
        if fitting_bins_count >= 1 && next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            let open_waste = bin_residual.saturating_sub(item_size);
            if fresh_left >= next_item_size && open_waste >= 20 {
                score -= 4.0 + 0.1 * ((open_waste - 20) as f64).min(25.0);
            } else if fresh_left > 0 && fresh_left < 8 && open_waste <= 10 {
                score += 5.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap_f = bin_capacity as f64;
    let resid_f = bin_residual as f64;

    // Perfect fill reward
    if post_residual == 0 {
        score -= 65.0;
    }

    // Near-exact capacity match: residual just above item size
    let slack = bin_residual as i64 - item_size as i64;
    if slack >= 0 && slack <= 4 {
        score -= 20.0;
    }

    // --- 2-step lookahead core ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0 + 22.0 * (1.0 - progress);
        } else if post_residual > next_item_size {
            let slack_after_next = post_residual - next_item_size;
            score -= 25.0 - (slack_after_next as f64).min(40.0) * 0.3;
            if slack_after_next > 40 {
                score += (slack_after_next as f64 - 40.0) * 0.2;
            }
        } else {
            let shortfall = (next_item_size - post_residual) as f64;
            score += shortfall * 0.85;
            let half_next = next_item_size / 2;
            if post_residual > 0 && post_residual < half_next {
                score += 14.0;
            }
        }
    } else {
        score -= 10.0;
    }

    // Dead-space penalty: graded, fragmentation-aware waste pressure
    if post_residual > 0 {
        let waste_ratio = post_residual as f64 / cap_f;
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        let severity = 1.4 - 0.8 * tightness;
        if post_residual < next_item_size && next_item_size > 0 {
            let unusability = 1.0 - (post_residual as f64 / next_item_size as f64);
            score += 16.0 * unusability * (1.0 - 0.5 * progress) * severity;
            if post_residual < 10 {
                score += 9.0 * severity * (1.0 - 0.4 * progress);
            }
        } else if waste_ratio < 0.05 {
            score += 7.0 * (1.0 - progress) * severity;
        } else if waste_ratio < 0.10 && post_residual < 40 {
            score += 3.0 * (1.0 - progress) * severity;
        }
    }

    // Mean-residual coupling: fill tight bins, save roomy bins for big items
    if resid_f > mean_residual + 20.0 && item_size < 30 {
        if next_item_size == 0 || post_residual < next_item_size {
            score += 10.0;
        }
    } else if resid_f < mean_residual - 20.0 {
        score -= 8.0;
    }

    // Last-chance bonus: only bin that fits -> use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
        if post_residual >= 10 {
            score -= 10.0;
        }
    }

    // Consolidation pressure: prefer bins with larger residual when many bins open
    if open_bins_count > 8 {
        score += (resid_f / cap_f) * 6.0;
    }
    score -= (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Fragmentation-aware tiebreak: reward residuals likely reusable
    if post_residual >= 25 {
        score -= 4.0;
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 15 {
            score -= 6.0;
        }
    }

    // Triple-fit chain: scaled by remainder quality
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 20 {
            let sweet = if after_next <= 60 { 3.0 } else { 0.0 };
            score -= 5.0 + 5.0 * (1.0 - progress) + sweet;
        }
    }

    // Waste-ratio gradient: continuous pressure proportional to dead-space fraction
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 6.0 * (post_residual as f64 / cap_f) * 10.0;
    }

    // Dead-space anticipation weighted by scarcity
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let strandedness = 1.0 - (post_residual as f64 / next_item_size as f64);
        let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0);
        score += 9.0 * strandedness * scarcity;
    }

    // Residual-quality gradient — reusable band 20..=60
    if post_residual >= 20 && post_residual <= 60 {
        score -= 3.0 + 4.0 * (1.0 - progress);
    }

    // Avoid exact-dead residuals 1..=5
    if post_residual >= 1 && post_residual <= 5 {
        score += 5.0;
    }

    // Harmonic-anticipation — reward residuals that pair with the next item
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap > 0 && gap <= 8 {
            score -= 4.0 + 3.0 * (1.0 - progress);
        }
    }

    // Item-residual coupling — prefer bins whose residual is a tight multiple
    if item_size > 0 && bin_residual % item_size == 0 && bin_residual != bin_capacity {
        score -= 5.0;
        if post_residual == 0 {
            score -= 4.0;
        }
    }

    // Exact-fill lookahead with early-stream bonus
    if next_item_size > 0 && post_residual == next_item_size && progress < 0.4 {
        score -= 6.0;
    }

    // Two-item lookahead chain — absorb BOTH current and next item with reusable remainder
    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let chain_left = bin_residual - item_size - next_item_size;
        if chain_left >= 15 && chain_left <= 55 {
            score -= 7.0 + 5.0 * (1.0 - progress);
        }
    }

    // Waste-shape gradient — graded penalty on post-fit dead space
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap > 8 && gap <= 20 {
            score += 1.5;
        } else if gap > 20 && gap <= 35 {
            score += 3.5;
        }
    }

    // Scarcity-weighted last-fit — tight fits under scarcity are decisive
    if fitting_bins_count <= 2 && bin_residual != bin_capacity && post_residual <= 12 {
        score -= 6.0 + 4.0 * (1.0 - progress);
    }

    // Consolidation gradient — many open bins: prefer tightest residual bins
    if open_bins_count > 12 && bin_residual != bin_capacity {
        score += 8.0 * (1.0 - resid_f / cap_f);
    }

    // Dead-space slope pressure
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unus = 1.0 - (post_residual as f64 / next_item_size as f64);
        score += 4.5 * unus * (1.0 - 0.3 * progress);
    }

    // Residual entropy guard — awkward 61..=99 band is hard to reuse
    if post_residual > 60 && post_residual < 100 {
        score += 2.5 + 2.0 * (1.0 - progress);
    }

    // Scarcity-weighted exact chain
    if fitting_bins_count <= 2 && next_item_size > 0 && post_residual == next_item_size {
        score -= 8.0;
    }

    // Continuous tightness gradient — smooth penalty on dead space, weighted by global tightness
    if post_residual > 0 && bin_residual != bin_capacity {
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        score += 0.12 * (post_residual as f64) * (0.6 + 0.8 * tightness);
    }

    // Chain-closure bonus — deepen reward for near-emptying bins
    if post_residual > 0 && post_residual <= 20 && bin_residual != bin_capacity {
        score -= 5.0 * (1.0 - post_residual as f64 / 20.0) * (1.0 - 0.4 * progress);
    }

    // Open-bin load balancing guard
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && open_bins_count > 10 {
        score += 1.5 * ((open_bins_count - 10) as f64).min(8.0) * 0.5;
    }

    // Waste-floor refinement — convex (quadratic) waste cost
    if post_residual > 0 && bin_residual != bin_capacity {
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        let pr = post_residual as f64;
        score += (0.09 * pr + 0.0022 * pr * pr) * (0.6 + 0.8 * tightness);
    }

    // Post-fit chainability bonus
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let after_next = post_residual - next_item_size;
        if after_next >= 10 && after_next <= 45 {
            score -= 4.0 * (1.0 - after_next as f64 / 45.0) * (1.0 - 0.5 * progress);
        }
    }

    // Residual-mismatch guard — near-miss stranding penalty
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 6.0 {
            score += 10.0 * (1.0 - miss / 6.0) * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // MUTATION (gen 9): residual-harmony gradient — sharpen the reusable-band
    // reward around the empirically dense 30..=55 zone, weighted centrally.
    if post_residual >= 30 && post_residual <= 55 && bin_residual != bin_capacity {
        let d = ((post_residual as f64 - 42.5).abs() / 12.5).min(1.0);
        score -= 5.0 * (1.0 - d) * (0.6 + 0.4 * (1.0 - progress));
    }

    // MUTATION (gen 9): scarcity-damped adaptive waste cost — dead space is
    // forgivable when few bins fit, punished harder when many compete.
    if post_residual > 0 && bin_residual != bin_capacity {
        let scarcity_damp = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
        let pr = post_residual as f64;
        score += (0.05 * pr + 0.0018 * pr * pr) * scarcity_damp;
    }

    // MUTATION (gen 9): mid-band stranding penalty — residual in 13..=29 that
    // cannot host the next item is graded as unusable proportional to miss size.
    if post_residual >= 13 && post_residual <= 29 && next_item_size > 0 && post_residual < next_item_size && bin_residual != bin_capacity {
        let unus = 1.0 - (post_residual as f64 / next_item_size as f64);
        score += 7.0 * unus * (0.7 + 0.5 * progress);
    }

    // MUTATION (gen 10): dead-space ceiling guard — residuals that can host the
    // next item but leave an awkward tail (just above the reusable band) get a
    // graded penalty; residuals whose tail is exactly reusable get extra reward.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let tail = post_residual - next_item_size;
        if tail > 55 && tail < 100 {
            score += 3.0 * (1.0 - (tail as f64 - 55.0) / 45.0) * (0.5 + 0.5 * (1.0 - progress));
        } else if tail >= 60 {
            score += 2.0;
        }
    }

    // MUTATION (gen 10): exact two-item closure — reward bins where current +
    // next item leave exactly zero or a tiny (<=3) remainder, scaled by how
    // many competing bins exist (scarcity amplifies the payoff).
    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let chain_left = bin_residual - item_size - next_item_size;
        if chain_left <= 3 {
            score -= 10.0 + 6.0 * (1.0 - progress) + 3.0 / (fitting_bins_count as f64).max(1.0);
        }
    }

    // MUTATION (gen 10): item-size-aware waste gradient — large items (>50)
    // should tolerate generous residual hosts, small items should seek the
    // tightest possible fit; graded penalty scaled by item size mismatch.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let size_factor = (item_size as f64 / 100.0).powf(1.5);
        score += pr * 0.045 * (1.0 - size_factor) * (1.0 - 0.3 * progress);
    }

    // MUTATION (gen 10): residual-momentum coupling — when mean residual is
    // low (globally tight packing), tighten the reusable-band reward so bins
    // landing in the 20..=45 band get an extra scarcity-weighted discount.
    if post_residual >= 20 && post_residual <= 45 && bin_residual != bin_capacity {
        let tightness = (1.0 - (mean_residual / cap_f).min(1.0)).max(0.0);
        score -= 3.5 * tightness * (0.5 + 0.5 * (1.0 - progress));
    }

    // MUTATION (gen 11): next-item-fit anticipation — when the next item is
    // large and would be stranded by this placement, penalize proportionally
    // to how likely the next item is (large items late in stream are rare).
    if next_item_size > 35 && post_residual > 0 && post_residual < next_item_size && bin_residual != bin_capacity {
        let stranded = (next_item_size - post_residual) as f64 / next_item_size as f64;
        score += 5.0 * stranded * (1.0 - 0.4 * progress);
    }

    // MUTATION (gen 11): residual decay shaping — residuals in the awkward
    // 6..=12 band are nearly unusable for typical item sizes; apply a graded
    // penalty that grows with progress (late stream = fewer chances to fix).
    if post_residual >= 6 && post_residual <= 12 && bin_residual != bin_capacity {
        score += 2.5 + 3.0 * progress;
    }

    // MUTATION (gen 11): pair-closure lookahead — reward bins whose post-fit
    // residual equals a plausible sum of two future small items (<= 20), which
    // effectively empties the bin within two more placements.
    if post_residual > 0 && post_residual <= 20 && bin_residual != bin_capacity {
        score -= 3.0 * (1.0 - post_residual as f64 / 20.0) * (0.5 + 0.5 * progress);
    }

    // MUTATION (gen 12): dead-space absorption gradient — when many bins are
    // open, small dead spaces (<= 18) can be absorbed by future small items,
    // so grade their cost down; but large dead spaces (> 30) that cannot host
    // the next item are charged harder as open-bin count grows.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let crowd = ((open_bins_count as f64 - 6.0).max(0.0) / 10.0).min(1.0);
        if pr <= 18.0 {
            score -= 2.0 * (1.0 - pr / 18.0) * crowd;
        } else if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0 * crowd * (1.0 - progress);
        }
    }

    // MUTATION (gen 12): three-step chain bonus — reward placements whose
    // post-fit residual can absorb the next item AND leave a remainder in the
    // dense reusable 25..=50 zone; this extends the two-item lookahead one
    // step further and directly targets residual dead-space reduction.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let tail = post_residual - next_item_size;
        if tail >= 25 && tail <= 50 {
            score -= 4.5 * (1.0 - (tail as f64 - 25.0).abs() / 25.0) * (0.6 + 0.4 * (1.0 - progress));
        }
    }

    // MUTATION (gen 12): tightness-scaled exact-fill escalation — when the
    // global mean residual is very low (near-perfect packing regime), exact
    // and near-exact fills become the dominant bin-saving mechanism; boost
    // their reward proportionally to how close the stream is to that regime.
    if post_residual == 0 {
        let tightness = (1.0 - (mean_residual / cap_f).min(1.0)).max(0.0);
        score -= 4.0 * tightness;
    } else if slack >= 0 && slack <= 2 {
        let tightness = (1.0 - (mean_residual / cap_f).min(1.0)).max(0.0);
        score -= 2.5 * tightness * (1.0 - 0.5 * progress);
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score = 55.0 - 15.0 * progress;
        if next_item_size > 0 && item_size + next_item_size >= bin_capacity {
            score -= 45.0;
        }
        if item_size as f64 > 0.6 * cap_f {
            score -= 30.0;
        }
        if progress > 0.8 {
            score += 10.0;
        }
        if fitting_bins_count > 2 {
            score += 20.0;
        }
        if fitting_bins_count == 1 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover >= next_item_size {
                score -= 12.0;
            }
        }
        if next_item_size > 0 && item_size + next_item_size < bin_capacity {
            let leftover = bin_capacity - item_size - next_item_size;
            if leftover < 10 {
                score -= 8.0;
            } else if leftover < 25 {
                score -= 3.0;
            }
            if leftover >= 25 && leftover <= 60 {
                score -= 6.0;
            } else if leftover >= 1 && leftover <= 5 {
                score += 6.0;
            }
        }
        if open_bins_count < 4 && progress < 0.3 {
            score -= 12.0;
        }
        if next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover >= next_item_size {
                score -= 10.0;
            }
        }
        if item_size < 15 && progress > 0.5 && fitting_bins_count >= 1 {
            score += 15.0;
        }
        if fitting_bins_count >= 1 && item_size <= bin_residual {
            let best_case_waste = bin_residual - item_size;
            if best_case_waste <= 5 {
                score += 25.0;
            } else if best_case_waste <= 15 {
                score += 8.0;
            }
        }
        if progress > 0.6 {
            score += 7.5 * (progress - 0.6) * 25.0;
        }
        if open_bins_count > 10 && progress > 0.35 && progress < 0.7 {
            let roomy = (mean_residual / cap_f).min(1.0);
            score += 6.0 * roomy;
        }
        if item_size > 60 && next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 8.0;
        }
        if next_item_size > 0 && item_size + next_item_size < bin_capacity {
            let leftover = bin_capacity - item_size - next_item_size;
            if leftover >= next_item_size {
                score -= 6.0;
            }
        }
        if next_item_size > 0 && fitting_bins_count >= 2 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover > 0 && leftover < 12 {
                score += 9.0;
            }
        }
        if fitting_bins_count >= 1 && item_size <= bin_residual {
            let open_waste = bin_residual - item_size;
            if open_waste > 15 && open_waste <= 35 {
                let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
                if next_item_size > 0 && fresh_left >= next_item_size {
                    score -= 4.0;
                } else {
                    score += 5.0;
                }
            }
        }
        // Fresh-bin convex-waste coupling
        if fitting_bins_count >= 1 && item_size <= bin_residual {
            let open_waste = bin_residual - item_size;
            if open_waste > 35 {
                score -= 3.0 + 0.05 * ((open_waste - 35) as f64).min(30.0);
            }
        }
        // Fresh-bin near-miss guard
        if next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size);
            if leftover < next_item_size {
                let miss = (next_item_size - leftover) as f64;
                if miss <= 8.0 {
                    score += 12.0 * (1.0 - miss / 8.0);
                }
            }
        }
        // Fresh-bin waste-quadratic mirror
        if next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover > 25 {
                score += 0.05 * ((leftover - 25) as f64).min(40.0);
            }
        }
        // MUTATION (gen 9): fresh-bin scarcity coupling — when only one open
        // bin fits and reusing it would strand a mid-band residual while a
        // fresh bin leaves a chainable leftover, prefer opening fresh.
        if fitting_bins_count == 1 && next_item_size > 0 {
            let open_waste = bin_residual.saturating_sub(item_size);
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if open_waste >= 13 && open_waste <= 29 && fresh_left >= next_item_size {
                score -= 9.0;
            }
        }
        // MUTATION (gen 9): fresh-bin late-stream waste floor — opening fresh
        // late in the stream must leave a genuinely usable leftover, otherwise
        // it is pure bin-count inflation; tighten the late discipline.
        if progress > 0.55 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover < 20 {
                score += 6.0 * (progress - 0.55) * 20.0;
            }
        }
        // MUTATION (gen 10): fresh-bin exact-closure preference — a fresh bin
        // is decisively better when current + next item close it exactly or
        // leave <=4 slack, but only mid-stream when open-bin waste would be
        // substantial; prevents fresh-bin inflation in trivial cases.
        if progress > 0.25 && progress < 0.85 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover <= 4 {
                if fitting_bins_count >= 1 && bin_residual.saturating_sub(item_size) > 12 {
                    score -= 14.0;
                }
            } else if leftover <= 12 && fitting_bins_count >= 1 {
                let open_waste = bin_residual.saturating_sub(item_size);
                if open_waste > leftover + 8 {
                    score -= 5.0;
                }
            }
        }
        // MUTATION (gen 10): fresh-bin large-item reserve — when the next item
        // is large (>45) and no open bin could host it after this item, a
        // fresh bin with enough room for both is strongly preferred.
        if next_item_size > 45 && fitting_bins_count >= 1 {
            let open_after = bin_residual.saturating_sub(item_size);
            let fresh_after = bin_capacity.saturating_sub(item_size);
            if open_after < next_item_size && fresh_after >= next_item_size {
                score -= 11.0;
            }
        }
        // MUTATION (gen 11): fresh-bin waste-parity guard — compare the fresh
        // bin's post-two-item leftover against the best open-bin waste; open
        // fresh only when its leftover is strictly more reusable than what
        // reusing an open bin would leave behind.
        if fitting_bins_count >= 1 && next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            let open_waste = bin_residual.saturating_sub(item_size);
            if fresh_left >= next_item_size && open_waste >= 20 {
                score -= 4.0 + 0.1 * ((open_waste - 20) as f64).min(25.0);
            } else if fresh_left > 0 && fresh_left < 8 && open_waste <= 10 {
                score += 5.0;
            }
        }
        // MUTATION (gen 12): fresh-bin residual-regime gate — in a tight global
        // regime (low mean residual), fresh bins should only open when they
        // close within two items or leave a dense-band leftover; otherwise
        // they inflate the bin count. In a loose regime, keep existing bias.
        if progress > 0.3 && next_item_size > 0 {
            let tightness = (1.0 - (mean_residual / cap_f).min(1.0)).max(0.0);
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if tightness > 0.6 && leftover > 50 {
                score += 8.0 * (tightness - 0.6) * 10.0;
            } else if tightness > 0.6 && leftover >= 25 && leftover <= 50 {
                score -= 5.0 * (tightness - 0.6) * 10.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap_f = bin_capacity as f64;
    let resid_f = bin_residual as f64;

    // Perfect fill reward
    if post_residual == 0 {
        score -= 65.0;
    }

    // Near-exact capacity match: residual just above item size
    let slack = bin_residual as i64 - item_size as i64;
    if slack >= 0 && slack <= 4 {
        score -= 20.0;
    }

    // --- 2-step lookahead core ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0 + 22.0 * (1.0 - progress);
        } else if post_residual > next_item_size {
            let slack_after_next = post_residual - next_item_size;
            score -= 25.0 - (slack_after_next as f64).min(40.0) * 0.3;
            if slack_after_next > 40 {
                score += (slack_after_next as f64 - 40.0) * 0.2;
            }
        } else {
            let shortfall = (next_item_size - post_residual) as f64;
            score += shortfall * 0.85;
            let half_next = next_item_size / 2;
            if post_residual > 0 && post_residual < half_next {
                score += 14.0;
            }
        }
    } else {
        score -= 10.0;
    }

    // Dead-space penalty: graded, fragmentation-aware waste pressure
    if post_residual > 0 {
        let waste_ratio = post_residual as f64 / cap_f;
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        let severity = 1.4 - 0.8 * tightness;
        if post_residual < next_item_size && next_item_size > 0 {
            let unusability = 1.0 - (post_residual as f64 / next_item_size as f64);
            score += 16.0 * unusability * (1.0 - 0.5 * progress) * severity;
            if post_residual < 10 {
                score += 9.0 * severity * (1.0 - 0.4 * progress);
            }
        } else if waste_ratio < 0.05 {
            score += 7.0 * (1.0 - progress) * severity;
        } else if waste_ratio < 0.10 && post_residual < 40 {
            score += 3.0 * (1.0 - progress) * severity;
        }
    }

    // Mean-residual coupling: fill tight bins, save roomy bins for big items
    if resid_f > mean_residual + 20.0 && item_size < 30 {
        if next_item_size == 0 || post_residual < next_item_size {
            score += 10.0;
        }
    } else if resid_f < mean_residual - 20.0 {
        score -= 8.0;
    }

    // Last-chance bonus: only bin that fits -> use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
        if post_residual >= 10 {
            score -= 10.0;
        }
    }

    // Consolidation pressure: prefer bins with larger residual when many bins open
    if open_bins_count > 8 {
        score += (resid_f / cap_f) * 6.0;
    }
    score -= (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Fragmentation-aware tiebreak: reward residuals likely reusable
    if post_residual >= 25 {
        score -= 4.0;
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 15 {
            score -= 6.0;
        }
    }

    // Triple-fit chain: scaled by remainder quality
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 20 {
            let sweet = if after_next <= 60 { 3.0 } else { 0.0 };
            score -= 5.0 + 5.0 * (1.0 - progress) + sweet;
        }
    }

    // Waste-ratio gradient: continuous pressure proportional to dead-space fraction
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 6.0 * (post_residual as f64 / cap_f) * 10.0;
    }

    // Dead-space anticipation weighted by scarcity
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let strandedness = 1.0 - (post_residual as f64 / next_item_size as f64);
        let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0);
        score += 9.0 * strandedness * scarcity;
    }

    // Residual-quality gradient — reusable band 20..=60
    if post_residual >= 20 && post_residual <= 60 {
        score -= 3.0 + 4.0 * (1.0 - progress);
    }

    // Avoid exact-dead residuals 1..=5
    if post_residual >= 1 && post_residual <= 5 {
        score += 5.0;
    }

    // Harmonic-anticipation — reward residuals that pair with the next item
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap > 0 && gap <= 8 {
            score -= 4.0 + 3.0 * (1.0 - progress);
        }
    }

    // Item-residual coupling — prefer bins whose residual is a tight multiple
    if item_size > 0 && bin_residual % item_size == 0 && bin_residual != bin_capacity {
        score -= 5.0;
        if post_residual == 0 {
            score -= 4.0;
        }
    }

    // Exact-fill lookahead with early-stream bonus
    if next_item_size > 0 && post_residual == next_item_size && progress < 0.4 {
        score -= 6.0;
    }

    // Two-item lookahead chain — absorb BOTH current and next item with reusable remainder
    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let chain_left = bin_residual - item_size - next_item_size;
        if chain_left >= 15 && chain_left <= 55 {
            score -= 7.0 + 5.0 * (1.0 - progress);
        }
    }

    // Waste-shape gradient — graded penalty on post-fit dead space
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap > 8 && gap <= 20 {
            score += 1.5;
        } else if gap > 20 && gap <= 35 {
            score += 3.5;
        }
    }

    // Scarcity-weighted last-fit — tight fits under scarcity are decisive
    if fitting_bins_count <= 2 && bin_residual != bin_capacity && post_residual <= 12 {
        score -= 6.0 + 4.0 * (1.0 - progress);
    }

    // Consolidation gradient — many open bins: prefer tightest residual bins
    if open_bins_count > 12 && bin_residual != bin_capacity {
        score += 8.0 * (1.0 - resid_f / cap_f);
    }

    // Dead-space slope pressure
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unus = 1.0 - (post_residual as f64 / next_item_size as f64);
        score += 4.5 * unus * (1.0 - 0.3 * progress);
    }

    // Residual entropy guard — awkward 61..=99 band is hard to reuse
    if post_residual > 60 && post_residual < 100 {
        score += 2.5 + 2.0 * (1.0 - progress);
    }

    // Scarcity-weighted exact chain
    if fitting_bins_count <= 2 && next_item_size > 0 && post_residual == next_item_size {
        score -= 8.0;
    }

    // Continuous tightness gradient — smooth penalty on dead space, weighted by global tightness
    if post_residual > 0 && bin_residual != bin_capacity {
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        score += 0.12 * (post_residual as f64) * (0.6 + 0.8 * tightness);
    }

    // Chain-closure bonus — deepen reward for near-emptying bins
    if post_residual > 0 && post_residual <= 20 && bin_residual != bin_capacity {
        score -= 5.0 * (1.0 - post_residual as f64 / 20.0) * (1.0 - 0.4 * progress);
    }

    // Open-bin load balancing guard
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && open_bins_count > 10 {
        score += 1.5 * ((open_bins_count - 10) as f64).min(8.0) * 0.5;
    }

    // Waste-floor refinement — convex (quadratic) waste cost
    if post_residual > 0 && bin_residual != bin_capacity {
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        let pr = post_residual as f64;
        score += (0.09 * pr + 0.0022 * pr * pr) * (0.6 + 0.8 * tightness);
    }

    // Post-fit chainability bonus
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let after_next = post_residual - next_item_size;
        if after_next >= 10 && after_next <= 45 {
            score -= 4.0 * (1.0 - after_next as f64 / 45.0) * (1.0 - 0.5 * progress);
        }
    }

    // Residual-mismatch guard — near-miss stranding penalty
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 6.0 {
            score += 10.0 * (1.0 - miss / 6.0) * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // MUTATION (gen 9): residual-harmony gradient — sharpen the reusable-band
    // reward around the empirically dense 30..=55 zone, weighted centrally.
    if post_residual >= 30 && post_residual <= 55 && bin_residual != bin_capacity {
        let d = ((post_residual as f64 - 42.5).abs() / 12.5).min(1.0);
        score -= 5.0 * (1.0 - d) * (0.6 + 0.4 * (1.0 - progress));
    }

    // MUTATION (gen 9): scarcity-damped adaptive waste cost — dead space is
    // forgivable when few bins fit, punished harder when many compete.
    if post_residual > 0 && bin_residual != bin_capacity {
        let scarcity_damp = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
        let pr = post_residual as f64;
        score += (0.05 * pr + 0.0018 * pr * pr) * scarcity_damp;
    }

    // MUTATION (gen 9): mid-band stranding penalty — residual in 13..=29 that
    // cannot host the next item is graded as unusable proportional to miss size.
    if post_residual >= 13 && post_residual <= 29 && next_item_size > 0 && post_residual < next_item_size && bin_residual != bin_capacity {
        let unus = 1.0 - (post_residual as f64 / next_item_size as f64);
        score += 7.0 * unus * (0.7 + 0.5 * progress);
    }

    // MUTATION (gen 10): dead-space ceiling guard — residuals that can host the
    // next item but leave an awkward tail (just above the reusable band) get a
    // graded penalty; residuals whose tail is exactly reusable get extra reward.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let tail = post_residual - next_item_size;
        if tail > 55 && tail < 100 {
            score += 3.0 * (1.0 - (tail as f64 - 55.0) / 45.0) * (0.5 + 0.5 * (1.0 - progress));
        } else if tail >= 60 {
            score += 2.0;
        }
    }

    // MUTATION (gen 10): exact two-item closure — reward bins where current +
    // next item leave exactly zero or a tiny (<=3) remainder, scaled by how
    // many competing bins exist (scarcity amplifies the payoff).
    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let chain_left = bin_residual - item_size - next_item_size;
        if chain_left <= 3 {
            score -= 10.0 + 6.0 * (1.0 - progress) + 3.0 / (fitting_bins_count as f64).max(1.0);
        }
    }

    // MUTATION (gen 10): item-size-aware waste gradient — large items (>50)
    // should tolerate generous residual hosts, small items should seek the
    // tightest possible fit; graded penalty scaled by item size mismatch.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let size_factor = (item_size as f64 / 100.0).powf(1.5);
        score += pr * 0.045 * (1.0 - size_factor) * (1.0 - 0.3 * progress);
    }

    // MUTATION (gen 10): residual-momentum coupling — when mean residual is
    // low (globally tight packing), tighten the reusable-band reward so bins
    // landing in the 20..=45 band get an extra scarcity-weighted discount.
    if post_residual >= 20 && post_residual <= 45 && bin_residual != bin_capacity {
        let tightness = (1.0 - (mean_residual / cap_f).min(1.0)).max(0.0);
        score -= 3.5 * tightness * (0.5 + 0.5 * (1.0 - progress));
    }

    // MUTATION (gen 11): next-item-fit anticipation — when the next item is
    // large and would be stranded by this placement, penalize proportionally
    // to how likely the next item is (large items late in stream are rare).
    if next_item_size > 35 && post_residual > 0 && post_residual < next_item_size && bin_residual != bin_capacity {
        let stranded = (next_item_size - post_residual) as f64 / next_item_size as f64;
        score += 5.0 * stranded * (1.0 - 0.4 * progress);
    }

    // MUTATION (gen 11): residual decay shaping — residuals in the awkward
    // 6..=12 band are nearly unusable for typical item sizes; apply a graded
    // penalty that grows with progress (late stream = fewer chances to fix).
    if post_residual >= 6 && post_residual <= 12 && bin_residual != bin_capacity {
        score += 2.5 + 3.0 * progress;
    }

    // MUTATION (gen 11): pair-closure lookahead — reward bins whose post-fit
    // residual equals a plausible sum of two future small items (<= 20), which
    // effectively empties the bin within two more placements.
    if post_residual > 0 && post_residual <= 20 && bin_residual != bin_capacity {
        score -= 3.0 * (1.0 - post_residual as f64 / 20.0) * (0.5 + 0.5 * progress);
    }

    // MUTATION (gen 12): dead-space absorption gradient — when many bins are
    // open, small dead spaces (<= 18) can be absorbed by future small items,
    // so grade their cost down; but large dead spaces (> 30) that cannot host
    // the next item are charged harder as open-bin count grows.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let crowd = ((open_bins_count as f64 - 6.0).max(0.0) / 10.0).min(1.0);
        if pr <= 18.0 {
            score -= 2.0 * (1.0 - pr / 18.0) * crowd;
        } else if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0 * crowd * (1.0 - progress);
        }
    }

    // MUTATION (gen 12): three-step chain bonus — reward placements whose
    // post-fit residual can absorb the next item AND leave a remainder in the
    // dense reusable 25..=50 zone; this extends the two-item lookahead one
    // step further and directly targets residual dead-space reduction.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let tail = post_residual - next_item_size;
        if tail >= 25 && tail <= 50 {
            score -= 4.5 * (1.0 - (tail as f64 - 25.0).abs() / 25.0) * (0.6 + 0.4 * (1.0 - progress));
        }
    }

    // MUTATION (gen 12): tightness-scaled exact-fill escalation — when the
    // global mean residual is very low (near-perfect packing regime), exact
    // and near-exact fills become the dominant bin-saving mechanism; boost
    // their reward proportionally to how close the stream is to that regime.
    if post_residual == 0 {
        let tightness = (1.0 - (mean_residual / cap_f).min(1.0)).max(0.0);
        score -= 4.0 * tightness;
    } else if slack >= 0 && slack <= 2 {
        let tightness = (1.0 - (mean_residual / cap_f).min(1.0)).max(0.0);
        score -= 2.5 * tightness * (1.0 - 0.5 * progress);
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score = 55.0 - 15.0 * progress;
        if next_item_size > 0 && item_size + next_item_size >= bin_capacity {
            score -= 45.0;
        }
        if item_size as f64 > 0.6 * cap_f {
            score -= 30.0;
        }
        if progress > 0.8 {
            score += 10.0;
        }
        if fitting_bins_count > 2 {
            score += 20.0;
        }
        if fitting_bins_count == 1 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover >= next_item_size {
                score -= 12.0;
            }
        }
        if next_item_size > 0 && item_size + next_item_size < bin_capacity {
            let leftover = bin_capacity - item_size - next_item_size;
            if leftover < 10 {
                score -= 8.0;
            } else if leftover < 25 {
                score -= 3.0;
            }
            if leftover >= 25 && leftover <= 60 {
                score -= 6.0;
            } else if leftover >= 1 && leftover <= 5 {
                score += 6.0;
            }
        }
        if open_bins_count < 4 && progress < 0.3 {
            score -= 12.0;
        }
        if next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover >= next_item_size {
                score -= 10.0;
            }
        }
        if item_size < 15 && progress > 0.5 && fitting_bins_count >= 1 {
            score += 15.0;
        }
        if fitting_bins_count >= 1 && item_size <= bin_residual {
            let best_case_waste = bin_residual - item_size;
            if best_case_waste <= 5 {
                score += 25.0;
            } else if best_case_waste <= 15 {
                score += 8.0;
            }
        }
        if progress > 0.6 {
            score += 7.5 * (progress - 0.6) * 25.0;
        }
        if open_bins_count > 10 && progress > 0.35 && progress < 0.7 {
            let roomy = (mean_residual / cap_f).min(1.0);
            score += 6.0 * roomy;
        }
        if item_size > 60 && next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 8.0;
        }
        if next_item_size > 0 && item_size + next_item_size < bin_capacity {
            let leftover = bin_capacity - item_size - next_item_size;
            if leftover >= next_item_size {
                score -= 6.0;
            }
        }
        if next_item_size > 0 && fitting_bins_count >= 2 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover > 0 && leftover < 12 {
                score += 9.0;
            }
        }
        if fitting_bins_count >= 1 && item_size <= bin_residual {
            let open_waste = bin_residual - item_size;
            if open_waste > 15 && open_waste <= 35 {
                let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
                if next_item_size > 0 && fresh_left >= next_item_size {
                    score -= 4.0;
                } else {
                    score += 5.0;
                }
            }
        }
        // Fresh-bin convex-waste coupling
        if fitting_bins_count >= 1 && item_size <= bin_residual {
            let open_waste = bin_residual - item_size;
            if open_waste > 35 {
                score -= 3.0 + 0.05 * ((open_waste - 35) as f64).min(30.0);
            }
        }
        // Fresh-bin near-miss guard
        if next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size);
            if leftover < next_item_size {
                let miss = (next_item_size - leftover) as f64;
                if miss <= 8.0 {
                    score += 12.0 * (1.0 - miss / 8.0);
                }
            }
        }
        // Fresh-bin waste-quadratic mirror
        if next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover > 25 {
                score += 0.05 * ((leftover - 25) as f64).min(40.0);
            }
        }
        // MUTATION (gen 9): fresh-bin scarcity coupling — when only one open
        // bin fits and reusing it would strand a mid-band residual while a
        // fresh bin leaves a chainable leftover, prefer opening fresh.
        if fitting_bins_count == 1 && next_item_size > 0 {
            let open_waste = bin_residual.saturating_sub(item_size);
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if open_waste >= 13 && open_waste <= 29 && fresh_left >= next_item_size {
                score -= 9.0;
            }
        }
        // MUTATION (gen 9): fresh-bin late-stream waste floor — opening fresh
        // late in the stream must leave a genuinely usable leftover, otherwise
        // it is pure bin-count inflation; tighten the late discipline.
        if progress > 0.55 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover < 20 {
                score += 6.0 * (progress - 0.55) * 20.0;
            }
        }
        // MUTATION (gen 10): fresh-bin exact-closure preference — a fresh bin
        // is decisively better when current + next item close it exactly or
        // leave <=4 slack, but only mid-stream when open-bin waste would be
        // substantial; prevents fresh-bin inflation in trivial cases.
        if progress > 0.25 && progress < 0.85 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover <= 4 {
                if fitting_bins_count >= 1 && bin_residual.saturating_sub(item_size) > 12 {
                    score -= 14.0;
                }
            } else if leftover <= 12 && fitting_bins_count >= 1 {
                let open_waste = bin_residual.saturating_sub(item_size);
                if open_waste > leftover + 8 {
                    score -= 5.0;
                }
            }
        }
        // MUTATION (gen 10): fresh-bin large-item reserve — when the next item
        // is large (>45) and no open bin could host it after this item, a
        // fresh bin with enough room for both is strongly preferred.
        if next_item_size > 45 && fitting_bins_count >= 1 {
            let open_after = bin_residual.saturating_sub(item_size);
            let fresh_after = bin_capacity.saturating_sub(item_size);
            if open_after < next_item_size && fresh_after >= next_item_size {
                score -= 11.0;
            }
        }
        // MUTATION (gen 11): fresh-bin waste-parity guard — compare the fresh
        // bin's post-two-item leftover against the best open-bin waste; open
        // fresh only when its leftover is strictly more reusable than what
        // reusing an open bin would leave behind.
        if fitting_bins_count >= 1 && next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            let open_waste = bin_residual.saturating_sub(item_size);
            if fresh_left >= next_item_size && open_waste >= 20 {
                score -= 4.0 + 0.1 * ((open_waste - 20) as f64).min(25.0);
            } else if fresh_left > 0 && fresh_left < 8 && open_waste <= 10 {
                score += 5.0;
            }
        }
        // MUTATION (gen 12): fresh-bin residual-regime gate — in a tight global
        // regime (low mean residual), fresh bins should only open when they
        // close within two items or leave a dense-band leftover; otherwise
        // they inflate the bin count. In a loose regime, keep existing bias.
        if progress > 0.3 && next_item_size > 0 {
            let tightness = (1.0 - (mean_residual / cap_f).min(1.0)).max(0.0);
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if tightness > 0.6 && leftover > 50 {
                score += 8.0 * (tightness - 0.6) * 10.0;
            } else if tightness > 0.6 && leftover >= 25 && leftover <= 50 {
                score -= 5.0 * (tightness - 0.6) * 10.0;
            }
        }
        // MUTATION (gen 13): fresh-bin next-item-strand parity — when the next
        // item is medium-large and reusing an open bin would strand it while
        // a fresh bin could host both, bias toward opening fresh; but if the
        // next item is small enough to be absorbed by typical residuals,
        // keep the fresh-bin cost high to avoid inflation.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let open_after = bin_residual.saturating_sub(item_size);
            let fresh_after = bin_capacity.saturating_sub(item_size);
            if open_after < next_item_size && fresh_after >= next_item_size {
                let mid_next = next_item_size >= 25 && next_item_size <= 70;
                if mid_next {
                    score -= 6.0 + 4.0 * (1.0 - progress);
                } else if next_item_size < 25 {
                    score += 4.0;
                }
            }
        }
        // MUTATION (gen 13): fresh-bin mean-residual bar — a fresh bin must
        // beat the global average dead-space expectation; if its two-item
        // leftover exceeds the current mean residual by a wide margin late
        // in the stream, charge it proportionally.
        if progress > 0.45 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size) as f64;
            let excess = leftover - mean_residual.max(0.0);
            if excess > 15.0 {
                score += 0.08 * (excess - 15.0).min(40.0);
            }
        }
    } else {
        // MUTATION (gen 13): open-bin next-item strand mirror — when this
        // placement strands the next item but another placement would not
        // (many fitting bins imply alternatives exist), charge the stranding
        // harder; when this bin is the only host, forgive the stranding.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let alternatives = (fitting_bins_count as f64).max(1.0);
            score += (3.0 / alternatives.sqrt()) * (1.0 - 0.3 * progress);
        }
        // MUTATION (gen 13): dead-space curvature refinement — replace part of
        // the linear waste cost with a steeper convex term for residuals that
        // can host the next item but leave a tail larger than the next item
        // itself (double-stranding risk two steps ahead).
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail > next_item_size {
                score += 0.05 * ((tail - next_item_size) as f64).min(50.0) * (0.5 + 0.5 * progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap_f = bin_capacity as f64;
    let resid_f = bin_residual as f64;

    // Perfect fill reward
    if post_residual == 0 {
        score -= 65.0;
    }

    // Near-exact capacity match: residual just above item size
    let slack = bin_residual as i64 - item_size as i64;
    if slack >= 0 && slack <= 4 {
        score -= 20.0;
    }

    // --- 2-step lookahead core ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0 + 22.0 * (1.0 - progress);
        } else if post_residual > next_item_size {
            let slack_after_next = post_residual - next_item_size;
            score -= 25.0 - (slack_after_next as f64).min(40.0) * 0.3;
            if slack_after_next > 40 {
                score += (slack_after_next as f64 - 40.0) * 0.2;
            }
        } else {
            let shortfall = (next_item_size - post_residual) as f64;
            score += shortfall * 0.85;
            let half_next = next_item_size / 2;
            if post_residual > 0 && post_residual < half_next {
                score += 14.0;
            }
        }
    } else {
        score -= 10.0;
    }

    // Dead-space penalty: graded, fragmentation-aware waste pressure
    if post_residual > 0 {
        let waste_ratio = post_residual as f64 / cap_f;
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        let severity = 1.4 - 0.8 * tightness;
        if post_residual < next_item_size && next_item_size > 0 {
            let unusability = 1.0 - (post_residual as f64 / next_item_size as f64);
            score += 16.0 * unusability * (1.0 - 0.5 * progress) * severity;
            if post_residual < 10 {
                score += 9.0 * severity * (1.0 - 0.4 * progress);
            }
        } else if waste_ratio < 0.05 {
            score += 7.0 * (1.0 - progress) * severity;
        } else if waste_ratio < 0.10 && post_residual < 40 {
            score += 3.0 * (1.0 - progress) * severity;
        }
    }

    // Mean-residual coupling: fill tight bins, save roomy bins for big items
    if resid_f > mean_residual + 20.0 && item_size < 30 {
        if next_item_size == 0 || post_residual < next_item_size {
            score += 10.0;
        }
    } else if resid_f < mean_residual - 20.0 {
        score -= 8.0;
    }

    // Last-chance bonus: only bin that fits -> use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
        if post_residual >= 10 {
            score -= 10.0;
        }
    }

    // Consolidation pressure: prefer bins with larger residual when many bins open
    if open_bins_count > 8 {
        score += (resid_f / cap_f) * 6.0;
    }
    score -= (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Fragmentation-aware tiebreak: reward residuals likely reusable
    if post_residual >= 25 {
        score -= 4.0;
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 15 {
            score -= 6.0;
        }
    }

    // Triple-fit chain: scaled by remainder quality
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 20 {
            let sweet = if after_next <= 60 { 3.0 } else { 0.0 };
            score -= 5.0 + 5.0 * (1.0 - progress) + sweet;
        }
    }

    // Waste-ratio gradient: continuous pressure proportional to dead-space fraction
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 6.0 * (post_residual as f64 / cap_f) * 10.0;
    }

    // Dead-space anticipation weighted by scarcity
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let strandedness = 1.0 - (post_residual as f64 / next_item_size as f64);
        let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0);
        score += 9.0 * strandedness * scarcity;
    }

    // Residual-quality gradient — reusable band 20..=60
    if post_residual >= 20 && post_residual <= 60 {
        score -= 3.0 + 4.0 * (1.0 - progress);
    }

    // Avoid exact-dead residuals 1..=5
    if post_residual >= 1 && post_residual <= 5 {
        score += 5.0;
    }

    // Harmonic-anticipation — reward residuals that pair with the next item
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap > 0 && gap <= 8 {
            score -= 4.0 + 3.0 * (1.0 - progress);
        }
    }

    // Item-residual coupling — prefer bins whose residual is a tight multiple
    if item_size > 0 && bin_residual % item_size == 0 && bin_residual != bin_capacity {
        score -= 5.0;
        if post_residual == 0 {
            score -= 4.0;
        }
    }

    // Exact-fill lookahead with early-stream bonus
    if next_item_size > 0 && post_residual == next_item_size && progress < 0.4 {
        score -= 6.0;
    }

    // Two-item lookahead chain — absorb BOTH current and next item with reusable remainder
    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let chain_left = bin_residual - item_size - next_item_size;
        if chain_left >= 15 && chain_left <= 55 {
            score -= 7.0 + 5.0 * (1.0 - progress);
        }
    }

    // Waste-shape gradient — graded penalty on post-fit dead space
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap > 8 && gap <= 20 {
            score += 1.5;
        } else if gap > 20 && gap <= 35 {
            score += 3.5;
        }
    }

    // Scarcity-weighted last-fit — tight fits under scarcity are decisive
    if fitting_bins_count <= 2 && bin_residual != bin_capacity && post_residual <= 12 {
        score -= 6.0 + 4.0 * (1.0 - progress);
    }

    // Consolidation gradient — many open bins: prefer tightest residual bins
    if open_bins_count > 12 && bin_residual != bin_capacity {
        score += 8.0 * (1.0 - resid_f / cap_f);
    }

    // Dead-space slope pressure
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unus = 1.0 - (post_residual as f64 / next_item_size as f64);
        score += 4.5 * unus * (1.0 - 0.3 * progress);
    }

    // Residual entropy guard — awkward 61..=99 band is hard to reuse
    if post_residual > 60 && post_residual < 100 {
        score += 2.5 + 2.0 * (1.0 - progress);
    }

    // Scarcity-weighted exact chain
    if fitting_bins_count <= 2 && next_item_size > 0 && post_residual == next_item_size {
        score -= 8.0;
    }

    // Continuous tightness gradient — smooth penalty on dead space, weighted by global tightness
    if post_residual > 0 && bin_residual != bin_capacity {
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        score += 0.12 * (post_residual as f64) * (0.6 + 0.8 * tightness);
    }

    // Chain-closure bonus — deepen reward for near-emptying bins
    if post_residual > 0 && post_residual <= 20 && bin_residual != bin_capacity {
        score -= 5.0 * (1.0 - post_residual as f64 / 20.0) * (1.0 - 0.4 * progress);
    }

    // Open-bin load balancing guard
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && open_bins_count > 10 {
        score += 1.5 * ((open_bins_count - 10) as f64).min(8.0) * 0.5;
    }

    // Waste-floor refinement — convex (quadratic) waste cost
    if post_residual > 0 && bin_residual != bin_capacity {
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        let pr = post_residual as f64;
        score += (0.09 * pr + 0.0022 * pr * pr) * (0.6 + 0.8 * tightness);
    }

    // Post-fit chainability bonus
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let after_next = post_residual - next_item_size;
        if after_next >= 10 && after_next <= 45 {
            score -= 4.0 * (1.0 - after_next as f64 / 45.0) * (1.0 - 0.5 * progress);
        }
    }

    // Residual-mismatch guard — near-miss stranding penalty
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 6.0 {
            score += 10.0 * (1.0 - miss / 6.0) * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // MUTATION (gen 9): residual-harmony gradient — sharpen the reusable-band
    // reward around the empirically dense 30..=55 zone, weighted centrally.
    if post_residual >= 30 && post_residual <= 55 && bin_residual != bin_capacity {
        let d = ((post_residual as f64 - 42.5).abs() / 12.5).min(1.0);
        score -= 5.0 * (1.0 - d) * (0.6 + 0.4 * (1.0 - progress));
    }

    // MUTATION (gen 9): scarcity-damped adaptive waste cost — dead space is
    // forgivable when few bins fit, punished harder when many compete.
    if post_residual > 0 && bin_residual != bin_capacity {
        let scarcity_damp = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
        let pr = post_residual as f64;
        score += (0.05 * pr + 0.0018 * pr * pr) * scarcity_damp;
    }

    // MUTATION (gen 9): mid-band stranding penalty — residual in 13..=29 that
    // cannot host the next item is graded as unusable proportional to miss size.
    if post_residual >= 13 && post_residual <= 29 && next_item_size > 0 && post_residual < next_item_size && bin_residual != bin_capacity {
        let unus = 1.0 - (post_residual as f64 / next_item_size as f64);
        score += 7.0 * unus * (0.7 + 0.5 * progress);
    }

    // MUTATION (gen 10): dead-space ceiling guard — residuals that can host the
    // next item but leave an awkward tail (just above the reusable band) get a
    // graded penalty; residuals whose tail is exactly reusable get extra reward.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let tail = post_residual - next_item_size;
        if tail > 55 && tail < 100 {
            score += 3.0 * (1.0 - (tail as f64 - 55.0) / 45.0) * (0.5 + 0.5 * (1.0 - progress));
        } else if tail >= 60 {
            score += 2.0;
        }
    }

    // MUTATION (gen 10): exact two-item closure — reward bins where current +
    // next item close exactly or leave <=3 slack, scarcity-amplified.
    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let chain_left = bin_residual - item_size - next_item_size;
        if chain_left <= 3 {
            score -= 10.0 + 6.0 * (1.0 - progress) + 3.0 / (fitting_bins_count as f64).max(1.0);
        }
    }

    // MUTATION (gen 10): item-size-aware waste gradient — large items tolerate
    // generous residual hosts, small items seek the tightest fit.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let size_factor = (item_size as f64 / 100.0).powf(1.5);
        score += pr * 0.045 * (1.0 - size_factor) * (1.0 - 0.3 * progress);
    }

    // MUTATION (gen 10): residual-momentum coupling — in a globally tight
    // regime, tighten the 20..=45 reusable-band reward.
    if post_residual >= 20 && post_residual <= 45 && bin_residual != bin_capacity {
        let tightness = (1.0 - (mean_residual / cap_f).min(1.0)).max(0.0);
        score -= 3.5 * tightness * (0.5 + 0.5 * (1.0 - progress));
    }

    // MUTATION (gen 11): next-item-fit anticipation — when the next item is
    // large and would be stranded by this placement, penalize proportionally.
    if next_item_size > 35 && post_residual > 0 && post_residual < next_item_size && bin_residual != bin_capacity {
        let stranded = (next_item_size - post_residual) as f64 / next_item_size as f64;
        score += 5.0 * stranded * (1.0 - 0.4 * progress);
    }

    // MUTATION (gen 11): residual decay shaping — awkward 6..=12 band penalty
    // grows with progress.
    if post_residual >= 6 && post_residual <= 12 && bin_residual != bin_capacity {
        score += 2.5 + 3.0 * progress;
    }

    // MUTATION (gen 11): pair-closure lookahead — reward bins whose post-fit
    // residual can be emptied within two more small placements.
    if post_residual > 0 && post_residual <= 20 && bin_residual != bin_capacity {
        score -= 3.0 * (1.0 - post_residual as f64 / 20.0) * (0.5 + 0.5 * progress);
    }

    // MUTATION (gen 12): dead-space absorption gradient — crowd-aware grading.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let crowd = ((open_bins_count as f64 - 6.0).max(0.0) / 10.0).min(1.0);
        if pr <= 18.0 {
            score -= 2.0 * (1.0 - pr / 18.0) * crowd;
        } else if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0 * crowd * (1.0 - progress);
        }
    }

    // MUTATION (gen 12): three-step chain bonus — post-fit residual can absorb
    // the next item AND leave a dense reusable 25..=50 tail.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let tail = post_residual - next_item_size;
        if tail >= 25 && tail <= 50 {
            score -= 4.5 * (1.0 - (tail as f64 - 25.0).abs() / 25.0) * (0.6 + 0.4 * (1.0 - progress));
        }
    }

    // MUTATION (gen 12): tightness-scaled exact-fill escalation.
    if post_residual == 0 {
        let tightness = (1.0 - (mean_residual / cap_f).min(1.0)).max(0.0);
        score -= 4.0 * tightness;
    } else if slack >= 0 && slack <= 2 {
        let tightness = (1.0 - (mean_residual / cap_f).min(1.0)).max(0.0);
        score -= 2.5 * tightness * (1.0 - 0.5 * progress);
    }

    // MUTATION (gen 14): dense-band item-coupled sharpening — the reusable-band
    // reward is strongest when the post-fit residual sits near the empirical
    // mode AND the next item can chain into it, scaled by open-bin competition.
    if post_residual >= 28 && post_residual <= 48 && next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let d = ((post_residual as f64 - 38.0).abs() / 10.0).min(1.0);
        let crowd = 1.0 + 0.5 * ((open_bins_count as f64 - 8.0).max(0.0) / 12.0).min(1.0);
        score -= 3.0 * (1.0 - d) * crowd * (0.5 + 0.5 * (1.0 - progress));
    }

    // MUTATION (gen 14): exact-tail closure gradient — reward placements whose
    // post-fit residual minus next item leaves a tail that is itself near a
    // plausible small-item size (tail in 1..=12), i.e. a two-step emptying path.
    if next_item_size > 0 && post_residual > next_item_size && bin_residual != bin_capacity {
        let tail = post_residual - next_item_size;
        if tail >= 1 && tail <= 12 {
            score -= 3.5 * (1.0 - tail as f64 / 12.0) * (1.0 - 0.4 * progress);
        }
    }

    // MUTATION (gen 14): waste-curvature refinement — add a cubic term so
    // large dead spaces are charged super-linearly, while tiny dead spaces
    // (<= 6) are forgiven since small items can absorb them.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        if pr <= 6.0 {
            score -= 1.5 * (1.0 - pr / 6.0);
        } else {
            score += 0.00004 * pr * pr * pr;
        }
    }

    if bin_residual == bin_capacity {
        score = 55.0 - 15.0 * progress;
        if next_item_size > 0 && item_size + next_item_size >= bin_capacity {
            score -= 45.0;
        }
        if item_size as f64 > 0.6 * cap_f {
            score -= 30.0;
        }
        if progress > 0.8 {
            score += 10.0;
        }
        if fitting_bins_count > 2 {
            score += 20.0;
        }
        if fitting_bins_count == 1 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover >= next_item_size {
                score -= 12.0;
            }
        }
        if next_item_size > 0 && item_size + next_item_size < bin_capacity {
            let leftover = bin_capacity - item_size - next_item_size;
            if leftover < 10 {
                score -= 8.0;
            } else if leftover < 25 {
                score -= 3.0;
            }
            if leftover >= 25 && leftover <= 60 {
                score -= 6.0;
            } else if leftover >= 1 && leftover <= 5 {
                score += 6.0;
            }
        }
        if open_bins_count < 4 && progress < 0.3 {
            score -= 12.0;
        }
        if next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover >= next_item_size {
                score -= 10.0;
            }
        }
        if item_size < 15 && progress > 0.5 && fitting_bins_count >= 1 {
            score += 15.0;
        }
        if fitting_bins_count >= 1 && item_size <= bin_residual {
            let best_case_waste = bin_residual - item_size;
            if best_case_waste <= 5 {
                score += 25.0;
            } else if best_case_waste <= 15 {
                score += 8.0;
            }
        }
        if progress > 0.6 {
            score += 7.5 * (progress - 0.6) * 25.0;
        }
        if open_bins_count > 10 && progress > 0.35 && progress < 0.7 {
            let roomy = (mean_residual / cap_f).min(1.0);
            score += 6.0 * roomy;
        }
        if item_size > 60 && next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 8.0;
        }
        if next_item_size > 0 && item_size + next_item_size < bin_capacity {
            let leftover = bin_capacity - item_size - next_item_size;
            if leftover >= next_item_size {
                score -= 6.0;
            }
        }
        if next_item_size > 0 && fitting_bins_count >= 2 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover > 0 && leftover < 12 {
                score += 9.0;
            }
        }
        if fitting_bins_count >= 1 && item_size <= bin_residual {
            let open_waste = bin_residual - item_size;
            if open_waste > 15 && open_waste <= 35 {
                let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
                if next_item_size > 0 && fresh_left >= next_item_size {
                    score -= 4.0;
                } else {
                    score += 5.0;
                }
            }
        }
        // Fresh-bin convex-waste coupling
        if fitting_bins_count >= 1 && item_size <= bin_residual {
            let open_waste = bin_residual - item_size;
            if open_waste > 35 {
                score -= 3.0 + 0.05 * ((open_waste - 35) as f64).min(30.0);
            }
        }
        // Fresh-bin near-miss guard
        if next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size);
            if leftover < next_item_size {
                let miss = (next_item_size - leftover) as f64;
                if miss <= 8.0 {
                    score += 12.0 * (1.0 - miss / 8.0);
                }
            }
        }
        // Fresh-bin waste-quadratic mirror
        if next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover > 25 {
                score += 0.05 * ((leftover - 25) as f64).min(40.0);
            }
        }
        // MUTATION (gen 9): fresh-bin scarcity coupling.
        if fitting_bins_count == 1 && next_item_size > 0 {
            let open_waste = bin_residual.saturating_sub(item_size);
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if open_waste >= 13 && open_waste <= 29 && fresh_left >= next_item_size {
                score -= 9.0;
            }
        }
        // MUTATION (gen 9): fresh-bin late-stream waste floor.
        if progress > 0.55 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover < 20 {
                score += 6.0 * (progress - 0.55) * 20.0;
            }
        }
        // MUTATION (gen 10): fresh-bin exact-closure preference.
        if progress > 0.25 && progress < 0.85 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover <= 4 {
                if fitting_bins_count >= 1 && bin_residual.saturating_sub(item_size) > 12 {
                    score -= 14.0;
                }
            } else if leftover <= 12 && fitting_bins_count >= 1 {
                let open_waste = bin_residual.saturating_sub(item_size);
                if open_waste > leftover + 8 {
                    score -= 5.0;
                }
            }
        }
        // MUTATION (gen 10): fresh-bin large-item reserve.
        if next_item_size > 45 && fitting_bins_count >= 1 {
            let open_after = bin_residual.saturating_sub(item_size);
            let fresh_after = bin_capacity.saturating_sub(item_size);
            if open_after < next_item_size && fresh_after >= next_item_size {
                score -= 11.0;
            }
        }
        // MUTATION (gen 11): fresh-bin waste-parity guard.
        if fitting_bins_count >= 1 && next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            let open_waste = bin_residual.saturating_sub(item_size);
            if fresh_left >= next_item_size && open_waste >= 20 {
                score -= 4.0 + 0.1 * ((open_waste - 20) as f64).min(25.0);
            } else if fresh_left > 0 && fresh_left < 8 && open_waste <= 10 {
                score += 5.0;
            }
        }
        // MUTATION (gen 12): fresh-bin residual-regime gate.
        if progress > 0.3 && next_item_size > 0 {
            let tightness = (1.0 - (mean_residual / cap_f).min(1.0)).max(0.0);
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if tightness > 0.6 && leftover > 50 {
                score += 8.0 * (tightness - 0.6) * 10.0;
            } else if tightness > 0.6 && leftover >= 25 && leftover <= 50 {
                score -= 5.0 * (tightness - 0.6) * 10.0;
            }
        }
        // MUTATION (gen 13): fresh-bin next-item-strand parity.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let open_after = bin_residual.saturating_sub(item_size);
            let fresh_after = bin_capacity.saturating_sub(item_size);
            if open_after < next_item_size && fresh_after >= next_item_size {
                let mid_next = next_item_size >= 25 && next_item_size <= 70;
                if mid_next {
                    score -= 6.0 + 4.0 * (1.0 - progress);
                } else if next_item_size < 25 {
                    score += 4.0;
                }
            }
        }
        // MUTATION (gen 13): fresh-bin mean-residual bar.
        if progress > 0.45 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size) as f64;
            let excess = leftover - mean_residual.max(0.0);
            if excess > 15.0 {
                score += 0.08 * (excess - 15.0).min(40.0);
            }
        }
        // MUTATION (gen 14): fresh-bin dense-band closure requirement — late in
        // the stream, a fresh bin must leave a leftover in the empirically
        // dense 20..=45 zone (chainable within two items) or pay a graded
        // penalty; this suppresses fresh-bin inflation that strands mid-band
        // dead space.
        if progress > 0.4 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if !(leftover >= 20 && leftover <= 45) && leftover > 0 {
                let dist = if leftover < 20 { 20 - leftover } else { leftover - 45 };
                score += 0.35 * (dist as f64).min(40.0) * (0.4 + 0.6 * (progress - 0.4));
            }
        }
    } else {
        // MUTATION (gen 13): open-bin next-item strand mirror.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let alternatives = (fitting_bins_count as f64).max(1.0);
            score += (3.0 / alternatives.sqrt()) * (1.0 - 0.3 * progress);
        }
        // MUTATION (gen 13): dead-space curvature refinement.
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail > next_item_size {
                score += 0.05 * ((tail - next_item_size) as f64).min(50.0) * (0.5 + 0.5 * progress);
            }
        }
        // MUTATION (gen 14): residual-multiple chain reward — when the post-fit
        // residual is an exact multiple of a small plausible item size, it is
        // highly reusable; reward it progressively with open-bin competition.
        if post_residual >= 10 && bin_residual != bin_capacity {
            let reusable = [10u32, 12, 15, 20, 25, 30, 40, 50]
                .iter()
                .any(|&m| post_residual % m == 0);
            if reusable {
                let crowd = 1.0 + 0.4 * ((open_bins_count as f64 - 8.0).max(0.0) / 12.0).min(1.0);
                score -= 2.5 * crowd;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap_f = bin_capacity as f64;
    let resid_f = bin_residual as f64;

    // Perfect fill reward
    if post_residual == 0 {
        score -= 65.0;
    }

    // Near-exact capacity match: residual just above item size
    let slack = bin_residual as i64 - item_size as i64;
    if slack >= 0 && slack <= 4 {
        score -= 20.0;
    }

    // --- 2-step lookahead core ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0 + 22.0 * (1.0 - progress);
        } else if post_residual > next_item_size {
            let slack_after_next = post_residual - next_item_size;
            score -= 25.0 - (slack_after_next as f64).min(40.0) * 0.3;
            if slack_after_next > 40 {
                score += (slack_after_next as f64 - 40.0) * 0.2;
            }
        } else {
            let shortfall = (next_item_size - post_residual) as f64;
            score += shortfall * 0.85;
            let half_next = next_item_size / 2;
            if post_residual > 0 && post_residual < half_next {
                score += 14.0;
            }
        }
    } else {
        score -= 10.0;
    }

    // Dead-space penalty: graded, fragmentation-aware waste pressure
    if post_residual > 0 {
        let waste_ratio = post_residual as f64 / cap_f;
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        let severity = 1.4 - 0.8 * tightness;
        if post_residual < next_item_size && next_item_size > 0 {
            let unusability = 1.0 - (post_residual as f64 / next_item_size as f64);
            score += 16.0 * unusability * (1.0 - 0.5 * progress) * severity;
            if post_residual < 10 {
                score += 9.0 * severity * (1.0 - 0.4 * progress);
            }
        } else if waste_ratio < 0.05 {
            score += 7.0 * (1.0 - progress) * severity;
        } else if waste_ratio < 0.10 && post_residual < 40 {
            score += 3.0 * (1.0 - progress) * severity;
        }
    }

    // Mean-residual coupling: fill tight bins, save roomy bins for big items
    if resid_f > mean_residual + 20.0 && item_size < 30 {
        if next_item_size == 0 || post_residual < next_item_size {
            score += 10.0;
        }
    } else if resid_f < mean_residual - 20.0 {
        score -= 8.0;
    }

    // Last-chance bonus: only bin that fits -> use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
        if post_residual >= 10 {
            score -= 10.0;
        }
    }

    // Consolidation pressure: prefer bins with larger residual when many bins open
    if open_bins_count > 8 {
        score += (resid_f / cap_f) * 6.0;
    }
    score -= (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Fragmentation-aware tiebreak: reward residuals likely reusable
    if post_residual >= 25 {
        score -= 4.0;
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 15 {
            score -= 6.0;
        }
    }

    // Triple-fit chain: scaled by remainder quality
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 20 {
            let sweet = if after_next <= 60 { 3.0 } else { 0.0 };
            score -= 5.0 + 5.0 * (1.0 - progress) + sweet;
        }
    }

    // Waste-ratio gradient: continuous pressure proportional to dead-space fraction
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 6.0 * (post_residual as f64 / cap_f) * 10.0;
    }

    // Dead-space anticipation weighted by scarcity
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let strandedness = 1.0 - (post_residual as f64 / next_item_size as f64);
        let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0);
        score += 9.0 * strandedness * scarcity;
    }

    // Residual-quality gradient — reusable band 20..=60
    if post_residual >= 20 && post_residual <= 60 {
        score -= 3.0 + 4.0 * (1.0 - progress);
    }

    // Avoid exact-dead residuals 1..=5
    if post_residual >= 1 && post_residual <= 5 {
        score += 5.0;
    }

    // Harmonic-anticipation — reward residuals that pair with the next item
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap > 0 && gap <= 8 {
            score -= 4.0 + 3.0 * (1.0 - progress);
        }
    }

    // Item-residual coupling — prefer bins whose residual is a tight multiple
    if item_size > 0 && bin_residual % item_size == 0 && bin_residual != bin_capacity {
        score -= 5.0;
        if post_residual == 0 {
            score -= 4.0;
        }
    }

    // Exact-fill lookahead with early-stream bonus
    if next_item_size > 0 && post_residual == next_item_size && progress < 0.4 {
        score -= 6.0;
    }

    // Two-item lookahead chain — absorb BOTH current and next item with reusable remainder
    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let chain_left = bin_residual - item_size - next_item_size;
        if chain_left >= 15 && chain_left <= 55 {
            score -= 7.0 + 5.0 * (1.0 - progress);
        }
    }

    // Waste-shape gradient — graded penalty on post-fit dead space
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap > 8 && gap <= 20 {
            score += 1.5;
        } else if gap > 20 && gap <= 35 {
            score += 3.5;
        }
    }

    // Scarcity-weighted last-fit — tight fits under scarcity are decisive
    if fitting_bins_count <= 2 && bin_residual != bin_capacity && post_residual <= 12 {
        score -= 6.0 + 4.0 * (1.0 - progress);
    }

    // Consolidation gradient — many open bins: prefer tightest residual bins
    if open_bins_count > 12 && bin_residual != bin_capacity {
        score += 8.0 * (1.0 - resid_f / cap_f);
    }

    // Dead-space slope pressure
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unus = 1.0 - (post_residual as f64 / next_item_size as f64);
        score += 4.5 * unus * (1.0 - 0.3 * progress);
    }

    // Residual entropy guard — awkward 61..=99 band is hard to reuse
    if post_residual > 60 && post_residual < 100 {
        score += 2.5 + 2.0 * (1.0 - progress);
    }

    // Scarcity-weighted exact chain
    if fitting_bins_count <= 2 && next_item_size > 0 && post_residual == next_item_size {
        score -= 8.0;
    }

    // Continuous tightness gradient — smooth penalty on dead space, weighted by global tightness
    if post_residual > 0 && bin_residual != bin_capacity {
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        score += 0.12 * (post_residual as f64) * (0.6 + 0.8 * tightness);
    }

    // Chain-closure bonus — deepen reward for near-emptying bins
    if post_residual > 0 && post_residual <= 20 && bin_residual != bin_capacity {
        score -= 5.0 * (1.0 - post_residual as f64 / 20.0) * (1.0 - 0.4 * progress);
    }

    // Open-bin load balancing guard
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && open_bins_count > 10 {
        score += 1.5 * ((open_bins_count - 10) as f64).min(8.0) * 0.5;
    }

    // Waste-floor refinement — convex (quadratic) waste cost
    if post_residual > 0 && bin_residual != bin_capacity {
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        let pr = post_residual as f64;
        score += (0.09 * pr + 0.0022 * pr * pr) * (0.6 + 0.8 * tightness);
    }

    // Post-fit chainability bonus
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let after_next = post_residual - next_item_size;
        if after_next >= 10 && after_next <= 45 {
            score -= 4.0 * (1.0 - after_next as f64 / 45.0) * (1.0 - 0.5 * progress);
        }
    }

    // Residual-mismatch guard — near-miss stranding penalty
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 6.0 {
            score += 10.0 * (1.0 - miss / 6.0) * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // MUTATION (gen 9): residual-harmony gradient
    if post_residual >= 30 && post_residual <= 55 && bin_residual != bin_capacity {
        let d = ((post_residual as f64 - 42.5).abs() / 12.5).min(1.0);
        score -= 5.0 * (1.0 - d) * (0.6 + 0.4 * (1.0 - progress));
    }

    // MUTATION (gen 9): scarcity-damped adaptive waste cost
    if post_residual > 0 && bin_residual != bin_capacity {
        let scarcity_damp = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
        let pr = post_residual as f64;
        score += (0.05 * pr + 0.0018 * pr * pr) * scarcity_damp;
    }

    // MUTATION (gen 9): mid-band stranding penalty
    if post_residual >= 13 && post_residual <= 29 && next_item_size > 0 && post_residual < next_item_size && bin_residual != bin_capacity {
        let unus = 1.0 - (post_residual as f64 / next_item_size as f64);
        score += 7.0 * unus * (0.7 + 0.5 * progress);
    }

    // MUTATION (gen 10): dead-space ceiling guard
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let tail = post_residual - next_item_size;
        if tail > 55 && tail < 100 {
            score += 3.0 * (1.0 - (tail as f64 - 55.0) / 45.0) * (0.5 + 0.5 * (1.0 - progress));
        } else if tail >= 60 {
            score += 2.0;
        }
    }

    // MUTATION (gen 10): exact two-item closure
    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let chain_left = bin_residual - item_size - next_item_size;
        if chain_left <= 3 {
            score -= 10.0 + 6.0 * (1.0 - progress) + 3.0 / (fitting_bins_count as f64).max(1.0);
        }
    }

    // MUTATION (gen 10): item-size-aware waste gradient
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let size_factor = (item_size as f64 / 100.0).powf(1.5);
        score += pr * 0.045 * (1.0 - size_factor) * (1.0 - 0.3 * progress);
    }

    // MUTATION (gen 10): residual-momentum coupling
    if post_residual >= 20 && post_residual <= 45 && bin_residual != bin_capacity {
        let tightness = (1.0 - (mean_residual / cap_f).min(1.0)).max(0.0);
        score -= 3.5 * tightness * (0.5 + 0.5 * (1.0 - progress));
    }

    // MUTATION (gen 11): next-item-fit anticipation
    if next_item_size > 35 && post_residual > 0 && post_residual < next_item_size && bin_residual != bin_capacity {
        let stranded = (next_item_size - post_residual) as f64 / next_item_size as f64;
        score += 5.0 * stranded * (1.0 - 0.4 * progress);
    }

    // MUTATION (gen 11): residual decay shaping
    if post_residual >= 6 && post_residual <= 12 && bin_residual != bin_capacity {
        score += 2.5 + 3.0 * progress;
    }

    // MUTATION (gen 11): pair-closure lookahead
    if post_residual > 0 && post_residual <= 20 && bin_residual != bin_capacity {
        score -= 3.0 * (1.0 - post_residual as f64 / 20.0) * (0.5 + 0.5 * progress);
    }

    // MUTATION (gen 12): dead-space absorption gradient
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let crowd = ((open_bins_count as f64 - 6.0).max(0.0) / 10.0).min(1.0);
        if pr <= 18.0 {
            score -= 2.0 * (1.0 - pr / 18.0) * crowd;
        } else if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0 * crowd * (1.0 - progress);
        }
    }

    // MUTATION (gen 12): three-step chain bonus
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let tail = post_residual - next_item_size;
        if tail >= 25 && tail <= 50 {
            score -= 4.5 * (1.0 - (tail as f64 - 25.0).abs() / 25.0) * (0.6 + 0.4 * (1.0 - progress));
        }
    }

    // MUTATION (gen 12): tightness-scaled exact-fill escalation
    if post_residual == 0 {
        let tightness = (1.0 - (mean_residual / cap_f).min(1.0)).max(0.0);
        score -= 4.0 * tightness;
    } else if slack >= 0 && slack <= 2 {
        let tightness = (1.0 - (mean_residual / cap_f).min(1.0)).max(0.0);
        score -= 2.5 * tightness * (1.0 - 0.5 * progress);
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score = 55.0 - 15.0 * progress;
        if next_item_size > 0 && item_size + next_item_size >= bin_capacity {
            score -= 45.0;
        }
        if item_size as f64 > 0.6 * cap_f {
            score -= 30.0;
        }
        if progress > 0.8 {
            score += 10.0;
        }
        if fitting_bins_count > 2 {
            score += 20.0;
        }
        if fitting_bins_count == 1 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover >= next_item_size {
                score -= 12.0;
            }
        }
        if next_item_size > 0 && item_size + next_item_size < bin_capacity {
            let leftover = bin_capacity - item_size - next_item_size;
            if leftover < 10 {
                score -= 8.0;
            } else if leftover < 25 {
                score -= 3.0;
            }
            if leftover >= 25 && leftover <= 60 {
                score -= 6.0;
            } else if leftover >= 1 && leftover <= 5 {
                score += 6.0;
            }
        }
        if open_bins_count < 4 && progress < 0.3 {
            score -= 12.0;
        }
        if next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover >= next_item_size {
                score -= 10.0;
            }
        }
        if item_size < 15 && progress > 0.5 && fitting_bins_count >= 1 {
            score += 15.0;
        }
        if fitting_bins_count >= 1 && item_size <= bin_residual {
            let best_case_waste = bin_residual - item_size;
            if best_case_waste <= 5 {
                score += 25.0;
            } else if best_case_waste <= 15 {
                score += 8.0;
            }
        }
        if progress > 0.6 {
            score += 7.5 * (progress - 0.6) * 25.0;
        }
        if open_bins_count > 10 && progress > 0.35 && progress < 0.7 {
            let roomy = (mean_residual / cap_f).min(1.0);
            score += 6.0 * roomy;
        }
        if item_size > 60 && next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 8.0;
        }
        if next_item_size > 0 && item_size + next_item_size < bin_capacity {
            let leftover = bin_capacity - item_size - next_item_size;
            if leftover >= next_item_size {
                score -= 6.0;
            }
        }
        if next_item_size > 0 && fitting_bins_count >= 2 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover > 0 && leftover < 12 {
                score += 9.0;
            }
        }
        if fitting_bins_count >= 1 && item_size <= bin_residual {
            let open_waste = bin_residual - item_size;
            if open_waste > 15 && open_waste <= 35 {
                let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
                if next_item_size > 0 && fresh_left >= next_item_size {
                    score -= 4.0;
                } else {
                    score += 5.0;
                }
            }
        }
        // Fresh-bin convex-waste coupling
        if fitting_bins_count >= 1 && item_size <= bin_residual {
            let open_waste = bin_residual - item_size;
            if open_waste > 35 {
                score -= 3.0 + 0.05 * ((open_waste - 35) as f64).min(30.0);
            }
        }
        // Fresh-bin near-miss guard
        if next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size);
            if leftover < next_item_size {
                let miss = (next_item_size - leftover) as f64;
                if miss <= 8.0 {
                    score += 12.0 * (1.0 - miss / 8.0);
                }
            }
        }
        // Fresh-bin waste-quadratic mirror
        if next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover > 25 {
                score += 0.05 * ((leftover - 25) as f64).min(40.0);
            }
        }
        // MUTATION (gen 9): fresh-bin scarcity coupling
        if fitting_bins_count == 1 && next_item_size > 0 {
            let open_waste = bin_residual.saturating_sub(item_size);
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if open_waste >= 13 && open_waste <= 29 && fresh_left >= next_item_size {
                score -= 9.0;
            }
        }
        // MUTATION (gen 9): fresh-bin late-stream waste floor
        if progress > 0.55 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover < 20 {
                score += 6.0 * (progress - 0.55) * 20.0;
            }
        }
        // MUTATION (gen 10): fresh-bin exact-closure preference
        if progress > 0.25 && progress < 0.85 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover <= 4 {
                if fitting_bins_count >= 1 && bin_residual.saturating_sub(item_size) > 12 {
                    score -= 14.0;
                }
            } else if leftover <= 12 && fitting_bins_count >= 1 {
                let open_waste = bin_residual.saturating_sub(item_size);
                if open_waste > leftover + 8 {
                    score -= 5.0;
                }
            }
        }
        // MUTATION (gen 10): fresh-bin large-item reserve
        if next_item_size > 45 && fitting_bins_count >= 1 {
            let open_after = bin_residual.saturating_sub(item_size);
            let fresh_after = bin_capacity.saturating_sub(item_size);
            if open_after < next_item_size && fresh_after >= next_item_size {
                score -= 11.0;
            }
        }
        // MUTATION (gen 11): fresh-bin waste-parity guard
        if fitting_bins_count >= 1 && next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            let open_waste = bin_residual.saturating_sub(item_size);
            if fresh_left >= next_item_size && open_waste >= 20 {
                score -= 4.0 + 0.1 * ((open_waste - 20) as f64).min(25.0);
            } else if fresh_left > 0 && fresh_left < 8 && open_waste <= 10 {
                score += 5.0;
            }
        }
        // MUTATION (gen 12): fresh-bin residual-regime gate
        if progress > 0.3 && next_item_size > 0 {
            let tightness = (1.0 - (mean_residual / cap_f).min(1.0)).max(0.0);
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if tightness > 0.6 && leftover > 50 {
                score += 8.0 * (tightness - 0.6) * 10.0;
            } else if tightness > 0.6 && leftover >= 25 && leftover <= 50 {
                score -= 5.0 * (tightness - 0.6) * 10.0;
            }
        }
        // MUTATION (gen 13): fresh-bin next-item-strand parity
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let open_after = bin_residual.saturating_sub(item_size);
            let fresh_after = bin_capacity.saturating_sub(item_size);
            if open_after < next_item_size && fresh_after >= next_item_size {
                let mid_next = next_item_size >= 25 && next_item_size <= 70;
                if mid_next {
                    score -= 6.0 + 4.0 * (1.0 - progress);
                } else if next_item_size < 25 {
                    score += 4.0;
                }
            }
        }
        // MUTATION (gen 13): fresh-bin mean-residual bar
        if progress > 0.45 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size) as f64;
            let excess = leftover - mean_residual.max(0.0);
            if excess > 15.0 {
                score += 0.08 * (excess - 15.0).min(40.0);
            }
        }
    } else {
        // MUTATION (gen 13): open-bin next-item strand mirror
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let alternatives = (fitting_bins_count as f64).max(1.0);
            score += (3.0 / alternatives.sqrt()) * (1.0 - 0.3 * progress);
        }
        // MUTATION (gen 13): dead-space curvature refinement
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail > next_item_size {
                score += 0.05 * ((tail - next_item_size) as f64).min(50.0) * (0.5 + 0.5 * progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap_f = bin_capacity as f64;
    let resid_f = bin_residual as f64;

    // Perfect fill reward
    if post_residual == 0 {
        score -= 65.0;
    }

    // Near-exact capacity match: residual just above item size
    let slack = bin_residual as i64 - item_size as i64;
    if slack >= 0 && slack <= 4 {
        score -= 20.0;
    }

    // --- 2-step lookahead core ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0 + 22.0 * (1.0 - progress);
        } else if post_residual > next_item_size {
            let slack_after_next = post_residual - next_item_size;
            score -= 25.0 - (slack_after_next as f64).min(40.0) * 0.3;
            if slack_after_next > 40 {
                score += (slack_after_next as f64 - 40.0) * 0.2;
            }
        } else {
            let shortfall = (next_item_size - post_residual) as f64;
            score += shortfall * 0.85;
            let half_next = next_item_size / 2;
            if post_residual > 0 && post_residual < half_next {
                score += 14.0;
            }
        }
    } else {
        score -= 10.0;
    }

    // Dead-space penalty: graded, fragmentation-aware waste pressure
    if post_residual > 0 {
        let waste_ratio = post_residual as f64 / cap_f;
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        let severity = 1.4 - 0.8 * tightness;
        if post_residual < next_item_size && next_item_size > 0 {
            let unusability = 1.0 - (post_residual as f64 / next_item_size as f64);
            score += 16.0 * unusability * (1.0 - 0.5 * progress) * severity;
            if post_residual < 10 {
                score += 9.0 * severity * (1.0 - 0.4 * progress);
            }
        } else if waste_ratio < 0.05 {
            score += 7.0 * (1.0 - progress) * severity;
        } else if waste_ratio < 0.10 && post_residual < 40 {
            score += 3.0 * (1.0 - progress) * severity;
        }
    }

    // Mean-residual coupling: fill tight bins, save roomy bins for big items
    if resid_f > mean_residual + 20.0 && item_size < 30 {
        if next_item_size == 0 || post_residual < next_item_size {
            score += 10.0;
        }
    } else if resid_f < mean_residual - 20.0 {
        score -= 8.0;
    }

    // Last-chance bonus: only bin that fits -> use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
        if post_residual >= 10 {
            score -= 10.0;
        }
    }

    // Consolidation pressure: prefer bins with larger residual when many bins open
    if open_bins_count > 8 {
        score += (resid_f / cap_f) * 6.0;
    }
    score -= (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Fragmentation-aware tiebreak: reward residuals likely reusable
    if post_residual >= 25 {
        score -= 4.0;
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 15 {
            score -= 6.0;
        }
    }

    // Triple-fit chain: scaled by remainder quality
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 20 {
            let sweet = if after_next <= 60 { 3.0 } else { 0.0 };
            score -= 5.0 + 5.0 * (1.0 - progress) + sweet;
        }
    }

    // Waste-ratio gradient: continuous pressure proportional to dead-space fraction
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 6.0 * (post_residual as f64 / cap_f) * 10.0;
    }

    // Dead-space anticipation weighted by scarcity
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let strandedness = 1.0 - (post_residual as f64 / next_item_size as f64);
        let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0);
        score += 9.0 * strandedness * scarcity;
    }

    // Residual-quality gradient — reusable band 20..=60
    if post_residual >= 20 && post_residual <= 60 {
        score -= 3.0 + 4.0 * (1.0 - progress);
    }

    // Avoid exact-dead residuals 1..=5
    if post_residual >= 1 && post_residual <= 5 {
        score += 5.0;
    }

    // Harmonic-anticipation — reward residuals that pair with the next item
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap > 0 && gap <= 8 {
            score -= 4.0 + 3.0 * (1.0 - progress);
        }
    }

    // Item-residual coupling — prefer bins whose residual is a tight multiple
    if item_size > 0 && bin_residual % item_size == 0 && bin_residual != bin_capacity {
        score -= 5.0;
        if post_residual == 0 {
            score -= 4.0;
        }
    }

    // Exact-fill lookahead with early-stream bonus
    if next_item_size > 0 && post_residual == next_item_size && progress < 0.4 {
        score -= 6.0;
    }

    // Two-item lookahead chain — absorb BOTH current and next item with reusable remainder
    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let chain_left = bin_residual - item_size - next_item_size;
        if chain_left >= 15 && chain_left <= 55 {
            score -= 7.0 + 5.0 * (1.0 - progress);
        }
    }

    // Waste-shape gradient — graded penalty on post-fit dead space
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap > 8 && gap <= 20 {
            score += 1.5;
        } else if gap > 20 && gap <= 35 {
            score += 3.5;
        }
    }

    // Scarcity-weighted last-fit — tight fits under scarcity are decisive
    if fitting_bins_count <= 2 && bin_residual != bin_capacity && post_residual <= 12 {
        score -= 6.0 + 4.0 * (1.0 - progress);
    }

    // Consolidation gradient — many open bins: prefer tightest residual bins
    if open_bins_count > 12 && bin_residual != bin_capacity {
        score += 8.0 * (1.0 - resid_f / cap_f);
    }

    // Dead-space slope pressure
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unus = 1.0 - (post_residual as f64 / next_item_size as f64);
        score += 4.5 * unus * (1.0 - 0.3 * progress);
    }

    // Residual entropy guard — awkward 61..=99 band is hard to reuse
    if post_residual > 60 && post_residual < 100 {
        score += 2.5 + 2.0 * (1.0 - progress);
    }

    // Scarcity-weighted exact chain
    if fitting_bins_count <= 2 && next_item_size > 0 && post_residual == next_item_size {
        score -= 8.0;
    }

    // Continuous tightness gradient — smooth penalty on dead space, weighted by global tightness
    if post_residual > 0 && bin_residual != bin_capacity {
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        score += 0.12 * (post_residual as f64) * (0.6 + 0.8 * tightness);
    }

    // Chain-closure bonus — deepen reward for near-emptying bins
    if post_residual > 0 && post_residual <= 20 && bin_residual != bin_capacity {
        score -= 5.0 * (1.0 - post_residual as f64 / 20.0) * (1.0 - 0.4 * progress);
    }

    // Open-bin load balancing guard
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && open_bins_count > 10 {
        score += 1.5 * ((open_bins_count - 10) as f64).min(8.0) * 0.5;
    }

    // Waste-floor refinement — convex (quadratic) waste cost
    if post_residual > 0 && bin_residual != bin_capacity {
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        let pr = post_residual as f64;
        score += (0.09 * pr + 0.0022 * pr * pr) * (0.6 + 0.8 * tightness);
    }

    // Post-fit chainability bonus
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let after_next = post_residual - next_item_size;
        if after_next >= 10 && after_next <= 45 {
            score -= 4.0 * (1.0 - after_next as f64 / 45.0) * (1.0 - 0.5 * progress);
        }
    }

    // Residual-mismatch guard — near-miss stranding penalty
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 6.0 {
            score += 10.0 * (1.0 - miss / 6.0) * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // MUTATION (gen 9): residual-harmony gradient — sharpen the reusable-band
    // reward around the empirically dense 30..=55 zone, weighted centrally.
    if post_residual >= 30 && post_residual <= 55 && bin_residual != bin_capacity {
        let d = ((post_residual as f64 - 42.5).abs() / 12.5).min(1.0);
        score -= 5.0 * (1.0 - d) * (0.6 + 0.4 * (1.0 - progress));
    }

    // MUTATION (gen 9): scarcity-damped adaptive waste cost — dead space is
    // forgivable when few bins fit, punished harder when many compete.
    if post_residual > 0 && bin_residual != bin_capacity {
        let scarcity_damp = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
        let pr = post_residual as f64;
        score += (0.05 * pr + 0.0018 * pr * pr) * scarcity_damp;
    }

    // MUTATION (gen 9): mid-band stranding penalty — residual in 13..=29 that
    // cannot host the next item is graded as unusable proportional to miss size.
    if post_residual >= 13 && post_residual <= 29 && next_item_size > 0 && post_residual < next_item_size && bin_residual != bin_capacity {
        let unus = 1.0 - (post_residual as f64 / next_item_size as f64);
        score += 7.0 * unus * (0.7 + 0.5 * progress);
    }

    // MUTATION (gen 10): dead-space ceiling guard — residuals that can host the
    // next item but leave an awkward tail (just above the reusable band) get a
    // graded penalty; residuals whose tail is exactly reusable get extra reward.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let tail = post_residual - next_item_size;
        if tail > 55 && tail < 100 {
            score += 3.0 * (1.0 - (tail as f64 - 55.0) / 45.0) * (0.5 + 0.5 * (1.0 - progress));
        } else if tail >= 60 {
            score += 2.0;
        }
    }

    // MUTATION (gen 10): exact two-item closure — reward bins where current +
    // next item leave exactly zero or a tiny (<=3) remainder, scaled by how
    // many competing bins exist (scarcity amplifies the payoff).
    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let chain_left = bin_residual - item_size - next_item_size;
        if chain_left <= 3 {
            score -= 10.0 + 6.0 * (1.0 - progress) + 3.0 / (fitting_bins_count as f64).max(1.0);
        }
    }

    // MUTATION (gen 10): item-size-aware waste gradient — large items (>50)
    // should tolerate generous residual hosts, small items should seek the
    // tightest possible fit; graded penalty scaled by item size mismatch.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let size_factor = (item_size as f64 / 100.0).powf(1.5);
        score += pr * 0.045 * (1.0 - size_factor) * (1.0 - 0.3 * progress);
    }

    // MUTATION (gen 10): residual-momentum coupling — when mean residual is
    // low (globally tight packing), tighten the reusable-band reward so bins
    // landing in the 20..=45 band get an extra scarcity-weighted discount.
    if post_residual >= 20 && post_residual <= 45 && bin_residual != bin_capacity {
        let tightness = (1.0 - (mean_residual / cap_f).min(1.0)).max(0.0);
        score -= 3.5 * tightness * (0.5 + 0.5 * (1.0 - progress));
    }

    // MUTATION (gen 11): next-item-fit anticipation — when the next item is
    // large and would be stranded by this placement, penalize proportionally
    // to how likely the next item is (large items late in stream are rare).
    if next_item_size > 35 && post_residual > 0 && post_residual < next_item_size && bin_residual != bin_capacity {
        let stranded = (next_item_size - post_residual) as f64 / next_item_size as f64;
        score += 5.0 * stranded * (1.0 - 0.4 * progress);
    }

    // MUTATION (gen 11): residual decay shaping — residuals in the awkward
    // 6..=12 band are nearly unusable for typical item sizes; apply a graded
    // penalty that grows with progress (late stream = fewer chances to fix).
    if post_residual >= 6 && post_residual <= 12 && bin_residual != bin_capacity {
        score += 2.5 + 3.0 * progress;
    }

    // MUTATION (gen 11): pair-closure lookahead — reward bins whose post-fit
    // residual equals a plausible sum of two future small items (<= 20), which
    // effectively empties the bin within two more placements.
    if post_residual > 0 && post_residual <= 20 && bin_residual != bin_capacity {
        score -= 3.0 * (1.0 - post_residual as f64 / 20.0) * (0.5 + 0.5 * progress);
    }

    // MUTATION (gen 12): dead-space absorption gradient — when many bins are
    // open, small dead spaces (<= 18) can be absorbed by future small items,
    // so grade their cost down; but large dead spaces (> 30) that cannot host
    // the next item are charged harder as open-bin count grows.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let crowd = ((open_bins_count as f64 - 6.0).max(0.0) / 10.0).min(1.0);
        if pr <= 18.0 {
            score -= 2.0 * (1.0 - pr / 18.0) * crowd;
        } else if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0 * crowd * (1.0 - progress);
        }
    }

    // MUTATION (gen 12): three-step chain bonus — reward placements whose
    // post-fit residual can absorb the next item AND leave a remainder in the
    // dense reusable 25..=50 zone; this extends the two-item lookahead one
    // step further and directly targets residual dead-space reduction.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let tail = post_residual - next_item_size;
        if tail >= 25 && tail <= 50 {
            score -= 4.5 * (1.0 - (tail as f64 - 25.0).abs() / 25.0) * (0.6 + 0.4 * (1.0 - progress));
        }
    }

    // MUTATION (gen 12): tightness-scaled exact-fill escalation — when the
    // global mean residual is very low (near-perfect packing regime), exact
    // and near-exact fills become the dominant bin-saving mechanism; boost
    // their reward proportionally to how close the stream is to that regime.
    if post_residual == 0 {
        let tightness = (1.0 - (mean_residual / cap_f).min(1.0)).max(0.0);
        score -= 4.0 * tightness;
    } else if slack >= 0 && slack <= 2 {
        let tightness = (1.0 - (mean_residual / cap_f).min(1.0)).max(0.0);
        score -= 2.5 * tightness * (1.0 - 0.5 * progress);
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score = 55.0 - 15.0 * progress;
        if next_item_size > 0 && item_size + next_item_size >= bin_capacity {
            score -= 45.0;
        }
        if item_size as f64 > 0.6 * cap_f {
            score -= 30.0;
        }
        if progress > 0.8 {
            score += 10.0;
        }
        if fitting_bins_count > 2 {
            score += 20.0;
        }
        if fitting_bins_count == 1 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover >= next_item_size {
                score -= 12.0;
            }
        }
        if next_item_size > 0 && item_size + next_item_size < bin_capacity {
            let leftover = bin_capacity - item_size - next_item_size;
            if leftover < 10 {
                score -= 8.0;
            } else if leftover < 25 {
                score -= 3.0;
            }
            if leftover >= 25 && leftover <= 60 {
                score -= 6.0;
            } else if leftover >= 1 && leftover <= 5 {
                score += 6.0;
            }
        }
        if open_bins_count < 4 && progress < 0.3 {
            score -= 12.0;
        }
        if next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover >= next_item_size {
                score -= 10.0;
            }
        }
        if item_size < 15 && progress > 0.5 && fitting_bins_count >= 1 {
            score += 15.0;
        }
        if fitting_bins_count >= 1 && item_size <= bin_residual {
            let best_case_waste = bin_residual - item_size;
            if best_case_waste <= 5 {
                score += 25.0;
            } else if best_case_waste <= 15 {
                score += 8.0;
            }
        }
        if progress > 0.6 {
            score += 7.5 * (progress - 0.6) * 25.0;
        }
        if open_bins_count > 10 && progress > 0.35 && progress < 0.7 {
            let roomy = (mean_residual / cap_f).min(1.0);
            score += 6.0 * roomy;
        }
        if item_size > 60 && next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 8.0;
        }
        if next_item_size > 0 && item_size + next_item_size < bin_capacity {
            let leftover = bin_capacity - item_size - next_item_size;
            if leftover >= next_item_size {
                score -= 6.0;
            }
        }
        if next_item_size > 0 && fitting_bins_count >= 2 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover > 0 && leftover < 12 {
                score += 9.0;
            }
        }
        if fitting_bins_count >= 1 && item_size <= bin_residual {
            let open_waste = bin_residual - item_size;
            if open_waste > 15 && open_waste <= 35 {
                let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
                if next_item_size > 0 && fresh_left >= next_item_size {
                    score -= 4.0;
                } else {
                    score += 5.0;
                }
            }
        }
        // Fresh-bin convex-waste coupling
        if fitting_bins_count >= 1 && item_size <= bin_residual {
            let open_waste = bin_residual.saturating_sub(item_size);
            if open_waste > 35 {
                score -= 3.0 + 0.05 * ((open_waste - 35) as f64).min(30.0);
            }
        }
        // Fresh-bin near-miss guard
        if next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size);
            if leftover < next_item_size {
                let miss = (next_item_size - leftover) as f64;
                if miss <= 8.0 {
                    score += 12.0 * (1.0 - miss / 8.0);
                }
            }
        }
        // Fresh-bin waste-quadratic mirror
        if next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover > 25 {
                score += 0.05 * ((leftover - 25) as f64).min(40.0);
            }
        }
        // MUTATION (gen 9): fresh-bin scarcity coupling — when only one open
        // bin fits and reusing it would strand a mid-band residual while a
        // fresh bin leaves a chainable leftover, prefer opening fresh.
        if fitting_bins_count == 1 && next_item_size > 0 {
            let open_waste = bin_residual.saturating_sub(item_size);
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if open_waste >= 13 && open_waste <= 29 && fresh_left >= next_item_size {
                score -= 9.0;
            }
        }
        // MUTATION (gen 9): fresh-bin late-stream waste floor — opening fresh
        // late in the stream must leave a genuinely usable leftover, otherwise
        // it is pure bin-count inflation; tighten the late discipline.
        if progress > 0.55 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover < 20 {
                score += 6.0 * (progress - 0.55) * 20.0;
            }
        }
        // MUTATION (gen 10): fresh-bin exact-closure preference — a fresh bin
        // is decisively better when current + next item close it exactly or
        // leave <=4 slack, but only mid-stream when open-bin waste would be
        // substantial; prevents fresh-bin inflation in trivial cases.
        if progress > 0.25 && progress < 0.85 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover <= 4 {
                if fitting_bins_count >= 1 && bin_residual.saturating_sub(item_size) > 12 {
                    score -= 14.0;
                }
            } else if leftover <= 12 && fitting_bins_count >= 1 {
                let open_waste = bin_residual.saturating_sub(item_size);
                if open_waste > leftover + 8 {
                    score -= 5.0;
                }
            }
        }
        // MUTATION (gen 10): fresh-bin large-item reserve — when the next item
        // is large (>45) and no open bin could host it after this item, a
        // fresh bin with enough room for both is strongly preferred.
        if next_item_size > 45 && fitting_bins_count >= 1 {
            let open_after = bin_residual.saturating_sub(item_size);
            let fresh_after = bin_capacity.saturating_sub(item_size);
            if open_after < next_item_size && fresh_after >= next_item_size {
                score -= 11.0;
            }
        }
        // MUTATION (gen 11): fresh-bin waste-parity guard — compare the fresh
        // bin's post-two-item leftover against the best open-bin waste; open
        // fresh only when its leftover is strictly more reusable than what
        // reusing an open bin would leave behind.
        if fitting_bins_count >= 1 && next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            let open_waste = bin_residual.saturating_sub(item_size);
            if fresh_left >= next_item_size && open_waste >= 20 {
                score -= 4.0 + 0.1 * ((open_waste - 20) as f64).min(25.0);
            } else if fresh_left > 0 && fresh_left < 8 && open_waste <= 10 {
                score += 5.0;
            }
        }
        // MUTATION (gen 12): fresh-bin residual-regime gate — in a tight global
        // regime (low mean residual), fresh bins should only open when they
        // close within two items or leave a dense-band leftover; otherwise
        // they inflate the bin count. In a loose regime, keep existing bias.
        if progress > 0.3 && next_item_size > 0 {
            let tightness = (1.0 - (mean_residual / cap_f).min(1.0)).max(0.0);
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if tightness > 0.6 && leftover > 50 {
                score += 8.0 * (tightness - 0.6) * 10.0;
            } else if tightness > 0.6 && leftover >= 25 && leftover <= 50 {
                score -= 5.0 * (tightness - 0.6) * 10.0;
            }
        }
        // MUTATION (gen 13): fresh-bin next-item-strand parity — when the next
        // item is medium-large and reusing an open bin would strand it while
        // a fresh bin could host both, bias toward opening fresh; but if the
        // next item is small enough to be absorbed by typical residuals,
        // keep the fresh-bin cost high to avoid inflation.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let open_after = bin_residual.saturating_sub(item_size);
            let fresh_after = bin_capacity.saturating_sub(item_size);
            if open_after < next_item_size && fresh_after >= next_item_size {
                let mid_next = next_item_size >= 25 && next_item_size <= 70;
                if mid_next {
                    score -= 6.0 + 4.0 * (1.0 - progress);
                } else if next_item_size < 25 {
                    score += 4.0;
                }
            }
        }
        // MUTATION (gen 13): fresh-bin mean-residual bar — a fresh bin must
        // beat the global average dead-space expectation; if its two-item
        // leftover exceeds the current mean residual by a wide margin late
        // in the stream, charge it proportionally.
        if progress > 0.45 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size) as f64;
            let excess = leftover - mean_residual.max(0.0);
            if excess > 15.0 {
                score += 0.08 * (excess - 15.0).min(40.0);
            }
        }
        // MUTATION (gen 14): fresh-bin exact-closure escalation — when the
        // two-item leftover is exactly zero, the fresh bin is a guaranteed
        // no-waste closure; deepen the reward as the stream progresses since
        // exact-closure opportunities become rarer and more valuable late.
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 9.0 + 8.0 * progress;
        }
        // MUTATION (gen 14): fresh-bin residual-band targeting — a fresh bin
        // whose post-two-item leftover lands in the empirically dense
        // 30..=55 reusable zone is preferred over one leaving an awkward
        // 56..=90 tail; graded by distance from the band center.
        if next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover >= 30 && leftover <= 55 {
                let d = ((leftover as f64 - 42.5).abs() / 12.5).min(1.0);
                score -= 4.0 * (1.0 - d);
            } else if leftover > 55 && leftover <= 90 {
                score += 2.0 * ((leftover as f64 - 55.0) / 35.0);
            }
        }
    } else {
        // MUTATION (gen 13): open-bin next-item strand mirror — when this
        // placement strands the next item but another placement would not
        // (many fitting bins imply alternatives exist), charge the stranding
        // harder; when this bin is the only host, forgive the stranding.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let alternatives = (fitting_bins_count as f64).max(1.0);
            score += (3.0 / alternatives.sqrt()) * (1.0 - 0.3 * progress);
        }
        // MUTATION (gen 13): dead-space curvature refinement — replace part of
        // the linear waste cost with a steeper convex term for residuals that
        // can host the next item but leave a tail larger than the next item
        // itself (double-stranding risk two steps ahead).
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail > next_item_size {
                score += 0.05 * ((tail - next_item_size) as f64).min(50.0) * (0.5 + 0.5 * progress);
            }
        }
        // MUTATION (gen 14): exact-zero closure escalation — fully emptying an
        // open bin is the single most bin-saving event; deepen the reward when
        // many bins are open (consolidation regime) and late in the stream.
        if post_residual == 0 {
            let crowd = ((open_bins_count as f64 - 4.0).max(0.0) / 12.0).min(1.0);
            score -= 6.0 * crowd + 4.0 * progress;
        }
        // MUTATION (gen 14): residual-sweep bonus — a post-fit residual in the
        // 1..=12 band with a small next item expected can be swept clean next
        // step; reward it proportionally to how close the next item is to the
        // residual (near-guaranteed closure), weighted by stream progress.
        if post_residual >= 1 && post_residual <= 12 && next_item_size > 0 && next_item_size <= post_residual {
            let closeness = 1.0 - (post_residual - next_item_size) as f64 / 12.0;
            score -= 3.5 * closeness * (0.4 + 0.6 * progress);
        }
        // MUTATION (gen 14): tight-fit scarcity gradient — under low scarcity
        // (many fitting bins), prefer the tightest possible fit by scaling a
        // graded penalty with the slack between residual and item size; this
        // sharpens best-fit selection among many candidates.
        if slack >= 0 && fitting_bins_count > 3 && bin_residual != bin_capacity {
            let sl = slack as f64;
            if sl > 8.0 {
                score += 0.06 * (sl - 8.0).min(50.0) * (0.5 + 0.5 * progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap_f = bin_capacity as f64;
    let resid_f = bin_residual as f64;

    // Perfect fill reward
    if post_residual == 0 {
        score -= 65.0;
    }

    // Near-exact capacity match: residual just above item size
    let slack = bin_residual as i64 - item_size as i64;
    if slack >= 0 && slack <= 4 {
        score -= 20.0;
    }

    // --- 2-step lookahead core ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0 + 22.0 * (1.0 - progress);
        } else if post_residual > next_item_size {
            let slack_after_next = post_residual - next_item_size;
            score -= 25.0 - (slack_after_next as f64).min(40.0) * 0.3;
            if slack_after_next > 40 {
                score += (slack_after_next as f64 - 40.0) * 0.2;
            }
        } else {
            let shortfall = (next_item_size - post_residual) as f64;
            score += shortfall * 0.85;
            let half_next = next_item_size / 2;
            if post_residual > 0 && post_residual < half_next {
                score += 14.0;
            }
        }
    } else {
        score -= 10.0;
    }

    // Dead-space penalty: graded, fragmentation-aware waste pressure
    if post_residual > 0 {
        let waste_ratio = post_residual as f64 / cap_f;
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        let severity = 1.4 - 0.8 * tightness;
        if post_residual < next_item_size && next_item_size > 0 {
            let unusability = 1.0 - (post_residual as f64 / next_item_size as f64);
            score += 16.0 * unusability * (1.0 - 0.5 * progress) * severity;
            if post_residual < 10 {
                score += 9.0 * severity * (1.0 - 0.4 * progress);
            }
        } else if waste_ratio < 0.05 {
            score += 7.0 * (1.0 - progress) * severity;
        } else if waste_ratio < 0.10 && post_residual < 40 {
            score += 3.0 * (1.0 - progress) * severity;
        }
    }

    // Mean-residual coupling: fill tight bins, save roomy bins for big items
    if resid_f > mean_residual + 20.0 && item_size < 30 {
        if next_item_size == 0 || post_residual < next_item_size {
            score += 10.0;
        }
    } else if resid_f < mean_residual - 20.0 {
        score -= 8.0;
    }

    // Last-chance bonus: only bin that fits -> use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
        if post_residual >= 10 {
            score -= 10.0;
        }
    }

    // Consolidation pressure: prefer bins with larger residual when many bins open
    if open_bins_count > 8 {
        score += (resid_f / cap_f) * 6.0;
    }
    score -= (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Fragmentation-aware tiebreak: reward residuals likely reusable
    if post_residual >= 25 {
        score -= 4.0;
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 15 {
            score -= 6.0;
        }
    }

    // Triple-fit chain: scaled by remainder quality
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 20 {
