            let fresh_after = bin_capacity.saturating_sub(item_size);
            if open_after < next_item_size && fresh_after >= next_item_size {
                let mid_next = next_item_size >= 25 && next_item_size <= 70;
                if mid_next {
                    score -= 6.0 + 4.0 * (1.0 - progress);
                } else if next_item_size < 25 {
                    score += 4.0;
                }
            }
        }
        // MUTATION (gen 13): fresh-bin mean-residual bar
        if progress > 0.45 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size) as f64;
            let excess = leftover - mean_residual.max(0.0);
            if excess > 15.0 {
                score += 0.08 * (excess - 15.0).min(40.0);
            }
        }
        // MUTATION (gen 14): fresh-bin exact-closure escalation
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 9.0 + 8.0 * progress;
        }
        // MUTATION (gen 14): fresh-bin residual-band targeting
        if next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover >= 30 && leftover <= 55 {
                let d = ((leftover as f64 - 42.5).abs() / 12.5).min(1.0);
                score -= 4.0 * (1.0 - d);
            } else if leftover > 55 && leftover <= 90 {
                score += 2.0 * ((leftover as f64 - 55.0) / 35.0);
            }
        }
        // MUTATION (gen 15): fresh-bin scarcity gate refinement — when many
        // bins fit, opening fresh must be justified by a decisive closure
        // advantage; otherwise raise the fresh-bar to protect bin count.
        if fitting_bins_count > 3 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            let open_waste = bin_residual.saturating_sub(item_size);
            if leftover > 12 && open_waste <= 10 {
                score += 5.0 * (1.0 - progress);
            }
        }
    } else {
        // MUTATION (gen 13): open-bin next-item strand mirror
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let alternatives = (fitting_bins_count as f64).max(1.0);
            score += (3.0 / alternatives.sqrt()) * (1.0 - 0.3 * progress);
        }
        // MUTATION (gen 13): dead-space curvature refinement
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            if tail > next_item_size {
                score += 0.05 * ((tail - next_item_size) as f64).min(50.0) * (0.5 + 0.5 * progress);
            }
        }
        // MUTATION (gen 14): exact-zero closure escalation
        if post_residual == 0 {
            let crowd = ((open_bins_count as f64 - 4.0).max(0.0) / 12.0).min(1.0);
            score -= 6.0 * crowd + 4.0 * progress;
        }
        // MUTATION (gen 14): residual-sweep bonus
        if post_residual >= 1 && post_residual <= 12 && next_item_size > 0 && next_item_size <= post_residual {
            let closeness = 1.0 - (post_residual - next_item_size) as f64 / 12.0;
            score -= 3.5 * closeness * (0.4 + 0.6 * progress);
        }
        // MUTATION (gen 14): tight-fit scarcity gradient
        if slack >= 0 && fitting_bins_count > 3 && bin_residual != bin_capacity {
            let sl = slack as f64;
            if sl > 8.0 {
                score += 0.06 * (sl - 8.0).min(50.0) * (0.5 + 0.5 * progress);
            }
        }
        // MUTATION (gen 15): exact-closure consolidation boost — emptying a
        // bin when many bins are open is the strongest bin-count lever;
        // deepen the reward scaled by open-bin count and stream progress.
        if post_residual == 0 && open_bins_count > 8 {
            score -= 2.0 * ((open_bins_count - 8) as f64).min(10.0) * 0.4 * (0.5 + 0.5 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap_f = bin_capacity as f64;
    let resid_f = bin_residual as f64;

    // Perfect fill reward
    if post_residual == 0 {
        score -= 65.0;
    }

    // Near-exact capacity match: residual just above item size
    let slack = bin_residual as i64 - item_size as i64;
    if slack >= 0 && slack <= 4 {
        score -= 20.0;
    }

    // --- 2-step lookahead core ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0 + 22.0 * (1.0 - progress);
        } else if post_residual > next_item_size {
            let slack_after_next = post_residual - next_item_size;
            score -= 25.0 - (slack_after_next as f64).min(40.0) * 0.3;
            if slack_after_next > 40 {
                score += (slack_after_next as f64 - 40.0) * 0.2;
            }
        } else {
            let shortfall = (next_item_size - post_residual) as f64;
            score += shortfall * 0.85;
            let half_next = next_item_size / 2;
            if post_residual > 0 && post_residual < half_next {
                score += 14.0;
            }
        }
    } else {
        score -= 10.0;
    }

    // Dead-space penalty: graded, fragmentation-aware waste pressure
    if post_residual > 0 {
