    if slack >= 0 && slack <= 6 && fitting_bins_count <= 3 && bin_residual != bin_capacity {
        let sl = slack as f64;
        score -= 6.0 * (1.0 - sl / 6.0) * (1.0 / (fitting_bins_count as f64).max(1.0)) * (0.6 + 0.4 * progress);
    }

    // MUTATION (gen 17): exact-zero consolidation boost — emptying a bin when
    // many bins are open is the strongest bin-count lever; deepen the reward
    // scaled by open-bin count and stream progress.
    if post_residual == 0 && open_bins_count > 8 {
        score -= 2.0 * ((open_bins_count - 8) as f64).min(10.0) * 0.4 * (0.5 + 0.5 * progress);
    }

    // MUTATION (gen 17): residual-sweep bonus — small residuals that exactly
    // host the next item are one step from closure; reward proportional to
    // closeness and progress.
    if post_residual >= 1 && post_residual <= 12 && next_item_size > 0 && next_item_size <= post_residual {
        let closeness = 1.0 - (post_residual - next_item_size) as f64 / 12.0;
        score -= 3.5 * closeness * (0.4 + 0.6 * progress);
    }

    // MUTATION (gen 17): loose-fit crowd penalty — when many bins fit and the
    // fit is loose, add graded pressure so crowded streams prefer tight hosts
    // and preserve roomy bins for large items.
    if slack >= 0 && fitting_bins_count > 3 && bin_residual != bin_capacity {
        let sl = slack as f64;
        if sl > 8.0 {
            score += 0.06 * (sl - 8.0).min(50.0) * (0.5 + 0.5 * progress);
        }
    }

