    // MUTATION (gen 12): dead-space absorption gradient
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let crowd = ((open_bins_count as f64 - 6.0).max(0.0) / 10.0).min(1.0);
        if pr <= 18.0 {
            score -= 2.0 * (1.0 - pr / 18.0) * crowd;
        } else if next_item_size > 0 && post_residual < next_item_size {
