    if post_residual == 0 && bin_residual != bin_capacity {
        let crowd = ((open_bins_count as f64 - 5.0).max(0.0) / 15.0).min(1.0);
        score -= 5.0 * crowd * (0.7 + 0.3 * progress);
    }

    // MUTATION (gen 18): tail-quality gradient refinement — post-next-item
    // tails in the 4..=14 band are the most reusable micro-remainders;
    // reward them with a smooth peak centered at 8, reinforcing chain
    // compaction without over-rewarding large tails.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let tail = post_residual - next_item_size;
        if tail >= 4 && tail <= 14 {
            let peak = 1.0 - ((tail as f64 - 8.0).abs() / 6.0).min(1.0);
            score -= 5.0 * peak * (0.6 + 0.4 * (1.0 - progress));
