    // otherwise nudge the fresh bar upward to protect bin count.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count >= 1 {
        let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
        let open_waste = bin_residual.saturating_sub(item_size);
        if fresh_left >= next_item_size && open_waste <= 8 {
