    }

    // MUTATION (gen 14): twin-residual pairing — when the post-fit residual
    // nearly matches the next item (ratio 0.9..=1.0), the bin is one step from
    // closure after the next placement; reward proportionally to closeness.
    if next_item_size > 0 && post_residual > 0 && bin_residual != bin_capacity {
