            let leftover = bin_capacity - item_size - next_item_size;
            if leftover < 10 {
                score -= 8.0;
            } else if leftover < 25 {
                score -= 3.0;
            }
            if leftover >= 25 && leftover <= 60 {
                score -= 6.0;
            } else if leftover >= 1 && leftover <= 5 {
                score += 6.0;
            }
        }
        if open_bins_count < 4 && progress < 0.3 {
            score -= 12.0;
        }
        if next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover >= next_item_size {
                score -= 10.0;
            }
        }
        if item_size < 15 && progress > 0.5 && fitting_bins_count >= 1 {
            score += 15.0;
        }
        if fitting_bins_count >= 1 && item_size <= bin_residual {
            let best_case_waste = bin_residual - item_size;
            if best_case_waste <= 5 {
                score += 25.0;
            } else if best_case_waste <= 15 {
                score += 8.0;
            }
        }
        if progress > 0.6 {
            score += 7.5 * (progress - 0.6) * 25.0;
        }
        if open_bins_count > 10 && progress > 0.35 && progress < 0.7 {
            let roomy = (mean_residual / cap_f).min(1.0);
            score += 6.0 * roomy;
        }
        if item_size > 60 && next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 8.0;
        }
        if next_item_size > 0 && item_size + next_item_size < bin_capacity {
            let leftover = bin_capacity - item_size - next_item_size;
            if leftover >= next_item_size {
                score -= 6.0;
            }
        }
        if next_item_size > 0 && fitting_bins_count >= 2 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover > 0 && leftover < 12 {
                score += 9.0;
            }
        }
        if fitting_bins_count >= 1 && item_size <= bin_residual {
            let open_waste = bin_residual - item_size;
            if open_waste > 15 && open_waste <= 35 {
                let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
                if next_item_size > 0 && fresh_left >= next_item_size {
                    score -= 4.0;
                } else {
                    score += 5.0;
                }
            }
        }
        if fitting_bins_count >= 1 && item_size <= bin_residual {
            let open_waste = bin_residual.saturating_sub(item_size);
            if open_waste > 35 {
                score -= 3.0 + 0.05 * ((open_waste - 35) as f64).min(30.0);
            }
        }
        if next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size);
            if leftover < next_item_size {
                let miss = (next_item_size - leftover) as f64;
                if miss <= 8.0 {
                    score += 12.0 * (1.0 - miss / 8.0);
                }
            }
        }
        if next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover > 25 {
                score += 0.05 * ((leftover - 25) as f64).min(40.0);
            }
        }
        if fitting_bins_count == 1 && next_item_size > 0 {
            let open_waste = bin_residual.saturating_sub(item_size);
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if open_waste >= 13 && open_waste <= 29 && fresh_left >= next_item_size {
                score -= 9.0;
            }
        }
        if progress > 0.55 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover < 20 {
                score += 6.0 * (progress - 0.55) * 20.0;
            }
        }
        if progress > 0.25 && progress < 0.85 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover <= 4 {
                if fitting_bins_count >= 1 && bin_residual.saturating_sub(item_size) > 12 {
                    score -= 14.0;
                }
            } else if leftover <= 12 && fitting_bins_count >= 1 {
                let open_waste = bin_residual.saturating_sub(item_size);
                if open_waste > leftover + 8 {
                    score -= 5.0;
                }
            }
        }
        if next_item_size > 45 && fitting_bins_count >= 1 {
            let open_after = bin_residual.saturating_sub(item_size);
            let fresh_after = bin_capacity.saturating_sub(item_size);
            if open_after < next_item_size && fresh_after >= next_item_size {
                score -= 11.0;
            }
        }
        if fitting_bins_count >= 1 && next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            let open_waste = bin_residual.saturating_sub(item_size);
            if fresh_left >= next_item_size && open_waste >= 20 {
                score -= 4.0 + 0.1 * ((open_waste - 20) as f64).min(25.0);
            } else if fresh_left > 0 && fresh_left < 8 && open_waste <= 10 {
                score += 5.0;
            }
        }
        if progress > 0.3 && next_item_size > 0 {
            let tightness = (1.0 - (mean_residual / cap_f).min(1.0)).max(0.0);
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if tightness > 0.6 && leftover > 50 {
                score += 8.0 * (tightness - 0.6) * 10.0;
            } else if tightness > 0.6 && leftover >= 25 && leftover <= 50 {
                score -= 5.0 * (tightness - 0.6) * 10.0;
            }
        }
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let open_after = bin_residual.saturating_sub(item_size);
            let fresh_after = bin_capacity.saturating_sub(item_size);
            if open_after < next_item_size && fresh_after >= next_item_size {
                let mid_next = next_item_size >= 25 && next_item_size <= 70;
                if mid_next {
                    score -= 6.0 + 4.0 * (1.0 - progress);
                } else if next_item_size < 25 {
                    score += 4.0;
                }
            }
        }
        if progress > 0.45 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size) as f64;
            let excess = leftover - mean_residual.max(0.0);
            if excess > 15.0 {
                score += 0.08 * (excess - 15.0).min(40.0);
            }
        }
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 9.0 + 8.0 * progress;
        }
        if next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover >= 30 && leftover <= 55 {
                let d = ((leftover as f64 - 42.5).abs() / 12.5).min(1.0);
                score -= 4.0 * (1.0 - d);
            } else if leftover > 55 && leftover <= 90 {
                score += 2.0 * ((leftover as f64 - 55.0) / 35.0);
            }
        }
        if fitting_bins_count > 3 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            let open_waste = bin_residual.saturating_sub(item_size);
            if leftover > 12 && open_waste <= 10 {
                score += 5.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            let open_waste = bin_residual.saturating_sub(item_size);
            if fresh_left >= 12 && fresh_left <= 30 && open_waste > 25 {
                score -= 5.0 * (1.0 - progress);
            } else if fresh_left > 30 && open_waste <= 20 {
                score += 4.0 * (0.5 + 0.5 * progress);
            }
        }
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.0004 * fresh_left * fresh_left * fresh_left * (0.5 + 0.7 * tightness);
        }
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let open_waste = bin_residual.saturating_sub(item_size) as f64;
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as f64;
            let excess = open_waste - fresh_left;
            if excess > 10.0 {
                score -= 2.5 * ((excess - 10.0) / 25.0).min(1.0) * (0.5 + 0.5 * (1.0 - progress));
            } else if excess < -10.0 {
                score += 2.0 * (((-excess) - 10.0) / 25.0).min(1.0) * (0.5 + 0.5 * progress);
            }
        }
        if progress > 0.75 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover > 0 {
                score += 3.0 + 0.08 * (leftover as f64) * (progress - 0.75) * 20.0;
            } else {
                score -= 6.0 * (progress - 0.75) * 10.0;
            }
        }
        if fitting_bins_count >= 1 && next_item_size > 0 {
            let tightness = (1.0 - (mean_residual / cap_f).min(1.0)).max(0.0);
            let open_waste = bin_residual.saturating_sub(item_size) as f64;
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as f64;
            if tightness > 0.55 && open_waste > 18.0 && fresh_left >= 20.0 {
                score -= 5.0 * (tightness - 0.55) * 10.0;
            }
        }
        if next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover >= 8 && leftover <= 25 {
                score -= 3.5 * (1.0 - (leftover as f64 - 8.0).abs() / 17.0);
            } else if leftover > 65 {
                score += 0.06 * ((leftover - 65) as f64).min(35.0) * (0.5 + 0.5 * progress);
            }
        }
        if fitting_bins_count >= 1 && next_item_size > 0 {
            let open_after = bin_residual.saturating_sub(item_size);
            if open_after > 0 && open_after < next_item_size {
                let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
                if fresh_left < next_item_size {
                    score += 4.0 + 2.0 * (1.0 - progress);
                }
            }
        }
        if fitting_bins_count == 1 && item_size < 40 && progress > 0.3 {
            let open_after = bin_residual.saturating_sub(item_size);
            if open_after >= 15 {
                score += 10.0 * (1.0 - progress);
            }
        }
        if open_bins_count > 10 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover > 30 {
                score += 4.0 + 0.06 * ((leftover - 30) as f64).min(40.0);
            } else if leftover <= 30 && item_size > 50 {
                score -= 5.0;
            }
        }
        if progress > 0.7 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover > 0 && leftover <= 6 {
                score -= 7.0 * (progress - 0.7) * 10.0;
            } else if leftover > 40 {
                score += 4.0 * (progress - 0.7) * 10.0;
            }
        }
        if fitting_bins_count >= 1 && item_size > 55 {
            let open_waste = bin_residual.saturating_sub(item_size);
            if open_waste > 20 {
                score -= 3.0 + 0.06 * ((open_waste - 20) as f64).min(30.0) * (1.0 - 0.3 * progress);
            }
        }

        // MUTATION (gen 22): fresh-bin open-bin residual parity — when the best open
        // bin's post-fit remainder is itself highly reusable (8..=25), opening a
        // fresh bin is usually wasteful; penalize fresh bins proportionally.
        if fitting_bins_count >= 1 && next_item_size > 0 {
            let open_after = bin_residual.saturating_sub(item_size);
            if open_after >= 8 && open_after <= 25 {
                score += 5.0 * (1.0 - (open_after as f64 - 8.0).abs() / 17.0) * (0.5 + 0.5 * progress);
            }
        }

        // MUTATION (gen 22): fresh-bin three-item horizon — when the fresh bin's
        // two-item leftover can still absorb a plausible mid-size item, reward it
        // more strongly than the parent's two-item-only view.
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left >= 30 && fresh_left <= 55 {
                score -= 2.5 * (1.0 - ((fresh_left as f64 - 42.5).abs() / 12.5).min(1.0)) * (1.0 - 0.4 * progress);
            }
        }

        // MUTATION (gen 22): fresh-bin crowd-scarcity coupling — open a fresh bin
        // more readily when many bins are open AND few can fit (avoids stranding
        // the item in a poor-fit bin while consolidating elsewhere).
        if open_bins_count > 6 && fitting_bins_count <= 2 && next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left > 0 && fresh_left < next_item_size {
                score += 3.0 * (1.0 - progress);
            }
        }

        // MUTATION (gen 22): fresh-bin exact-triple closure — reward when item +
        // next + a small trailing item (<=12) exactly closes the fresh bin.
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left >= 1 && fresh_left <= 12 {
                score -= 4.0 * (1.0 - fresh_left as f64 / 12.0) * (0.6 + 0.4 * (1.0 - progress));
            }
        }
    }

    // MUTATION (gen 23): dead-space divisibility anticipation — when the post-fit
    // remainder is an exact multiple of a plausible small-item size band (4..=16),
    // it is far more likely to be filled later; reward such remainders to reduce
    // long-tail dead space, the diagnosed weakness.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        for d in [4u32, 5, 6, 8, 10, 12, 15, 16] {
            if post_residual % d == 0 && post_residual / d >= 1 && post_residual / d <= 6 {
                score -= 3.0 * (1.0 - 0.4 * progress);
                break;
            }
        }
        // Complementary: odd remainders in the 20..=40 dead zone are hard to fill.
        if post_residual >= 20 && post_residual <= 40 && post_residual % 2 == 1 {
            score += 2.0 + 1.5 * progress;
        }
    }

    // MUTATION (gen 23): two-item fillability horizon — reward bins whose post-fit
    // remainder can absorb two more small items (2x next or next + <=10), sharpening
    // the chain-closure direction that drove recent gains.
    if next_item_size > 0 && post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual;
        if pr >= 2 * next_item_size && pr - 2 * next_item_size <= 6 {
            score -= 5.0 * (1.0 - 0.3 * progress);
        } else if next_item_size <= 10 && pr >= next_item_size + 10 && pr - (next_item_size + 10) <= 4 {
            score -= 3.5 * (1.0 - 0.3 * progress);
        }
    }

    // MUTATION (gen 23): scarcity-weighted residual smoothing — when few bins can
    // fit the item, tilt strongly toward the bin leaving the smallest remainder
    // (best-fit deepening under scarcity), reducing fragmented leftovers.
    if fitting_bins_count <= 2 && post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0);
        score += 0.10 * pr * scarcity * (0.4 + 0.6 * (1.0 - progress));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap_f = bin_capacity as f64;
    let resid_f = bin_residual as f64;
    let slack = bin_residual as i64 - item_size as i64;

    if post_residual == 0 {
        score -= 65.0;
    }
    if slack >= 0 && slack <= 4 {
        score -= 20.0;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0 + 22.0 * (1.0 - progress);
        } else if post_residual > next_item_size {
            let slack_after_next = post_residual - next_item_size;
            score -= 25.0 - (slack_after_next as f64).min(40.0) * 0.3;
            if slack_after_next > 40 {
                score += (slack_after_next as f64 - 40.0) * 0.2;
            }
        } else {
            let shortfall = (next_item_size - post_residual) as f64;
            score += shortfall * 0.85;
            let half_next = next_item_size / 2;
            if post_residual > 0 && post_residual < half_next {
                score += 14.0;
            }
        }
    } else {
        score -= 10.0;
    }

    if post_residual > 0 {
        let waste_ratio = post_residual as f64 / cap_f;
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        let severity = 1.4 - 0.8 * tightness;
        if post_residual < next_item_size && next_item_size > 0 {
            let unusability = 1.0 - (post_residual as f64 / next_item_size as f64);
            score += 16.0 * unusability * (1.0 - 0.5 * progress) * severity;
            if post_residual < 10 {
                score += 9.0 * severity * (1.0 - 0.4 * progress);
            }
        } else if waste_ratio < 0.05 {
            score += 7.0 * (1.0 - progress) * severity;
        } else if waste_ratio < 0.10 && post_residual < 40 {
            score += 3.0 * (1.0 - progress) * severity;
        }
    }

    if resid_f > mean_residual + 20.0 && item_size < 30 {
        if next_item_size == 0 || post_residual < next_item_size {
            score += 10.0;
        }
    } else if resid_f < mean_residual - 20.0 {
        score -= 8.0;
    }

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
        if post_residual >= 10 {
            score -= 10.0;
        }
    }

    if open_bins_count > 8 {
        score += (resid_f / cap_f) * 6.0;
    }
    score -= (open_bins_count as f64).ln().max(0.0) * 3.0;

    if post_residual >= 25 {
        score -= 4.0;
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 15 {
            score -= 6.0;
        }
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 20 {
            let sweet = if after_next <= 60 { 3.0 } else { 0.0 };
            score -= 5.0 + 5.0 * (1.0 - progress) + sweet;
        }
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 6.0 * (post_residual as f64 / cap_f) * 10.0;
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let strandedness = 1.0 - (post_residual as f64 / next_item_size as f64);
        let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0);
        score += 9.0 * strandedness * scarcity;
    }

    if post_residual >= 20 && post_residual <= 60 {
        score -= 3.0 + 4.0 * (1.0 - progress);
    }
    if post_residual >= 1 && post_residual <= 5 {
        score += 5.0;
    }

    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap > 0 && gap <= 8 {
            score -= 4.0 + 3.0 * (1.0 - progress);
        }
    }

    if item_size > 0 && bin_residual % item_size == 0 && bin_residual != bin_capacity {
        score -= 5.0;
        if post_residual == 0 {
            score -= 4.0;
        }
    }

    if next_item_size > 0 && post_residual == next_item_size && progress < 0.4 {
        score -= 6.0;
    }

    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let chain_left = bin_residual - item_size - next_item_size;
        if chain_left >= 15 && chain_left <= 55 {
            score -= 7.0 + 5.0 * (1.0 - progress);
        }
    }

    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap > 8 && gap <= 20 {
            score += 1.5;
        } else if gap > 20 && gap <= 35 {
            score += 3.5;
        }
    }

    if fitting_bins_count <= 2 && bin_residual != bin_capacity && post_residual <= 12 {
        score -= 6.0 + 4.0 * (1.0 - progress);
    }

    if open_bins_count > 12 && bin_residual != bin_capacity {
        score += 8.0 * (1.0 - resid_f / cap_f);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unus = 1.0 - (post_residual as f64 / next_item_size as f64);
        score += 4.5 * unus * (1.0 - 0.3 * progress);
    }

    if post_residual > 60 && post_residual < 100 {
        score += 2.5 + 2.0 * (1.0 - progress);
    }

    if post_residual == 0 && bin_residual != bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
        score -= 8.0 * scarcity * (0.5 + 0.5 * (1.0 - progress));
    }

    if post_residual >= 46 && post_residual <= 59 && bin_residual != bin_capacity {
        let d = (post_residual as f64 - 46.0) / 13.0;
        score += 1.5 + 2.0 * d * (1.0 - 0.4 * progress);
    }

    if open_bins_count > 6 && bin_residual != bin_capacity {
        let crowd = ((open_bins_count as f64 - 6.0) / 14.0).min(1.0);
        score += (resid_f / cap_f) * 2.5 * crowd * (0.6 + 0.4 * progress);
    }

    if next_item_size > 0 && post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let nx = next_item_size as f64;
        let ratio = pr / nx.max(1.0);
        if ratio > 0.9 && ratio <= 1.0 {
            score -= 6.0 * (ratio - 0.9) * 10.0 * (0.6 + 0.4 * (1.0 - progress));
        }
    }

    if post_residual > 0 && fitting_bins_count >= 2 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        let alignment = 1.0 - ((pr - 30.0).abs() / 30.0).min(1.0);
        score -= 3.5 * alignment * tightness * (0.4 + 0.6 * (1.0 - progress));
    }

    if post_residual == 0 && slack >= 0 && slack <= 4 && bin_residual != bin_capacity {
        score -= 3.0 + 2.0 * (1.0 - progress);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && bin_residual != bin_capacity {
        let alternatives = (fitting_bins_count as f64).max(1.0);
        score += (3.0 / alternatives.sqrt()) * (1.0 - 0.3 * progress);
    }

    if post_residual == 0 && bin_residual != bin_capacity {
        let crowd = ((open_bins_count as f64 - 4.0).max(0.0) / 12.0).min(1.0);
        score -= 6.0 * crowd + 4.0 * progress;
    }

