    }

    // MUTATION (gen 16): open-bin dead-space convexity sharpening
    if post_residual >= 25 && post_residual <= 40 && next_item_size > 0 && post_residual < next_item_size && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let stranded = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
        score += 3.5 * stranded * (1.0 - (pr - 25.0) / 15.0) * (0.6 + 0.4 * progress);
    }

    // MUTATION (gen 16): perfect-closure gradient
    if post_residual == 0 && fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score -= 3.0 * (1.0 - progress);
    }

    // MUTATION (gen 17): dual-item horizon sweep — reward open bins whose
    // post-fit residual can absorb BOTH the next item and a small trailing
    // item, tightening multi-item chains and reducing dead space.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let tail = post_residual - next_item_size;
        if tail >= 1 && tail <= 10 {
            score -= 6.5 * (1.0 - tail as f64 / 10.0) * (0.55 + 0.45 * (1.0 - progress));
        }
    }

    // MUTATION (gen 17): waste-band monotonicity repair — large post-fit
    // residuals (41..=70) that exceed the next item get a progressive penalty
    // so oversized leftovers are avoided more consistently mid-stream.
    if post_residual > 40 && post_residual <= 70 && next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let tail = (post_residual - next_item_size) as f64;
        if tail > 20.0 {
            score += 0.055 * (tail - 20.0) * (0.6 + 0.5 * progress);
        }
    }

    // MUTATION (gen 17): fresh-bin compaction parity — when the fresh bin's
    // post-item leftover is strictly smaller than every plausible open-bin
    // waste and the item is large, prefer the fresh bin (dead-space reset).
    if bin_residual == bin_capacity && next_item_size > 0 && item_size > 45 {
        let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as f64;
        let open_waste = bin_residual.saturating_sub(item_size) as f64;
        if fresh_left < open_waste * 0.6 && fresh_left < 20.0 {
            score -= 7.0 * (1.0 - fresh_left / 20.0) * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap_f = bin_capacity as f64;
    let resid_f = bin_residual as f64;
