            }
            // MUTATION (gen 16): excess-waste gradient — opening fresh wins when
            // the open-bin waste exceeds fresh leftover by a clear margin.
            let excess = open_waste - fresh_left;
            if next_item_size > 0 && fresh_left >= 0.0 && excess > 10.0 {
                score -= 2.5 * ((excess - 10.0) / 25.0).min(1.0) * (0.5 + 0.5 * (1.0 - progress));
