    // MUTATION (gen 16): open-bin mid-band dead-space convexity sharpening.
    if post_residual >= 25 && post_residual <= 40 && next_item_size > 0 && post_residual < next_item_size && !is_new_bin {
        let stranded = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
