    // concentrate small-item absorption where it compacts best.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && bin_residual != bin_capacity {
        let nx = next_item_size as f64;
        let pr = post_residual as f64;
        let half_fit = ((pr - nx / 2.0).abs() / (nx / 4.0).max(1.0)).min(1.0);
        score -= 3.0 * (1.0 - half_fit) * (0.5 + 0.5 * (1.0 - progress));
    }

    // MUTATION (gen 17): large-item corridor preservation — when the next item
    // is large (>50), open bins whose post-fit residual cannot host it but
    // whose current residual can host the current item should be slightly
    // deprioritized versus bins that stay above the large-item threshold,
    // keeping corridors open for big items and reducing stranded capacity.
    if next_item_size > 50 && bin_residual != bin_capacity && post_residual > 0 {
        let nx = next_item_size as f64;
        if post_residual < next_item_size {
            let shortfall = (nx - post_residual as f64) / nx;
            score += 2.0 * shortfall * (0.6 + 0.4 * (1.0 - progress));
        }
    }

    // MUTATION (gen 17): residual equalization pressure — gently penalize bins
    // whose post-fit residual is far below the stream's mean residual when many
    // bins are open, nudging selection toward bins that leave balanced,
    // reusable leftovers (reduces residual variance / dead-space dispersion).
    if post_residual > 0 && bin_residual != bin_capacity && open_bins_count > 6 {
        let pr = post_residual as f64;
        let dev = (pr - mean_residual.max(0.0)) / cap_f;
        if dev < 0.0 {
            score += (-dev) * 4.0 * ((open_bins_count as f64 - 6.0) / 10.0).min(1.0) * (0.3 + 0.7 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap_f = bin_capacity as f64;
    let resid_f = bin_residual as f64;
    let slack = bin_residual as i64 - item_size as i64;

    if post_residual == 0 {
        score -= 65.0;
    }
    if slack >= 0 && slack <= 4 {
        score -= 20.0;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0 + 22.0 * (1.0 - progress);
        } else if post_residual > next_item_size {
            let slack_after_next = post_residual - next_item_size;
            score -= 25.0 - (slack_after_next as f64).min(40.0) * 0.3;
            if slack_after_next > 40 {
                score += (slack_after_next as f64 - 40.0) * 0.2;
            }
        } else {
            let shortfall = (next_item_size - post_residual) as f64;
            score += shortfall * 0.85;
            let half_next = next_item_size / 2;
            if post_residual > 0 && post_residual < half_next {
                score += 14.0;
            }
        }
    } else {
        score -= 10.0;
    }

    if post_residual > 0 {
        let waste_ratio = post_residual as f64 / cap_f;
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        let severity = 1.4 - 0.8 * tightness;
        if post_residual < next_item_size && next_item_size > 0 {
            let unusability = 1.0 - (post_residual as f64 / next_item_size as f64);
