        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left >= 1 && fresh_left <= 12 {
                score -= 4.0 * (1.0 - fresh_left as f64 / 12.0) * (0.6 + 0.4 * (1.0 - progress));
            }
        }

        // MUTATION (gen 18): two-item horizon exactness (retained)
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left >= 1 && fresh_left <= 6 {
                score -= 8.0 * (1.0 - fresh_left as f64 / 6.0) * (0.7 + 0.3 * (1.0 - progress));
            }
        }

        // MUTATION (gen 18): scarcity override (retained)
        if fitting_bins_count == 1 && next_item_size > 0 {
            let open_waste = bin_residual.saturating_sub(item_size) as f64;
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as f64;
            if open_waste > fresh_left + 18.0 {
                score -= 4.0 * ((open_waste - fresh_left - 18.0) / 20.0).min(1.0) * (0.6 + 0.4 * (1.0 - progress));
            }
        }

        // MUTATION (gen 18): fresh-bin reuse-vs-waste parity gate — when the
        // fresh leftover lands in the dense 10..=40 band while the open bin's
        // post-fit waste exceeds it by >10, opening fresh is justified; but
        // when the fresh leftover is large and open waste is small, penalize.
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            let open_waste = bin_residual.saturating_sub(item_size) as f64;
            let fl = fresh_left as f64;
            if fl >= 10.0 && fl <= 40.0 && open_waste > fl + 10.0 {
                score -= 6.0 * (1.0 - (fl - 10.0).abs() / 15.0).max(0.0) * (0.6 + 0.4 * (1.0 - progress));
            } else if fl > 45.0 && open_waste <= 12.0 {
                score += 5.0 * (0.5 + 0.5 * progress);
            }
        }

        // MUTATION (gen 18): late-stream fresh-bin suppression — near the end
        // of the stream, a fresh bin's leftover can almost never be reused;
        // penalize proportional to the leftover size.
        if progress > 0.85 && next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left > 0 {
                score += 2.0 + 0.10 * (fresh_left as f64).min(60.0);
            } else {
                score -= 5.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap_f = bin_capacity as f64;
    let resid_f = bin_residual as f64;

    if post_residual == 0 {
        score -= 65.0;
    }

    let slack = bin_residual as i64 - item_size as i64;
    if slack >= 0 && slack <= 4 {
        score -= 20.0;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0 + 22.0 * (1.0 - progress);
        } else if post_residual > next_item_size {
            let slack_after_next = post_residual - next_item_size;
            score -= 25.0 - (slack_after_next as f64).min(40.0) * 0.3;
            if slack_after_next > 40 {
                score += (slack_after_next as f64 - 40.0) * 0.2;
            }
        } else {
            let shortfall = (next_item_size - post_residual) as f64;
