            score += 0.0004 * pr * pr * pr * (0.5 + 0.7 * tightness);
        }

        // MUTATION (gen 19): scarcity-locked chain continuity — when few bins
        // fit the item and the fresh bin supports a two-item chain, deepen the
        // preference for opening to preserve future compaction options.
        if fitting_bins_count <= 2 && next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left >= next_item_size {
                let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0);
                score -= 5.0 * scarcity * (0.5 + 0.5 * (1.0 - progress));
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
