        // gen-19 retained: open-bin salvage ceiling
        if fitting_bins_count >= 1 && next_item_size > 0 {
            let open_after = bin_residual.saturating_sub(item_size);
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if open_after < next_item_size && fresh_left >= next_item_size + 10 {
                score -= 3.0 + 3.0 * (1.0 - progress);
            }
        }

        // gen-19 retained: dead-space convexity tail extension
        if post_residual > 60 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.0004 * pr * pr * pr * (0.5 + 0.7 * tightness);
        }

        // gen-19 retained: scarcity-locked chain continuity
        if fitting_bins_count <= 2 && next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left >= next_item_size {
                let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0);
                score -= 5.0 * scarcity * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // MUTATION (gen 20): dead-space convexity floor deepening — the diagnosed
        // weakness is residual dead space; strengthen the cubic waste penalty on
        // open bins mid-stream where it compounds most, scaled by tightness.
        if post_residual > 0 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.00015 * pr * pr * pr * (0.4 + 0.8 * tightness) * (0.6 + 0.6 * progress);
        }

        // MUTATION (gen 20): near-exact fill preference sharpening — when the
        // post residual is within 2 of zero, deepen the reward slightly to
        // squeeze out the last few wasted bins.
        if post_residual >= 1 && post_residual <= 2 {
            score -= 6.0 * (1.0 - 0.3 * progress);
        }

        // MUTATION (gen 20): three-item chain lookahead — if a fresh/open bin
        // can absorb item, next item, and leave room matching the mean residual
        // band (a likely recurring size), reward the compaction horizon.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let after_two = bin_capacity - item_size - next_item_size;
            let target = mean_residual.max(1.0);
            if (after_two as f64 - target).abs() <= 4.0 {
                score -= 5.0 * (1.0 - 0.4 * progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
