            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.00035 * pr * pr * pr * (0.5 + 0.7 * tightness);
        }

        // MUTATION (gen 22): residual-dispersion dead-space guard widening —
        // lower the mean-residual trigger from 0.45 to 0.38 of capacity and
        // raise the slope slightly, so compaction pressure kicks in earlier
        // on slack-heavy streams.
        if post_residual > 0 && bin_residual != bin_capacity && mean_residual > 0.38 * cap_f {
            let pr = post_residual as f64;
            score += 0.075 * pr * (0.4 + 0.6 * progress);
        }

        // MUTATION (gen 22): open-bin salvage floor — when an open bin would
        // be left with a residual in the 5–15 "stranded zone" (too small for
        // typical items), penalize choosing it mildly unless it empties the
        // bin exactly; complements the fresh-bin parity logic.
        if bin_residual != bin_capacity && post_residual >= 5 && post_residual <= 15 {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score += 2.0 * (1.0 - (post_residual as f64 - 5.0) / 10.0) * scarcity * (0.6 + 0.4 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap_f = bin_capacity as f64;
    let resid_f = bin_residual as f64;
    let slack = bin_residual as i64 - item_size as i64;

    // --- 2-step lookahead core ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0 + 22.0 * (1.0 - progress);
        } else if post_residual > next_item_size {
            let slack_after_next = post_residual - next_item_size;
            score -= 25.0 - (slack_after_next as f64).min(40.0) * 0.3;
            if slack_after_next > 40 {
                score += (slack_after_next as f64 - 40.0) * 0.2;
            }
