        if next_item_size > 0 && mean_residual > 0.0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left > 0 && (fresh_left as f64 - mean_residual).abs() <= 3.0 {
                let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
                score -= 4.0 * (1.0 - (fresh_left as f64 - mean_residual).abs() / 3.0) * scarcity * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // MUTATION (gen 24): mid-band dead-space wedge — penalize open-bin
        // placements whose post_residual falls in the least reusable band
        // (just below typical next-item sizes), complementing the cubic
        // dead-space penalty with a localized wedge in the 8..=18 range.
        if post_residual >= 8 && post_residual <= 18 && next_item_size > 0 && post_residual < next_item_size && bin_residual != bin_capacity {
            let wedge = 1.0 - (post_residual as f64 - 8.0) / 10.0;
            score += 2.5 * wedge * (0.6 + 0.4 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
