        // near-full bins instead of short ones.
        if next_item_size > 0 && item_size + next_item_size < bin_capacity {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            let typical = mean_residual.max(1.0).min(cap_f * 0.5);
            if fresh_left as f64 >= typical * 0.5 {
                score -= 2.0 * (fresh_left as f64 / cap_f) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
