        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 14 && bin_residual != bin_capacity {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= 4.5 * (1.0 - (post_residual - next_item_size) as f64 / 14.0) * scarcity * (0.5 + 0.5 * progress);
        }

        // MUTATION (gen 25): exact-fill chain lookahead — when the fresh-bin
        // leftover after item+next is zero, an exact two-item fill of a new
        // bin is possible; reward it strongly to eliminate dead space at
        // creation time.
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 12.0 + 6.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
