                score -= 8.0 * (1.0 - fresh_left as f64 / 6.0) * (0.7 + 0.3 * (1.0 - progress));
            }
        }
        if fitting_bins_count == 1 && next_item_size > 0 {
            let open_waste = bin_residual.saturating_sub(item_size) as f64;
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as f64;
            if open_waste > fresh_left + 18.0 {
                score -= 4.0 * ((open_waste - fresh_left - 18.0) / 20.0).min(1.0) * (0.6 + 0.4 * (1.0 - progress));
            }
        }
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left >= 7 && fresh_left <= 10 {
                score -= 5.0 * (1.0 - fresh_left as f64 / 10.0) * (0.6 + 0.4 * (1.0 - progress));
            }
        }

        // gen 19 retained: fresh-bin horizon parity sharpening
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left == next_item_size {
                score -= 14.0 + 6.0 * (1.0 - progress);
            }
        }

        // gen 19 retained: open-bin salvage ceiling
        if fitting_bins_count >= 1 && next_item_size > 0 {
            let open_after = bin_residual.saturating_sub(item_size);
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if open_after < next_item_size && fresh_left >= next_item_size + 10 {
                score -= 3.0 + 3.0 * (1.0 - progress);
            }
        }

        // gen 19 retained: dead-space convexity tail extension
        if post_residual > 60 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.0004 * pr * pr * pr * (0.5 + 0.7 * tightness);
        }

        // gen 19 retained: scarcity-locked chain continuity
        if fitting_bins_count <= 2 && next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left >= next_item_size {
                let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0);
                score -= 5.0 * scarcity * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // gen 20: near-parity halo
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if d > 0 && d <= 2 {
                score -= (14.0 - 4.0 * d as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // gen 20: dead-space convexity gain
        if post_residual > 0 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.0001 * pr * pr * pr * (0.5 + 0.7 * tightness);
        }

        // gen 20: tight-fit preservation
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 && bin_residual != bin_capacity {
            score -= 5.0 + 4.0 * (1.0 - progress);
        }

        // gen 21: halo widening to ±4
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if d > 2 && d <= 4 {
                score -= (6.0 - 1.5 * (d - 2) as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // gen 21: dead-space convexity escalation
        if post_residual > 0 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.00022 * pr * pr * pr * (0.5 + 0.7 * tightness);
        }

        // gen 21: tight-fit preservation widening
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 && bin_residual != bin_capacity {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= (3.0 + 3.0 * (1.0 - progress)) * scarcity;
        }

        // gen 21: residual-dispersion dead-space guard
        if post_residual > 0 && bin_residual != bin_capacity && mean_residual > 0.45 * cap_f {
            let pr = post_residual as f64;
            score += 0.06 * pr * (0.4 + 0.6 * progress);
        }

        // gen 22: dead-space convexity escalation
        if post_residual > 0 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.00032 * pr * pr * pr * (0.5 + 0.7 * tightness);
        }

        // gen 22: open-bin compaction pull
        if post_residual > 0 && bin_residual != bin_capacity && fitting_bins_count >= 2 {
            let pr = post_residual as f64;
            let band = ((pr - mean_residual.max(0.0)) / cap_f).abs();
            score -= 2.0 * (1.0 - band.min(1.0)) * (0.4 + 0.6 * progress);
        }

        // gen 22: fresh-bin halo extension to ±6
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if d > 4 && d <= 6 {
                score -= (3.0 - 1.0 * (d - 4) as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // gen 22: late-stream waste-floor guard
        if post_residual > 0 && bin_residual != bin_capacity && progress > 0.66 && post_residual < next_item_size.max(20) {
            let unus = 1.0 - (post_residual as f64 / (next_item_size.max(20) as f64));
            score += 4.0 * unus * ((progress - 0.66) / 0.34).min(1.0);
        }

        // gen 23: dead-space convexity escalation
        if post_residual > 0 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.00045 * pr * pr * pr * (0.5 + 0.7 * tightness);
        }

        // gen 23: compaction pull strengthening
        if post_residual > 0 && bin_residual != bin_capacity && fitting_bins_count >= 2 {
            let pr = post_residual as f64;
            let band = ((pr - mean_residual.max(0.0)) / cap_f).abs();
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= (2.5 + 1.5 * scarcity) * (1.0 - band.min(1.0)) * (0.4 + 0.6 * progress);
        }

        // gen 23: fresh-bin halo extension to ±8
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if d > 6 && d <= 8 {
                score -= (2.0 - 0.75 * (d - 6) as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // gen 23: late-stream consolidation sharpening
        if post_residual > 0 && bin_residual != bin_capacity && progress > 0.60 && post_residual < next_item_size.max(20) {
            let unus = 1.0 - (post_residual as f64 / (next_item_size.max(20) as f64));
            score += 6.0 * unus * ((progress - 0.60) / 0.40).min(1.0);
        }

        // gen 23: residual-variance floor bonus
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 && bin_residual != bin_capacity {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / 10.0) * scarcity * (0.5 + 0.5 * progress);
        }

        // MUTATION (gen 26): dead-space convexity escalation continues — the
        // cubic family's momentum (0.0001 -> 0.00022 -> 0.00032 -> 0.00045)
        // keeps compressing residual dispersion; raise the extra coefficient
        // to 0.00062 while capping the cubic term so very large residuals do
        // not overwhelm the base scoring scale.
        if post_residual > 0 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            let cubic = 0.00062 * pr * pr * pr;
            score += cubic.min(18.0) * (0.5 + 0.7 * tightness);
        }

        // MUTATION (gen 26): compaction pull refinement — strengthen the
        // mean-residual band homogenization (2.5+1.5 -> 3.5+2.0 scarcity)
        // and extend it to single-fitting bins where variance concentrates.
        if post_residual > 0 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let band = ((pr - mean_residual.max(0.0)) / cap_f).abs();
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            let gate = if fitting_bins_count >= 2 { 1.0 } else { 0.4 };
            score -= (3.5 + 2.0 * scarcity) * gate * (1.0 - band.min(1.0)) * (0.4 + 0.6 * progress);
        }

        // MUTATION (gen 26): fresh-bin halo extension to ±12 — the widening
        // trend (±2 -> ±4 -> ±6 -> ±8) keeps capturing chain continuations;
        // extend with a shallow decay to ±12, gated to early/mid stream where
        // lookahead chains dominate.
        if next_item_size > 0 && progress < 0.85 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if d > 8 && d <= 12 {
                score -= (1.5 - 0.3 * (d - 8) as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // MUTATION (gen 26): late-stream consolidation sharpening — onset
        // pulled earlier (0.60 -> 0.54) and weight raised (6.0 -> 7.5) to
        // force residual consolidation into the final stretch.
        if post_residual > 0 && bin_residual != bin_capacity && progress > 0.54 && post_residual < next_item_size.max(20) {
            let unus = 1.0 - (post_residual as f64 / (next_item_size.max(20) as f64));
            score += 7.5 * unus * ((progress - 0.54) / 0.46).min(1.0);
        }

        // MUTATION (gen 26): residual-variance floor bonus widening — the
        // small-tail reward band (<=10) is extended to <=14 with a decay,
        // rewarding more reusable near-exact placements to compress Sigma_res.
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 14 && bin_residual != bin_capacity {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            let tail = (post_residual - next_item_size) as f64;
            let w = if tail <= 10.0 { 3.5 * (1.0 - tail / 10.0) } else { 3.5 * 0.35 * (1.0 - (tail - 10.0) / 4.0) };
            score -= w * scarcity * (0.5 + 0.5 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap_f = bin_capacity as f64;
    let resid_f = bin_residual as f64;
    let slack = bin_residual as i64 - item_size as i64;

    if post_residual == 0 {
        score -= 65.0;
    }
    if slack >= 0 && slack <= 4 {
        score -= 20.0;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0 + 22.0 * (1.0 - progress);
        } else if post_residual > next_item_size {
            let slack_after_next = post_residual - next_item_size;
            score -= 25.0 - (slack_after_next as f64).min(40.0) * 0.3;
            if slack_after_next > 40 {
                score += (slack_after_next as f64 - 40.0) * 0.2;
            }
        } else {
            let shortfall = (next_item_size - post_residual) as f64;
            score += shortfall * 0.85;
            let half_next = next_item_size / 2;
            if post_residual > 0 && post_residual < half_next {
                score += 14.0;
            }
        }
    } else {
        score -= 10.0;
    }

    if post_residual > 0 {
        let waste_ratio = post_residual as f64 / cap_f;
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        let severity = 1.4 - 0.8 * tightness;
        if post_residual < next_item_size && next_item_size > 0 {
            let unusability = 1.0 - (post_residual as f64 / next_item_size as f64);
            score += 16.0 * unusability * (1.0 - 0.5 * progress) * severity;
            if post_residual < 10 {
                score += 9.0 * severity * (1.0 - 0.4 * progress);
            }
        } else if waste_ratio < 0.05 {
            score += 7.0 * (1.0 - progress) * severity;
        } else if waste_ratio < 0.10 && post_residual < 40 {
            score += 3.0 * (1.0 - progress) * severity;
        }
    }

    if resid_f > mean_residual + 20.0 && item_size < 30 {
        if next_item_size == 0 || post_residual < next_item_size {
            score += 10.0;
        }
    } else if resid_f < mean_residual - 20.0 {
        score -= 8.0;
    }

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
        if post_residual >= 10 {
            score -= 10.0;
        }
    }

    if open_bins_count > 8 {
        score += (resid_f / cap_f) * 6.0;
    }
    score -= (open_bins_count as f64).ln().max(0.0) * 3.0;

    if post_residual >= 25 {
        score -= 4.0;
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 15 {
            score -= 6.0;
        }
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 20 {
            let sweet = if after_next <= 60 { 3.0 } else { 0.0 };
            score -= 5.0 + 5.0 * (1.0 - progress) + sweet;
        }
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 6.0 * (post_residual as f64 / cap_f) * 10.0;
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let strandedness = 1.0 - (post_residual as f64 / next_item_size as f64);
        let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0);
        score += 9.0 * strandedness * scarcity;
    }

    if post_residual >= 20 && post_residual <= 60 {
        score -= 3.0 + 4.0 * (1.0 - progress);
    }
    if post_residual >= 1 && post_residual <= 5 {
        score += 5.0;
    }

    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap > 0 && gap <= 8 {
            score -= 4.0 + 3.0 * (1.0 - progress);
        }
    }

    if item_size > 0 && bin_residual % item_size == 0 && bin_residual != bin_capacity {
        score -= 5.0;
        if post_residual == 0 {
            score -= 4.0;
        }
    }

    if next_item_size > 0 && post_residual == next_item_size && progress < 0.4 {
        score -= 6.0;
    }

    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let chain_left = bin_residual - item_size - next_item_size;
        if chain_left >= 15 && chain_left <= 55 {
            score -= 7.0 + 5.0 * (1.0 - progress);
        }
    }

    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap > 8 && gap <= 20 {
            score += 1.5;
        } else if gap > 20 && gap <= 35 {
            score += 3.5;
        }
    }

    if fitting_bins_count <= 2 && bin_residual != bin_capacity && post_residual <= 12 {
        score -= 6.0 + 4.0 * (1.0 - progress);
    }

    if open_bins_count > 12 && bin_residual != bin_capacity {
        score += 8.0 * (1.0 - resid_f / cap_f);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unus = 1.0 - (post_residual as f64 / next_item_size as f64);
        score += 4.5 * unus * (1.0 - 0.3 * progress);
    }

    if post_residual > 60 && post_residual < 100 {
        score += 2.5 + 2.0 * (1.0 - progress);
    }

    if post_residual == 0 && bin_residual != bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
        score -= 8.0 * scarcity * (0.5 + 0.5 * (1.0 - progress));
    }

    if post_residual >= 46 && post_residual <= 59 && bin_residual != bin_capacity {
        let d = (post_residual as f64 - 46.0) / 13.0;
        score += 1.5 + 2.0 * d * (1.0 - 0.4 * progress);
    }

    if open_bins_count > 6 && bin_residual != bin_capacity {
        let crowd = ((open_bins_count as f64 - 6.0) / 14.0).min(1.0);
        score += (resid_f / cap_f) * 2.5 * crowd * (0.6 + 0.4 * progress);
    }

    if next_item_size > 0 && post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let nx = next_item_size as f64;
        let ratio = pr / nx.max(1.0);
        if ratio > 0.9 && ratio <= 1.0 {
            score -= 6.0 * (ratio - 0.9) * 10.0 * (0.6 + 0.4 * (1.0 - progress));
        }
    }

    if post_residual > 0 && fitting_bins_count >= 2 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        let alignment = 1.0 - ((pr - 30.0).abs() / 30.0).min(1.0);
        score -= 3.5 * alignment * tightness * (0.4 + 0.6 * (1.0 - progress));
    }

    if post_residual == 0 && slack >= 0 && slack <= 4 && bin_residual != bin_capacity {
        score -= 3.0 + 2.0 * (1.0 - progress);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && bin_residual != bin_capacity {
        let alternatives = (fitting_bins_count as f64).max(1.0);
        score += (3.0 / alternatives.sqrt()) * (1.0 - 0.3 * progress);
    }

    if post_residual == 0 && bin_residual != bin_capacity {
        let crowd = ((open_bins_count as f64 - 4.0).max(0.0) / 12.0).min(1.0);
        score -= 6.0 * crowd + 4.0 * progress;
    }

    if post_residual >= 1 && post_residual <= 12 && next_item_size > 0 && next_item_size <= post_residual && bin_residual != bin_capacity {
        let closeness = 1.0 - (post_residual - next_item_size) as f64 / 12.0;
        score -= 3.5 * closeness * (0.4 + 0.6 * progress);
    }

    if slack >= 0 && fitting_bins_count > 3 && bin_residual != bin_capacity {
        let sl = slack as f64;
        if sl > 8.0 {
            score += 0.06 * (sl - 8.0).min(50.0) * (0.5 + 0.5 * progress);
        }
    }

    if post_residual == 0 && open_bins_count > 8 && bin_residual != bin_capacity {
        score -= 2.0 * ((open_bins_count - 8) as f64).min(10.0) * 0.4 * (0.5 + 0.5 * progress);
    }

    if post_residual >= 1 && post_residual <= 8 && next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        score -= 2.5 * (1.0 - post_residual as f64 / 8.0) * (0.5 + 0.5 * progress);
    }

    // gen 22 retained mutations (condensed but behaviorally identical families)
    if post_residual > 14 && post_residual < 46 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let peak = 1.0 - ((pr - 30.0).abs() / 16.0).min(1.0);
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        score += 0.09 * pr * peak * (0.7 + 0.6 * tightness);
    }

    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let tail = post_residual - next_item_size;
        if tail >= 12 && tail <= 30 {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= (4.0 + 3.0 * (1.0 - progress)) * (1.0 - (tail as f64 - 12.0).abs() / 18.0) * scarcity;
        }
    }

    if slack >= 0 && slack <= 6 && fitting_bins_count <= 3 && bin_residual != bin_capacity {
        let sl = slack as f64;
        score -= 6.0 * (1.0 - sl / 6.0) * (1.0 / (fitting_bins_count as f64).max(1.0)) * (0.6 + 0.4 * progress);
    }

    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        score += 0.0004 * pr * pr * pr * (0.5 + 0.7 * tightness);
    }

    if post_residual > 0 && next_item_size > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let nx = next_item_size as f64;
        let mismatch = ((pr - nx).abs() / nx.max(1.0)).min(1.5);
        if pr > nx {
            let tail = pr - nx;
            if tail > 15.0 && tail < 60.0 {
                score += 0.10 * (tail - 15.0) * (1.0 - 0.5 * progress);
            }
        } else {
            score += 2.0 * mismatch * (1.0 - 0.3 * progress);
        }
    }

    if post_residual >= 30 && post_residual <= 55 && bin_residual != bin_capacity {
        let d = ((post_residual as f64 - 42.5).abs() / 12.5).min(1.0);
        score -= 5.0 * (1.0 - d) * (0.6 + 0.4 * (1.0 - progress));
    }

    if post_residual > 0 && bin_residual != bin_capacity {
        let scarcity_damp = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
        let pr = post_residual as f64;
        score += (0.05 * pr + 0.0018 * pr * pr) * scarcity_damp;
    }

    if post_residual >= 13 && post_residual <= 29 && next_item_size > 0 && post_residual < next_item_size && bin_residual != bin_capacity {
        let unus = 1.0 - (post_residual as f64 / next_item_size as f64);
        score += 7.0 * unus * (0.7 + 0.5 * progress);
    }

    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let tail = post_residual - next_item_size;
        if tail > 55 && tail < 100 {
            score += 3.0 * (1.0 - (tail as f64 - 55.0) / 45.0) * (0.5 + 0.5 * (1.0 - progress));
        } else if tail >= 60 {
            score += 2.0;
        }
    }

    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
