            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= (3.0 + 2.0 * scarcity) * (1.0 - band.min(1.0)) * (0.3 + 0.7 * progress);
        }

        // MUTATION (gen 27): fresh-bin halo extension to ±11 — the widening
        // trend (±2 -> ±4 -> ±6 -> ±8) keeps capturing near-parity chain
        // continuations; extend with a shallow decay to ±11.
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if d > 8 && d <= 11 {
                score -= (1.4 - 0.4 * (d - 8) as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // MUTATION (gen 27): late-stream consolidation sharpening — onset
        // pulled earlier (0.60 -> 0.55) with strength 6.0 -> 8.0, forcing
        // residual consolidation into fewer usable slacks during the final
        // stretch where the bin gap concentrates.
        if post_residual > 0 && bin_residual != bin_capacity && progress > 0.55 && post_residual < next_item_size.max(20) {
            let unus = 1.0 - (post_residual as f64 / (next_item_size.max(20) as f64));
            score += 8.0 * unus * ((progress - 0.55) / 0.45).min(1.0);
        }

        // MUTATION (gen 27): residual-variance floor bonus strengthening —
        // reward open-bin placements whose post_residual is small but
        // reusable (tight tail after next item), directly compressing
        // residual dispersion; widened to tail <= 14 with scarcity weighting.
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 14 && bin_residual != bin_capacity {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            let tail = (post_residual - next_item_size) as f64;
            score -= (4.5 * (1.0 - tail / 14.0) + 1.5 * (1.0 - tail / 14.0) * scarcity) * (0.4 + 0.6 * progress);
        }

        // MUTATION (gen 27): two-item lookahead exactness — when the fresh
        // bin can close exactly with item + next (or leave a tiny reusable
        // remainder <= 3), reward strongly; this complements the halo family
        // by rewarding zero-tail fresh-bin chains.
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left == 0 {
                score -= 12.0 + 8.0 * (1.0 - progress);
            } else if fresh_left <= 3 {
                score -= 6.0 * (1.0 - fresh_left as f64 / 3.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap_f = bin_capacity as f64;
    let resid_f = bin_residual as f64;

    if post_residual == 0 {
        score -= 65.0;
    }

    let slack = bin_residual as i64 - item_size as i64;
    if slack >= 0 && slack <= 4 {
        score -= 20.0;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0 + 22.0 * (1.0 - progress);
        } else if post_residual > next_item_size {
            let slack_after_next = post_residual - next_item_size;
            score -= 25.0 - (slack_after_next as f64).min(40.0) * 0.3;
            if slack_after_next > 40 {
                score += (slack_after_next as f64 - 40.0) * 0.2;
            }
        } else {
            let shortfall = (next_item_size - post_residual) as f64;
            score += shortfall * 0.85;
            let half_next = next_item_size / 2;
            if post_residual > 0 && post_residual < half_next {
                score += 14.0;
            }
        }
    } else {
        score -= 10.0;
    }

    if post_residual > 0 {
        let waste_ratio = post_residual as f64 / cap_f;
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        let severity = 1.4 - 0.8 * tightness;
        if post_residual < next_item_size && next_item_size > 0 {
            let unusability = 1.0 - (post_residual as f64 / next_item_size as f64);
            score += 16.0 * unusability * (1.0 - 0.5 * progress) * severity;
            if post_residual < 10 {
