            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if d > 4 && d <= 8 {
                score -= (3.0 - 0.35 * (d - 4) as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // gen 23: late-stream consolidation sharpening
        if post_residual > 0 && bin_residual != bin_capacity && progress > 0.60 && post_residual < next_item_size.max(20) {
            let unus = 1.0 - (post_residual as f64 / (next_item_size.max(20) as f64));
            score += 6.0 * unus * ((progress - 0.60) / 0.40).min(1.0);
        }

        // gen 23: residual-variance floor bonus
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 && bin_residual != bin_capacity {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / 10.0) * scarcity * (0.5 + 0.5 * progress);
        }

        // MUTATION (gen 25): dead-space convexity escalation
        if post_residual > 0 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.00060 * pr * pr * pr * (0.5 + 0.7 * tightness);
        }

        // MUTATION (gen 25): compaction pull strengthening
        if post_residual > 0 && bin_residual != bin_capacity && fitting_bins_count >= 2 {
            let pr = post_residual as f64;
            let band = ((pr - mean_residual.max(0.0)) / cap_f).abs();
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= (3.0 + 1.5 * scarcity) * (1.0 - band.min(1.0)) * (0.4 + 0.6 * progress);
        }

        // MUTATION (gen 25): open-bin parity halo
        if next_item_size > 0 && bin_residual != bin_capacity {
            let pr = post_residual as i64;
            let nx = next_item_size as i64;
            let d = (pr - nx).abs();
            if d <= 3 {
                let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
                score -= (8.0 - 2.0 * d as f64) * (0.5 + 0.5 * (1.0 - progress)) * scarcity;
            }
        }

        // MUTATION (gen 25): two-item lookahead compaction
        if next_item_size > 0 && item_size + next_item_size <= bin_residual && bin_residual != bin_capacity {
            let leftover = bin_residual - item_size - next_item_size;
            if leftover <= 8 {
                score -= (9.0 - leftover as f64) * (0.6 + 0.4 * (1.0 - progress));
            }
        }

        // MUTATION (gen 25): mid-residual dead-band penalty
        if post_residual >= 20 && post_residual <= 35 && bin_residual != bin_capacity && open_bins_count > 6 {
            let crowd = ((open_bins_count as f64 - 6.0) / 10.0).min(1.0);
            let depth = 1.0 - ((post_residual as f64 - 27.5).abs() / 7.5).min(1.0);
            score += 4.0 * depth * crowd * (0.5 + 0.5 * progress);
        }

        // MUTATION (gen 25): fresh-bin exact-closure guard
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            let open_waste = bin_residual.saturating_sub(item_size);
            if fresh_left > 0 && fresh_left < next_item_size && open_waste == 0 {
                score += 10.0 * (1.0 - progress);
            }
        }
    }

    // gen 22: dead-space convexity escalation (base cubic family)
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        score += 0.00030 * pr * pr * pr * (0.5 + 0.7 * tightness);
    }

    // gen 22: residual-dispersion guard
    if post_residual > 0 && bin_residual != bin_capacity && mean_residual > 0.45 * cap_f {
        let pr = post_residual as f64;
        score += 0.07 * pr * (0.4 + 0.6 * progress);
    }

    // gen 22: tight-fit preservation
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 && bin_residual != bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
        score -= (3.0 + 3.0 * (1.0 - progress)) * scarcity;
    }

    // gen 22: open-bin parity halo
    if next_item_size > 0 && bin_residual != bin_capacity {
        let pr = post_residual as i64;
        let nx = next_item_size as i64;
        let d = (pr - nx).abs();
        if d <= 3 {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= (8.0 - 2.0 * d as f64) * (0.5 + 0.5 * (1.0 - progress)) * scarcity;
        }
    }

    // gen 22: two-item lookahead compaction
    if next_item_size > 0 && item_size + next_item_size <= bin_residual && bin_residual != bin_capacity {
        let leftover = bin_residual - item_size - next_item_size;
        if leftover <= 8 {
            score -= (9.0 - leftover as f64) * (0.6 + 0.4 * (1.0 - progress));
        }
    }

    // gen 22: mid-residual dead-band penalty
    if post_residual >= 20 && post_residual <= 35 && bin_residual != bin_capacity && open_bins_count > 6 {
        let crowd = ((open_bins_count as f64 - 6.0) / 10.0).min(1.0);
        let depth = 1.0 - ((post_residual as f64 - 27.5).abs() / 7.5).min(1.0);
        score += 3.5 * depth * crowd * (0.5 + 0.5 * progress);
    }

    // MUTATION (gen 28): sigmoid reuse halo — smooth logistic preference for
    // open bins whose post-fit residual sits near the 25–35 reusable zone,
    // combining fine-grained residual fitting with lookahead chain readiness
    // (targets the diagnosed dead-space weakness with a smooth kernel).
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let reuse = 1.0 / (1.0 + (-(pr - 30.0) / 12.0).exp());
        let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
        score -= 3.5 * reuse * scarcity * (0.5 + 0.5 * (1.0 - progress));
    }

    // MUTATION (gen 28): perfect-closure lookahead bonus — when the current
    // item plus the next item exactly fills the bin, reward hard; when it
    // leaves <= 4 dead space, reward proportionally. Extends the two-item
    // compaction family with exact-closure detection.
    if next_item_size > 0 && item_size + next_item_size == bin_residual && bin_residual != bin_capacity {
        score -= 12.0 + 6.0 * (1.0 - progress);
    } else if next_item_size > 0 && item_size + next_item_size <= bin_residual && bin_residual != bin_capacity {
        let leftover = bin_residual - item_size - next_item_size;
        if leftover > 8 && leftover <= 14 {
            score -= 2.0 * (1.0 - (leftover - 8) as f64 / 6.0) * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // MUTATION (gen 28): stranded-residual quadratic wedge — penalize
    // post-fit residuals that cannot hold the next item but are large
    // enough to be "wasted capacity", scaled by how many open bins could
    // still absorb the next item instead (lookahead trade-off).
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && bin_residual != bin_capacity {
        let miss = (next_item_size - post_residual) as f64;
        let crowd = ((open_bins_count as f64 - 4.0).max(0.0) / 12.0).min(1.0);
        score += 0.020 * miss * miss * crowd * (0.6 + 0.4 * progress);
    }

    // MUTATION (gen 28): fresh-bin last-resort tightening — when few bins
    // fit and the fresh-bin leftover after the next item is small (tight
    // chain), lower the fresh-bin score further so tight chains are not
    // broken by premature new-bin openings.
    if bin_residual == bin_capacity && fitting_bins_count >= 1 && fitting_bins_count <= 3 && next_item_size > 0 {
        let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
        if fresh_left < next_item_size {
            score += 6.0 * (1.0 - fresh_left as f64 / next_item_size.max(1) as f64) * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful again are heavily penalized. Anything below the smallest useful
    // chunk (min item size = 1, but practically below next item or tiny gap)
    // becomes "dead space".
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Dead-space threshold: residual too small for the lookahead item or
    // generally tiny gaps that nothing in [1,100] can use efficiently.
    if post_residual > 0 {
        // Gap unusable by next item -> likely dead weight.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 40.0 + 0.5 * post_residual as f64;
        }
        // Very small absolute gap: near-dead space, penalize superlinearly.
        if post_residual <= 10 {
            score += 60.0 * (11.0 - post_residual as f64);
        } else if post_residual <= 25 {
            score += 15.0;
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits (small but nonzero usable remainder).
    if post_residual > 0 && post_residual <= 15 {
        score -= 20.0;
    }

    // Last-chance bin pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open,
    // encourage consolidation when few are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and progress.
        score += 50.0 + 3.0 * open_bins_count as f64 + 30.0 * progress;
        // Opening a new bin is acceptable if this bin's fit would be terrible.
        if post_residual > 0 && post_residual < 5 {
            score -= 70.0;
        }
    } else {
        // Existing bin: mild consolidation bonus.
        score -= 2.0 * open_bins_count as f64;
    }

    // Prefer bins below mean residual (tighter bins) slightly.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Lookahead synergy: if next item fits exactly in post_residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size + 10 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
