        score -= 8.0;
    }

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 35.0;
        if post_residual >= 10 {
            score -= 10.0;
        }
    }

    // Open-bin pressure: spread when crowded, mild log penalty for new bins.
    if open_bins_count > 8 && !is_new_bin {
