    if post_residual >= 25 {
        score -= 4.0;
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 15 {
            score -= 6.0;
        }
    }

    // Mid-band residuals that pair well with future items.
    if post_residual >= 20 && post_residual <= 60 {
        score -= 3.0 + 4.0 * (1.0 - progress);
    }
    if post_residual >= 1 && post_residual <= 5 {
        score += 5.0;
    }

    // Chain feasibility: item + next fits with useful leftover.
    if next_item_size > 0 && item_size + next_item_size <= bin_residual && !is_new_bin {
        let chain_left = bin_residual - item_size - next_item_size;
        if chain_left <= 3 {
            score -= 10.0 + 6.0 * (1.0 - progress) + 3.0 / (fitting_bins_count as f64).max(1.0);
        } else if chain_left >= 15 && chain_left <= 55 {
            score -= 7.0 + 5.0 * (1.0 - progress);
        }
    }

    // Exact-fit scarcity bonus.
    if post_residual == 0 && !is_new_bin {
        let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
        score -= 8.0 * scarcity * (0.5 + 0.5 * (1.0 - progress));
        let crowd = ((open_bins_count as f64 - 5.0).max(0.0) / 15.0).min(1.0);
        score -= 7.0 * crowd * (0.5 + 0.5 * (1.0 - progress));
    }

    // Salvageability of residuals: prefer residuals close to reusable sizes.
    if post_residual > 0 && !is_new_bin {
        let pr = post_residual as f64;
        let nx = if next_item_size > 0 { next_item_size as f64 } else { 30.0 };
        let salvage = (pr / nx.max(1.0)).min(1.5);
        let crowd = ((open_bins_count as f64) / 14.0).min(1.0);
        if salvage < 1.0 {
            score += 4.5 * (1.0 - salvage) * crowd * (0.7 + 0.5 * progress);
        }
    }

    // NEW-BIN CANDIDATE: decide when opening a fresh bin beats a poor fit.
    if is_new_bin {
        score = 55.0 - 15.0 * progress;
        // If item + next nearly fills a fresh bin, opening is great.
        if next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if item_size + next_item_size == bin_capacity {
                score -= 9.0 + 8.0 * progress;
            } else if leftover == next_item_size {
                score -= 14.0 + 6.0 * (1.0 - progress);
            } else if leftover >= next_item_size {
                score -= 10.0;
            }
            // Near-parity halo: leftover close to next item size.
            let d = (leftover as i64 - next_item_size as i64).abs();
            if d > 0 && d <= 6 {
                score -= (14.0 - 2.0 * d as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
            // Tiny leftovers in a fresh bin are future dead space.
            if leftover >= 1 && leftover <= 6 {
                score -= 8.0 * (1.0 - leftover as f64 / 6.0) * (0.7 + 0.3 * (1.0 - progress));
            } else if leftover > 25 {
                score += 0.05 * ((leftover - 25) as f64).min(40.0);
            }
            // If next item won't fit after placing here, prefer fresh bin
            // only when the open-bin alternative wastes a lot.
            if fitting_bins_count >= 1 {
                let open_waste = bin_residual.saturating_sub(item_size);
                let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
                if fresh_left >= next_item_size && open_waste >= 20 {
                    score -= 4.0 + 0.1 * ((open_waste - 20) as f64).min(25.0);
                } else if fresh_left > 0 && fresh_left < 8 && open_waste <= 10 {
                    score += 5.0;
                }
            }
        }
        // Large items favor fresh bins.
        if item_size as f64 > 0.6 * cap_f {
            score -= 30.0;
        }
        if item_size > 60 && next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 8.0;
        }
        // Scarcity of alternatives.
        if fitting_bins_count > 2 {
            score += 20.0;
        }
        if fitting_bins_count == 1 && next_item_size > 0 {
            let open_waste = bin_residual.saturating_sub(item_size) as f64;
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as f64;
            if open_waste > fresh_left + 18.0 {
                score -= 4.0 * ((open_waste - fresh_left - 18.0) / 20.0).min(1.0) * (0.6 + 0.4 * (1.0 - progress));
            }
        }
        // Small items late in the stream: prefer existing bins.
        if item_size < 15 && progress > 0.5 && fitting_bins_count >= 1 {
            score += 15.0;
        }
        // If an open bin can take the item with tiny waste, avoid opening.
        if fitting_bins_count >= 1 && item_size <= bin_residual {
            let open_waste = bin_residual - item_size;
            if open_waste <= 5 {
                score += 25.0;
            } else if open_waste <= 15 {
                score += 8.0;
            }
        }
        // Late-stream: fresh bins accumulate waste.
        if progress > 0.6 {
            score += 7.5 * (progress - 0.6) * 25.0;
        }
        // Early stream with few bins: opening is cheap.
        if open_bins_count < 4 && progress < 0.3 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: prefer bins where item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Perfect or near-perfect fit bonus.
    if post_residual < 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 8.0;
    }

    // Dead-space penalty: leaving awkward slivers that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // Scarcity pressure: fewer fitting bins -> slightly favor using this one.
        score -= 3.0 / fitting_bins_count as f64;
    }

    // Lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chaining potential: reward, scaled by how well next item fills remainder.
            let chain = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 10.0 * chain;
        } else {
            // Next item won't fit here; penalize leaving large-ish residuals that
            // will strand unless they match common small sizes.
            if post_residual < next_item_size as f64 * 0.5 {
                score += 5.0;
            }
            // If next item is small and residual stays large, mild bonus to keep it open.
            if next_item_size <= 20 && post_residual >= next_item_size as f64 * 2.0 {
                score -= 3.0;
            }
        }
    } else {
        // Last item: strongly prefer consuming existing bins fully.
        score -= 40.0;
    }

    // Global state coupling: prefer bins with residual above the mean when
    // many bins are open (keep uniform residuals, easier future packing);
    // prefer below-mean bins when few bins are open (consolidate).
    let dev = bin_residual as f64 - mean_residual;
    if open_bins_count > 4 {
        score += 0.15 * dev;
    } else {
        score -= 0.15 * dev;
    }

    // Time horizon: early in stream, be conservative with new bins (favor
    // filling existing ones); late in stream, allow fresh bins for clean fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, discount late.
        score += 18.0 * (1.0 - progress) - 10.0 * progress;
        // But if nothing fits anywhere else, opening is fine.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Don't open a new bin when current bin already fits item tightly.
        if fit_ratio > 0.8 {
            score += 25.0;
        }
    } else {
        // Late stream: reward using existing bins even more to avoid sprawl.
        score -= 5.0 * progress;
    }

    // Mild preference for bins with small residuals overall (best-fit flavor),
    // scaled by how full the stream is.
    score += (bin_residual as f64 / bin_capacity as f64) * (2.0 + 4.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
