            score += 0.00022 * pr * pr * pr * (0.5 + 0.7 * tightness);
        }

        // gen 21: tight-fit preservation widening
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 && bin_residual != bin_capacity {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= (3.0 + 3.0 * (1.0 - progress)) * scarcity;
        }

        // gen 21: residual-dispersion dead-space guard
        if post_residual > 0 && bin_residual != bin_capacity && mean_residual > 0.45 * cap_f {
            let pr = post_residual as f64;
            score += 0.06 * pr * (0.4 + 0.6 * progress);
        }

        // gen 22: dead-space convexity escalation
        if post_residual > 0 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.00032 * pr * pr * pr * (0.5 + 0.7 * tightness);
        }

        // gen 22: open-bin compaction pull
        if post_residual > 0 && bin_residual != bin_capacity && fitting_bins_count >= 2 {
            let pr = post_residual as f64;
            let band = ((pr - mean_residual.max(0.0)) / cap_f).abs();
            score -= 2.0 * (1.0 - band.min(1.0)) * (0.4 + 0.6 * progress);
        }

        // gen 22: fresh-bin halo extension to ±6
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if d > 4 && d <= 6 {
                score -= (3.0 - 1.0 * (d - 4) as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // gen 22: late-stream waste-floor guard
        if post_residual > 0 && bin_residual != bin_capacity && progress > 0.66 && post_residual < next_item_size.max(20) {
            let unus = 1.0 - (post_residual as f64 / (next_item_size.max(20) as f64));
            score += 4.0 * unus * ((progress - 0.66) / 0.34).min(1.0);
        }

        // gen 23: dead-space convexity escalation
        if post_residual > 0 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.00045 * pr * pr * pr * (0.5 + 0.7 * tightness);
        }

        // gen 23: compaction pull strengthening
        if post_residual > 0 && bin_residual != bin_capacity && fitting_bins_count >= 2 {
            let pr = post_residual as f64;
            let band = ((pr - mean_residual.max(0.0)) / cap_f).abs();
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= (2.5 + 1.5 * scarcity) * (1.0 - band.min(1.0)) * (0.4 + 0.6 * progress);
        }

        // gen 23: fresh-bin halo extension to ±8
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if d > 6 && d <= 8 {
                score -= (2.0 - 0.75 * (d - 6) as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // gen 23: late-stream consolidation sharpening
        if post_residual > 0 && bin_residual != bin_capacity && progress > 0.60 && post_residual < next_item_size.max(20) {
            let unus = 1.0 - (post_residual as f64 / (next_item_size.max(20) as f64));
            score += 6.0 * unus * ((progress - 0.60) / 0.40).min(1.0);
        }

        // gen 23: residual-variance floor bonus
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 && bin_residual != bin_capacity {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / 10.0) * scarcity * (0.5 + 0.5 * progress);
        }

        // MUTATION (gen 30): dead-space convexity escalation continues — raise
        // the extra cubic coefficient from 0.00045 to 0.00060, further deepening
        // the diagnosed dead-space penalty on stranded mid/large residuals
        // (momentum: ContinueDirection on the cubic family).
        if post_residual > 0 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.00060 * pr * pr * pr * (0.5 + 0.7 * tightness);
        }

        // MUTATION (gen 30): compaction pull strengthening — reinforce the
        // mean-residual band homogenization (3.0 -> 4.0 base + scarcity term)
        // and extend it to all fitting bins >= 2 with a mild progress ramp,
        // targeting the residual-variance weakness Sigma_res (0.2981).
        if post_residual > 0 && bin_residual != bin_capacity && fitting_bins_count >= 2 {
            let pr = post_residual as f64;
            let band = ((pr - mean_residual.max(0.0)) / cap_f).abs();
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= (3.0 + 2.0 * scarcity) * (1.0 - band.min(1.0)) * (0.45 + 0.55 * progress);
        }

        // MUTATION (gen 30): fresh-bin halo extension to ±11 — continue the
        // widening trend (±2 -> ±4 -> ±6 -> ±8) with a shallow decay band
        // covering near-parity chain continuations up to 3 extra items.
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if d > 8 && d <= 11 {
                score -= (1.5 - 0.4 * (d - 8) as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // MUTATION (gen 30): late-stream consolidation sharpening — strengthen
        // the waste-floor guard (6.0 -> 8.0) and pull its onset earlier
        // (0.60 -> 0.55), forcing residual consolidation into fewer usable
        // slacks during the final stretch where the 45-bin gap concentrates.
        if post_residual > 0 && bin_residual != bin_capacity && progress > 0.55 && post_residual < next_item_size.max(20) {
            let unus = 1.0 - (post_residual as f64 / (next_item_size.max(20) as f64));
            score += 8.0 * unus * ((progress - 0.55) / 0.45).min(1.0);
        }

        // MUTATION (gen 30): residual-variance floor bonus strengthening —
        // reward open-bin placements whose post_residual is small but reusable
        // (within 12 of the next item), directly compressing residual
        // dispersion; widen the band from 10 to 12 and raise weight 3.5 -> 4.5.
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 12 && bin_residual != bin_capacity {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= 4.5 * (1.0 - (post_residual - next_item_size) as f64 / 12.0) * scarcity * (0.5 + 0.5 * progress);
        }

        // MUTATION (gen 30): dispersion-aware residual homogenization — a new
        // complementary term that penalizes open-bin placements whose
        // post_residual deviates strongly from the mean residual even when few
        // fitting bins exist, completing the compaction-pull coverage.
        if post_residual > 0 && bin_residual != bin_capacity && fitting_bins_count == 1 && progress > 0.3 {
            let pr = post_residual as f64;
            let band = ((pr - mean_residual.max(0.0)) / cap_f).abs();
            if band > 0.25 {
                score += 2.5 * (band - 0.25).min(0.75) * (0.5 + 0.5 * progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the post-residual: residue classes mod 25 (C/4)
    let pr = post_residual;
    let class = pr % 25;
    // Dead-space penalty: residuals in awkward classes are less reusable
    let awkward = match class {
        0 => 0.0,          // perfect quarter fill
        1..=5 => 3.0,
        6..=12 => 7.0,
        13..=19 => 10.0,
        _ => 5.0,
    };
    score += awkward;

    // Reward exact fits strongly
    if pr == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: does post_residual accommodate next item's class?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // next item can reuse the leftover: reward proportional to tightness
            let slack = (pr - next_item_size) as f64;
            score -= 12.0 - (slack / cap) * 10.0;
            // harmonic bonus if next item leaves another clean class
            if (pr - next_item_size) % 25 == 0 {
                score -= 8.0;
            }
        } else {
            // leftover too small for next item: penalize proportionally to waste
            score += (pr as f64 / cap) * 15.0;
        }
        // if next item is large, prefer bins that keep big residuals
        if next_item_size > 50 && pr < next_item_size {
            score += 6.0;
        }
    } else {
        // last item: minimize leftover
        score += 5.0;
    }

    // Last-chance bin before opening a new bin: strong reward to avoid new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        // baseline for a fresh bin: its residual is cap, so score already high;
        // discount slightly when many bins open / item is large
        score -= 5.0 + (item_size as f64 / cap) * 10.0;
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    // Fractional capacity thresholds on item size (harmonic split at C/2, C/3)
    if item_size > bin_capacity / 2 {
        score -= 4.0; // big items: placing them anywhere is fine, prefer quick placement
    }

    // Progress modulation: late in the stream, tighten packing (favor small residuals more)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.25 * progress;

    // Keep mean residual as soft reference: bins far below mean are worse to waste
    score += (mean_residual - post_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

