        if progress > 0.55 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size) as f64;
            let excess = leftover - mean_residual.max(0.0);
            if excess > 15.0 {
                score += 0.08 * (excess - 15.0).min(40.0);
            }
        }
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 9.0 + 8.0 * progress;
        }
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.0004 * fresh_left * fresh_left * fresh_left * (0.5 + 0.7 * tightness);
        }
        if fitting_bins_count >= 1 && next_item_size > 0 {
            let open_waste = bin_residual.saturating_sub(item_size) as f64;
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as f64;
            let excess = open_waste - fresh_left;
            if excess > 10.0 {
                score -= 2.5 * ((excess - 10.0) / 25.0).min(1.0) * (0.5 + 0.5 * (1.0 - progress));
            } else if excess < -10.0 {
                score += 2.0 * (((-excess) - 10.0) / 25.0).min(1.0) * (0.5 + 0.5 * progress);
            }
        }
        if progress > 0.7 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover > 0 && leftover <= 6 {
                score -= 7.0 * (progress - 0.7) * 10.0;
            } else if leftover > 40 {
                score += 4.0 * (progress - 0.7) * 10.0;
            }
        }
        if fitting_bins_count >= 1 && item_size > 55 {
            let open_waste = bin_residual.saturating_sub(item_size);
            if open_waste > 20 {
                score -= 3.0 + 0.06 * ((open_waste - 20) as f64).min(30.0) * (1.0 - 0.3 * progress);
            }
        }
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if d > 4 && d <= 6 {
                score -= (3.0 - 1.0 * (d - 4) as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if post_residual > 0 && fitting_bins_count >= 2 {
            let pr = post_residual as f64;
            let band = ((pr - mean_residual.max(0.0)) / cap_f).abs();
            score -= 2.5 * (1.0 - band.min(1.0)) * (0.4 + 0.6 * progress);
        }
        if post_residual > 0 && bin_residual != bin_capacity && progress > 0.60 && post_residual < next_item_size.max(20) {
            let unus = 1.0 - (post_residual as f64 / (next_item_size.max(20) as f64));
            score += 6.0 * unus * ((progress - 0.60) / 0.40).min(1.0);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 && bin_residual != bin_capacity {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / 10.0) * scarcity * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0 {
            let open_after = bin_residual.saturating_sub(item_size);
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if open_after < next_item_size && fresh_left >= next_item_size + 10 {
                score -= 3.0 + 3.0 * (1.0 - progress);
            }
        }
        if post_residual == 0 && bin_residual != bin_capacity {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= 18.0 + 10.0 * (1.0 - progress) + 6.0 * scarcity;
        }
        if post_residual > 0 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let reuse = 1.0 / (1.0 + (-(pr - 30.0) / 12.0).exp());
            score -= 5.0 * reuse * (0.5 + 0.5 * (1.0 - progress));
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_residual {
            let chain_left = bin_residual - item_size - next_item_size;
            if chain_left == 0 {
                score -= 12.0 + 8.0 * progress;
            } else if chain_left <= 4 {
                score -= (4.0 + (4 - chain_left) as f64 * 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left >= 13 && fresh_left <= 24 && fresh_left < next_item_size {
                score += 5.0 * (1.0 - (fresh_left as f64 - 13.0) / 11.0) * (0.6 + 0.4 * (1.0 - progress));
            }
        }
        if post_residual >= 6 && post_residual <= 12 && fitting_bins_count >= 3 && next_item_size > 0 && post_residual < next_item_size {
            score += 3.0 * (1.0 - (post_residual as f64 - 6.0) / 6.0) * (0.5 + 0.5 * progress);
        }

        // MUTATION (gen 30): exact-fill anchor reinforcement — the gen-26
        // exact-fill bonus is combined with a crowd term so that closing a
        // bin perfectly when many bins are open (maximizing consolidation)
        // is rewarded even more, directly attacking the 196-bin waste gap.
        if post_residual == 0 && bin_residual != bin_capacity {
            let crowd = ((open_bins_count as f64 - 4.0).max(0.0) / 12.0).min(1.0);
            score -= 6.0 * crowd * (0.5 + 0.5 * (1.0 - progress));
        }

        // MUTATION (gen 30): near-miss refusal shaping — when the open bin
        // misses an exact fill by a tiny margin (post_residual 1..=4) the
        // leftover is nearly unusable; penalize proportionally so near-perfect
        // placements that strand 1-4 units are avoided in favor of bins
        // leaving reusable tails.
        if post_residual >= 1 && post_residual <= 4 && bin_residual != bin_capacity {
            score += 4.0 * (1.0 - post_residual as f64 / 4.0) + 2.0 * (1.0 - progress);
        }

        // MUTATION (gen 30): fresh-bin third-item horizon — open a fresh bin
        // preferentially when item + next leaves room for a typical third
        // item (>= 25) or an exact two-chain; penalize fresh openings that
        // strand a large unreusable tail (> 60) mid-stream.
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left >= 25 {
                score -= 3.0 * (1.0 - progress);
            } else if fresh_left > 60 && progress < 0.75 {
                score += 2.5 + 0.02 * ((fresh_left - 60) as f64).min(30.0);
            }
        }

        // MUTATION (gen 30): slack-tightness compaction coupling — combine
        // fine-grained slack (bin_residual - item_size) with stream progress:
        // tiny slack (<= 2) is strongly rewarded late (compaction into
        // nearly-full bins), while large slack under crowding is penalized
        // to keep the open-bin pool tight.
        if slack >= 0 && slack <= 2 && bin_residual != bin_capacity {
            score -= 5.0 * (0.4 + 0.6 * progress);
        }
        if slack > 30 && open_bins_count > 10 && bin_residual != bin_capacity {
            score += 0.04 * ((slack - 30) as f64).min(50.0) * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (gen 30, open bins): sigmoid reuse attraction — apply the
    // logistic preference for post-residuals near the reusable 30 band to
    // open bins as well (parent only used it inside the fresh-bin branch),
    // homogenizing residual distribution and lowering Sigma_res.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let reuse = 1.0 / (1.0 + (-(pr - 30.0) / 12.0).exp());
        score -= 3.0 * reuse * (0.4 + 0.4 * (1.0 - progress));
    }

    // MUTATION (gen 30, open bins): exact-fill scarcity bonus mirrored from
    // the fresh-bin branch so perfect closures on open bins always win.
    if post_residual == 0 && bin_residual != bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
        score -= 10.0 + 6.0 * (1.0 - progress) + 5.0 * scarcity;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    // Medium gaps (< 20) that likely fit nothing (items >= 10... but sizes 1..100, so
    // penalize gaps smaller than typical small item sizes with graded penalty).
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            score -= 10.0;
        } else {
            // Next item won't fit here; dead space is locked in unless another item comes.
            score += 5.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (penalize opening new bins implicitly via new-bin candidate scoring).
    let open_pressure = open_bins_count as f64 * 0.5;
    score += open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, avoid wasting it on a bad fit.
    if fitting_bins_count == 1 && post_residual > 0 {
        score -= 20.0;
    }

    // Mean residual coupling: prefer bins whose post_residual is close to mean residual
    // (balanced packing), penalize outliers.
    let diff = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * diff;

    // Late in the stream, be more conservative with large leftover gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.2;

    // New-bin candidate: make empty bins attractive only when item is large relative
    // to typical residuals, i.e., a fresh bin has high utility for big items.
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64 - 30.0 * (item_size as f64 / bin_capacity as f64);
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap_f = bin_capacity as f64;
    let resid_f = bin_residual as f64;

    if post_residual == 0 {
        score -= 65.0;
    }

    let slack = bin_residual as i64 - item_size as i64;
    if slack >= 0 && slack <= 4 {
        score -= 20.0;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0 + 22.0 * (1.0 - progress);
        } else if post_residual > next_item_size {
            let slack_after_next = post_residual - next_item_size;
            score -= 25.0 - (slack_after_next as f64).min(40.0) * 0.3;
