    if next_item_size > 0 && bin_residual != bin_capacity {
        let pr = post_residual as i64;
        let nx = next_item_size as i64;
        let d = (pr - nx).abs();
        if d <= 3 {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= (8.0 - 2.0 * d as f64) * (0.5 + 0.5 * (1.0 - progress)) * scarcity;
        }
    }

    // gen 22: two-item lookahead compaction
    if next_item_size > 0 && item_size + next_item_size <= bin_residual && bin_residual != bin_capacity {
        let leftover = bin_residual - item_size - next_item_size;
        if leftover <= 8 {
            score -= (9.0 - leftover as f64) * (0.6 + 0.4 * (1.0 - progress));
        }
    }

    // gen 22: mid-residual dead-band penalty
    if post_residual >= 20 && post_residual <= 35 && bin_residual != bin_capacity && open_bins_count > 6 {
        let crowd = ((open_bins_count as f64 - 6.0) / 10.0).min(1.0);
        let depth = 1.0 - ((post_residual as f64 - 27.5).abs() / 7.5).min(1.0);
        score += 3.5 * depth * crowd * (0.5 + 0.5 * progress);
    }

    // MUTATION (gen 30): global closure-cascade (applies outside the fresh-
    // bin branch as well) — near-closure placements get a late-stream boost
    // so stranded slacks are harvested before the stream ends.
    if post_residual > 0 && post_residual <= 6 && bin_residual != bin_capacity && progress > 0.5 {
        score -= 4.0 * (1.0 - post_residual as f64 / 6.0) * ((progress - 0.5) / 0.5).min(1.0);
    }

    // MUTATION (gen 30): dead-band convexity tail — large stranded residuals
    // (> 60) receive an additional superlinear penalty scaled by progress,
    // squeezing the tail of the residual distribution at stream end.
    if post_residual > 60 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        score += 0.0004 * pr * pr * pr * (0.4 + 0.8 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (small dead space).
    if post_residual <= 3 {
        score -= 60.0;
    } else if post_residual <= 8 {
        score -= 25.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item fits exactly or nearly: big reward.
            if gap <= 2.0 {
                score -= 45.0;
            } else if gap <= 10.0 {
                score -= 20.0 / (1.0 + gap * 0.1);
            } else {
                score -= 10.0 / (1.0 + gap * 0.05);
            }
            // Penalize leaving a large awkward remainder the next item barely misses.
            if gap > 0.0 && gap <= 5.0 && post_residual < next_item_size + 5 {
                score += 5.0;
            }
        } else {
            // Next item does NOT fit: penalize proportional to overflow gap,
            // but less harsh if the remainder is tiny (already good fit).
            let overflow = (next_item_size as f64 - post_residual as f64).max(0.0);
            score += 0.35 * overflow;
            if post_residual <= 3 {
                score -= 30.0; // perfect fit outweighs lookahead mismatch
            }
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    let dev = mean_residual - post_residual as f64;
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mild penalty for opening new bins when many bins are already open
    // and the fit into an existing bin is decent.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 4.0; // fresh bin can host the pair coherently
        }
    }

    // Slight time-dependent tightening: later in stream, waste matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.1 * progress;

    score
}

