        if post_residual > 0 && bin_residual != bin_capacity && progress > 0.55 && post_residual < next_item_size.max(20) {
            let unus = 1.0 - (post_residual as f64 / (next_item_size.max(20) as f64));
            score += 7.5 * unus * ((progress - 0.55) / 0.45).min(1.0);
        }

        // MUTATION (gen 31): residual-variance floor bonus widening — extend
        // the tight-tail reward (post - next <= 10) to <= 14 with a decayed
        // amplitude, rewarding placements that leave reusable compact tails.
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 14 && bin_residual != bin_capacity {
            let tail = (post_residual - next_item_size) as f64;
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            let amp = if tail <= 10.0 { 3.5 * (1.0 - tail / 10.0) } else { 1.2 * (1.0 - (tail - 10.0) / 4.0) };
            score -= amp * scarcity * (0.5 + 0.5 * progress);
        }

        // MUTATION (gen 31): residual-dispersion quadratic damp — add a
        // complementary quadratic term that penalizes post_residuals far from
        // the mean-residual mode, directly attacking Sigma_res in the
        // mid-stream where the cubic family is weak.
        if post_residual > 0 && bin_residual != bin_capacity && fitting_bins_count >= 1 {
            let pr = post_residual as f64;
            let band = ((pr - mean_residual.max(0.0)) / cap_f).abs().min(1.5);
            score += 1.8 * band * band * (0.4 + 0.6 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 + 0.8 * progress) - 0.6 * norm_pr * norm_pr * (1.0 - progress);

    let mut score = 100.0 * poly;

    // Penalize dead space relative to next item: unusable gap is costly
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * (0.5 + progress);
    }
    // Reward residual that exactly fits the next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0 * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild penalty for leaving very small unusable slivers
    let sliver = norm_pr * (1.0 - norm_pr);
    score += 10.0 * sliver * sliver;

    // Smooth coupling with mean residual: prefer bins deviating from mean when mean is high
    let dev = pr - mean_residual;
    score -= 0.1 * dev * (mean_residual / cap);

    // Late stream: prefer tighter fills
    score += progress * norm_pr * 30.0;

    // New bin candidate: mild penalty so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap_f = bin_capacity as f64;
    let is_fresh = bin_residual == bin_capacity;

    // Dead-space avoidance: graded penalty for unusable small gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: exact-fit next item strongly favored; near-exact fit graded.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            let tail = post_residual - next_item_size;
            score -= 10.0;
            if tail <= 5 {
                score -= (5.0 - tail as f64) * 2.0 * (0.6 + 0.4 * (1.0 - progress));
            } else if tail > 20 {
                score += (tail as f64 - 20.0) * 0.15;
            }
        } else {
            score += 5.0;
            let miss = (next_item_size - post_residual) as f64;
            if miss <= 6.0 {
                score += 8.0 * (1.0 - miss / 6.0);
            }
        }
    }

    // Open-bin pressure: consolidate when many bins are open.
    let open_pressure = open_bins_count as f64 * 0.5;
    score += open_pressure * (post_residual as f64 / cap_f);

    // Last-chance bin: only bin that fits — protect it from bad fits.
    if fitting_bins_count == 1 && post_residual > 0 && !is_fresh {
        score -= 20.0;
        if post_residual >= 10 {
            score -= 10.0;
        }
    }

    // Mean residual coupling.
    let diff = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * diff;

    // Late-stream conservatism.
    score += progress * post_residual as f64 * 0.2;

    // Dead-space convexity: cubic penalty on stranded residuals, scaled by
    // residual tightness (compresses residual dispersion).
    if post_residual > 0 && !is_fresh {
        let pr = post_residual as f64;
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        score += 0.00045 * pr * pr * pr * (0.5 + 0.7 * tightness);
    }

    // Compaction pull: with alternatives, prefer bins whose post_residual
    // sits near the mean residual (reduces Sigma_res).
    if post_residual > 0 && !is_fresh && fitting_bins_count >= 2 {
        let pr = post_residual as f64;
        let band = ((pr - mean_residual.max(0.0)) / cap_f).abs();
        let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
        score -= (2.5 + 1.5 * scarcity) * (1.0 - band.min(1.0)) * (0.4 + 0.6 * progress);
    }

    // Tight-fit preservation: leaving a gap that exactly/nearly fits the next
    // item is valuable — reward small tails.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 && !is_fresh {
        let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
        score -= (3.0 + 3.0 * (1.0 - progress)) * scarcity;
    }

    // Reusable post-residual bonus: small but still fits next item.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 && !is_fresh {
        let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
        score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / 10.0) * scarcity * (0.5 + 0.5 * progress);
    }

    // Late-stream waste-floor guard.
    if post_residual > 0 && !is_fresh && progress > 0.60 && post_residual < next_item_size.max(20) {
        let unus = 1.0 - (post_residual as f64 / (next_item_size.max(20) as f64));
        score += 6.0 * unus * ((progress - 0.60) / 0.40).min(1.0);
    }

    // Chain lookahead: item + next item both fit in this bin.
    if next_item_size > 0 && item_size + next_item_size <= bin_residual && !is_fresh {
        let chain_left = bin_residual - item_size - next_item_size;
        if chain_left <= 3 {
            score -= 10.0 + 6.0 * (1.0 - progress);
        } else if chain_left >= 8 && chain_left <= 20 {
            score -= 5.0 * (1.0 - (chain_left as f64 - 8.0) / 12.0) * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // New-bin candidate: score the option of opening a fresh bin.
    if is_fresh {
        score = (bin_capacity - item_size) as f64 - 30.0 * (item_size as f64 / cap_f);
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        }
        score += 55.0 - 15.0 * progress;

        // Big items pair well with fresh capacity.
        if item_size as f64 > 0.6 * cap_f {
            score -= 30.0;
        }
        if next_item_size > 0 && item_size + next_item_size >= bin_capacity {
            score -= 45.0;
        }
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 9.0 + 8.0 * progress;
        }

        // Fresh-bin chain halo: fresh leftover near next item size is excellent.
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if fresh_left == nx {
                score -= 14.0 + 6.0 * (1.0 - progress);
            } else if d > 0 && d <= 2 {
                score -= (14.0 - 4.0 * d as f64) * (0.5 + 0.5 * (1.0 - progress));
            } else if d > 2 && d <= 4 {
                score -= (6.0 - 1.5 * (d - 2) as f64) * (0.5 + 0.5 * (1.0 - progress));
            } else if d > 4 && d <= 6 {
                score -= (3.0 - 1.0 * (d - 4) as f64) * (0.5 + 0.5 * (1.0 - progress));
            } else if d > 6 && d <= 8 {
                score -= (2.0 - 0.75 * (d - 6) as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
            // Tiny fresh leftovers are dead space.
            let fl = fresh_left.max(0) as u32;
            if fl >= 1 && fl <= 6 {
                score += 8.0 * (1.0 - fl as f64 / 6.0) * (0.7 + 0.3 * (1.0 - progress));
            } else if fl > 6 && fl <= 12 {
                score += 4.0 * (1.0 - fl as f64 / 12.0) * (0.6 + 0.4 * (1.0 - progress));
            }
        }

        // Compare against open-bin waste: prefer fresh bin when open bins
        // would strand much more space and the fresh bin can host next item.
        if fitting_bins_count >= 1 && next_item_size > 0 {
            let open_waste = bin_residual.saturating_sub(item_size);
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left >= next_item_size && open_waste >= 20 {
                score -= 4.0 + 0.1 * ((open_waste - 20) as f64).min(25.0);
            }
            let open_after = bin_residual.saturating_sub(item_size);
            let fresh_after = bin_capacity.saturating_sub(item_size);
            if open_after < next_item_size && fresh_after >= next_item_size {
                if next_item_size >= 25 && next_item_size <= 70 {
                    score -= 6.0 + 4.0 * (1.0 - progress);
                } else if next_item_size < 25 {
                    score += 4.0;
                }
            }
        }

        // With many open bins, opening new bins is expensive unless it
        // prevents large stranded waste.
        if fitting_bins_count > 2 {
            score += 20.0;
        }
        if open_bins_count > 10 && progress > 0.35 && progress < 0.7 {
            let roomy = (mean_residual / cap_f).min(1.0);
            score += 6.0 * roomy;
        }
        if item_size < 15 && progress > 0.5 && fitting_bins_count >= 1 {
            score += 15.0;
        }
        if progress > 0.6 {
            score += 7.5 * (progress - 0.6) * 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which "slot band" it lands in.
    // Capacity 100 -> classes of 20 (fifths). Smaller class index = tighter fit.
    let class = post_residual / 20;
    score += class as f64 * 6.0;

    // Perfect-harmonic residuals reward: post_residual exactly divisible by
    // common item sizes (10, 20, 25, 50) means the leftover is likely reusable.
    if post_residual > 0 {
        let reusable = (post_residual % 10 == 0) as i32
            + (post_residual % 20 == 0) as i32
            + (post_residual % 25 == 0) as i32
            + (post_residual % 50 == 0) as i32;
        score -= reusable as f64 * 5.0;
    } else {
        // Perfect closure is ideal.
        score -= 15.0;
    }

    // Dead-space penalty: tiny unusable remainders (1..=9) are waste.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead coupling: if next item fits the post residual exactly or
    // harmonically (multiple-of-10 relationship), reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
        if post_residual % next_item_size.max(1) == 0 {
            score -= 6.0;
        }
        if (post_residual as i32 - next_item_size as i32) < 10
            && (post_residual as i32 - next_item_size as i32) >= 0 {
            // next item leaves another dead space -> penalize
            score += 4.0;
        }
    } else if next_item_size > post_residual {
        // Next item won't fit here anyway; leftover becomes dead space unless reusable.
        if post_residual > 0 && post_residual < 10 {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 14.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // existing residuals are poor (high mean residual fragmentation).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 18.0;
        // At stream start, opening bins is cheap and useful.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 10.0;
        // If many open bins but none fit well (fragmented), new bin is fine.
        if mean_residual < 15.0 && open_bins_count > 2 {
            score -= 8.0;
        }
        // Harmonic alignment: a fresh bin is attractive if the item is a
        // "large class" item (integer division threshold at half capacity).
        if item_size > bin_capacity / 2 {
            score -= 6.0;
        }
    } else {
        // Existing bin: reward tightness relative to mean residual.
        score -= (mean_residual - bin_residual as f64) * 0.5;
        // Many open bins: prefer consolidating into existing bins.
        score += open_bins_count as f64 * 0.15;
    }

    // Integer-division threshold on item size: big items (>= 50) prefer
    // bins with residual close to their size (exact class match).
    if item_size >= 50 && bin_residual == item_size {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap_f = bin_capacity as f64;
    let resid_f = bin_residual as f64;
    let slack = bin_residual as i64 - item_size as i64;
    let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
    let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);

    if post_residual == 0 {
        score -= 65.0;
    }
    if slack >= 0 && slack <= 4 {
        score -= 20.0;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0 + 22.0 * (1.0 - progress);
        } else if post_residual > next_item_size {
            let slack_after_next = post_residual - next_item_size;
            score -= 25.0 - (slack_after_next as f64).min(40.0) * 0.3;
            if slack_after_next > 40 {
                score += (slack_after_next as f64 - 40.0) * 0.2;
            }
        } else {
            let shortfall = (next_item_size - post_residual) as f64;
            score += shortfall * 0.85;
            let half_next = next_item_size / 2;
            if post_residual > 0 && post_residual < half_next {
                score += 14.0;
            }
        }
    } else {
        score -= 10.0;
    }

    if post_residual > 0 {
        let waste_ratio = post_residual as f64 / cap_f;
        let severity = 1.4 - 0.8 * tightness;
        if next_item_size > 0 && post_residual < next_item_size {
            let unusability = 1.0 - (post_residual as f64 / next_item_size as f64);
            score += 16.0 * unusability * (1.0 - 0.5 * progress) * severity;
            if post_residual < 10 {
                score += 9.0 * severity * (1.0 - 0.4 * progress);
            }
        } else if waste_ratio < 0.05 {
            score += 7.0 * (1.0 - progress) * severity;
        } else if waste_ratio < 0.10 && post_residual < 40 {
            score += 3.0 * (1.0 - progress) * severity;
        }
    }

    if resid_f > mean_residual + 20.0 && item_size < 30 {
        if next_item_size == 0 || post_residual < next_item_size {
            score += 10.0;
        }
    } else if resid_f < mean_residual - 20.0 {
        score -= 8.0;
    }

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
        if post_residual >= 10 {
            score -= 10.0;
        }
    }

    if open_bins_count > 8 {
        score += (resid_f / cap_f) * 6.0;
    }
    score -= (open_bins_count as f64).ln().max(0.0) * 3.0;

    if post_residual >= 25 {
        score -= 4.0;
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 15 {
            score -= 6.0;
        }
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 20 {
            let sweet = if after_next <= 60 { 3.0 } else { 0.0 };
            score -= 5.0 + 5.0 * (1.0 - progress) + sweet;
        }
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 6.0 * (post_residual as f64 / cap_f) * 10.0;
        let strandedness = 1.0 - (post_residual as f64 / next_item_size as f64);
        let scar = 1.0 / (fitting_bins_count as f64).max(1.0);
        score += 9.0 * strandedness * scar;
        let unus = strandedness;
        score += 4.5 * unus * (1.0 - 0.3 * progress);
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 6.0 {
            score += 10.0 * (1.0 - miss / 6.0) * (0.5 + 0.5 * (1.0 - progress));
        }
        if next_item_size > 35 {
            score += 5.0 * unus * (1.0 - 0.4 * progress);
        }
        if open_bins_count > 10 {
            score += 1.5 * ((open_bins_count - 10) as f64).min(8.0) * 0.5;
        }
        let ratio = post_residual as f64 / next_item_size as f64;
        if ratio < 0.5 {
            score += 3.0 * (1.0 - ratio * 2.0) * (0.6 + 0.4 * (1.0 - progress));
        }
        if post_residual >= (next_item_size / 2) && bin_residual != bin_capacity {
            let reach = ratio;
            score -= 5.0 * (reach - 0.5) * 2.0 * scarcity * (0.5 + 0.5 * (1.0 - progress));
        }
        if post_residual >= 13 && post_residual <= 29 {
            score += 7.0 * unus * (0.7 + 0.5 * progress);
        }
        if post_residual >= 18 && post_residual <= 24 {
            score += 4.0 * unus * (0.6 + 0.4 * progress);
        }
        if post_residual >= 25 && post_residual <= 40 {
            let pr = post_residual as f64;
            score += 3.5 * unus * (1.0 - (pr - 25.0) / 15.0) * (0.6 + 0.4 * progress);
        }
    }

    if post_residual >= 20 && post_residual <= 60 {
        score -= 3.0 + 4.0 * (1.0 - progress);
    }
    if post_residual >= 1 && post_residual <= 5 {
        score += 5.0;
    }

    if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap > 0 && gap <= 8 {
            score -= 4.0 + 3.0 * (1.0 - progress);
        } else if gap > 8 && gap <= 20 {
            score += 1.5;
        } else if gap > 20 && gap <= 35 {
            score += 3.5;
        }
        if gap >= 10 && gap <= 45 {
            score -= 4.0 * (1.0 - gap as f64 / 45.0) * (1.0 - 0.5 * progress);
        }
        if gap >= 12 && gap <= 30 {
            score -= (4.0 + 3.0 * (1.0 - progress)) * (1.0 - (gap as f64 - 12.0).abs() / 18.0) * scarcity;
        }
        if gap >= 25 && gap <= 50 {
            score -= 4.5 * (1.0 - (gap as f64 - 25.0).abs() / 25.0) * (0.6 + 0.4 * (1.0 - progress));
        }
        if gap > 55 && gap < 100 {
            score += 3.0 * (1.0 - (gap as f64 - 55.0) / 45.0) * (0.5 + 0.5 * (1.0 - progress));
        } else if gap >= 60 {
            score += 2.0;
        }
        if gap <= 10 {
            score -= 3.5 * (1.0 - gap as f64 / 10.0) * scarcity * (0.5 + 0.5 * progress);
        }
    }

    if item_size > 0 && bin_residual % item_size == 0 && bin_residual != bin_capacity {
        score -= 5.0;
        if post_residual == 0 {
            score -= 4.0;
        }
    }

    if next_item_size > 0 && post_residual == next_item_size && progress < 0.4 {
        score -= 6.0;
    }

    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let chain_left = bin_residual - item_size - next_item_size;
        if chain_left >= 15 && chain_left <= 55 {
            score -= 7.0 + 5.0 * (1.0 - progress);
        }
        if chain_left >= 8 && chain_left <= 20 {
            score -= 5.0 * (1.0 - (chain_left as f64 - 8.0) / 12.0) * (0.5 + 0.5 * (1.0 - progress));
        }
        if chain_left <= 3 {
            score -= 10.0 + 6.0 * (1.0 - progress) + 3.0 / (fitting_bins_count as f64).max(1.0);
        }
        if chain_left <= 8 && bin_residual != bin_capacity {
            score -= (9.0 - chain_left as f64) * (0.6 + 0.4 * (1.0 - progress));
        }
    }

    if fitting_bins_count <= 2 && bin_residual != bin_capacity && post_residual <= 12 {
        score -= 6.0 + 4.0 * (1.0 - progress);
    }

    if open_bins_count > 12 && bin_residual != bin_capacity {
        score += 8.0 * (1.0 - resid_f / cap_f);
    }

    if post_residual > 60 && post_residual < 100 {
        score += 2.5 + 2.0 * (1.0 - progress);
    }

    if post_residual == 0 && bin_residual != bin_capacity {
        let scar = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
        score -= 8.0 * scar * (0.5 + 0.5 * (1.0 - progress));
        let crowd = ((open_bins_count as f64 - 4.0).max(0.0) / 12.0).min(1.0);
        score -= 6.0 * crowd + 4.0 * progress;
