    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score = 55.0 - 15.0 * progress;
        if next_item_size > 0 && item_size + next_item_size >= bin_capacity {
            score -= 45.0;
        }
        if item_size as f64 > 0.6 * cap_f {
