    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        score += 0.00015 * pr * pr * pr * (0.5 + 0.7 * tightness);
    }

    // MUTATION (gen 32): late-stream exact-closure pull — when progress is
    // deep and an open bin can be closed to zero residual, sharpen the
    // preference beyond the base -65 to consolidate the final stretch.
    if post_residual == 0 && bin_residual != bin_capacity && progress > 0.5 {
        score -= 6.0 * ((progress - 0.5) / 0.5).min(1.0);
    }

    // MUTATION (gen 32): fresh-bin anti-sprawl guard — when many bins are
    // open and a fresh bin would leave a large unfillable remainder after
    // the next item, penalize opening it so dead space stays consolidated.
    if bin_residual == bin_capacity && open_bins_count > 8 && next_item_size > 0 {
        let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
        if fresh_left > 45 {
            let crowd = ((open_bins_count as f64 - 8.0) / 10.0).min(1.0);
            score += 5.0 * crowd * (0.5 + 0.5 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is extremely desirable.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize small dead space (unusable slivers) super-linearly.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let dead_threshold = 15.0;
        if pr < dead_threshold {
            score += (dead_threshold - pr) * (dead_threshold - pr) * 4.0;
        }
    }

    // Reward tight fits relative to bin residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 40.0;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if next item exactly fills the post-residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            // next item still fits: mildly good
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here: penalize leaving large residuals
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor.
    if bin_residual == bin_capacity {
        // Base penalty so new bins aren't opened frivolously.
        score += 120.0;
        // But if open bins are congested (few fitting bins, high mean residual usage),
        // relax the penalty.
        if fitting_bins_count <= 1 {
            score -= 80.0;
        }
        // Later in the stream, prefer consolidating into existing bins less strictly.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 40.0;
        // If mean residual across open bins is small, existing bins are tight; new bin is fine.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 50.0;
        }
    }

    // Mild preference for bins with residuals close to the item (avoid scattering).
    let spread = (bin_residual as f64 - item_size as f64).abs();
    score += spread * 0.2;

    // Many open bins: slight incentive to fill existing ones rather than spread.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
