        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 14 && bin_residual != bin_capacity {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / 14.0) * scarcity * (0.5 + 0.5 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - progress) * 0.5;
    score += 20.0 * poly;

    // Penalize tiny dead space that can never be reused (smooth logistic ramp).
    let dead = (norm_pr / 0.12).exp() / (1.0 + (norm_pr / 0.12).exp());
    score += 15.0 * dead * (1.0 - progress);

    // Reward tight fits more strongly as stream progresses.
    score -= 10.0 * (1.0 - norm_pr) * progress;

    // Last-chance bin bonus (smooth).
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward leaving room for the next item.
    let nxs = next_item_size as f64;
    if nxs > 0.0 {
        let fits_next = if pr >= nxs { 1.0 } else { 0.0 };
        let gap = (pr - nxs).abs() / cap;
        score -= 8.0 * fits_next * (1.0 - gap);
    }

    // Slight preference for concentrating items when many bins are open.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

