        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 && bin_residual != bin_capacity {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / 10.0) * scarcity * (0.5 + 0.5 * progress);
        }

        // MUTATION (gen 33): dead-space convexity escalation continues —
        // raise the extra cubic coefficient from 0.00045 to 0.00062 and make
        // it progress-gated so the penalty concentrates on the late-stream
        // dead space where the 45-bin gap accumulates.
        if post_residual > 0 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            let gate = 0.6 + 0.7 * progress;
            score += 0.00062 * pr * pr * pr * (0.5 + 0.7 * tightness) * gate;
        }

        // MUTATION (gen 33): compaction pull strengthening — reinforce the
        // mean-residual band homogenization (base 2.5 -> 3.0) and extend it
        // to fitting_bins_count == 1 with a scarcity multiplier, since
        // Sigma_res (0.2981) remains the diagnosed weakness.
        if post_residual > 0 && bin_residual != bin_capacity && fitting_bins_count >= 1 {
            let pr = post_residual as f64;
            let band = ((pr - mean_residual.max(0.0)) / cap_f).abs();
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= (3.0 + 1.5 * scarcity) * (1.0 - band.min(1.0)) * (0.4 + 0.6 * progress);
        }

        // MUTATION (gen 33): fresh-bin halo extension to ±10 — the widening
        // trend (±2 -> ±4 -> ±6 -> ±8) keeps capturing near-parity chain
        // continuations; extend with a shallow decay to ±10.
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if d > 8 && d <= 10 {
                score -= (1.5 - 0.5 * (d - 8) as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // MUTATION (gen 33): late-stream consolidation sharpening — the
        // waste-floor guard is strengthened (6.0 -> 8.0) and its onset pulled
        // earlier (0.60 -> 0.55), forcing residual consolidation into fewer
        // usable slacks during the final stretch.
        if post_residual > 0 && bin_residual != bin_capacity && progress > 0.55 && post_residual < next_item_size.max(20) {
            let unus = 1.0 - (post_residual as f64 / (next_item_size.max(20) as f64));
            score += 8.0 * unus * ((progress - 0.55) / 0.45).min(1.0);
        }

        // MUTATION (gen 33): residual-variance floor bonus reinforcement —
        // the reusable-tail bonus is widened from <= 10 to <= 14 slack and
        // its weight raised (3.5 -> 4.5), directly compressing residual
        // dispersion by rewarding placements that leave a still-usable tail.
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 14 && bin_residual != bin_capacity {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= 4.5 * (1.0 - (post_residual - next_item_size) as f64 / 14.0) * scarcity * (0.5 + 0.5 * progress);
        }

        // MUTATION (gen 33): stranded-residual quadratic ramp — complementary
        // to the cubic family, add a quadratic term that penalizes residuals
        // just above the next item's size (partially reusable but wasteful)
        // more smoothly across the whole residual range.
        if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size && bin_residual != bin_capacity {
            let tail = (post_residual - next_item_size) as f64;
            if tail > 5.0 && tail <= 45.0 {
                let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
                score += 0.010 * tail * tail * (0.4 + 0.6 * tightness) * (0.5 + 0.5 * progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues that form "dead space"
    // classes are penalized super-linearly, residues near useful multiples
    // of small item sizes are rewarded.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class A: perfectly tight fit -> strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Class B: residual divisible by common small sizes (5,10,20,25)
        // keeps future packing options open.
        let r = post_residual;
        if r % 25 == 0 { score -= 18.0; }
        else if r % 20 == 0 { score -= 14.0; }
        else if r % 10 == 0 { score -= 10.0; }
        else if r % 5 == 0 { score -= 5.0; }
        else {
            // Awkward residue class: penalize dead space harder.
            score += (r % 5) as f64 * 2.5;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            // fraction of next item the leftover can host
            let fit_frac = next_item_size as f64 / post.max(1.0);
            score -= 12.0 * fit_frac.min(1.0);
        } else {
            // next item cannot use this bin's leftover; leftover likely dead
            score += 8.0;
        }
    } else {
        // Last item: prefer tightest fill.
        score -= 20.0 * (1.0 - post / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        // Baseline for a fresh bin: moderate score.
        score = 0.45 * cap;
        if next_item_size > 0 && next_item_size >= item_size {
            // pairing potential with next item in a fresh bin
            score -= 10.0;
        }
        if fitting_bins_count >= 1 && mean_residual > post.max(20.0) as f64 * 1.5 {
            // existing bins have plenty of room; discourage new bin
            score += 25.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Prefer bins whose residual is closest to item (best fit) beyond raw post_residual.
        score -= 6.0 * (1.0 - (item_size as f64 / bin_residual.max(1) as f64));
        // Slight preference for bins below mean residual (consolidating fuller bins).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    // Stream progression: late in stream, tighten packing and avoid new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap_f = bin_capacity as f64;
