            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover <= 4 {
                if fitting_bins_count >= 1 && bin_residual.saturating_sub(item_size) > 12 {
                    score -= 14.0;
                }
            } else if leftover <= 12 && fitting_bins_count >= 1 {
                let open_waste = bin_residual.saturating_sub(item_size);
                if open_waste > leftover + 8 {
                    score -= 5.0;
                }
            }
        }
        if next_item_size > 45 && fitting_bins_count >= 1 {
            let open_after = bin_residual.saturating_sub(item_size);
            let fresh_after = bin_capacity.saturating_sub(item_size);
            if open_after < next_item_size && fresh_after >= next_item_size {
                score -= 11.0;
            }
        }
        if fitting_bins_count >= 1 && next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            let open_waste = bin_residual.saturating_sub(item_size);
            if fresh_left >= next_item_size && open_waste >= 20 {
                score -= 4.0 + 0.1 * ((open_waste - 20) as f64).min(25.0);
            } else if fresh_left > 0 && fresh_left < 8 && open_waste <= 10 {
                score += 5.0;
            }
        }
        if progress > 0.3 && next_item_size > 0 {
            let tightness = (1.0 - (mean_residual / cap_f).min(1.0)).max(0.0);
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if tightness > 0.6 && leftover > 50 {
                score += 8.0 * (tightness - 0.6) * 10.0;
            } else if tightness > 0.6 && leftover >= 25 && leftover <= 50 {
                score -= 5.0 * (tightness - 0.6) * 10.0;
            }
        }
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let open_after = bin_residual.saturating_sub(item_size);
            let fresh_after = bin_capacity.saturating_sub(item_size);
            if open_after < next_item_size && fresh_after >= next_item_size {
                let mid_next = next_item_size >= 25 && next_item_size <= 70;
                if mid_next {
                    score -= 6.0 + 4.0 * (1.0 - progress);
                } else if next_item_size < 25 {
                    score += 4.0;
                }
            }
        }
        if progress > 0.45 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size) as f64;
            let excess = leftover - mean_residual.max(0.0);
            if excess > 15.0 {
                score += 0.08 * (excess - 15.0).min(40.0);
            }
        }
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 9.0 + 8.0 * progress;
        }
        if next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover >= 30 && leftover <= 55 {
                let d = ((leftover as f64 - 42.5).abs() / 12.5).min(1.0);
                score -= 4.0 * (1.0 - d);
            } else if leftover > 55 && leftover <= 90 {
                score += 2.0 * ((leftover as f64 - 55.0) / 35.0);
            }
        }
        if fitting_bins_count > 3 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            let open_waste = bin_residual.saturating_sub(item_size);
            if leftover > 12 && open_waste <= 10 {
                score += 5.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            let open_waste = bin_residual.saturating_sub(item_size);
            if fresh_left >= 12 && fresh_left <= 30 && open_waste > 25 {
                score -= 5.0 * (1.0 - progress);
            } else if fresh_left > 30 && open_waste <= 20 {
                score += 4.0 * (0.5 + 0.5 * progress);
            }
        }
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.0004 * fresh_left * fresh_left * fresh_left * (0.5 + 0.7 * tightness);
        }
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let open_waste = bin_residual.saturating_sub(item_size) as f64;
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as f64;
            let excess = open_waste - fresh_left;
            if excess > 10.0 {
                score -= 2.5 * ((excess - 10.0) / 25.0).min(1.0) * (0.5 + 0.5 * (1.0 - progress));
            } else if excess < -10.0 {
                score += 2.0 * (((-excess) - 10.0) / 25.0).min(1.0) * (0.5 + 0.5 * progress);
            }
        }
        if progress > 0.75 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover > 0 {
                score += 3.0 + 0.08 * (leftover as f64) * (progress - 0.75) * 20.0;
            } else {
                score -= 6.0 * (progress - 0.75) * 10.0;
            }
        }
        if fitting_bins_count >= 1 && next_item_size > 0 {
            let tightness = (1.0 - (mean_residual / cap_f).min(1.0)).max(0.0);
            let open_waste = bin_residual.saturating_sub(item_size) as f64;
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as f64;
            if tightness > 0.55 && open_waste > 18.0 && fresh_left >= 20.0 {
                score -= 5.0 * (tightness - 0.55) * 10.0;
            }
        }
        if next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover >= 8 && leftover <= 25 {
                score -= 3.5 * (1.0 - (leftover as f64 - 8.0).abs() / 17.0);
            } else if leftover > 65 {
                score += 0.06 * ((leftover - 65) as f64).min(35.0) * (0.5 + 0.5 * progress);
            }
        }
        if fitting_bins_count >= 1 && next_item_size > 0 {
            let open_after = bin_residual.saturating_sub(item_size);
            if open_after > 0 && open_after < next_item_size {
                let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
                if fresh_left < next_item_size {
                    score += 4.0 + 2.0 * (1.0 - progress);
                }
            }
        }
        if fitting_bins_count == 1 && item_size < 40 && progress > 0.3 {
            let open_after = bin_residual.saturating_sub(item_size);
            if open_after >= 15 {
                score += 10.0 * (1.0 - progress);
            }
        }
        if open_bins_count > 10 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover > 30 {
                score += 4.0 + 0.06 * ((leftover - 30) as f64).min(40.0);
            } else if leftover <= 30 && item_size > 50 {
                score -= 5.0;
            }
        }
        if progress > 0.7 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover > 0 && leftover <= 6 {
                score -= 7.0 * (progress - 0.7) * 10.0;
            } else if leftover > 40 {
                score += 4.0 * (progress - 0.7) * 10.0;
            }
        }
        if fitting_bins_count >= 1 && item_size > 55 {
            let open_waste = bin_residual.saturating_sub(item_size);
            if open_waste > 20 {
                score -= 3.0 + 0.06 * ((open_waste - 20) as f64).min(30.0) * (1.0 - 0.3 * progress);
            }
        }
        if fitting_bins_count >= 1 && next_item_size > 0 {
            let open_after = bin_residual.saturating_sub(item_size);
            if open_after >= 8 && open_after <= 25 {
                score += 5.0 * (1.0 - (open_after as f64 - 8.0).abs() / 17.0) * (0.5 + 0.5 * progress);
            }
        }
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left >= 30 && fresh_left <= 55 {
                score -= 2.5 * (1.0 - ((fresh_left as f64 - 42.5).abs() / 12.5).min(1.0)) * (1.0 - 0.4 * progress);
            }
        }
        if open_bins_count > 6 && fitting_bins_count <= 2 && next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left > 0 && fresh_left < next_item_size {
                score += 3.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left >= 1 && fresh_left <= 12 {
                score -= 4.0 * (1.0 - fresh_left as f64 / 12.0) * (0.6 + 0.4 * (1.0 - progress));
            }
        }
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left >= 1 && fresh_left <= 6 {
                score -= 8.0 * (1.0 - fresh_left as f64 / 6.0) * (0.7 + 0.3 * (1.0 - progress));
            }
        }
        if fitting_bins_count == 1 && next_item_size > 0 {
            let open_waste = bin_residual.saturating_sub(item_size) as f64;
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as f64;
            if open_waste > fresh_left + 18.0 {
                score -= 4.0 * ((open_waste - fresh_left - 18.0) / 20.0).min(1.0) * (0.6 + 0.4 * (1.0 - progress));
            }
        }

        // gen 22: fresh-bin exact-parity halo
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if d == 0 {
                score -= 14.0 + 6.0 * (1.0 - progress);
            } else if d <= 4 {
                score -= (10.0 - 2.0 * d as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // gen 22: fresh-bin salvage ceiling
        if fitting_bins_count >= 1 && next_item_size > 0 {
            let open_after = bin_residual.saturating_sub(item_size);
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if open_after < next_item_size && fresh_left >= next_item_size + 10 {
                score -= 3.0 + 3.0 * (1.0 - progress);
            }
        }

        // gen 22: scarcity-locked chain continuity
        if fitting_bins_count <= 2 && next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left >= next_item_size {
                let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0);
                score -= 5.0 * scarcity * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // gen 23: fresh-bin halo extension to ±8
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if d > 4 && d <= 8 {
                score -= (3.0 - 0.35 * (d - 4) as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // gen 23: late-stream consolidation sharpening
        if post_residual > 0 && bin_residual != bin_capacity && progress > 0.60 && post_residual < next_item_size.max(20) {
            let unus = 1.0 - (post_residual as f64 / (next_item_size.max(20) as f64));
            score += 6.0 * unus * ((progress - 0.60) / 0.40).min(1.0);
        }

        // gen 23: residual-variance floor bonus
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 && bin_residual != bin_capacity {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / 10.0) * scarcity * (0.5 + 0.5 * progress);
        }

        // gen 25: dead-space convexity escalation
        if post_residual > 0 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.00060 * pr * pr * pr * (0.5 + 0.7 * tightness);
        }

        // gen 25: compaction pull strengthening
        if post_residual > 0 && bin_residual != bin_capacity && fitting_bins_count >= 2 {
            let pr = post_residual as f64;
            let band = ((pr - mean_residual.max(0.0)) / cap_f).abs();
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= (3.0 + 1.5 * scarcity) * (1.0 - band.min(1.0)) * (0.4 + 0.6 * progress);
        }

        // gen 25: open-bin parity halo
        if next_item_size > 0 && bin_residual != bin_capacity {
            let pr = post_residual as i64;
            let nx = next_item_size as i64;
            let d = (pr - nx).abs();
            if d <= 3 {
                let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
                score -= (8.0 - 2.0 * d as f64) * (0.5 + 0.5 * (1.0 - progress)) * scarcity;
            }
        }

        // gen 25: two-item lookahead compaction
        if next_item_size > 0 && item_size + next_item_size <= bin_residual && bin_residual != bin_capacity {
            let leftover = bin_residual - item_size - next_item_size;
            if leftover <= 8 {
                score -= (9.0 - leftover as f64) * (0.6 + 0.4 * (1.0 - progress));
            }
        }

        // gen 25: mid-residual dead-band penalty
        if post_residual >= 20 && post_residual <= 35 && bin_residual != bin_capacity && open_bins_count > 6 {
            let crowd = ((open_bins_count as f64 - 6.0) / 10.0).min(1.0);
            let depth = 1.0 - ((post_residual as f64 - 27.5).abs() / 7.5).min(1.0);
            score += 4.0 * depth * crowd * (0.5 + 0.5 * progress);
        }

        // gen 25: fresh-bin exact-closure guard
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            let open_waste = bin_residual.saturating_sub(item_size);
            if fresh_left > 0 && fresh_left < next_item_size && open_waste == 0 {
                score += 10.0 * (1.0 - progress);
            }
        }

        // MUTATION (gen 33): combine fine-grained residual fitting with lookahead
        // anticipation — extend the open-bin parity halo from ±3 to a graded
        // ±7 band so near-miss chain continuations are also rewarded, with
        // scarcity weighting (targets diagnosed dead-space weakness).
        if next_item_size > 0 && bin_residual != bin_capacity {
            let pr = post_residual as i64;
            let nx = next_item_size as i64;
            let d = (pr - nx).abs();
            if d > 3 && d <= 7 {
                let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
                score -= (4.0 - 0.5 * (d - 3) as f64) * (0.5 + 0.5 * (1.0 - progress)) * scarcity;
            }
        }

        // MUTATION (gen 33): dead-space convexity escalation — cubic stranded-
        // residual pressure raised further (0.00060 -> 0.00075) to keep
        // squeezing the mid/large dead-space band identified as the weakness.
        if post_residual > 0 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.00075 * pr * pr * pr * (0.5 + 0.7 * tightness);
        }

        // MUTATION (gen 33): scarcity-locked compaction pull — the mean-
        // residual homogenization pull is deepened (3.0 -> 4.0 base) and
        // gated to late-stream progress where the 50-bin waste concentrates.
        if post_residual > 0 && bin_residual != bin_capacity && fitting_bins_count >= 2 && progress > 0.35 {
            let pr = post_residual as f64;
            let band = ((pr - mean_residual.max(0.0)) / cap_f).abs();
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= (2.0 + 2.0 * scarcity) * (1.0 - band.min(1.0)) * ((progress - 0.35) / 0.65).min(1.0);
        }

        // MUTATION (gen 33): two-item lookahead closure tightening — extend
        // the exact-closure window from <=8 to <=12 with graded decay, so
        // near-closing two-item chains are preferred over stranding slack.
        if next_item_size > 0 && item_size + next_item_size <= bin_residual && bin_residual != bin_capacity {
            let leftover = bin_residual - item_size - next_item_size;
            if leftover > 8 && leftover <= 12 {
                score -= (2.0 - 0.4 * (leftover - 9) as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // MUTATION (gen 33): late-stream stranded-residual hardening — when
        // the stream is nearly done and an open bin's post-fit residual
        // cannot fit the next item, penalize proportionally to unusability
        // to force consolidation into the few remaining usable slacks.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && bin_residual != bin_capacity && progress > 0.7 {
            let unus = 1.0 - (post_residual as f64 / next_item_size as f64);
            score += 5.0 * unus * ((progress - 0.7) / 0.3).min(1.0) / (fitting_bins_count as f64).max(1.0).sqrt();
        }

        // MUTATION (gen 33): fresh-bin anti-fragmentation guard — when many
        // bins are already open and a fresh bin would leave a large
        // unmatchable leftover, discourage opening it (dead-space control).
        if open_bins_count > 8 && next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left > 40 && fresh_left < next_item_size * 2 {
                score += 4.0 * (1.0 - progress);
            }
        }
    }

    // gen 22: dead-space convexity escalation (base cubic family)
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        score += 0.00030 * pr * pr * pr * (0.5 + 0.7 * tightness);
    }

    // gen 22: residual-dispersion guard
    if post_residual > 0 && bin_residual != bin_capacity && mean_residual > 0.45 * cap_f {
        let pr = post_residual as f64;
        score += 0.07 * pr * (0.4 + 0.6 * progress);
    }

    // gen 22: tight-fit preservation
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 && bin_residual != bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
        score -= (3.0 + 3.0 * (1.0 - progress)) * scarcity;
    }

    // gen 22: open-bin parity halo
    if next_item_size > 0 && bin_residual != bin_capacity {
        let pr = post_residual as i64;
        let nx = next_item_size as i64;
        let d = (pr - nx).abs();
        if d <= 3 {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= (8.0 - 2.0 * d as f64) * (0.5 + 0.5 * (1.0 - progress)) * scarcity;
        }
    }

    // gen 22: two-item lookahead compaction
    if next_item_size > 0 && item_size + next_item_size <= bin_residual && bin_residual != bin_capacity {
        let leftover = bin_residual - item_size - next_item_size;
        if leftover <= 8 {
            score -= (9.0 - leftover as f64) * (0.6 + 0.4 * (1.0 - progress));
        }
    }

    // gen 22: mid-residual dead-band penalty
    if post_residual >= 20 && post_residual <= 35 && bin_residual != bin_capacity && open_bins_count > 6 {
        let crowd = ((open_bins_count as f64 - 6.0) / 10.0).min(1.0);
        let depth = 1.0 - ((post_residual as f64 - 27.5).abs() / 7.5).min(1.0);
        score += 3.5 * depth * crowd * (0.5 + 0.5 * progress);
    }

    // MUTATION (gen 33): global open-bin parity halo extension (mirrors the
    // fresh-bin branch extension, applied to all open-bin candidates so the
    // graded ±7 band is evaluated uniformly).
    if next_item_size > 0 && bin_residual != bin_capacity {
        let pr = post_residual as i64;
        let nx = next_item_size as i64;
        let d = (pr - nx).abs();
        if d > 3 && d <= 7 {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= (3.5 - 0.45 * (d - 3) as f64) * (0.5 + 0.5 * (1.0 - progress)) * scarcity;
        }
    }

    // MUTATION (gen 33): global late-stream stranded hardening (outside the
    // fresh-bin branch so it applies to every open-bin candidate).
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && bin_residual != bin_capacity && progress > 0.7 {
        let unus = 1.0 - (post_residual as f64 / next_item_size as f64);
        score += 4.0 * unus * ((progress - 0.7) / 0.3).min(1.0) / (fitting_bins_count as f64).max(1.0).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for any plausible item (items >= 1, but practically >= 10 historically)
    // are heavily penalized dead space.
    let dead_threshold = 9.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual as f64);
    }

    // Reward near-perfect fits (residual just above the dead threshold).
    if post_residual > 0 && post_residual <= 12 {
        score -= 25.0;
    }

    // Open-bins pressure: when many bins are open, prefer using them
    // rather than opening new ones.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if the item is large and
        // existing bins would leave big unusable gaps, or nothing fits well.
        let poor_fit_elsewhere = mean_residual < item_size as f64 * 0.5;
        if poor_fit_elsewhere || fitting_bins_count == 0 {
            score -= 40.0;
        } else {
            score += 30.0;
        }
    }

    // Lookahead coupling: if the next item could exactly use the post
    // residual, reward this placement (chain fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap <= 12 {
            score -= 20.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Post residual too small for the next item: mild penalty unless tiny.
        if (post_residual as f64) >= dead_threshold {
            score += 8.0;
        }
    }

    // Prefer bins whose residual is already small (consolidate tightness),
    // scaled by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.1 * (bin_residual as f64 - mean_residual) * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
