        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 && bin_residual != bin_capacity && fitting_bins_count <= 3 {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0);
