        if post_residual > 0 && bin_residual != bin_capacity && progress > 0.55 && post_residual < next_item_size.max(20) {
            let unus = 1.0 - (post_residual as f64 / (next_item_size.max(20) as f64));
            score += 8.0 * unus * ((progress - 0.55) / 0.45).min(1.0);
        }

        // MUTATION (gen 34): residual-variance floor bonus strengthening —
        // reward open-bin placements whose post_residual is small but
        // reusable, directly compressing residual dispersion; widened to
        // tail <= 14 and weighted by scarcity.
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 14 && bin_residual != bin_capacity {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= 4.5 * (1.0 - (post_residual - next_item_size) as f64 / 14.0) * scarcity * (0.5 + 0.5 * progress);
        }

        // MUTATION (gen 34): chain-continuity quadratic guard — when the
        // fresh-bin leftover after item+next is small, penalize proportionally
        // to its square so near-exhausted fresh bins are avoided in favor of
        // open-bin compaction, reducing dead space at stream end.
        if next_item_size > 0 && fitting_bins_count >= 1 && progress > 0.35 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as f64;
            if fresh_left > 0.0 && fresh_left <= 16.0 {
                let frac = 1.0 - fresh_left / 16.0;
                score += 2.2 * frac * frac * (0.6 + 0.4 * progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let frag = post_residual as f64 / bin_capacity as f64;
        score += frag * frag * 60.0; // quadratic penalty on wasted space
    }

    // Reward filling bins deeply (high fill ratio of this placement).
    let fill = item_size as f64 / bin_residual as f64;
    score -= fill * 25.0;

    // Lookahead: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 && next_item_size <= post_residual {
        let lookahead_fit = (post_residual - next_item_size) as f64;
        score -= 40.0 - lookahead_fit * 0.4;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post-residual too small for next item: penalize dead space mildly,
        // more so if post_residual is in the "unusable" low band.
        if post_residual < 10 {
            score += 30.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Crowding: many open bins -> prefer consolidating into existing ones.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += pressure * 0.5;

    // Time horizon: late in the stream, be conservative, keep residuals large.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when no bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening new bins unless item is large relative to capacity
        // or existing bins are all poor fits.
        score += 55.0 - (item_size as f64 / bin_capacity as f64) * 30.0;
        if fitting_bins_count > 0 {
            score += 20.0;
        }
    }

    // Mean residual coupling: when mean residual is small, prefer exact fills.
    if (mean_residual - post_residual as f64).abs() < 1.0 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
