        // gen 19 retained: scarcity-locked chain continuity
        if fitting_bins_count <= 2 && next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left >= next_item_size {
                let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0);
                score -= 5.0 * scarcity * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // gen 20: near-parity halo
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if d > 0 && d <= 2 {
                score -= (14.0 - 4.0 * d as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // gen 20: dead-space convexity gain
        if post_residual > 0 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.0001 * pr * pr * pr * (0.5 + 0.7 * tightness);
        }

        // gen 20: tight-fit preservation
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 && bin_residual != bin_capacity {
            score -= 5.0 + 4.0 * (1.0 - progress);
        }

        // gen 21: halo widening to ±4
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if d > 2 && d <= 4 {
                score -= (6.0 - 1.5 * (d - 2) as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // gen 21: dead-space convexity escalation
        if post_residual > 0 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.00022 * pr * pr * pr * (0.5 + 0.7 * tightness);
        }

        // gen 21: tight-fit preservation widening
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 && bin_residual != bin_capacity {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= (3.0 + 3.0 * (1.0 - progress)) * scarcity;
        }

        // gen 21: residual-dispersion dead-space guard
        if post_residual > 0 && bin_residual != bin_capacity && mean_residual > 0.45 * cap_f {
            let pr = post_residual as f64;
            score += 0.06 * pr * (0.4 + 0.6 * progress);
        }

        // gen 22: dead-space convexity escalation
        if post_residual > 0 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.00032 * pr * pr * pr * (0.5 + 0.7 * tightness);
        }

        // gen 22: open-bin compaction pull
        if post_residual > 0 && bin_residual != bin_capacity && fitting_bins_count >= 2 {
            let pr = post_residual as f64;
            let band = ((pr - mean_residual.max(0.0)) / cap_f).abs();
            score -= 2.0 * (1.0 - band.min(1.0)) * (0.4 + 0.6 * progress);
        }

        // gen 22: fresh-bin halo extension to ±6
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if d > 4 && d <= 6 {
                score -= (3.0 - 1.0 * (d - 4) as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // gen 22: late-stream waste-floor guard
        if post_residual > 0 && bin_residual != bin_capacity && progress > 0.66 && post_residual < next_item_size.max(20) {
            let unus = 1.0 - (post_residual as f64 / (next_item_size.max(20) as f64));
            score += 4.0 * unus * ((progress - 0.66) / 0.34).min(1.0);
        }

        // gen 23: dead-space convexity escalation
        if post_residual > 0 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.00045 * pr * pr * pr * (0.5 + 0.7 * tightness);
        }

        // gen 23: compaction pull strengthening
        if post_residual > 0 && bin_residual != bin_capacity && fitting_bins_count >= 2 {
            let pr = post_residual as f64;
            let band = ((pr - mean_residual.max(0.0)) / cap_f).abs();
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= (2.5 + 1.5 * scarcity) * (1.0 - band.min(1.0)) * (0.4 + 0.6 * progress);
        }

        // gen 23: fresh-bin halo extension to ±8
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if d > 6 && d <= 8 {
                score -= (2.0 - 0.75 * (d - 6) as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // gen 23: late-stream consolidation sharpening
        if post_residual > 0 && bin_residual != bin_capacity && progress > 0.60 && post_residual < next_item_size.max(20) {
            let unus = 1.0 - (post_residual as f64 / (next_item_size.max(20) as f64));
            score += 6.0 * unus * ((progress - 0.60) / 0.40).min(1.0);
        }

        // gen 23: residual-variance floor bonus
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 && bin_residual != bin_capacity {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / 10.0) * scarcity * (0.5 + 0.5 * progress);
        }

        // MUTATION (gen 35): dead-space convexity escalation continues — raise
        // the extra cubic coefficient from 0.00045 to 0.00062, deepening the
        // dead-space penalty on stranded mid/large residuals (momentum:
        // ContinueDirection on the diagnosed dead-space weakness).
        if post_residual > 0 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.00062 * pr * pr * pr * (0.5 + 0.7 * tightness);
        }

        // MUTATION (gen 35): compaction pull strengthening — extend the
        // mean-residual band homogenization to all fitting bins (>=1) with a
        // mild weight, further compressing residual dispersion Sigma_res.
        if post_residual > 0 && bin_residual != bin_capacity && fitting_bins_count == 1 {
            let pr = post_residual as f64;
            let band = ((pr - mean_residual.max(0.0)) / cap_f).abs();
            score -= 1.5 * (1.0 - band.min(1.0)) * (0.4 + 0.6 * progress);
        }

        // MUTATION (gen 35): fresh-bin halo extension to ±10 — continue the
        // widening trend (±8 -> ±10) with a shallow decay for near-parity
        // chain continuations.
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if d > 8 && d <= 10 {
                score -= (1.2 - 0.5 * (d - 8) as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // MUTATION (gen 35): late-stream consolidation sharpening — onset
        // pulled earlier (0.60 -> 0.52) and weight raised (6.0 -> 7.5),
        // forcing residual consolidation into fewer usable slacks during the
        // final stretch where the 45-bin gap concentrates.
        if post_residual > 0 && bin_residual != bin_capacity && progress > 0.52 && post_residual < next_item_size.max(20) {
            let unus = 1.0 - (post_residual as f64 / (next_item_size.max(20) as f64));
            score += 7.5 * unus * ((progress - 0.52) / 0.48).min(1.0);
        }

        // MUTATION (gen 35): residual-variance floor bonus widening — extend
        // the tight-tail reward from <=10 to <=14 of slack after the next
        // item, rewarding placements that leave immediately reusable space.
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 14 && bin_residual != bin_capacity {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= 3.0 * (1.0 - (post_residual - next_item_size) as f64 / 14.0) * scarcity * (0.5 + 0.5 * progress);
        }

        // MUTATION (gen 35): mid-stream dead-space guard — penalize open-bin
        // placements leaving stranded residuals in the 60..100 window during
        // the middle of the stream, where dead space most often accumulates.
        if post_residual >= 60 && post_residual <= 100 && bin_residual != bin_capacity && progress > 0.3 && progress < 0.75 {
            let severity = ((progress - 0.3) / 0.45).min(1.0);
            score += 3.0 * severity * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tight fits, but keep some usable slack for future items.
    if post_residual == 0 {
        score -= 60.0; // perfect fit: ideal
    } else if post_residual < 10 {
        score -= 15.0; // near-perfect fit
    } else if post_residual <= 20 {
        score -= 5.0; // still usable by the smallest items
    } else {
        // Harmonic dead-space class: penalize residuals in "wasted" classes
        // (residuals that few item sizes can exploit).
        let cls = post_residual / 10; // 1..10 harmonic class
        score += (cls as f64) * 2.0;
        // Odd residuals are harder to fill exactly with even-ish items.
        if post_residual % 2 == 1 {
            score += 3.0;
        }
        if post_residual % 5 != 0 {
            score += 1.5;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (item barely fits nowhere or all fits leave huge dead space).
    if bin_residual == bin_capacity {
        // Neutral baseline; make new bins preferable to very poor fits.
        let poor_fit_penalty = (post_residual as f64) * 1.2;
        if fitting_bins_count == 0 || poor_fit_penalty > 70.0 {
            score -= 40.0;
        } else {
            score += 55.0; // discourage opening new bins when decent fits exist
        }
    }

    // Lookahead coupling: if the next item exactly matches this bin's post_residual,
    // strongly favor this placement (chain fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            // next item still fits: mild reward proportional to leftover fit quality
            let r2 = post_residual - next_item_size;
            if r2 < 10 {
                score -= 12.0;
            }
        } else {
            // next item won't fit here after placement: slight penalty if bin becomes dead
            if post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
                score += 5.0;
            }
        }
    }

    // Late in the stream, prefer closing bins tightly (fewer total bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 8.0;

    // Prefer bins with residuals near the mean (balance load across bins).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.15;

    // Many open bins: discourage spreading; prefer filling existing ones.
    if open_bins_count > 5 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap_f = bin_capacity as f64;
    let resid_f = bin_residual as f64;

    if post_residual == 0 {
        score -= 65.0;
    }

    let slack = bin_residual as i64 - item_size as i64;
    if slack >= 0 && slack <= 4 {
        score -= 20.0;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0 + 22.0 * (1.0 - progress);
        } else if post_residual > next_item_size {
            let slack_after_next = post_residual - next_item_size;
            score -= 25.0 - (slack_after_next as f64).min(40.0) * 0.3;
            if slack_after_next > 40 {
                score += (slack_after_next as f64 - 40.0) * 0.2;
            }
        } else {
            let shortfall = (next_item_size - post_residual) as f64;
            score += shortfall * 0.85;
            let half_next = next_item_size / 2;
            if post_residual > 0 && post_residual < half_next {
                score += 14.0;
            }
        }
    } else {
        score -= 10.0;
    }

    if post_residual > 0 {
        let waste_ratio = post_residual as f64 / cap_f;
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        let severity = 1.4 - 0.8 * tightness;
        if post_residual < next_item_size && next_item_size > 0 {
            let unusability = 1.0 - (post_residual as f64 / next_item_size as f64);
            score += 16.0 * unusability * (1.0 - 0.5 * progress) * severity;
            if post_residual < 10 {
                score += 9.0 * severity * (1.0 - 0.4 * progress);
            }
        } else if waste_ratio < 0.05 {
            score += 7.0 * (1.0 - progress) * severity;
        } else if waste_ratio < 0.10 && post_residual < 40 {
            score += 3.0 * (1.0 - progress) * severity;
        }
    }

    if resid_f > mean_residual + 20.0 && item_size < 30 {
        if next_item_size == 0 || post_residual < next_item_size {
            score += 10.0;
        }
    } else if resid_f < mean_residual - 20.0 {
        score -= 8.0;
    }

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
        if post_residual >= 10 {
            score -= 10.0;
        }
    }

    if open_bins_count > 8 {
        score += (resid_f / cap_f) * 6.0;
    }
    score -= (open_bins_count as f64).ln().max(0.0) * 3.0;

    if post_residual >= 25 {
        score -= 4.0;
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 15 {
            score -= 6.0;
