        if fitting_bins_count >= 1 && next_item_size > 0 {
            let open_after = bin_residual.saturating_sub(item_size);
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if open_after < next_item_size && fresh_left >= next_item_size + 10 {
                score -= 3.0 + 3.0 * (1.0 - progress);
            }
        }

        // gen 22: scarcity-locked chain continuity
        if fitting_bins_count <= 2 && next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left >= next_item_size {
                let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0);
                score -= 5.0 * scarcity * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // gen 23: fresh-bin halo extension to ±8
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if d > 4 && d <= 8 {
                score -= (3.0 - 0.35 * (d - 4) as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // gen 23: late-stream consolidation sharpening
        if post_residual > 0 && bin_residual != bin_capacity && progress > 0.60 && post_residual < next_item_size.max(20) {
            let unus = 1.0 - (post_residual as f64 / (next_item_size.max(20) as f64));
            score += 6.0 * unus * ((progress - 0.60) / 0.40).min(1.0);
        }

        // gen 23: residual-variance floor bonus
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 && bin_residual != bin_capacity {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / 10.0) * scarcity * (0.5 + 0.5 * progress);
        }

        // gen 25: dead-space convexity escalation (cubic family)
        if post_residual > 0 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.00075 * pr * pr * pr * (0.5 + 0.7 * tightness);
        }

        // gen 25: compaction pull strengthening (mean-residual band homogenization)
        if post_residual > 0 && bin_residual != bin_capacity && fitting_bins_count >= 2 {
            let pr = post_residual as f64;
            let band = ((pr - mean_residual.max(0.0)) / cap_f).abs();
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= (4.0 + 1.5 * scarcity) * (1.0 - band.min(1.0)) * (0.4 + 0.6 * progress);
        }

        // gen 25: open-bin parity halo
        if next_item_size > 0 && bin_residual != bin_capacity {
            let pr = post_residual as i64;
            let nx = next_item_size as i64;
            let d = (pr - nx).abs();
            if d <= 3 {
                let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
                score -= (8.0 - 2.0 * d as f64) * (0.5 + 0.5 * (1.0 - progress)) * scarcity;
            }
        }

        // gen 25: two-item lookahead compaction
        if next_item_size > 0 && item_size + next_item_size <= bin_residual && bin_residual != bin_capacity {
            let leftover = bin_residual - item_size - next_item_size;
            if leftover <= 8 {
                score -= (9.0 - leftover as f64) * (0.6 + 0.4 * (1.0 - progress));
            }
        }

        // gen 25: mid-residual dead-band penalty
        if post_residual >= 20 && post_residual <= 35 && bin_residual != bin_capacity && open_bins_count > 6 {
            let crowd = ((open_bins_count as f64 - 6.0) / 10.0).min(1.0);
            let depth = 1.0 - ((post_residual as f64 - 27.5).abs() / 7.5).min(1.0);
            score += 4.0 * depth * crowd * (0.5 + 0.5 * progress);
        }

        // gen 25: fresh-bin exact-closure guard
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            let open_waste = bin_residual.saturating_sub(item_size);
            if fresh_left > 0 && fresh_left < next_item_size && open_waste == 0 {
                score += 10.0 * (1.0 - progress);
            }
        }

        // MUTATION (gen 35): dead-space convexity escalation — cubic stranded-
        // residual pressure raised further (0.00060 -> 0.00075), pushing the
        // diagnosed dead-space weakness harder in the mid/large residual band.
        if post_residual > 0 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.00075 * pr * pr * pr * (0.5 + 0.7 * tightness);
        }

        // MUTATION (gen 35): compaction pull strengthening — mean-residual
        // band homogenization reinforced (3.0 -> 4.0) with scarcity weighting,
        // compressing residual dispersion (Sigma_res weakness).
        if post_residual > 0 && bin_residual != bin_capacity && fitting_bins_count >= 2 {
            let pr = post_residual as f64;
            let band = ((pr - mean_residual.max(0.0)) / cap_f).abs();
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= (4.0 + 1.5 * scarcity) * (1.0 - band.min(1.0)) * (0.4 + 0.6 * progress);
        }

        // MUTATION (gen 35): open-bin parity halo — reward open bins whose
        // post-fit residual lands within ±3 of the next item, combining
        // fine-grained residual fitting with lookahead chain continuation.
        if next_item_size > 0 && bin_residual != bin_capacity {
            let pr = post_residual as i64;
            let nx = next_item_size as i64;
            let d = (pr - nx).abs();
            if d <= 3 {
                let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
                score -= (8.0 - 2.0 * d as f64) * (0.5 + 0.5 * (1.0 - progress)) * scarcity;
            }
        }

        // MUTATION (gen 35): two-item lookahead compaction — when the current
        // item plus the next item nearly fills the bin, push hard toward
        // exact closure without opening new bins.
        if next_item_size > 0 && item_size + next_item_size <= bin_residual && bin_residual != bin_capacity {
            let leftover = bin_residual - item_size - next_item_size;
            if leftover <= 8 {
                score -= (9.0 - leftover as f64) * (0.6 + 0.4 * (1.0 - progress));
            }
        }

        // MUTATION (gen 35): mid-residual dead-band penalty — the 20–35
        // dead-space zone is penalized progressively when many bins are open,
        // squeezing stranded slacks into consolidation.
        if post_residual >= 20 && post_residual <= 35 && bin_residual != bin_capacity && open_bins_count > 6 {
            let crowd = ((open_bins_count as f64 - 6.0) / 10.0).min(1.0);
            let depth = 1.0 - ((post_residual as f64 - 27.5).abs() / 7.5).min(1.0);
            score += 4.0 * depth * crowd * (0.5 + 0.5 * progress);
        }

        // MUTATION (gen 35): fresh-bin exact-closure guard — when placing the
        // current item in a fresh bin leaves a residual that cannot fit the
        // next item but an open bin closes exactly, strongly prefer reuse.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            let open_waste = bin_residual.saturating_sub(item_size);
            if fresh_left > 0 && fresh_left < next_item_size && open_waste == 0 {
                score += 10.0 * (1.0 - progress);
            }
        }

        // MUTATION (gen 35): late-stream exact-fit escalation — in the final
        // third of the stream, exact post-fit closures (post_residual == 0)
        // are rewarded more aggressively so remaining items pack into open
        // bins rather than spawning fresh ones.
        if post_residual == 0 && bin_residual != bin_capacity && progress > 0.65 {
            score -= 5.0 * ((progress - 0.65) / 0.35).min(1.0);
        }

        // MUTATION (gen 35): fresh-bin crowding guard — when many bins are
        // already open, opening yet another bin is penalized unless the
        // current item is large relative to capacity.
        if bin_residual == bin_capacity && open_bins_count > 8 && item_size as f64 <= 0.55 * cap_f {
            let crowd = ((open_bins_count - 8) as f64).min(10.0) / 10.0;
            score += 6.0 * crowd * (0.4 + 0.6 * progress);
        }
    }

    // gen 22: dead-space convexity escalation (base cubic family)
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        score += 0.00030 * pr * pr * pr * (0.5 + 0.7 * tightness);
    }

    // gen 22: residual-dispersion guard
    if post_residual > 0 && bin_residual != bin_capacity && mean_residual > 0.45 * cap_f {
        let pr = post_residual as f64;
        score += 0.07 * pr * (0.4 + 0.6 * progress);
    }

    // gen 22: tight-fit preservation
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 && bin_residual != bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
        score -= (3.0 + 3.0 * (1.0 - progress)) * scarcity;
    }

    // gen 22: open-bin parity halo
    if next_item_size > 0 && bin_residual != bin_capacity {
        let pr = post_residual as i64;
        let nx = next_item_size as i64;
        let d = (pr - nx).abs();
        if d <= 3 {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= (8.0 - 2.0 * d as f64) * (0.5 + 0.5 * (1.0 - progress)) * scarcity;
        }
    }

    // gen 22: two-item lookahead compaction
    if next_item_size > 0 && item_size + next_item_size <= bin_residual && bin_residual != bin_capacity {
        let leftover = bin_residual - item_size - next_item_size;
        if leftover <= 8 {
            score -= (9.0 - leftover as f64) * (0.6 + 0.4 * (1.0 - progress));
        }
    }

    // gen 22: mid-residual dead-band penalty
    if post_residual >= 20 && post_residual <= 35 && bin_residual != bin_capacity && open_bins_count > 6 {
        let crowd = ((open_bins_count as f64 - 6.0) / 10.0).min(1.0);
        let depth = 1.0 - ((post_residual as f64 - 27.5).abs() / 7.5).min(1.0);
        score += 3.5 * depth * crowd * (0.5 + 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible item are pure waste. Penalize them super-linearly.
    let min_item = 1u32;
    if post_residual < min_item.max(next_item_size.min(item_size)) {
        score += 50.0;
    }
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0; // tiny unusable slivers
    }

    // Reward tight fits: residual close to zero is ideal.
    if post_residual == 0 {
        score -= 100.0; // perfect fill
    } else {
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= 20.0 * tightness * tightness;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 60.0;
        } else if slack < 10 {
            score -= 15.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 10.0; // dead space for the known next item
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling.
    let pressure = (open_bins_count as f64) / 20.0;
    if bin_residual < bin_capacity {
        score -= pressure * 5.0;
    } else {
        // New-bin candidate: only attractive when current bins are crowded/poor fits.
        score += pressure * 8.0 + mean_residual * 0.3;
        if fitting_bins_count > 0 && post_residual > bin_capacity - item_size - 10 {
            score += 30.0; // don't open new bin when a decent fit exists
        }
    }

    // Late in stream: consolidate harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= 15.0 * progress;
    }

    // Prefer bins whose residual is close to mean (balanced usage) unless tight fit.
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap_f = bin_capacity as f64;
    let slack = bin_residual as i64 - item_size as i64;

    if post_residual == 0 {
        score -= 65.0;
    }

    // Exact small-slack compaction
    if slack >= 0 && slack <= 4 {
        score -= 20.0;
    }

    // Lookahead chain logic
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0 + 22.0 * (1.0 - progress);
        } else if post_residual > next_item_size {
            let slack_after_next = post_residual - next_item_size;
            score -= 25.0 - (slack_after_next as f64).min(40.0) * 0.3;
            if slack_after_next > 40 {
                score += (slack_after_next as f64 - 40.0) * 0.2;
            }
        } else {
            let shortfall = (next_item_size - post_residual) as f64;
            score += shortfall * 0.85;
            let half_next = next_item_size / 2;
            if post_residual > 0 && post_residual < half_next {
                score += 14.0;
            }
        }
    } else {
        score -= 10.0;
    }

    // Dead-space unusability penalties
    if post_residual > 0 {
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        let severity = 1.4 - 0.8 * tightness;
        if next_item_size > 0 && post_residual < next_item_size {
            let unusability = 1.0 - (post_residual as f64 / next_item_size as f64);
            score += 16.0 * unusability * (1.0 - 0.5 * progress) * severity;
            if post_residual < 10 {
                score += 9.0 * severity * (1.0 - 0.4 * progress);
            }
        } else {
            let waste_ratio = post_residual as f64 / cap_f;
            if waste_ratio < 0.05 {
                score += 7.0 * (1.0 - progress) * severity;
            } else if waste_ratio < 0.10 && post_residual < 40 {
                score += 3.0 * (1.0 - progress) * severity;
            }
        }
        // Dead-space convexity: heavily penalize stranded mid/large residuals
        let pr = post_residual as f64;
        score += 0.00045 * pr * pr * pr * (0.5 + 0.7 * tightness);
    }

    // Residual dispersion control
    if fitting_bins_count >= 2 && bin_residual != bin_capacity && post_residual > 0 {
        let pr = post_residual as f64;
        let band = ((pr - mean_residual.max(0.0)) / cap_f).abs();
        let scarcity = 1.0 / (fitting_bins_count as f64).sqrt();
        score -= (2.5 + 1.5 * scarcity) * (1.0 - band.min(1.0)) * (0.4 + 0.6 * progress);
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
        if post_residual >= 10 {
            score -= 10.0;
        }
    }

    // Open-bin pressure
    if open_bins_count > 8 {
        score += (bin_residual as f64 / cap_f) * 6.0;
    }
    score -= (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Sweet spot residuals
    if post_residual >= 25 {
        score -= 4.0;
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 15 {
            score -= 6.0;
        }
    }
    if post_residual >= 20 && post_residual <= 60 {
        score -= 3.0 + 4.0 * (1.0 - progress);
    }
    if post_residual >= 1 && post_residual <= 5 {
        score += 5.0;
    }

    // Chain continuity: reward bins that fit item + next item tightly
    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let chain_left = bin_residual - item_size - next_item_size;
        if chain_left <= 3 {
            score -= 10.0 + 6.0 * (1.0 - progress) + 3.0 / (fitting_bins_count as f64).max(1.0);
        } else if chain_left >= 8 && chain_left <= 20 {
            score -= 5.0 * (1.0 - (chain_left as f64 - 8.0) / 12.0) * (0.5 + 0.5 * (1.0 - progress));
        } else if chain_left >= 25 && chain_left <= 50 {
            score -= 4.5 * (1.0 - (chain_left as f64 - 25.0).abs() / 25.0) * (0.6 + 0.4 * (1.0 - progress));
        }
    }

    // Scarcity-weighted strandedness
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
