        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= (3.0 + 3.0 * (1.0 - progress)) * scarcity;
        }

        // Mean-residual alignment
        score -= (mean_residual - post_residual as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: does next item fit exactly in the post-residual?
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual == next_item_size {
            score -= 800.0; // perfect 2-chain
        } else if post_residual >= next_item_size {
            score -= 300.0 * (nr / pr); // next item fits: reward tight coupling
            let leftover_after_next = pr - nr;
            score -= 200.0 * (1.0 - leftover_after_next / bin_capacity as f64);
        } else {
            // next item does not fit here: penalize dead space proportionally
            score += 250.0 * (1.0 - pr / (bin_capacity as f64 * 0.5)).max(0.0);
            // if next item fits in a fresh bin but not here, slight penalty for wasting capacity
            score += 50.0;
        }
        // bonus when this bin's post-residual pairs well with mean residual structure
        if (pr - nr).abs() < mean_residual.abs() * 0.5 {
            score -= 40.0;
        }
    } else {
        // last item: just minimize waste
        score += 100.0 * (1.0 - (post_residual as f64) / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 150.0;
    } else if fitting_bins_count > 1 {
        score += 30.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Prefer bins tighter than the mean residual (best-fit style)
    if (bin_residual as f64) < mean_residual {
        score -= 60.0;
    } else {
        score += 30.0;
    }

    // Early in the stream, allow opening new bins more freely; late, consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: attractive early, expensive late
        score = score * 0.5 + 80.0 * (1.0 - progress) + 250.0 * progress;
    } else {
        score -= 50.0 * progress;
    }

    // Mild preference for fewer open bins (consolidation)
    score += open_bins_count as f64 * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap_f = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let slack = bin_residual as i64 - item_size as i64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 70.0 + 30.0 * (1.0 - progress);
        let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
        score -= 10.0 * scarcity;
    }

    // Near-perfect fit band
    if slack >= 0 && slack <= 4 {
        score -= 18.0;
    }

    // Two-step lookahead
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual == next_item_size {
            score -= 60.0 + 25.0 * (1.0 - progress);
        } else if post_residual >= next_item_size {
            let tail = post_residual - next_item_size;
            // reward tight chains, penalize large tails
            score -= 25.0 * (nx / pr.max(1.0));
            if tail <= 10 {
                score -= 8.0 * (1.0 - tail as f64 / 10.0) * (0.5 + 0.5 * (1.0 - progress));
            } else if tail > 60 {
                score += 0.10 * (tail as f64 - 60.0);
            }
        } else {
            // next item does not fit here: penalize stranded residual
            let unus = 1.0 - pr / nx;
            score += 20.0 * unus * (1.0 - 0.4 * progress);
            if pr < nx / 2 {
                score += 10.0;
            }
        }
        // chain feasibility: item + next fits in residual
        if item_size as u64 + next_item_size as u64 <= bin_residual as u64 {
            let chain_left = bin_residual - item_size - next_item_size;
            if chain_left <= 5 {
                score -= 10.0 + 6.0 * (1.0 - progress);
            } else if chain_left <= 25 {
                score -= 6.0 * (1.0 - (chain_left as f64 - 5.0) / 20.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // alignment with mean residual structure
        if (pr - nx).abs() < mean_residual.abs() * 0.5 {
            score -= 25.0;
        }
    } else {
        score -= 10.0;
    }

    // Dead-space convex penalty on open bins (compress residual variance)
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        score += 0.00035 * pr * pr * pr * (0.5 + 0.7 * tightness);
        score += 0.10 * pr * (0.6 + 0.8 * tightness);
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
        if post_residual >= 10 {
            score -= 10.0;
        }
    } else if fitting_bins_count > 1 {
        score += 15.0 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // Best-fit style: prefer tighter-than-mean bins
    if (bin_residual as f64) < mean_residual - 10.0 {
        score -= 25.0;
    } else if (bin_residual as f64) > mean_residual + 20.0 && item_size < 30 {
        score += 12.0;
    }

    // Consolidation pressure with open-bin count
    score += (open_bins_count as f64).ln().max(0.0) * 4.0;
    if open_bins_count > 8 {
        score += (bin_residual as f64 / cap_f) * 7.0;
    }

    // NEW-BIN CANDIDATE handling
    if bin_residual == bin_capacity {
        let mut s = 55.0 - 15.0 * progress;
        if next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            // perfect 2-chain in a fresh bin
            if leftover == next_item_size as u32 {
                s -= 40.0 + 15.0 * (1.0 - progress);
            } else if leftover >= next_item_size {
                let d = (leftover - next_item_size) as i64;
                if d <= 8 {
                    s -= (18.0 - 2.0 * d as f64) * (0.5 + 0.5 * (1.0 - progress));
                }
            }
            // fresh bin can't host the chain: less attractive
            if item_size as u64 + next_item_size as u64 > bin_capacity as u64 {
                s += 8.0;
            }
            // big item: fresh bin is good
            if item_size > 60 {
                s -= 12.0;
            }
        }
        // compare against best open-bin waste
        if fitting_bins_count >= 1 {
            let open_waste = bin_residual.saturating_sub(item_size);
            if open_waste <= 5 {
                s += 30.0; // an open bin is near-perfect: don't open new
            } else if open_waste <= 15 {
                s += 10.0;
            } else if open_waste > 30 {
                s -= 4.0 + 0.08 * ((open_waste - 30) as f64).min(35.0);
            }
            // fresh bin keeps next item placeable while open bin would strand it
            if next_item_size > 0 {
                let open_after = bin_residual.saturating_sub(item_size);
                let fresh_after = bin_capacity.saturating_sub(item_size);
                if open_after < next_item_size && fresh_after >= next_item_size {
                    s -= 10.0 + 5.0 * (1.0 - progress);
                }
            }
        }
        // late stream: strongly discourage new bins
        if progress > 0.6 {
            s += 12.0 * (progress - 0.6) * 25.0;
        }
        // early stream: allow free opening
        if open_bins_count < 4 && progress < 0.3 {
            s -= 12.0;
        }
        if fitting_bins_count > 3 {
            s += 18.0;
        }
        score = s;
    } else {
        score -= 40.0 * progress;
    }

    // Late-stream waste-floor guard
    if post_residual > 0 && bin_residual != bin_capacity && progress > 0.6 && next_item_size > 0 && post_residual < next_item_size {
        let unus = 1.0 - post_residual as f64 / next_item_size as f64;
        score += 6.0 * unus * ((progress - 0.6) / 0.4).min(1.0);
    }

    // Compaction pull toward mean residual
    if post_residual > 0 && bin_residual != bin_capacity && fitting_bins_count >= 2 {
        let pr = post_residual as f64;
        let band = ((pr - mean_residual.max(0.0)) / cap_f).abs();
        score -= 3.0 * (1.0 - band.min(1.0)) * (0.4 + 0.6 * progress);
    }

    // Reusable small residual bonus
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 && bin_residual != bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
        score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / 10.0) * scarcity;
    }

    score
}

