            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left >= next_item_size {
                let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0);
                score -= 5.0 * scarcity * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // gen 20: near-parity halo
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if d > 0 && d <= 2 {
                score -= (14.0 - 4.0 * d as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // gen 20: dead-space convexity gain
        if post_residual > 0 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.0001 * pr * pr * pr * (0.5 + 0.7 * tightness);
        }

        // gen 20: tight-fit preservation
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 && bin_residual != bin_capacity {
            score -= 5.0 + 4.0 * (1.0 - progress);
        }

        // gen 21: halo widening to ±4
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if d > 2 && d <= 4 {
                score -= (6.0 - 1.5 * (d - 2) as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // gen 21: dead-space convexity escalation
        if post_residual > 0 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.00022 * pr * pr * pr * (0.5 + 0.7 * tightness);
        }

        // gen 21: tight-fit preservation widening
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 && bin_residual != bin_capacity {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= (3.0 + 3.0 * (1.0 - progress)) * scarcity;
        }

        // gen 21: residual-dispersion dead-space guard
        if post_residual > 0 && bin_residual != bin_capacity && mean_residual > 0.45 * cap_f {
            let pr = post_residual as f64;
            score += 0.06 * pr * (0.4 + 0.6 * progress);
        }

        // gen 22: dead-space convexity escalation
        if post_residual > 0 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.00032 * pr * pr * pr * (0.5 + 0.7 * tightness);
        }

        // gen 22: open-bin compaction pull
        if post_residual > 0 && bin_residual != bin_capacity && fitting_bins_count >= 2 {
            let pr = post_residual as f64;
            let band = ((pr - mean_residual.max(0.0)) / cap_f).abs();
            score -= 2.0 * (1.0 - band.min(1.0)) * (0.4 + 0.6 * progress);
        }

        // gen 22: fresh-bin halo extension to ±6
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if d > 4 && d <= 6 {
                score -= (3.0 - 1.0 * (d - 4) as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // gen 22: late-stream waste-floor guard
        if post_residual > 0 && bin_residual != bin_capacity && progress > 0.66 && post_residual < next_item_size.max(20) {
            let unus = 1.0 - (post_residual as f64 / (next_item_size.max(20) as f64));
            score += 4.0 * unus * ((progress - 0.66) / 0.34).min(1.0);
        }

        // gen 23 mutations (retained)
        if post_residual > 0 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.00045 * pr * pr * pr * (0.5 + 0.7 * tightness);
        }

        if post_residual > 0 && bin_residual != bin_capacity && fitting_bins_count >= 2 {
            let pr = post_residual as f64;
            let band = ((pr - mean_residual.max(0.0)) / cap_f).abs();
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= (2.5 + 1.5 * scarcity) * (1.0 - band.min(1.0)) * (0.4 + 0.6 * progress);
        }

        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if d > 6 && d <= 8 {
                score -= (2.0 - 0.75 * (d - 6) as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        if post_residual > 0 && bin_residual != bin_capacity && progress > 0.60 && post_residual < next_item_size.max(20) {
            let unus = 1.0 - (post_residual as f64 / (next_item_size.max(20) as f64));
            score += 6.0 * unus * ((progress - 0.60) / 0.40).min(1.0);
        }

        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 && bin_residual != bin_capacity {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / 10.0) * scarcity * (0.5 + 0.5 * progress);
        }

        // MUTATION (gen 36): dead-space convexity escalation continues — raise
        // the extra cubic coefficient from 0.00045 to 0.00060, deepening the
        // penalty on stranded mid/large residuals (momentum: ContinueDirection
        // on the diagnosed dead-space weakness).
        if post_residual > 0 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.00060 * pr * pr * pr * (0.5 + 0.7 * tightness);
        }

        // MUTATION (gen 36): compaction pull strengthening — widen the
        // mean-residual band homogenization gain (2.5 -> 3.2 base) and extend
        // it to fitting_bins_count == 1 so single-fitting bins are pulled
        // toward the residual mean instead of left as variance outliers.
        if post_residual > 0 && bin_residual != bin_capacity && fitting_bins_count >= 1 {
            let pr = post_residual as f64;
            let band = ((pr - mean_residual.max(0.0)) / cap_f).abs();
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            let single = if fitting_bins_count == 1 { 0.6 } else { 0.0 };
            score -= (3.2 + 1.5 * scarcity + single) * (1.0 - band.min(1.0)) * (0.4 + 0.6 * progress);
        }

        // MUTATION (gen 36): fresh-bin halo extension to ±10 — the widening
        // trend (±2 -> ±4 -> ±6 -> ±8) keeps capturing near-parity chain
        // continuations; extend with a shallow decay to ±10.
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if d > 8 && d <= 10 {
                score -= (1.5 - 0.5 * (d - 8) as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // MUTATION (gen 36): late-stream consolidation sharpening — waste-floor
        // guard strengthened (6.0 -> 8.0) with onset pulled earlier
        // (0.60 -> 0.55), forcing residual consolidation into fewer usable
        // slacks during the final stretch where the 45-bin gap concentrates.
        if post_residual > 0 && bin_residual != bin_capacity && progress > 0.55 && post_residual < next_item_size.max(20) {
            let unus = 1.0 - (post_residual as f64 / (next_item_size.max(20) as f64));
            score += 8.0 * unus * ((progress - 0.55) / 0.45).min(1.0);
        }

        // MUTATION (gen 36): residual-variance floor bonus strengthening —
        // reward open-bin placements whose post_residual is small but reusable
        // (within 10 of next item), directly compressing residual dispersion;
        // gain raised 3.5 -> 4.5 and window widened to 12.
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 12 && bin_residual != bin_capacity {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= 4.5 * (1.0 - (post_residual - next_item_size) as f64 / 12.0) * scarcity * (0.5 + 0.5 * progress);
        }

        // MUTATION (gen 36): near-parity fresh-bin exactness — exact chain
        // continuation bonus extended with a tightness-scaled component so
        // scarce streams favor exact two-item fills of fresh bins.
        if next_item_size > 0 && fitting_bins_count <= 2 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left == 0 {
                let tightness = (1.0 - (mean_residual / cap_f).min(1.0)).max(0.0);
                score -= 6.0 + 4.0 * tightness * (1.0 - progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that is too small to fit the smallest plausible item.
    if post_residual > 0 && post_residual < item_size.min(10) {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0;
        } else {
            // Penalize leaving residual that next item cannot use.
            score += 8.0;
        }
        // Strong synergy: post residual can host next item almost exactly.
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score -= 20.0 * (-gap / 15.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Global state: when mean residual is high, prefer reusing existing space.
    if mean_residual > 0.0 {
        let waste_vs_mean = post_residual as f64 - mean_residual;
        score += 0.15 * waste_vs_mean;
    }

    // Time horizon: early in stream, be more conservative (prefer new bins for large items);
    // late in stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    // Many open bins: encourage closing them out by filling residual.
    let bin_pressure = open_bins_count as f64 / (1.0 + (total_items as f64).sqrt());
    score += 3.0 * bin_pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: neutral-ish baseline; open a new bin only when this placement
    // would leave a very fragmented residual or item barely fits elsewhere.
    if bin_residual == bin_capacity {
        score = 55.0 - 10.0 * (item_size as f64 / bin_capacity as f64);
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap_f = bin_capacity as f64;
