        let crowd = ((open_bins_count as f64 - 6.0) / 10.0).min(1.0);
        let depth = 1.0 - ((post_residual as f64 - 27.5).abs() / 7.5).min(1.0);
        score += 3.5 * depth * crowd * (0.5 + 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = item_size as f64 / cap;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post residual)
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    // Early: tolerate larger residuals; Late: heavily penalize wasted space
    let progress_weight = 0.5 + 2.0 * progress * progress;
    score += progress_weight * norm_pr * norm_pr * cap * 0.1;

    // Reward high fill ratio, amplified quadratically as stream progresses
    score -= (1.0 - (1.0 - fit_ratio) * (1.0 - fit_ratio)) * (10.0 + 30.0 * progress);

    // Dead-space penalty: residuals too small for typical future items
    let dead = norm_pr * (1.0 - norm_pr);
    score += 8.0 * dead * dead * (0.5 + progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: bonus if next item fits the post residual
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 12.0;
        } else if (post_residual as u32) > 0 {
            score += 5.0 * (1.0 - pr / (next_item_size as f64)).max(0.0);
        }
    }

    // Mean-residual coupling: penalize bins far from the mean residual (keeps diversity)
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev * cap * 0.1;

    // New-bin candidate: penalize opening a new bin when open bins exist, more so late
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 15.0 + 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
