        // MUTATION (gen 36): fresh-bin halo extension to ±10 — the widening
        // trend (±2 -> ±4 -> ±6 -> ±8) keeps capturing near-parity chain
        // continuations; extend with a shallow decay to ±10.
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if d > 8 && d <= 10 {
                score -= (1.2 - 0.5 * (d - 8) as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // MUTATION (gen 36): late-stream consolidation sharpening — the
        // waste-floor guard onset is pulled earlier (0.60 -> 0.55) and the
        // amplitude raised (6.0 -> 7.5), forcing residual consolidation into
        // fewer usable slacks across the final stretch where the 45-bin gap
        // concentrates.
        if post_residual > 0 && bin_residual != bin_capacity && progress > 0.55 && post_residual < next_item_size.max(20) {
            let unus = 1.0 - (post_residual as f64 / (next_item_size.max(20) as f64));
            score += 7.5 * unus * ((progress - 0.55) / 0.45).min(1.0);
        }

        // MUTATION (gen 36): residual-variance floor bonus widening — the
        // small-but-reusable post-residual reward is extended from a
        // 10-wide to a 16-wide tail with a gentler decay, compressing
        // residual dispersion across a broader band of chain continuations.
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 16 && bin_residual != bin_capacity {
            let tail = (post_residual - next_item_size) as f64;
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= (3.5 - 0.6 * tail) * (1.0 - tail / 16.0).max(0.0) * scarcity * (0.5 + 0.5 * progress);
        }

        // MUTATION (gen 36): mid-stream dead-space alignment — a mild
        // complementary term rewarding open-bin placements whose
        // post_residual lands close to the mean residual during the middle
        // of the stream, reinforcing the compaction pull direction early
        // where the late-stream guard cannot act.
        if post_residual > 0 && bin_residual != bin_capacity && progress >= 0.2 && progress <= 0.55 && fitting_bins_count >= 2 {
            let pr = post_residual as f64;
            let band = ((pr - mean_residual.max(0.0)) / cap_f).abs();
            if band < 0.12 {
                score -= 2.0 * (1.0 - band / 0.12) * (0.6 + 0.4 * progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible into nice classes
    // (0 exact fit, small dead space, medium, large) get different bonuses.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit: exact fill is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Class boundaries via integer division thresholds on post_residual.
    let class = post_residual / 10; // 0..10 harmonic class
    match class {
        0 => score -= 60.0,          // tiny leftover (1..9): near-perfect
        1 => score -= 40.0,          // 10..19: still fillable by small items
        2 | 3 => score -= 20.0,      // 20..39: moderately usable
        4 | 5 => score -= 5.0,       // 40..59
        6 | 7 => score += 10.0,      // 60..79: wasteful unless new bin
        _ => {}                      // 80..99: large residual, keep open
    }

    // Dead-space penalty: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 0.0; // already rewarded above; exact smallness is fine
    }

    // Lookahead coupling: if next item fits the post residual, big reward.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 30.0 + 0.5 * (next_item_size as f64);
        } else if next_item_size > post_residual as u32 && post_residual > 0 {
            // next item won't fit here; penalize if residual becomes stranded
            score += 15.0 * (1.0 - pr / cap);
        }
    }

    // Last-chance bin: only one fitting bin -> strongly favor using it
    // to avoid opening a new bin, unless post residual is tiny dead space.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
        if post_residual > 0 && post_residual < 5 {
            score += 90.0; // but not if it strands near-zero space... actually keep reward
            score -= 90.0;
        }
    }

    // New-bin candidate handling: empty bin should only win when all open
    // bins would leave bad residuals. Base penalty so it's usually avoided.
    if bin_residual == bin_capacity {
        score += 120.0;
        // Early stream: allow more bins (exploration).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 40.0 * (1.0 - progress);
        // If mean residual across open bins is small, opening fresh is fine.
        score -= (mean_residual / cap).max(0.0) * 30.0;
        // If item is huge, a fresh bin guarantees a good post residual.
        if item_size >= 50 {
            score -= 25.0;
        }
    }

    // Prefer tighter bins overall: closeness of fit to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Mild penalty for proliferating bins when existing ones suffice.
    score += 0.5 * open_bins_count as f64;

    // Harmonic modulo bonus: post_residual divisible by 10 keeps clean
    // packing classes (helps future modulo-friendly fits).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    }
    if post_residual % 5 == 0 && post_residual % 10 != 0 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
