        let depth = 1.0 - ((post_residual as f64 - 27.5).abs() / 7.5).min(1.0);
        score += 3.5 * depth * crowd * (0.5 + 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill * fill;

    // Penalize small dead space that few future items can use.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 30.0 * (10.0 - dead);
        } else if dead < 20.0 {
            score += 8.0;
        }
    }

    // Perfect fit is excellent.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead: check whether next item could reuse the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain fit: excellent, residual stays productive.
            score -= 20.0 + 0.2 * next_item_size as f64;
        } else {
            // Next item won't fit here; residual likely becomes dead space.
            score += 0.3 * (next_item_size as f64 - post_residual as f64).min(50.0);
        }
    }

    // Global state: when many bins are open, encourage consolidation
    // (prefer filling existing bins); when few open, allow new bins.
    let consolidation = (open_bins_count as f64).ln().max(0.0);
    if bin_residual < bin_capacity {
        score -= 6.0 * consolidation;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.15 * (mean_residual - post_residual as f64);

    // Time horizon: late in the stream, close bins out aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * fill;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when open count is low
        // or the stream is early, hardened late in the stream.
        let base = 45.0 - 5.0 * consolidation - 15.0 * (1.0 - progress);
        score += base;
        // If this is the only fitting option, new bin is fine.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap_f = bin_capacity as f64;
    let slack = bin_residual as i64 - item_size as i64;

    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            let leftover_after_next = pr - nr;
            score -= 300.0 * (nr / pr);
            score -= 200.0 * (1.0 - leftover_after_next / cap_f);
            // tight-fit preservation: leaving a small reusable tail is valuable
            if leftover_after_next <= 5.0 {
                score -= 12.0 + 8.0 * (1.0 - progress);
            }
        } else {
            let unusability = 1.0 - pr / nr;
            score += 250.0 * unusability;
            // near-miss penalty: stranded residual just below next item
            let miss = nr - pr;
            if miss <= 6.0 {
                score += 12.0 * (1.0 - miss / 6.0);
            }
        }
        if (pr - nr).abs() < mean_residual.abs() * 0.5 {
            score -= 40.0;
        }
    } else {
        score += 100.0 * (1.0 - (post_residual as f64) / cap_f);
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    } else if fitting_bins_count > 1 {
        score += 30.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Best-fit style
    if (bin_residual as f64) < mean_residual {
        score -= 60.0;
    } else {
        score += 30.0;
    }

    // Consolidation pressure grows with stream progress
    if bin_residual != bin_capacity {
        score -= 50.0 * progress;
    }

    // Dead-space convexity: penalize large stranded residuals
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        score += 0.0004 * pr * pr * pr * (0.5 + 0.7 * tightness);
        // waste-ratio guard
        let waste_ratio = pr / cap_f;
        if waste_ratio < 0.05 {
            score += 7.0 * (1.0 - progress);
        }
        // small residual salvageable: mild reward
        if pr <= 12.0 {
            score -= 3.0 * (1.0 - pr / 12.0) * (0.5 + 0.5 * progress);
        }
    }

    // Scarcity-weighted stranding penalty
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && bin_residual != bin_capacity {
        let strandedness = 1.0 - (post_residual as f64 / next_item_size as f64);
        let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
        score += 9.0 * strandedness * scarcity;
    }

    // Mean-residual band compaction pull (reduce residual variance)
    if post_residual > 0 && bin_residual != bin_capacity && fitting_bins_count >= 2 {
        let pr = post_residual as f64;
        let band = ((pr - mean_residual.max(0.0)) / cap_f).abs();
        score -= 3.0 * (1.0 - band.min(1.0)) * (0.4 + 0.6 * progress);
    }

    // Late-stream waste-floor guard
    if post_residual > 0 && bin_residual != bin_capacity && progress > 0.60 && post_residual < next_item_size.max(20) {
        let unus = 1.0 - (post_residual as f64 / (next_item_size.max(20) as f64));
        score += 6.0 * unus * ((progress - 0.60) / 0.40).min(1.0);
    }

    // Open-bin count pressure
    score += open_bins_count as f64 * 2.0;
    if open_bins_count > 8 && bin_residual != bin_capacity {
        score += ((bin_residual as f64) / cap_f) * 6.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        score = 55.0 - 15.0 * progress;
        // exact 2-chain in a fresh bin is excellent
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 60.0 + 20.0 * progress;
        } else if next_item_size > 0 && item_size + next_item_size >= bin_capacity {
            score -= 45.0;
        }
        if item_size as f64 > 0.6 * cap_f {
            score -= 30.0;
        }
        if progress > 0.8 {
            score += 10.0;
        }
        if fitting_bins_count > 2 {
            score += 20.0;
        }
        if open_bins_count < 4 && progress < 0.3 {
            score -= 12.0;
        }
        if next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            // fresh-bin near-parity halo: leftover close to next item means a
            // future item may chain into it
            let d = (leftover as i64 - next_item_size as i64).abs();
            if leftover >= next_item_size {
                score -= 10.0 + 6.0 * (1.0 - progress);
                if d > 0 && d <= 4 {
                    score -= (14.0 - 3.0 * d as f64) * (0.5 + 0.5 * (1.0 - progress));
                }
            } else if leftover < 10 {
                score += 6.0; // tiny dead space in a fresh bin is bad
            }
            if leftover > 60 {
                score += 0.06 * ((leftover - 60) as f64).min(35.0);
            }
        }
        // prefer fresh bin when the best open fit would strand a lot
        if fitting_bins_count >= 1 {
            let open_waste = bin_residual.saturating_sub(item_size) as f64;
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as f64;
            if open_waste > fresh_left + 18.0 {
                score -= 4.0 * ((open_waste - fresh_left - 18.0) / 20.0).min(1.0) * (0.6 + 0.4 * (1.0 - progress));
            }
            if open_waste > 35 {
                score -= 3.0 + 0.05 * ((open_waste - 35.0) as f64).min(30.0);
            }
        }
        // late stream: opening bins is expensive
        if progress > 0.6 {
            score += 7.5 * (progress - 0.6) * 25.0;
        }
        if item_size < 15 && progress > 0.5 && fitting_bins_count >= 1 {
            score += 15.0;
        }
        // next item won't fit after this placement anywhere good
        if next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size);
            if leftover < next_item_size {
                let miss = (next_item_size - leftover) as f64;
                if miss <= 8.0 {
                    score += 12.0 * (1.0 - miss / 8.0);
                }
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap_f = bin_capacity as f64;
    let resid_f = bin_residual as f64;
    let slack = bin_residual as i64 - item_size as i64;

    if post_residual == 0 {
        score -= 65.0;
    }
    if slack >= 0 && slack <= 4 {
        score -= 20.0;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0 + 22.0 * (1.0 - progress);
        } else if post_residual > next_item_size {
            let slack_after_next = post_residual - next_item_size;
            score -= 25.0 - (slack_after_next as f64).min(40.0) * 0.3;
            if slack_after_next > 40 {
                score += (slack_after_next as f64 - 40.0) * 0.2;
            }
        } else {
            let shortfall = (next_item_size - post_residual) as f64;
            score += shortfall * 0.85;
            let half_next = next_item_size / 2;
            if post_residual > 0 && post_residual < half_next {
                score += 14.0;
            }
        }
    } else {
        score -= 10.0;
    }

    if post_residual > 0 {
        let waste_ratio = post_residual as f64 / cap_f;
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        let severity = 1.4 - 0.8 * tightness;
        if post_residual < next_item_size && next_item_size > 0 {
            let unusability = 1.0 - (post_residual as f64 / next_item_size as f64);
            score += 16.0 * unusability * (1.0 - 0.5 * progress) * severity;
            if post_residual < 10 {
                score += 9.0 * severity * (1.0 - 0.4 * progress);
            }
        } else if waste_ratio < 0.05 {
            score += 7.0 * (1.0 - progress) * severity;
        } else if waste_ratio < 0.10 && post_residual < 40 {
            score += 3.0 * (1.0 - progress) * severity;
        }
    }

    if resid_f > mean_residual + 20.0 && item_size < 30 {
        if next_item_size == 0 || post_residual < next_item_size {
            score += 10.0;
        }
    } else if resid_f < mean_residual - 20.0 {
        score -= 8.0;
    }

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
        if post_residual >= 10 {
            score -= 10.0;
        }
    }

    if open_bins_count > 8 {
        score += (resid_f / cap_f) * 6.0;
    }
    score -= (open_bins_count as f64).ln().max(0.0) * 3.0;

    if post_residual >= 25 {
        score -= 4.0;
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 15 {
            score -= 6.0;
        }
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 20 {
            let sweet = if after_next <= 60 { 3.0 } else { 0.0 };
            score -= 5.0 + 5.0 * (1.0 - progress) + sweet;
        }
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 6.0 * (post_residual as f64 / cap_f) * 10.0;
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let strandedness = 1.0 - (post_residual as f64 / next_item_size as f64);
        let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0);
        score += 9.0 * strandedness * scarcity;
    }

    if post_residual >= 20 && post_residual <= 60 {
        score -= 3.0 + 4.0 * (1.0 - progress);
    }
    if post_residual >= 1 && post_residual <= 5 {
        score += 5.0;
    }

    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap > 0 && gap <= 8 {
            score -= 4.0 + 3.0 * (1.0 - progress);
        }
    }

    if item_size > 0 && bin_residual % item_size == 0 && bin_residual != bin_capacity {
        score -= 5.0;
        if post_residual == 0 {
            score -= 4.0;
        }
    }

    if next_item_size > 0 && post_residual == next_item_size && progress < 0.4 {
        score -= 6.0;
    }

    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let chain_left = bin_residual - item_size - next_item_size;
        if chain_left >= 15 && chain_left <= 55 {
            score -= 7.0 + 5.0 * (1.0 - progress);
        }
    }

    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap > 8 && gap <= 20 {
            score += 1.5;
