                score -= 5.0 * scarcity * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // gen 20: near-parity halo
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if d > 0 && d <= 2 {
                score -= (14.0 - 4.0 * d as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // gen 20: dead-space convexity gain
        if post_residual > 0 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.0001 * pr * pr * pr * (0.5 + 0.7 * tightness);
        }

        // gen 20: tight-fit preservation
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 && bin_residual != bin_capacity {
            score -= 5.0 + 4.0 * (1.0 - progress);
        }

        // gen 21: halo widening to ±4
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if d > 2 && d <= 4 {
                score -= (6.0 - 1.5 * (d - 2) as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // gen 21: dead-space convexity escalation
        if post_residual > 0 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.00022 * pr * pr * pr * (0.5 + 0.7 * tightness);
        }

        // gen 21: tight-fit preservation widening
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 && bin_residual != bin_capacity {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= (3.0 + 3.0 * (1.0 - progress)) * scarcity;
        }

        // gen 21: residual-dispersion dead-space guard
        if post_residual > 0 && bin_residual != bin_capacity && mean_residual > 0.45 * cap_f {
            let pr = post_residual as f64;
            score += 0.06 * pr * (0.4 + 0.6 * progress);
        }

        // gen 22: dead-space convexity escalation
        if post_residual > 0 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.00032 * pr * pr * pr * (0.5 + 0.7 * tightness);
        }

        // gen 22: open-bin compaction pull
        if post_residual > 0 && bin_residual != bin_capacity && fitting_bins_count >= 2 {
            let pr = post_residual as f64;
            let band = ((pr - mean_residual.max(0.0)) / cap_f).abs();
            score -= 2.0 * (1.0 - band.min(1.0)) * (0.4 + 0.6 * progress);
        }

        // gen 22: fresh-bin halo extension to ±6
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if d > 4 && d <= 6 {
                score -= (3.0 - 1.0 * (d - 4) as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // gen 22: late-stream waste-floor guard
        if post_residual > 0 && bin_residual != bin_capacity && progress > 0.66 && post_residual < next_item_size.max(20) {
            let unus = 1.0 - (post_residual as f64 / (next_item_size.max(20) as f64));
            score += 4.0 * unus * ((progress - 0.66) / 0.34).min(1.0);
        }

        // gen 23: dead-space convexity escalation
        if post_residual > 0 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.00045 * pr * pr * pr * (0.5 + 0.7 * tightness);
        }

        // gen 23: compaction pull strengthening
        if post_residual > 0 && bin_residual != bin_capacity && fitting_bins_count >= 2 {
            let pr = post_residual as f64;
            let band = ((pr - mean_residual.max(0.0)) / cap_f).abs();
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= (2.5 + 1.5 * scarcity) * (1.0 - band.min(1.0)) * (0.4 + 0.6 * progress);
        }

        // gen 23: fresh-bin halo extension to ±8
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if d > 6 && d <= 8 {
                score -= (2.0 - 0.75 * (d - 6) as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // gen 23: late-stream consolidation sharpening
        if post_residual > 0 && bin_residual != bin_capacity && progress > 0.60 && post_residual < next_item_size.max(20) {
            let unus = 1.0 - (post_residual as f64 / (next_item_size.max(20) as f64));
            score += 6.0 * unus * ((progress - 0.60) / 0.40).min(1.0);
        }

        // gen 23: residual-variance floor bonus
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 && bin_residual != bin_capacity {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / 10.0) * scarcity * (0.5 + 0.5 * progress);
        }

        // MUTATION (gen 38): dead-space convexity escalation continues — raise
        // the extra cubic coefficient from 0.00045 to 0.00060 (momentum:
        // ContinueDirection), deepening the dead-space penalty on stranded
        // mid/large residuals, which remains the diagnosed weakness.
        if post_residual > 0 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.00060 * pr * pr * pr * (0.5 + 0.7 * tightness);
        }

        // MUTATION (gen 38): compaction pull strengthening — the mean-residual
        // band homogenization is reinforced (2.5+1.5s -> 3.5+2.0s) and its
        // scarcity weighting extended, since Sigma_res (0.2981) remains the
        // diagnosed weakness and the pull direction kept improving.
        if post_residual > 0 && bin_residual != bin_capacity && fitting_bins_count >= 2 {
            let pr = post_residual as f64;
            let band = ((pr - mean_residual.max(0.0)) / cap_f).abs();
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= (3.5 + 2.0 * scarcity) * (1.0 - band.min(1.0)) * (0.4 + 0.6 * progress);
        }

        // MUTATION (gen 38): fresh-bin halo extension to ±11 — the widening
        // trend (±2 -> ±4 -> ±6 -> ±8) keeps capturing near-parity chain
        // continuations; extend with a shallow decay to ±11.
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if d > 8 && d <= 11 {
                score -= (1.2 - 0.35 * (d - 8) as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // MUTATION (gen 38): late-stream consolidation sharpening — the
        // waste-floor guard is strengthened (6.0 -> 8.5) with onset pulled
        // earlier (0.60 -> 0.55), forcing residual consolidation into fewer
        // usable slacks in the final stretch where the 45-bin gap
        // concentrates.
        if post_residual > 0 && bin_residual != bin_capacity && progress > 0.55 && post_residual < next_item_size.max(20) {
            let unus = 1.0 - (post_residual as f64 / (next_item_size.max(20) as f64));
            score += 8.5 * unus * ((progress - 0.55) / 0.45).min(1.0);
        }

        // MUTATION (gen 38): residual-variance floor bonus strengthening —
        // reward open-bin placements whose post_residual leaves a tight,
        // reusable tail (0..=12 after next item), directly compressing
        // residual dispersion (10 -> 12 window, 3.5 -> 4.5 magnitude).
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 12 && bin_residual != bin_capacity {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= 4.5 * (1.0 - (post_residual - next_item_size) as f64 / 12.0) * scarcity * (0.5 + 0.5 * progress);
        }

        // MUTATION (gen 38): slack-quadratic compaction term — a mild convex
        // penalty on mid-range post residuals (15..=45) that are neither
        // near-zero nor chain-reusable, complementing the cubic family by
        // targeting the residual-variance weakness from a second direction.
        if post_residual > 14 && post_residual < 45 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.012 * pr * (1.0 - pr / 45.0) * (0.6 + 0.7 * tightness) * (0.5 + 0.5 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post residual), non-linearly
    let mut score = pr.powf(1.5) / (1.0 + 0.5 * norm_pr);

    // Smooth progress coupling: late in stream, penalize wasted space more
    let late = progress * progress;
    score += 20.0 * late * norm_pr * norm_pr;

    // Mean residual coupling: if this bin's residual deviates from mean, prefer
    // using bins with small residual (harmonizing open bins)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev.max(0.0) * (1.0 + late);

    // Last-chance bonus: if only this bin fits, strongly reward using it
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else {
        // More competing bins: slight penalty to avoid scattering
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: penalize if next item cannot use this post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr {
            score += 6.0 * late + 3.0 * (nx - pr) / cap;
        } else {
            // Reward when next item fits snugly into the resulting residual
            score -= 4.0 * (1.0 - ((pr - nx) / cap).abs()) * (1.0 - late);
        }
    }

    // New-bin candidate: discourage opening a new bin unless residuals are tight
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - (mean_residual / cap);
        score += 25.0 * (1.0 - avg_fill) * (1.0 + late) + 10.0 * (open_bins_count as f64).ln().max(0.0);
        if fitting_bins_count == 1 {
            score += 40.0; // never open when a last-chance bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let cap_f = bin_capacity as f64;
    let resid_f = bin_residual as f64;
    let slack = bin_residual as i64 - item_size as i64;

    // Perfect fit reward, scaled by scarcity of fitting bins.
    if post_residual == 0 {
        score -= 65.0;
        let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
        score -= 8.0 * scarcity * (0.5 + 0.5 * (1.0 - progress));
        let crowd = ((open_bins_count as f64 - 5.0).max(0.0) / 15.0).min(1.0);
        score -= 6.0 * crowd * (0.5 + 0.5 * (1.0 - progress));
    }

    // Dead-space avoidance: graded penalties on small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }
    // Small-gap reversal: tiny slacks (1..=5) are actually near-perfect fills.
    if post_residual >= 1 && post_residual <= 5 {
        score += 5.0;
    }

    // Lookahead coupling with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0 + 22.0 * (1.0 - progress);
        } else if post_residual > next_item_size {
            let tail = post_residual - next_item_size;
            // Tight chain continuation is valuable.
            if tail <= 5 {
                score -= (3.0 + 3.0 * (1.0 - progress)) / (fitting_bins_count as f64).max(1.0).sqrt();
            } else if tail <= 30 {
                let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
                score -= (4.0 + 3.0 * (1.0 - progress)) * (1.0 - (tail as f64 - 5.0).abs() / 25.0) * scarcity;
            } else if tail > 55 {
                score += (tail as f64 - 55.0) * 0.15;
            }
        } else {
            // Next item won't fit here: stranded dead space.
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 0.85;
            if miss <= 6.0 {
                score += 10.0 * (1.0 - miss / 6.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
    } else {
        score -= 10.0;
    }

    // Two-item chain lookahead: does item + next fit with a reusable remainder?
    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let chain_left = bin_residual - item_size - next_item_size;
        if chain_left == 0 {
            score -= 10.0 + 6.0 * (1.0 - progress);
        } else if chain_left <= 3 {
            score -= 10.0 + 6.0 * (1.0 - progress) + 3.0 / (fitting_bins_count as f64).max(1.0);
        } else if chain_left >= 8 && chain_left <= 55 {
            score -= 7.0 + 5.0 * (1.0 - progress);
        }
    }

    // Open-bin pressure: consolidate when many bins are open.
    if open_bins_count > 8 {
        score += (resid_f / cap_f) * 6.0;
    }
    score -= (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Last-chance bin handling.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
        if post_residual >= 10 {
            score -= 10.0;
        }
    }

    // Mean-residual alignment: penalize residual outliers to reduce variance.
    if post_residual > 0 && bin_residual != bin_capacity {
        let dev = ((post_residual as f64 - mean_residual.max(0.0)) / cap_f).abs();
        score += 3.0 * dev;
        score -= 2.5 * (1.0 - dev.min(1.0)) * (0.4 + 0.6 * (1.0 - progress));
