    }

    // New-bin candidate: comprehensive fresh-bin evaluation.
    if bin_residual == bin_capacity {
        score = 55.0 - 15.0 * progress;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        }
        if next_item_size > 0 && item_size + next_item_size >= bin_capacity {
            score -= 45.0;
        }
        if item_size as f64 > 0.6 * cap_f {
            score -= 30.0;
        }
        if progress > 0.8 {
            score += 10.0;
        }
        if fitting_bins_count > 2 {
            score += 20.0;
        }
        if open_bins_count < 4 && progress < 0.3 {
            score -= 12.0;
        }
        // Compare fresh-bin leftover vs open-bin waste for next-item continuity.
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            let open_waste = bin_residual.saturating_sub(item_size);
            if fresh_left >= next_item_size && open_waste >= 20 {
