        }
        // Mid-band fresh leftovers (30..=55) are reusable.
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left >= 30 && fresh_left <= 55 {
                score -= 2.5 * (1.0 - ((fresh_left as f64 - 42.5).abs() / 12.5).min(1.0)) * (1.0 - 0.4 * progress);
            } else if fresh_left > 65 {
                score += 0.06 * ((fresh_left - 65) as f64).min(35.0) * (0.5 + 0.5 * progress);
            }
        }
        // Scarcity-locked chain continuity for fresh bins.
        if fitting_bins_count <= 2 && next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left >= next_item_size {
                let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0);
                score -= 5.0 * scarcity * (0.5 + 0.5 * (1.0 - progress));
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: perfect fits (0), and small residues
    // that pair with common item sizes are rewarded.
    if post_residual == 0 {
        score -= 500.0; // perfect fit
    } else {
        let pr = post_residual as f64;
        let frac = pr / cap;

        // Reward small, reusable residues (good pairing potential).
        if post_residual <= 10 { score -= 120.0; }
        else if post_residual <= 20 { score -= 60.0; }
        else if post_residual <= 30 { score -= 25.0; }

        // Penalize awkward mid-range dead space.
        if post_residual > 40 && post_residual < 60 { score += 30.0; }

        // Modulo-10 structure: residues divisible by 10 tend to pair with
        // integer item sizes drawn from coarse grids.
        if post_residual % 10 == 0 { score -= 15.0; }
        if post_residual % 5 == 0 { score -= 5.0; }

        // Capacity-fraction harmony: exact quarter/half/three-quarter residues
        // are structurally useful.
        if (frac * 4.0).fract() == 0.0 { score -= 20.0; }
        if (frac * 3.0).fract() == 0.0 { score -= 10.0; }

        // Lookahead: strongly favor bins whose residue fits the next item.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                let slack = (post_residual - next_item_size) as f64;
                score -= 40.0 - 0.3 * slack.min(40.0);
                if slack == 0.0 { score -= 60.0; } // chain of perfect fits
            } else {
                score += 25.0; // next item won't fit here
            }
        }

        // Dead-space penalty scaled by remaining stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 0.5 * pr * (1.0 - progress);
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // otherwise the item forces a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when no open bin is a good home.
    if bin_residual == bin_capacity {
        let good_open = mean_residual >= item_size as f64 + 5.0;
        if good_open {
            score += 200.0; // keep using open bins
        } else {
            score -= 80.0; // better to open fresh capacity
        }
        // Late in the stream, avoid opening bins for marginal gains.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress > 0.8 { score += 60.0 * progress; }
    }

    // Mild preference for tighter bins overall.
    score += 0.1 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
