            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left > 45 && progress > 0.25 {
                score += 0.10 * ((fresh_left - 45) as f64).min(45.0) * (0.5 + 0.5 * progress);
            } else if fresh_left >= next_item_size && fresh_left <= 40 {
                score -= 4.0 * (1.0 - progress);
            }
        }

        // MUTATION (gen 38): open-bin exact-adjacent reward — when an open bin
        // can absorb the item AND the next item nearly exactly (leftover <= 2),
        // reward strongly regardless of crowd, since these closures directly
        // eliminate dead space that accumulates into wasted bins.
        if next_item_size > 0 && item_size + next_item_size <= bin_residual {
            let chain_left = bin_residual - item_size - next_item_size;
            if chain_left <= 2 {
                score -= 8.0 + 5.0 * (1.0 - progress);
            }
        }
    }

    // gen 30 retained: sigmoid reuse attraction on open bins
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let reuse = 1.0 / (1.0 + (-(pr - 30.0) / 12.0).exp());
        score -= 3.0 * reuse * (0.4 + 0.4 * (1.0 - progress));
    }

    // gen 30 retained: exact-fill scarcity bonus on open bins
    if post_residual == 0 && bin_residual != bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
        score -= 10.0 + 6.0 * (1.0 - progress) + 5.0 * scarcity;
    }

    // MUTATION (gen 38): tail-reuse lookahead on open bins — reward placements
    // whose post_residual still accommodates the next item with a tight,
    // re-usable remainder (<= 12), steering residual space toward compact,
    // chainable states and shrinking Sigma_res.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let tail = post_residual - next_item_size;
        if tail <= 12 {
            score -= 3.0 * (1.0 - tail as f64 / 12.0) * (0.5 + 0.5 * (1.0 - progress));
        } else if tail > 50 && open_bins_count > 8 {
            score += 0.05 * ((tail - 50) as f64).min(40.0) * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION (gen 38): large-item crowding guard — when the item is large
    // (> 60) and open-bin space is plentiful, prefer consolidating into the
    // fullest fitting bin; penalize choices that leave big slack unused while
    // many bins remain open, tightening the open pool.
    if item_size > 60 && open_bins_count > 10 && bin_residual != bin_capacity {
        let slack_f = slack.max(0) as f64;
        score += 0.05 * slack_f.min(40.0) * (0.5 + 0.5 * (1.0 - progress));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever fit
    // another item (min size 1..10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Reward tight fits relative to the residual (small waste fraction).
    if bin_residual > 0 {
        let waste_frac = post_residual as f64 / bin_residual as f64;
        score += waste_frac * 20.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // reward this placement strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // Next item cannot use this bin: post residual is more likely dead space.
            score += 10.0;
        }
    }

    // Open-bin pressure: prefer reusing bins when many are open, but when this
    // is the ONLY fitting bin, strongly discourage opening a new bin instead.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 100.0;
    } else if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening a bin when open bins exist and fit,
        // unless the item is large and open bins are fragmented.
        if fitting_bins_count > 0 {
            score += 45.0 + open_bins_count as f64 * 3.0;
        }
        // Opening a new bin for a large item with fragmented open bins is fine.
        if item_size > 60 && mean_residual < item_size as f64 {
            score -= 25.0;
        }
    }

    // Mean-residual coupling: placing into a bin whose residual is far below
    // the mean keeps the mean high (many usable bins), reward that.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= diff * 0.3;
    } else {
        score += (-diff) * 0.15;
    }

    // Late-stream tightening: as the stream progresses, avoid leaving gaps
    // below the median item size (assume ~ mid-range), since fewer chances remain.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 && post_residual < 30 {
        score += progress * 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
