pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with smooth polynomial shaping
    let mut score = pr;

    // Non-linear polynomial coupling: dead space penalty grows quadratically
    // with residual, and more steeply as the stream progresses.
    let dead = norm_pr * norm_pr * cap;
    score += dead * (0.5 + progress);

    // Cubic interaction: very large residuals late in the stream are heavily penalized
    score += norm_pr * norm_pr * norm_pr * cap * progress * 2.0;

    // Perfect fit reward (post_residual near zero)
    if pr == 0 {
        score -= 25.0 + 25.0 * progress;
    }

    // Lookahead: reward if next item fits the post-residual smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let tight = 1.0 - (pr - nx) / cap;
            score -= 10.0 * tight * tight;
        } else {
            // next item won't fit here: penalize leaving a gap that blocks it
            score += 5.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: mild penalty so it's only chosen when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 8.0 + 12.0 * (1.0 - progress);
    }

    // Slight preference for bins with residual close to mean (balance preservation)
    let dev = (pr - mean_residual).abs() / cap;
    score += dev * dev * 10.0;

    score
}

