                score -= 4.0 * (1.0 - fresh_left as f64 / 12.0) * (0.6 + 0.4 * (1.0 - progress));
            }
        }
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left >= 1 && fresh_left <= 6 {
                score -= 8.0 * (1.0 - fresh_left as f64 / 6.0) * (0.7 + 0.3 * (1.0 - progress));
            }
        }
        if fitting_bins_count == 1 && next_item_size > 0 {
            let open_waste = bin_residual.saturating_sub(item_size) as f64;
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as f64;
            if open_waste > fresh_left + 18.0 {
                score -= 4.0 * ((open_waste - fresh_left - 18.0) / 20.0).min(1.0) * (0.6 + 0.4 * (1.0 - progress));
            }
        }

        // gen 22: fresh-bin exact-parity halo
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if d == 0 {
                score -= 14.0 + 6.0 * (1.0 - progress);
            } else if d <= 4 {
                score -= (10.0 - 2.0 * d as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // gen 22: fresh-bin salvage ceiling
        if fitting_bins_count >= 1 && next_item_size > 0 {
            let open_after = bin_residual.saturating_sub(item_size);
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if open_after < next_item_size && fresh_left >= next_item_size + 10 {
                score -= 3.0 + 3.0 * (1.0 - progress);
            }
        }

        // gen 22: scarcity-locked chain continuity
        if fitting_bins_count <= 2 && next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left >= next_item_size {
                let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0);
                score -= 5.0 * scarcity * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // gen 23: fresh-bin halo extension to ±8
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if d > 4 && d <= 8 {
                score -= (3.0 - 0.35 * (d - 4) as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // gen 23: late-stream consolidation sharpening
        if post_residual > 0 && bin_residual != bin_capacity && progress > 0.60 && post_residual < next_item_size.max(20) {
            let unus = 1.0 - (post_residual as f64 / (next_item_size.max(20) as f64));
            score += 6.0 * unus * ((progress - 0.60) / 0.40).min(1.0);
        }

        // gen 23: residual-variance floor bonus
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 && bin_residual != bin_capacity {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / 10.0) * scarcity * (0.5 + 0.5 * progress);
        }

        // gen 25: dead-space convexity escalation
        if post_residual > 0 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.00060 * pr * pr * pr * (0.5 + 0.7 * tightness);
        }

        // gen 25: compaction pull strengthening
        if post_residual > 0 && bin_residual != bin_capacity && fitting_bins_count >= 2 {
            let pr = post_residual as f64;
            let band = ((pr - mean_residual.max(0.0)) / cap_f).abs();
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= (3.0 + 1.5 * scarcity) * (1.0 - band.min(1.0)) * (0.4 + 0.6 * progress);
        }

        // gen 25: open-bin parity halo
        if next_item_size > 0 && bin_residual != bin_capacity {
            let pr = post_residual as i64;
            let nx = next_item_size as i64;
            let d = (pr - nx).abs();
            if d <= 3 {
                let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
                score -= (8.0 - 2.0 * d as f64) * (0.5 + 0.5 * (1.0 - progress)) * scarcity;
            }
        }

        // gen 25: two-item lookahead compaction
        if next_item_size > 0 && item_size + next_item_size <= bin_residual && bin_residual != bin_capacity {
            let leftover = bin_residual - item_size - next_item_size;
            if leftover <= 8 {
                score -= (9.0 - leftover as f64) * (0.6 + 0.4 * (1.0 - progress));
            }
        }

        // gen 25: mid-residual dead-band penalty
        if post_residual >= 20 && post_residual <= 35 && bin_residual != bin_capacity && open_bins_count > 6 {
            let crowd = ((open_bins_count as f64 - 6.0) / 10.0).min(1.0);
            let depth = 1.0 - ((post_residual as f64 - 27.5).abs() / 7.5).min(1.0);
            score += 4.0 * depth * crowd * (0.5 + 0.5 * progress);
        }

        // gen 25: fresh-bin exact-closure guard
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            let open_waste = bin_residual.saturating_sub(item_size);
            if fresh_left > 0 && fresh_left < next_item_size && open_waste == 0 {
                score += 10.0 * (1.0 - progress);
            }
        }
    }

    // gen 22: dead-space convexity escalation (base cubic family)
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        score += 0.00030 * pr * pr * pr * (0.5 + 0.7 * tightness);
    }

    // gen 22: residual-dispersion guard
    if post_residual > 0 && bin_residual != bin_capacity && mean_residual > 0.45 * cap_f {
        let pr = post_residual as f64;
        score += 0.07 * pr * (0.4 + 0.6 * progress);
    }

    // gen 22: tight-fit preservation
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 && bin_residual != bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
        score -= (3.0 + 3.0 * (1.0 - progress)) * scarcity;
    }

    // gen 22: open-bin parity halo
    if next_item_size > 0 && bin_residual != bin_capacity {
        let pr = post_residual as i64;
        let nx = next_item_size as i64;
        let d = (pr - nx).abs();
        if d <= 3 {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= (8.0 - 2.0 * d as f64) * (0.5 + 0.5 * (1.0 - progress)) * scarcity;
        }
    }

    // gen 22: two-item lookahead compaction
    if next_item_size > 0 && item_size + next_item_size <= bin_residual && bin_residual != bin_capacity {
        let leftover = bin_residual - item_size - next_item_size;
        if leftover <= 8 {
            score -= (9.0 - leftover as f64) * (0.6 + 0.4 * (1.0 - progress));
        }
    }

    // gen 22: mid-residual dead-band penalty
    if post_residual >= 20 && post_residual <= 35 && bin_residual != bin_capacity && open_bins_count > 6 {
        let crowd = ((open_bins_count as f64 - 6.0) / 10.0).min(1.0);
        let depth = 1.0 - ((post_residual as f64 - 27.5).abs() / 7.5).min(1.0);
        score += 3.5 * depth * crowd * (0.5 + 0.5 * progress);
    }

    // MUTATION (gen 39): dead-space convexity escalation — cubic stranded-
    // residual pressure raised from 0.00060 to 0.00075, continuing the
    // diagnosed dead-space weakness (Sigma_res 0.2929) in the mid/large band.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        score += 0.00015 * pr * pr * pr * (0.5 + 0.7 * tightness);
    }

    // MUTATION (gen 39): compaction pull strengthening — mean-residual band
    // homogenization reinforced (3.0 -> 4.0 base) with scarcity weighting,
    // directly compressing residual dispersion.
    if post_residual > 0 && bin_residual != bin_capacity && fitting_bins_count >= 2 {
        let pr = post_residual as f64;
        let band = ((pr - mean_residual.max(0.0)) / cap_f).abs();
        let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
        score -= (1.0 + 1.0 * scarcity) * (1.0 - band.min(1.0)) * (0.4 + 0.6 * progress);
    }

    // MUTATION (gen 39): open-bin parity halo widening — extend the fine-
    // grained ±3 residual-to-next-item halo to ±5 with linear decay, coupling
    // fine residual fitting with lookahead chain continuation.
    if next_item_size > 0 && bin_residual != bin_capacity {
        let pr = post_residual as i64;
        let nx = next_item_size as i64;
        let d = (pr - nx).abs();
        if d > 3 && d <= 5 {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= (2.5 - 1.0 * (d - 3) as f64) * (0.5 + 0.5 * (1.0 - progress)) * scarcity;
        }
    }

    // MUTATION (gen 39): exact-closure chain bonus — when the current item
    // plus the next item closes the bin exactly, push hard toward closure.
    if next_item_size > 0 && item_size + next_item_size == bin_residual && bin_residual != bin_capacity {
        score -= 6.0 + 5.0 * (1.0 - progress);
    }

    // MUTATION (gen 39): sub-halving dead-space penalty — post-fit residuals
    // smaller than half the next item are nearly unusable; escalate the
    // stranded penalty when many bins are open to force consolidation.
    if post_residual > 0 && next_item_size > 0 && post_residual * 2 < next_item_size && bin_residual != bin_capacity && open_bins_count > 8 {
        let unus = 1.0 - (post_residual as f64 / (next_item_size as f64 / 2.0));
        let crowd = ((open_bins_count as f64 - 8.0) / 8.0).min(1.0);
        score += 5.0 * unus * crowd * (0.5 + 0.5 * progress);
    }

    // MUTATION (gen 39): fresh-bin perfect-parity deepening — when a fresh
    // bin's post-two-item leftover exactly matches the item after next's
    // size class (next_item_size), deepen the exact-parity halo reward.
    if next_item_size > 0 && fitting_bins_count >= 1 {
        let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
        if fresh_left == next_item_size {
            score -= 4.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap_f = bin_capacity as f64;
    let resid_f = bin_residual as f64;
    let slack = bin_residual as i64 - item_size as i64;

    // --- 2-step lookahead core ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0 + 22.0 * (1.0 - progress);
        } else if post_residual > next_item_size {
            let slack_after_next = post_residual - next_item_size;
            score -= 25.0 - (slack_after_next as f64).min(40.0) * 0.3;
            if slack_after_next > 40 {
                score += (slack_after_next as f64 - 40.0) * 0.2;
            }
        } else {
            let shortfall = (next_item_size - post_residual) as f64;
            score += shortfall * 0.85;
            let half_next = next_item_size / 2;
            if post_residual > 0 && post_residual < half_next {
                score += 14.0;
            }
        }
    } else {
        score -= 10.0;
    }

    // --- Dead-space / unusability penalties ---
    if post_residual > 0 {
        let waste_ratio = post_residual as f64 / cap_f;
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        let severity = 1.4 - 0.8 * tightness;
        if post_residual < next_item_size && next_item_size > 0 {
            let unusability = 1.0 - (post_residual as f64 / next_item_size as f64);
            score += 16.0 * unusability * (1.0 - 0.5 * progress) * severity;
            if post_residual < 10 {
                score += 9.0 * severity * (1.0 - 0.4 * progress);
            }
        } else if waste_ratio < 0.05 {
            score += 7.0 * (1.0 - progress) * severity;
        } else if waste_ratio < 0.10 && post_residual < 40 {
            score += 3.0 * (1.0 - progress) * severity;
        }
    }

    // --- Relative-to-mean coupling ---
    if resid_f > mean_residual + 20.0 && item_size < 30 {
        if next_item_size == 0 || post_residual < next_item_size {
            score += 10.0;
        }
    } else if resid_f < mean_residual - 20.0 {
        score -= 8.0;
    }

    // --- Last-chance bonus ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
        if post_residual >= 10 {
            score -= 10.0;
        }
    }

    // --- Open-bin crowd pressure ---
    if open_bins_count > 8 {
        score += (resid_f / cap_f) * 6.0;
    }
    score -= (open_bins_count as f64).ln().max(0.0) * 3.0;

    // --- Roomy post-residual rewards ---
    if post_residual >= 25 {
        score -= 4.0;
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 15 {
            score -= 6.0;
        }
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 20 {
            let sweet = if after_next <= 60 { 3.0 } else { 0.0 };
            score -= 5.0 + 5.0 * (1.0 - progress) + sweet;
        }
    }

    // --- Strandedness / scarcity coupling ---
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let strandedness = 1.0 - (post_residual as f64 / next_item_size as f64);
        let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0);
        score += 9.0 * strandedness * scarcity;
    }

    // --- Chain-continuation windows ---
    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let chain_left = bin_residual - item_size - next_item_size;
        if chain_left <= 3 {
            score -= 10.0 + 6.0 * (1.0 - progress) + 3.0 / (fitting_bins_count as f64).max(1.0);
        }
        if chain_left >= 8 && chain_left <= 20 {
            score -= 5.0 * (1.0 - (chain_left as f64 - 8.0) / 12.0) * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // --- Exact-divisibility bonus ---
    if item_size > 0 && bin_residual % item_size == 0 && bin_residual != bin_capacity {
        score -= 5.0;
        if post_residual == 0 {
            score -= 4.0;
        }
    }

    // --- Convex dead-space floor ---
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        score += 0.0004 * pr * pr * pr * (0.5 + 0.7 * tightness);
        score += (0.05 * pr + 0.0018 * pr * pr) * (1.0 / (fitting_bins_count as f64).max(1.0).sqrt());
    }

    // --- Mid-residual alignment shaping ---
    if post_residual >= 30 && post_residual <= 55 && bin_residual != bin_capacity {
        let d = ((post_residual as f64 - 42.5).abs() / 12.5).min(1.0);
        score -= 5.0 * (1.0 - d) * (0.6 + 0.4 * (1.0 - progress));
    }

    if post_residual >= 13 && post_residual <= 29 && next_item_size > 0 && post_residual < next_item_size && bin_residual != bin_capacity {
        let unus = 1.0 - (post_residual as f64 / next_item_size as f64);
        score += 7.0 * unus * (0.7 + 0.5 * progress);
    }

    // --- Tail-band shaping after next item ---
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let tail = post_residual - next_item_size;
        if tail >= 12 && tail <= 30 {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= (4.0 + 3.0 * (1.0 - progress)) * (1.0 - (tail as f64 - 12.0).abs() / 18.0) * scarcity;
        }
        if tail > 55 && tail < 100 {
            score += 3.0 * (1.0 - (tail as f64 - 55.0) / 45.0) * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // --- Small-sliver and small-fit shaping ---
    if post_residual >= 1 && post_residual <= 5 {
        score += 5.0;
    }
    if post_residual >= 1 && post_residual <= 12 && next_item_size > 0 && next_item_size <= post_residual && bin_residual != bin_capacity {
        let closeness = 1.0 - (post_residual - next_item_size) as f64 / 12.0;
        score -= 3.5 * closeness * (0.4 + 0.6 * progress);
    }

    // --- Slack-band scarcity ---
    if slack >= 0 && slack <= 6 && fitting_bins_count <= 3 && bin_residual != bin_capacity {
        let sl = slack as f64;
        score -= 6.0 * (1.0 - sl / 6.0) * (1.0 / (fitting_bins_count as f64).max(1.0)) * (0.6 + 0.4 * progress);
    }

    // --- Mid-residual peak ---
    if post_residual > 14 && post_residual < 46 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let peak = 1.0 - ((pr - 30.0).abs() / 16.0).min(1.0);
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        score += 0.09 * pr * peak * (0.7 + 0.6 * tightness);
    }

    // --- Salvage / crowd coupling ---
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let nx = if next_item_size > 0 { next_item_size as f64 } else { 30.0 };
        let salvage = (pr / nx.max(1.0)).min(1.5);
        let crowd = ((open_bins_count as f64) / 14.0).min(1.0);
        if salvage < 1.0 {
            score += 4.5 * (1.0 - salvage) * crowd * (0.7 + 0.5 * progress);
        }
    }

    // --- Mean-deviation alignment ---
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let dev = ((pr - mean_residual.max(0.0)) / cap_f).abs();
        score -= 2.5 * (1.0 - dev.min(1.0)) * (0.4 + 0.6 * (1.0 - progress));
    }

    // --- Near-parity halo on open bins (tight-fit preservation) ---
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 && bin_residual != bin_capacity {
        score -= 5.0 + 4.0 * (1.0 - progress);
    }

    // ===================== NEW-BIN CANDIDATE =====================
    if bin_residual == bin_capacity {
        score = 55.0 - 15.0 * progress;
        if next_item_size > 0 && item_size + next_item_size >= bin_capacity {
            score -= 45.0;
        }
        if item_size as f64 > 0.6 * cap_f {
            score -= 30.0;
        }
        if progress > 0.8 {
            score += 10.0;
        }
        if fitting_bins_count > 2 {
            score += 20.0;
        }
        if open_bins_count < 4 && progress < 0.3 {
            score -= 12.0;
        }
        if next_item_size > 0 && item_size + next_item_size < bin_capacity {
            let leftover = bin_capacity - item_size - next_item_size;
            if leftover >= next_item_size {
                score -= 10.0;
            }
            if leftover < 10 {
                score -= 8.0;
            } else if leftover < 25 {
                score -= 3.0;
            }
            if leftover >= 25 && leftover <= 60 {
                score -= 6.0;
            } else if leftover >= 1 && leftover <= 5 {
                score += 6.0;
            }
        }
        if item_size < 15 && progress > 0.5 && fitting_bins_count >= 1 {
            score += 15.0;
        }
        if fitting_bins_count >= 1 && item_size <= bin_residual {
            let best_case_waste = bin_residual - item_size;
            if best_case_waste <= 5 {
                score += 25.0;
            } else if best_case_waste <= 15 {
                score += 8.0;
            }
        }
        if progress > 0.6 {
            score += 7.5 * (progress - 0.6) * 25.0;
        }
        if open_bins_count > 10 && progress > 0.35 && progress < 0.7 {
            let roomy = (mean_residual / cap_f).min(1.0);
            score += 6.0 * roomy;
        }
        if next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover >= 30 && leftover <= 55 {
                let d = ((leftover as f64 - 42.5).abs() / 12.5).min(1.0);
                score -= 4.0 * (1.0 - d);
            } else if leftover > 55 && leftover <= 90 {
                score += 2.0 * ((leftover as f64 - 55.0) / 35.0);
            }
        }
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left >= 1 && fresh_left <= 6 {
                score -= 8.0 * (1.0 - fresh_left as f64 / 6.0) * (0.7 + 0.3 * (1.0 - progress));
            } else if fresh_left >= 7 && fresh_left <= 12 {
                score -= 4.0 * (1.0 - fresh_left as f64 / 12.0) * (0.6 + 0.4 * (1.0 - progress));
            }
        }
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left == next_item_size {
                score -= 14.0 + 6.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if d > 0 && d <= 2 {
                score -= (14.0 - 4.0 * d as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if d > 2 && d <= 4 {
                score -= (6.0 - 1.5 * (d - 2) as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if fitting_bins_count <= 2 && next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left >= next_item_size {
                let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0);
                score -= 5.0 * scarcity * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if post_residual > 0 && mean_residual > 0.45 * cap_f {
            let pr = post_residual as f64;
            score += 0.06 * pr * (0.4 + 0.6 * progress);
        }
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let open_after = bin_residual.saturating_sub(item_size);
            let fresh_after = bin_capacity.saturating_sub(item_size);
            if open_after < next_item_size && fresh_after >= next_item_size {
                if next_item_size >= 25 && next_item_size <= 70 {
                    score -= 6.0 + 4.0 * (1.0 - progress);
                } else if next_item_size < 25 {
                    score += 4.0;
                }
            }
        }
        if progress > 0.55 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size) as f64;
            let excess = leftover - mean_residual.max(0.0);
            if excess > 15.0 {
                score += 0.08 * (excess - 15.0).min(40.0);
            }
        }
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 9.0 + 8.0 * progress;
        }
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.0004 * fresh_left * fresh_left * fresh_left * (0.5 + 0.7 * tightness);
        }
        if fitting_bins_count >= 1 && next_item_size > 0 {
            let open_waste = bin_residual.saturating_sub(item_size) as f64;
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as f64;
            let excess = open_waste - fresh_left;
            if excess > 10.0 {
                score -= 2.5 * ((excess - 10.0) / 25.0).min(1.0) * (0.5 + 0.5 * (1.0 - progress));
            } else if excess < -10.0 {
                score += 2.0 * (((-excess) - 10.0) / 25.0).min(1.0) * (0.5 + 0.5 * progress);
            }
        }
        if progress > 0.7 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover > 0 && leftover <= 6 {
                score -= 7.0 * (progress - 0.7) * 10.0;
            } else if leftover > 40 {
                score += 4.0 * (progress - 0.7) * 10.0;
            }
        }
        if fitting_bins_count >= 1 && item_size > 55 {
            let open_waste = bin_residual.saturating_sub(item_size);
            if open_waste > 20 {
                score -= 3.0 + 0.06 * ((open_waste - 20) as f64).min(30.0) * (1.0 - 0.3 * progress);
            }
        }
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if d > 4 && d <= 6 {
                score -= (3.0 - 1.0 * (d - 4) as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if post_residual > 0 && fitting_bins_count >= 2 {
            let pr = post_residual as f64;
            let band = ((pr - mean_residual.max(0.0)) / cap_f).abs();
            score -= 2.5 * (1.0 - band.min(1.0)) * (0.4 + 0.6 * progress);
        }
        if post_residual > 0 && bin_residual != bin_capacity && progress > 0.60 && post_residual < next_item_size.max(20) {
            let unus = 1.0 - (post_residual as f64 / (next_item_size.max(20) as f64));
            score += 6.0 * unus * ((progress - 0.60) / 0.40).min(1.0);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 && bin_residual != bin_capacity {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / 10.0) * scarcity * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && next_item_size > 0 {
            let open_after = bin_residual.saturating_sub(item_size);
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if open_after < next_item_size && fresh_left >= next_item_size + 10 {
                score -= 3.0 + 3.0 * (1.0 - progress);
            }
        }
        if post_residual == 0 && bin_residual != bin_capacity {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= 18.0 + 10.0 * (1.0 - progress) + 6.0 * scarcity;
        }
        if post_residual > 0 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let reuse = 1.0 / (1.0 + (-(pr - 30.0) / 12.0).exp());
            score -= 5.0 * reuse * (0.5 + 0.5 * (1.0 - progress));
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_residual {
            let chain_left = bin_residual - item_size - next_item_size;
            if chain_left == 0 {
                score -= 12.0 + 8.0 * progress;
            } else if chain_left <= 4 {
                score -= (4.0 + (4 - chain_left) as f64 * 2.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left >= 13 && fresh_left <= 24 && fresh_left < next_item_size {
                score += 5.0 * (1.0 - (fresh_left as f64 - 13.0) / 11.0) * (0.6 + 0.4 * (1.0 - progress));
            }
        }
        if post_residual >= 6 && post_residual <= 12 && fitting_bins_count >= 3 && next_item_size > 0 && post_residual < next_item_size {
            score += 3.0 * (1.0 - (post_residual as f64 - 6.0) / 6.0) * (0.5 + 0.5 * progress);
        }

        if post_residual == 0 && bin_residual != bin_capacity {
            let crowd = ((open_bins_count as f64 - 4.0).max(0.0) / 12.0).min(1.0);
            score -= 6.0 * crowd * (0.5 + 0.5 * (1.0 - progress));
        }

        if post_residual >= 1 && post_residual <= 4 && bin_residual != bin_capacity {
            score += 4.0 * (1.0 - post_residual as f64 / 4.0) + 2.0 * (1.0 - progress);
        }

        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left >= 25 {
                score -= 3.0 * (1.0 - progress);
            } else if fresh_left > 60 && progress < 0.75 {
                score += 2.5 + 0.02 * ((fresh_left - 60) as f64).min(30.0);
            }
        }

        if slack >= 0 && slack <= 2 && bin_residual != bin_capacity {
            score -= 5.0 * (0.4 + 0.6 * progress);
        }
        if slack > 30 && open_bins_count > 10 && bin_residual != bin_capacity {
            score += 0.04 * ((slack - 30) as f64).min(50.0) * (0.5 + 0.5 * progress);
        }
    }

    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let reuse = 1.0 / (1.0 + (-(pr - 30.0) / 12.0).exp());
        score -= 3.0 * reuse * (0.4 + 0.4 * (1.0 - progress));
    }

    if post_residual == 0 && bin_residual != bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
        score -= 10.0 + 6.0 * (1.0 - progress) + 5.0 * scarcity;
    }

    // MUTATION (gen 40): tight-slack anchor — borrow the best heuristic's
    // fine-grained slack reward (slack <= 4) and couple it with lookahead:
    // when the two-item chain also fits exactly (chain_left <= 2), deepen
    // the reward so near-perfect placements dominate over roomy-but-wasteful
    // ones, attacking the 135-bin gap directly.
    if slack >= 0 && slack <= 4 && bin_residual != bin_capacity {
        score -= 8.0 + 4.0 * (1.0 - progress);
        if next_item_size > 0 && item_size + next_item_size <= bin_residual {
            let chain_left = bin_residual - item_size - next_item_size;
            if chain_left <= 2 {
                score -= 6.0;
            }
        }
    }

    // MUTATION (gen 40): dead-space convexity escalation — raise the extra
    // cubic penalty coefficient (0.00045 -> 0.00060) on stranded mid/large
    // residuals to further compress the residual variance Sigma_res.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        score += 0.00060 * pr * pr * pr * (0.5 + 0.7 * tightness);
    }

    // MUTATION (gen 40): crowd-driven exact-fill reinforcement — perfect
    // closures on open bins are rewarded extra when many bins are open,
    // pushing consolidation of the open pool and fewer total bins.
    if post_residual == 0 && bin_residual != bin_capacity {
        let crowd = ((open_bins_count as f64 - 4.0).max(0.0) / 12.0).min(1.0);
        score -= 5.0 * crowd * (0.5 + 0.5 * (1.0 - progress));
    }

    // MUTATION (gen 40): near-miss refusal — open bins that strand 1..=4
    // unusable units get a graded penalty so placements leaving reusable
    // tails are preferred, cutting dead space late in the stream.
    if post_residual >= 1 && post_residual <= 4 && bin_residual != bin_capacity {
        score += 3.0 * (1.0 - post_residual as f64 / 4.0) * (0.5 + 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    score -= 20.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Harmonic classes: dead-space classes of post_residual.
    // Residuals that are too small to fit anything useful (<=10) are near-perfect.
    if post_residual <= 10 {
        score -= 30.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    } else if post_residual >= 50 {
        // Large leftover space is wasteful unless bin is fresh.
        score += 15.0;
    }

    // Modulo arithmetic on post_residual: quantize into harmonic classes.
    let class = post_residual % 10;
    score += class as f64 * 0.5; // prefer residuals aligned to decade boundaries

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap <= 5 {
            score -= 25.0;
        } else if gap <= 15 {
            score -= 8.0;
        }
    }
    // Penalize if next item does NOT fit but post_residual is medium (traps space).
    if next_item_size > post_residual && post_residual > 15 && post_residual < 45 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Prefer bins below mean residual (more filled bins first).
    score += ((bin_residual as f64) - mean_residual) * 0.15;

    // New-bin candidate: only attractive when current item is large and no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = item_size >= 60;
        let poor_fit = post_residual as f64 > 40.0 || fitting_bins_count == 0;
        if large_item && poor_fit {
            score -= 22.0;
        } else {
            score += 30.0 + 10.0 * progress;
        }
        // Fresh bin pairs well with a large next item.
        if next_item_size >= 60 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
