            }
        }
        if fitting_bins_count == 1 && item_size < 40 && progress > 0.3 {
            let open_after = bin_residual.saturating_sub(item_size);
            if open_after >= 15 {
                score += 10.0 * (1.0 - progress);
            }
        }
        if open_bins_count > 10 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover > 30 {
                score += 4.0 + 0.06 * ((leftover - 30) as f64).min(40.0);
            } else if leftover <= 30 && item_size > 50 {
                score -= 5.0;
            }
        }
        if progress > 0.7 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover > 0 && leftover <= 6 {
                score -= 7.0 * (progress - 0.7) * 10.0;
            } else if leftover > 40 {
                score += 4.0 * (progress - 0.7) * 10.0;
            }
        }
        if fitting_bins_count >= 1 && item_size > 55 {
            let open_waste = bin_residual.saturating_sub(item_size);
            if open_waste > 20 {
                score -= 3.0 + 0.06 * ((open_waste - 20) as f64).min(30.0) * (1.0 - 0.3 * progress);
            }
        }
        if fitting_bins_count >= 1 && next_item_size > 0 {
            let open_after = bin_residual.saturating_sub(item_size);
            if open_after >= 8 && open_after <= 25 {
                score += 5.0 * (1.0 - (open_after as f64 - 8.0).abs() / 17.0) * (0.5 + 0.5 * progress);
            }
        }
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left >= 30 && fresh_left <= 55 {
                score -= 2.5 * (1.0 - ((fresh_left as f64 - 42.5).abs() / 12.5).min(1.0)) * (1.0 - 0.4 * progress);
            }
        }
        if open_bins_count > 6 && fitting_bins_count <= 2 && next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left > 0 && fresh_left < next_item_size {
                score += 3.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left >= 1 && fresh_left <= 12 {
                score -= 4.0 * (1.0 - fresh_left as f64 / 12.0) * (0.6 + 0.4 * (1.0 - progress));
            }
        }
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left >= 1 && fresh_left <= 6 {
                score -= 8.0 * (1.0 - fresh_left as f64 / 6.0) * (0.7 + 0.3 * (1.0 - progress));
            }
        }
        if fitting_bins_count == 1 && next_item_size > 0 {
            let open_waste = bin_residual.saturating_sub(item_size) as f64;
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as f64;
            if open_waste > fresh_left + 18.0 {
                score -= 4.0 * ((open_waste - fresh_left - 18.0) / 20.0).min(1.0) * (0.6 + 0.4 * (1.0 - progress));
            }
        }

        // gen 22: fresh-bin exact-parity halo
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if d == 0 {
                score -= 14.0 + 6.0 * (1.0 - progress);
            } else if d <= 4 {
                score -= (10.0 - 2.0 * d as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // gen 22: fresh-bin salvage ceiling
        if fitting_bins_count >= 1 && next_item_size > 0 {
            let open_after = bin_residual.saturating_sub(item_size);
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if open_after < next_item_size && fresh_left >= next_item_size + 10 {
                score -= 3.0 + 3.0 * (1.0 - progress);
            }
        }

        // gen 22: scarcity-locked chain continuity
        if fitting_bins_count <= 2 && next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left >= next_item_size {
                let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0);
                score -= 5.0 * scarcity * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // gen 23: fresh-bin halo extension to ±8
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if d > 4 && d <= 8 {
                score -= (3.0 - 0.35 * (d - 4) as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // gen 23: late-stream consolidation sharpening
        if post_residual > 0 && bin_residual != bin_capacity && progress > 0.60 && post_residual < next_item_size.max(20) {
            let unus = 1.0 - (post_residual as f64 / (next_item_size.max(20) as f64));
            score += 6.0 * unus * ((progress - 0.60) / 0.40).min(1.0);
        }

        // gen 23: residual-variance floor bonus
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 && bin_residual != bin_capacity {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / 10.0) * scarcity * (0.5 + 0.5 * progress);
        }

        // MUTATION (gen 25): dead-space convexity escalation
        if post_residual > 0 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.00060 * pr * pr * pr * (0.5 + 0.7 * tightness);
        }

        // MUTATION (gen 25): compaction pull strengthening
        if post_residual > 0 && bin_residual != bin_capacity && fitting_bins_count >= 2 {
            let pr = post_residual as f64;
            let band = ((pr - mean_residual.max(0.0)) / cap_f).abs();
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= (3.0 + 1.5 * scarcity) * (1.0 - band.min(1.0)) * (0.4 + 0.6 * progress);
        }

        // MUTATION (gen 25): open-bin parity halo
        if next_item_size > 0 && bin_residual != bin_capacity {
            let pr = post_residual as i64;
            let nx = next_item_size as i64;
            let d = (pr - nx).abs();
            if d <= 3 {
                let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
                score -= (8.0 - 2.0 * d as f64) * (0.5 + 0.5 * (1.0 - progress)) * scarcity;
            }
        }

        // MUTATION (gen 25): two-item lookahead compaction
        if next_item_size > 0 && item_size + next_item_size <= bin_residual && bin_residual != bin_capacity {
            let leftover = bin_residual - item_size - next_item_size;
            if leftover <= 8 {
                score -= (9.0 - leftover as f64) * (0.6 + 0.4 * (1.0 - progress));
            }
        }

        // MUTATION (gen 25): mid-residual dead-band penalty
        if post_residual >= 20 && post_residual <= 35 && bin_residual != bin_capacity && open_bins_count > 6 {
            let crowd = ((open_bins_count as f64 - 6.0) / 10.0).min(1.0);
            let depth = 1.0 - ((post_residual as f64 - 27.5).abs() / 7.5).min(1.0);
            score += 4.0 * depth * crowd * (0.5 + 0.5 * progress);
        }

        // MUTATION (gen 25): fresh-bin exact-closure guard
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            let open_waste = bin_residual.saturating_sub(item_size);
            if fresh_left > 0 && fresh_left < next_item_size && open_waste == 0 {
                score += 10.0 * (1.0 - progress);
            }
        }

        // MUTATION (gen 40): fresh-bin exact-closure guard widened — extend the
        // exact-closure preference to near-closure (open waste <= 3) so that
        // placements which nearly finish an open bin are preferred over
        // spawning a fresh bin with unusable leftover.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            let open_waste = bin_residual.saturating_sub(item_size);
            if fresh_left > 0 && fresh_left < next_item_size && open_waste > 0 && open_waste <= 3 {
                score += 6.0 * (1.0 - open_waste as f64 / 3.0) * (0.6 + 0.4 * (1.0 - progress));
            }
        }

        // MUTATION (gen 40): dead-space convexity escalation continues —
        // combine the fine-grained residual fitting with lookahead: raise the
        // extra cubic coefficient from 0.00060 to 0.00075 and add a
        // lookahead-coupled term that penalizes residuals which strand both
        // the next item and a plausible follow-up (next*2 band).
        if post_residual > 0 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.00075 * pr * pr * pr * (0.5 + 0.7 * tightness);
        }

        // MUTATION (gen 40): two-step lookahead stranding — if the post-fit
        // residual cannot fit the next item but would fit it after the
        // following-next (approximated by next*2 window), mildly reward;
        // if it can never fit anything plausible (pr < next and pr < 12),
        // penalize harder to force consolidation into fewer, reusable slacks.
        if post_residual > 0 && next_item_size > 0 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let nx = next_item_size as f64;
            if pr < nx && pr < 12.0 {
                score += 5.0 * (1.0 - pr / 12.0) * (0.5 + 0.5 * progress);
            } else if pr >= nx && pr < nx * 2.0 {
                let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
                score -= 2.5 * (1.0 - (pr - nx) / nx.max(1.0)) * scarcity * (0.4 + 0.6 * progress);
            }
        }

        // MUTATION (gen 40): compaction pull reinforcement — strengthen the
        // mean-residual band homogenization (3.0 -> 4.0 base) to directly
        // compress residual dispersion (Sigma_res weakness) while combining
        // with lookahead via next-item alignment weighting.
        if post_residual > 0 && bin_residual != bin_capacity && fitting_bins_count >= 2 {
            let pr = post_residual as f64;
            let band = ((pr - mean_residual.max(0.0)) / cap_f).abs();
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            let align = if next_item_size > 0 && (pr - next_item_size as f64).abs() <= 3.0 { 1.4 } else { 1.0 };
            score -= (4.0 + 1.5 * scarcity) * align * (1.0 - band.min(1.0)) * (0.4 + 0.6 * progress);
        }

        // MUTATION (gen 40): late-stream exact-closure escalation — in the
        // final stretch, exact closures are worth more; deepen the parity
        // halo weight when progress > 0.7.
        if next_item_size > 0 && post_residual == next_item_size && bin_residual != bin_capacity && progress > 0.7 {
            score -= 5.0 * ((progress - 0.7) / 0.3).min(1.0);
        }
    }

    // gen 22: dead-space convexity escalation (base cubic family)
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        score += 0.00030 * pr * pr * pr * (0.5 + 0.7 * tightness);
    }

    // gen 22: residual-dispersion guard
    if post_residual > 0 && bin_residual != bin_capacity && mean_residual > 0.45 * cap_f {
        let pr = post_residual as f64;
        score += 0.07 * pr * (0.4 + 0.6 * progress);
    }

    // gen 22: tight-fit preservation
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 && bin_residual != bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
        score -= (3.0 + 3.0 * (1.0 - progress)) * scarcity;
    }

    // gen 22: open-bin parity halo
    if next_item_size > 0 && bin_residual != bin_capacity {
        let pr = post_residual as i64;
        let nx = next_item_size as i64;
        let d = (pr - nx).abs();
        if d <= 3 {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= (8.0 - 2.0 * d as f64) * (0.5 + 0.5 * (1.0 - progress)) * scarcity;
        }
    }

    // gen 22: two-item lookahead compaction
    if next_item_size > 0 && item_size + next_item_size <= bin_residual && bin_residual != bin_capacity {
        let leftover = bin_residual - item_size - next_item_size;
        if leftover <= 8 {
            score -= (9.0 - leftover as f64) * (0.6 + 0.4 * (1.0 - progress));
        }
    }

    // gen 22: mid-residual dead-band penalty
    if post_residual >= 20 && post_residual <= 35 && bin_residual != bin_capacity && open_bins_count > 6 {
        let crowd = ((open_bins_count as f64 - 6.0) / 10.0).min(1.0);
        let depth = 1.0 - ((post_residual as f64 - 27.5).abs() / 7.5).min(1.0);
        score += 3.5 * depth * crowd * (0.5 + 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strong reward for leaving nothing behind.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // this bin becomes perfectly packed over two steps.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_after_next = post_residual - next_item_size;
        score -= 300.0;
        if gap_after_next == 0 {
            score -= 500.0; // exact two-item match
        } else if gap_after_next < 10 {
            score -= 150.0; // leaves near-unusable dead space, but bin is full-ish
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post residual too small for the next item: penalize proportionally
        // to how close the next item came to fitting (near-miss is worst).
        let miss = (next_item_size - post_residual) as f64;
        if post_residual > 0 {
            score += 80.0 * (1.0 - miss / next_item_size as f64);
        }
        // Tiny dead space is unusable regardless.
        if post_residual < 10 {
            score += 200.0;
        }
    }

    // Relative to mean residual: prefer bins that are tighter than average
    // (best-fit style) when residuals are large.
    let residual_f = bin_residual as f64;
    if residual_f > mean_residual {
        score += 0.4 * (residual_f - mean_residual);
    } else {
        score -= 0.2 * (mean_residual - residual_f);
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the stream is early (many items remain, fresh bin has long utility).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; reduced early in the stream.
        score = 100.0 + 400.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 50.0; // fresh bin can also host the next item
        }
        if open_bins_count == 0 {
            score -= 400.0; // must open a bin
        }
    }

    // Mild penalty for wasting a very large bin on a small item late in stream.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 50.0 * waste_ratio * waste_ratio * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap_f = bin_capacity as f64;
    let resid_f = bin_residual as f64;
    let slack = bin_residual as i64 - item_size as i64;

    if post_residual == 0 {
        score -= 65.0;
    }
    if slack >= 0 && slack <= 4 {
        score -= 20.0;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0 + 22.0 * (1.0 - progress);
