}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls in "reusable"
    // residue classes (multiples of common item sizes) are worth keeping tidy.
    let post = post_residual;
    let reusable = (post > 0 && (post % 10 == 0 || post % 20 == 0 || post % 25 == 0 || post % 50 == 0)) as i32;

    // Exact-fit reward: harmonic zero class is perfect.
    if post == 0 {
        score -= 1000.0;
    } else {
        // Reward landing in a reusable harmonic class (divisible leftover).
        if reusable == 1 {
            score -= (post as f64) * 0.6;
        } else {
            // Penalize awkward dead space (prime-ish / odd leftovers).
            score += (post as f64) * 0.35;
            if post < 10 {
                score += 25.0; // tiny unusable sliver
            }
        }
    }

    // Lookahead coupling: does the next item fit the post residual harmonically?
    if next_item_size > 0 && post >= next_item_size {
        let gap = post - next_item_size;
        score -= 30.0 + (gap as f64) * 0.3;
        if gap % 10 == 0 {
            score -= 10.0; // next item also lands on a harmonic boundary
        }
    } else if next_item_size > 0 && next_item_size <= bin_capacity {
        // Next item cannot follow into this bin: penalize mildly.
        score += 15.0;
    }

    // Last-chance bonus: only one bin fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate handling: keep fresh bins neutral-to-slightly-positive
    // unless the current stream is early (better to spread) or item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = (bin_capacity as f64) * (0.5 + 0.5 * progress);
        if item_size > bin_capacity / 2 {
            score -= 20.0; // big items like fresh bins
        }
        if post > 0 && reusable == 0 && next_item_size > post && next_item_size > 0 {
            score -= 25.0; // current bin would strand the next item
        }
    }

    // Mild preference for filling bins that are already well-used relative to mean.
    score -= (bin_residual as f64 - mean_residual) * 0.05;

    // Congestion: many open bins -> favor consolidation into existing ones.
    score += (open_bins_count as f64) * 0.5;

    score
}

