            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if d > 0 && d <= 2 {
                score -= (14.0 - 4.0 * d as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // gen 20: dead-space convexity gain
        if post_residual > 0 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.0001 * pr * pr * pr * (0.5 + 0.7 * tightness);
        }

        // gen 20: tight-fit preservation
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 && bin_residual != bin_capacity {
            score -= 5.0 + 4.0 * (1.0 - progress);
        }

        // gen 21: halo widening to ±4
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if d > 2 && d <= 4 {
                score -= (6.0 - 1.5 * (d - 2) as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // gen 21: dead-space convexity escalation
        if post_residual > 0 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.00022 * pr * pr * pr * (0.5 + 0.7 * tightness);
        }

        // gen 21: tight-fit preservation widening
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 && bin_residual != bin_capacity {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= (3.0 + 3.0 * (1.0 - progress)) * scarcity;
        }

        // gen 21: residual-dispersion dead-space guard
        if post_residual > 0 && bin_residual != bin_capacity && mean_residual > 0.45 * cap_f {
            let pr = post_residual as f64;
            score += 0.06 * pr * (0.4 + 0.6 * progress);
        }

        // gen 22: dead-space convexity escalation
        if post_residual > 0 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.00032 * pr * pr * pr * (0.5 + 0.7 * tightness);
        }

        // gen 22: open-bin compaction pull
        if post_residual > 0 && bin_residual != bin_capacity && fitting_bins_count >= 2 {
            let pr = post_residual as f64;
            let band = ((pr - mean_residual.max(0.0)) / cap_f).abs();
            score -= 2.0 * (1.0 - band.min(1.0)) * (0.4 + 0.6 * progress);
        }

        // gen 22: fresh-bin halo extension to ±6
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if d > 4 && d <= 6 {
                score -= (3.0 - 1.0 * (d - 4) as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // gen 22: late-stream waste-floor guard
        if post_residual > 0 && bin_residual != bin_capacity && progress > 0.66 && post_residual < next_item_size.max(20) {
            let unus = 1.0 - (post_residual as f64 / (next_item_size.max(20) as f64));
            score += 4.0 * unus * ((progress - 0.66) / 0.34).min(1.0);
        }

        // gen 23: dead-space convexity escalation continues
        if post_residual > 0 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.00045 * pr * pr * pr * (0.5 + 0.7 * tightness);
        }

        // gen 23: compaction pull strengthening
        if post_residual > 0 && bin_residual != bin_capacity && fitting_bins_count >= 2 {
            let pr = post_residual as f64;
            let band = ((pr - mean_residual.max(0.0)) / cap_f).abs();
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= (2.5 + 1.5 * scarcity) * (1.0 - band.min(1.0)) * (0.4 + 0.6 * progress);
        }

        // gen 23: fresh-bin halo extension to ±8
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if d > 6 && d <= 8 {
                score -= (2.0 - 0.75 * (d - 6) as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // gen 23: late-stream consolidation sharpening
        if post_residual > 0 && bin_residual != bin_capacity && progress > 0.60 && post_residual < next_item_size.max(20) {
            let unus = 1.0 - (post_residual as f64 / (next_item_size.max(20) as f64));
            score += 6.0 * unus * ((progress - 0.60) / 0.40).min(1.0);
        }

        // gen 23: residual-variance floor bonus
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 && bin_residual != bin_capacity {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / 10.0) * scarcity * (0.5 + 0.5 * progress);
        }

        // MUTATION (gen 41): dead-space convexity escalation — continue the
        // proven ContinueDirection momentum by raising the extra cubic
        // coefficient from 0.00045 to 0.00062, deepening the dead-space
        // penalty on stranded mid/large residuals (diagnosed weakness:
        // residual dead space) while preserving the cubic family shape.
        if post_residual > 0 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.00062 * pr * pr * pr * (0.5 + 0.7 * tightness);
        }

        // MUTATION (gen 41): compaction pull refinement — strengthen the
        // mean-residual band homogenization (2.5+1.5s -> 3.0+2.0s) and extend
        // its reach earlier in the stream (0.4 -> 0.3 base), directly
        // compressing residual dispersion Sigma_res which remains the
        // diagnosed weakness.
        if post_residual > 0 && bin_residual != bin_capacity && fitting_bins_count >= 2 {
            let pr = post_residual as f64;
            let band = ((pr - mean_residual.max(0.0)) / cap_f).abs();
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= (3.0 + 2.0 * scarcity) * (1.0 - band.min(1.0)) * (0.3 + 0.7 * progress);
        }

        // MUTATION (gen 41): fresh-bin halo extension to ±10 — the widening
        // trend (±2 -> ±4 -> ±6 -> ±8) keeps capturing near-parity chain
        // continuations; extend with a shallow decay to ±10.
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if d > 8 && d <= 10 {
                score -= (1.5 - 0.5 * (d - 8) as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // MUTATION (gen 41): late-stream consolidation sharpening — strengthen
        // the waste-floor guard (6.0 -> 8.0) and pull its onset earlier
        // (0.60 -> 0.55), forcing residual consolidation into fewer usable
        // slacks during the final stretch where the bin gap concentrates.
        if post_residual > 0 && bin_residual != bin_capacity && progress > 0.55 && post_residual < next_item_size.max(20) {
            let unus = 1.0 - (post_residual as f64 / (next_item_size.max(20) as f64));
            score += 8.0 * unus * ((progress - 0.55) / 0.45).min(1.0);
        }

        // MUTATION (gen 41): residual-variance floor bonus widening — extend
        // the reusable-tail reward from <=10 to <=14 slack after next item,
        // rewarding placements that leave a compact, immediately reusable
        // residual and further compressing residual dispersion.
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 14 && bin_residual != bin_capacity {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= 3.0 * (1.0 - (post_residual - next_item_size) as f64 / 14.0) * scarcity * (0.5 + 0.5 * progress);
        }

        // MUTATION (gen 41): mid-stream dead-space guard — extend the
        // residual-dispersion guard to trigger at mean_residual > 0.40*cap
        // (from 0.45), catching moderately dispersed residual states earlier
        // and penalizing dead-space accumulation before it compounds.
        if post_residual > 0 && bin_residual != bin_capacity && mean_residual > 0.40 * cap_f {
            let pr = post_residual as f64;
            score += 0.05 * pr * (0.4 + 0.6 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let cap_f = bin_capacity as f64;
    let resid_f = bin_residual as f64;
    let slack = bin_residual as i64 - item_size as i64;
    let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();

    // Perfect fit reward, scaled by scarcity of fitting bins.
    if post_residual == 0 {
        score -= 70.0;
        score -= 8.0 * scarcity * (0.5 + 0.5 * (1.0 - progress));
        let crowd = ((open_bins_count as f64 - 5.0).max(0.0) / 15.0).min(1.0);
        score -= 6.0 * crowd * (0.5 + 0.5 * (1.0 - progress));
    }

    // Dead-space avoidance: graded penalties on small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 65.0 * (10 - post_residual) as f64;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }
    // Small-gap reversal: tiny slacks (1..=5) are actually near-perfect fills.
    if post_residual >= 1 && post_residual <= 5 {
        score += 5.0;
    }

    // Lookahead coupling with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 65.0 + 22.0 * (1.0 - progress);
        } else if post_residual > next_item_size {
            let tail = post_residual - next_item_size;
            if tail <= 5 {
                score -= (3.0 + 3.0 * (1.0 - progress)) * scarcity;
            } else if tail <= 30 {
                score -= (4.0 + 3.0 * (1.0 - progress)) * (1.0 - (tail as f64 - 5.0).abs() / 25.0) * scarcity;
            } else if tail > 55 {
                score += (tail as f64 - 55.0) * 0.15;
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 0.9;
            if miss <= 6.0 {
                score += 10.0 * (1.0 - miss / 6.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
    } else {
        score -= 10.0;
    }

    // Two-item chain lookahead: does item + next fit with a reusable remainder?
    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let chain_left = bin_residual - item_size - next_item_size;
        if chain_left == 0 {
            score -= 12.0 + 6.0 * (1.0 - progress);
        } else if chain_left <= 3 {
            score -= 10.0 + 6.0 * (1.0 - progress) + 3.0 / (fitting_bins_count as f64).max(1.0);
        } else if chain_left >= 8 && chain_left <= 55 {
            score -= 7.0 + 5.0 * (1.0 - progress);
        }
    }

    // Open-bin pressure: consolidate when many bins are open.
    if open_bins_count > 8 {
        score += (resid_f / cap_f) * 6.0;
    }
    score -= (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Last-chance bin handling.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
        if post_residual >= 10 {
            score -= 10.0;
        }
    }

    // Mean-residual alignment: penalize residual outliers to reduce variance.
    if post_residual > 0 && bin_residual != bin_capacity {
        let dev = ((post_residual as f64 - mean_residual.max(0.0)) / cap_f).abs();
        score += 3.0 * dev;
        score -= 2.5 * (1.0 - dev.min(1.0)) * (0.4 + 0.6 * (1.0 - progress));
    }

    // Quartic dead-space penalty on large stranded residuals (escalated).
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        score += 0.00055 * pr * pr * pr * (0.5 + 0.7 * tightness);
        // NEW: linear dead-space slope coupled to item size — big items leave
        // less recoverable space, so their stranded residuals cost more.
        let size_factor = (item_size as f64 / cap_f).powf(1.5);
        score += pr * 0.05 * (1.0 - size_factor) * (1.0 - 0.3 * progress);
    }

    // Late-stream waste-floor guard.
    if post_residual > 0 && bin_residual != bin_capacity && progress > 0.60 && post_residual < next_item_size.max(20) {
        let unus = 1.0 - (post_residual as f64 / (next_item_size.max(20) as f64));
        score += 7.0 * unus * ((progress - 0.60) / 0.40).min(1.0);
    }

    // Compaction pull toward mean residual with scarcity weighting.
    if post_residual > 0 && bin_residual != bin_capacity && fitting_bins_count >= 2 {
        let pr = post_residual as f64;
        let band = ((pr - mean_residual.max(0.0)) / cap_f).abs();
        score -= (3.0 + 1.5 * scarcity) * (1.0 - band.min(1.0)) * (0.4 + 0.6 * progress);
    }

    // Sweet-spot residuals (20..=45) reward, modulated by tightness.
    if post_residual >= 20 && post_residual <= 45 && bin_residual != bin_capacity {
        let tightness = (1.0 - (mean_residual / cap_f).min(1.0)).max(0.0);
        score -= 4.0 * tightness * (0.5 + 0.5 * (1.0 - progress));
    }

    // Scarcity-locked tight fits: don't waste the only bin that fits.
    if slack >= 0 && slack <= 6 && fitting_bins_count <= 3 && bin_residual != bin_capacity {
        let sl = slack as f64;
        score -= 7.0 * (1.0 - sl / 6.0) * (1.0 / (fitting_bins_count as f64).max(1.0)) * (0.6 + 0.4 * progress);
    }

    // Salvage: partially-reusable residuals under crowding.
    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let nx = if next_item_size > 0 { next_item_size as f64 } else { 30.0 };
        let salvage = (pr / nx.max(1.0)).min(1.5);
        let crowd = ((open_bins_count as f64) / 14.0).min(1.0);
        if salvage < 1.0 {
            score += 4.5 * (1.0 - salvage) * crowd * (0.7 + 0.5 * progress);
        }
    }

    // NEW: tight-fit preservation — keep bins whose residual after placing
    // this item is within a hair of the next item size (chain continuation).
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 && bin_residual != bin_capacity {
        score -= (4.0 + 3.0 * (1.0 - progress)) * scarcity;
    }

    // NEW: residual-dispersion guard — when mean residual is already high,
    // penalize adding more dead space to open bins.
    if post_residual > 0 && bin_residual != bin_capacity && mean_residual > 0.45 * cap_f {
        score += 0.06 * post_residual as f64 * (0.4 + 0.6 * progress);
    }

    // New-bin candidate: comprehensive fresh-bin evaluation.
    if bin_residual == bin_capacity {
        score = 55.0 - 15.0 * progress;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        }
        if next_item_size > 0 && item_size + next_item_size >= bin_capacity {
            score -= 45.0;
        }
        if item_size as f64 > 0.6 * cap_f {
            score -= 30.0;
        }
        if progress > 0.8 {
            score += 10.0;
        }
        if fitting_bins_count > 2 {
            score += 20.0;
        }
        if open_bins_count < 4 && progress < 0.3 {
            score -= 12.0;
        }
        // Compare fresh-bin leftover vs open-bin waste for next-item continuity.
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            let open_waste = bin_residual.saturating_sub(item_size);
            if fresh_left >= next_item_size && open_waste >= 20 {
                score -= 4.0 + 0.1 * ((open_waste - 20) as f64).min(25.0);
            } else if fresh_left > 0 && fresh_left < 8 && open_waste <= 10 {
                score += 5.0;
            }
        }
        // Near-parity chain halo: fresh leftover close to next item size.
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if d == 0 {
                score -= 16.0 + 6.0 * (1.0 - progress);
            } else if d <= 2 {
                score -= (14.0 - 4.0 * d as f64) * (0.5 + 0.5 * (1.0 - progress));
            } else if d <= 4 {
                score -= (6.0 - 1.5 * (d - 2) as f64) * (0.5 + 0.5 * (1.0 - progress));
            } else if d <= 6 {
                score -= (3.0 - 1.0 * (d - 4) as f64) * (0.5 + 0.5 * (1.0 - progress));
            } else if d <= 8 {
                score -= (2.0 - 0.75 * (d - 6) as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // Fresh-bin small leftovers are dead space.
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left >= 1 && fresh_left <= 6 {
                score -= 9.0 * (1.0 - fresh_left as f64 / 6.0) * (0.7 + 0.3 * (1.0 - progress));
            } else if fresh_left >= 7 && fresh_left <= 12 {
                score -= 4.5 * (1.0 - fresh_left as f64 / 12.0) * (0.6 + 0.4 * (1.0 - progress));
            }
        }
        // Salvage comparison: open-bin waste vs fresh-bin leftover.
        if fitting_bins_count == 1 && next_item_size > 0 {
            let open_waste = bin_residual.saturating_sub(item_size) as f64;
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as f64;
            if open_waste > fresh_left + 18.0 {
                score -= 4.0 * ((open_waste - fresh_left - 18.0) / 20.0).min(1.0) * (0.6 + 0.4 * (1.0 - progress));
            }
        }
        // Horizon parity: next item fits fresh bin but not salvaged open bin.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let open_after = bin_residual.saturating_sub(item_size);
            let fresh_after = bin_capacity.saturating_sub(item_size);
            if open_after < next_item_size && fresh_after >= next_item_size {
                if next_item_size >= 25 && next_item_size <= 70 {
                    score -= 8.0 + 4.0 * (1.0 - progress);
                } else if next_item_size < 25 {
                    score += 4.0;
                }
            }
        }
        // Big items prefer fresh bins when open waste is large.
        if fitting_bins_count >= 1 && item_size > 55 {
            let open_waste = bin_residual.saturating_sub(item_size);
            if open_waste > 20 {
                score -= 3.0 + 0.06 * ((open_waste - 20) as f64).min(30.0) * (1.0 - 0.3 * progress);
            }
        }
        // Tightness coupling: under tight packing, avoid fresh bins with huge leftovers.
        if progress > 0.3 && next_item_size > 0 {
            let tightness = (1.0 - (mean_residual / cap_f).min(1.0)).max(0.0);
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if tightness > 0.6 && leftover > 50 {
                score += 8.0 * (tightness - 0.6) * 10.0;
            } else if tightness > 0.6 && leftover >= 25 && leftover <= 50 {
                score -= 5.0 * (tightness - 0.6) * 10.0;
            }
        }
        // Late-stream: penalize any fresh-bin leftover.
        if progress > 0.75 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover > 0 {
                score += 3.0 + 0.08 * (leftover as f64) * (progress - 0.75) * 20.0;
            } else {
                score -= 6.0 * (progress - 0.75) * 10.0;
            }
        }
        // Small items late: keep them out of fresh bins.
        if item_size < 15 && progress > 0.5 && fitting_bins_count >= 1 {
            score += 15.0;
        }
        // Mid-band fresh leftovers (30..=55) are reusable.
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left >= 30 && fresh_left <= 55 {
                score -= 3.0 * (1.0 - ((fresh_left as f64 - 42.5).abs() / 12.5).min(1.0)) * (1.0 - 0.4 * progress);
            } else if fresh_left > 65 {
                score += 0.06 * ((fresh_left - 65) as f64).min(35.0) * (0.5 + 0.5 * progress);
            }
        }
        // Scarcity-locked chain continuity for fresh bins.
        if fitting_bins_count <= 2 && next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left >= next_item_size {
                let scarcity_f = 1.0 / (fitting_bins_count as f64).max(1.0);
                score -= 5.0 * scarcity_f * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // NEW: fresh-bin cubic leftover penalty under tightness — large fresh
        // leftovers mirror open-bin dead-space penalties.
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.00035 * fresh_left * fresh_left * fresh_left * (0.5 + 0.7 * tightness);
        }
        // NEW: exact two-item fill bonus for fresh bins.
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 10.0 + 8.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize post_residual that forms an unusable gap.
    // A residual gap is "dead" if no future item (min size 1, but practically small items)
    // can plausibly fill it. Penalize small-but-nonzero residuals heavily.
    let post = post_residual as f64;
    if post > 0.0 && post < 10.0 {
        // Very small gap: nearly guaranteed dead space. Harsh penalty.
        score += 60.0 * (10.0 - post) / 10.0;
    } else if post < 20.0 {
        // Small gap: likely unusable for most item sizes.
        score += 25.0 * (20.0 - post) / 10.0;
    }

    // Reward tight fits (near-zero post_residual) more aggressively than linear.
    if post == 0.0 {
        score -= 15.0;
    } else if post <= 5.0 {
        score -= 8.0;
    }

    // Perfect-fit lookahead: if the next item exactly fills post_residual, strong reward.
    if next_item_size > 0 && next_item_size as f64 == post {
        score -= 20.0;
    } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        // Next item fits here: mild reward for keeping the chain going.
        score -= 4.0;
    } else if next_item_size > 0 && next_item_size as f64 > post {
        // Next item cannot use this residual: the gap is likely dead. Penalize proportionally.
        score += 10.0 * (post / 100.0);
    }

    // Open-bin pressure: discourage scattering across many bins when the count is high.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.3;

    // Mean-residual coupling: if this bin's residual is far below mean, it's a tight bin;
    // prefer using it (keeps loose bins available for awkward items).
    let bin_res = bin_residual as f64;
    if bin_res < mean_residual {
        score -= (mean_residual - bin_res) * 0.2;
    } else {
        score += (bin_res - mean_residual) * 0.1;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: a fresh empty bin should only win when the current
    // fit is bad. Add a moderate baseline penalty so it loses against decent fits.
    if bin_residual == bin_capacity {
        score += 18.0;
        // But if the item is large relative to capacity, a fresh bin is fine.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 25.0;
        }
    }

    // Slight overall tightening bias: prefer bins with small residual generally.
    score += (bin_res / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap_f = bin_capacity as f64;
    let resid_f = bin_residual as f64;
    let slack = bin_residual as i64 - item_size as i64;

    if post_residual == 0 {
        score -= 65.0;
    }
    if slack >= 0 && slack <= 4 {
        score -= 20.0;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0 + 22.0 * (1.0 - progress);
        } else if post_residual > next_item_size {
            let slack_after_next = post_residual - next_item_size;
            score -= 25.0 - (slack_after_next as f64).min(40.0) * 0.3;
            if slack_after_next > 40 {
                score += (slack_after_next as f64 - 40.0) * 0.2;
            }
        } else {
            let shortfall = (next_item_size - post_residual) as f64;
            score += shortfall * 0.85;
            let half_next = next_item_size / 2;
            if post_residual > 0 && post_residual < half_next {
                score += 14.0;
            }
        }
    } else {
        score -= 10.0;
    }

    if post_residual > 0 {
        let waste_ratio = post_residual as f64 / cap_f;
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        let severity = 1.4 - 0.8 * tightness;
        if post_residual < next_item_size && next_item_size > 0 {
            let unusability = 1.0 - (post_residual as f64 / next_item_size as f64);
            score += 16.0 * unusability * (1.0 - 0.5 * progress) * severity;
            if post_residual < 10 {
                score += 9.0 * severity * (1.0 - 0.4 * progress);
            }
        } else if waste_ratio < 0.05 {
            score += 7.0 * (1.0 - progress) * severity;
        } else if waste_ratio < 0.10 && post_residual < 40 {
            score += 3.0 * (1.0 - progress) * severity;
        }
    }

    if resid_f > mean_residual + 20.0 && item_size < 30 {
        if next_item_size == 0 || post_residual < next_item_size {
            score += 10.0;
        }
    } else if resid_f < mean_residual - 20.0 {
        score -= 8.0;
    }

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
        if post_residual >= 10 {
            score -= 10.0;
        }
    }

    if open_bins_count > 8 {
        score += (resid_f / cap_f) * 6.0;
    }
    score -= (open_bins_count as f64).ln().max(0.0) * 3.0;

    if post_residual >= 25 {
        score -= 4.0;
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 15 {
            score -= 6.0;
        }
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 20 {
            let sweet = if after_next <= 60 { 3.0 } else { 0.0 };
            score -= 5.0 + 5.0 * (1.0 - progress) + sweet;
        }
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 6.0 * (post_residual as f64 / cap_f) * 10.0;
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let strandedness = 1.0 - (post_residual as f64 / next_item_size as f64);
        let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0);
        score += 9.0 * strandedness * scarcity;
    }

    if post_residual >= 20 && post_residual <= 60 {
        score -= 3.0 + 4.0 * (1.0 - progress);
    }
    if post_residual >= 1 && post_residual <= 5 {
        score += 5.0;
    }

    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap > 0 && gap <= 8 {
            score -= 4.0 + 3.0 * (1.0 - progress);
        }
    }

    if item_size > 0 && bin_residual % item_size == 0 && bin_residual != bin_capacity {
        score -= 5.0;
        if post_residual == 0 {
            score -= 4.0;
        }
    }

    if next_item_size > 0 && post_residual == next_item_size && progress < 0.4 {
        score -= 6.0;
    }

    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let chain_left = bin_residual - item_size - next_item_size;
        if chain_left >= 15 && chain_left <= 55 {
            score -= 7.0 + 5.0 * (1.0 - progress);
        }
    }

    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap > 8 && gap <= 20 {
            score += 1.5;
        } else if gap > 20 && gap <= 35 {
            score += 3.5;
        }
    }

    if fitting_bins_count <= 2 && bin_residual != bin_capacity && post_residual <= 12 {
        score -= 6.0 + 4.0 * (1.0 - progress);
    }

    if open_bins_count > 12 && bin_residual != bin_capacity {
        score += 8.0 * (1.0 - resid_f / cap_f);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unus = 1.0 - (post_residual as f64 / next_item_size as f64);
        score += 4.5 * unus * (1.0 - 0.3 * progress);
    }

    if post_residual > 60 && post_residual < 100 {
        score += 2.5 + 2.0 * (1.0 - progress);
    }

    if post_residual == 0 && bin_residual != bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
        score -= 8.0 * scarcity * (0.5 + 0.5 * (1.0 - progress));
    }

    if post_residual >= 46 && post_residual <= 59 && bin_residual != bin_capacity {
        let d = (post_residual as f64 - 46.0) / 13.0;
        score += 1.5 + 2.0 * d * (1.0 - 0.4 * progress);
    }

    if open_bins_count > 6 && bin_residual != bin_capacity {
        let crowd = ((open_bins_count as f64 - 6.0) / 14.0).min(1.0);
        score += (resid_f / cap_f) * 2.5 * crowd * (0.6 + 0.4 * progress);
    }

    if next_item_size > 0 && post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let nx = next_item_size as f64;
        let ratio = pr / nx.max(1.0);
        if ratio > 0.9 && ratio <= 1.0 {
            score -= 6.0 * (ratio - 0.9) * 10.0 * (0.6 + 0.4 * (1.0 - progress));
        }
    }

    if post_residual > 0 && fitting_bins_count >= 2 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        let alignment = 1.0 - ((pr - 30.0).abs() / 30.0).min(1.0);
        score -= 3.5 * alignment * tightness * (0.4 + 0.6 * (1.0 - progress));
    }

    if post_residual == 0 && slack >= 0 && slack <= 4 && bin_residual != bin_capacity {
        score -= 3.0 + 2.0 * (1.0 - progress);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && bin_residual != bin_capacity {
        let alternatives = (fitting_bins_count as f64).max(1.0);
        score += (3.0 / alternatives.sqrt()) * (1.0 - 0.3 * progress);
    }

    if post_residual == 0 && bin_residual != bin_capacity {
        let crowd = ((open_bins_count as f64 - 4.0).max(0.0) / 12.0).min(1.0);
        score -= 6.0 * crowd + 4.0 * progress;
    }

    if post_residual >= 1 && post_residual <= 12 && next_item_size > 0 && next_item_size <= post_residual && bin_residual != bin_capacity {
        let closeness = 1.0 - (post_residual - next_item_size) as f64 / 12.0;
        score -= 3.5 * closeness * (0.4 + 0.6 * progress);
    }

    if slack >= 0 && fitting_bins_count > 3 && bin_residual != bin_capacity {
        let sl = slack as f64;
        if sl > 8.0 {
            score += 0.06 * (sl - 8.0).min(50.0) * (0.5 + 0.5 * progress);
        }
    }

    if post_residual == 0 && open_bins_count > 8 && bin_residual != bin_capacity {
        score -= 2.0 * ((open_bins_count - 8) as f64).min(10.0) * 0.4 * (0.5 + 0.5 * progress);
    }

    if post_residual >= 1 && post_residual <= 8 && next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        score -= 2.5 * (1.0 - post_residual as f64 / 8.0) * (0.5 + 0.5 * progress);
    }

    // retained gen 22 mutation families (behaviorally identical)
    if post_residual > 14 && post_residual < 46 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let peak = 1.0 - ((pr - 30.0).abs() / 16.0).min(1.0);
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        score += 0.09 * pr * peak * (0.7 + 0.6 * tightness);
    }

    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let tail = post_residual - next_item_size;
        if tail >= 12 && tail <= 30 {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= (4.0 + 3.0 * (1.0 - progress)) * (1.0 - (tail as f64 - 12.0).abs() / 18.0) * scarcity;
        }
    }

    if slack >= 0 && slack <= 6 && fitting_bins_count <= 3 && bin_residual != bin_capacity {
        let sl = slack as f64;
        score -= 6.0 * (1.0 - sl / 6.0) * (1.0 / (fitting_bins_count as f64).max(1.0)) * (0.6 + 0.4 * progress);
    }

    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        score += 0.0004 * pr * pr * pr * (0.5 + 0.7 * tightness);
    }

    if post_residual > 0 && next_item_size > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let nx = next_item_size as f64;
        let mismatch = ((pr - nx).abs() / nx.max(1.0)).min(1.5);
        if pr > nx {
            let tail = pr - nx;
            if tail > 15.0 && tail < 60.0 {
                score += 0.10 * (tail - 15.0) * (1.0 - 0.5 * progress);
            }
        } else {
            score += 2.0 * mismatch * (1.0 - 0.3 * progress);
        }
    }

    if post_residual >= 30 && post_residual <= 55 && bin_residual != bin_capacity {
        let d = ((post_residual as f64 - 42.5).abs() / 12.5).min(1.0);
        score -= 5.0 * (1.0 - d) * (0.6 + 0.4 * (1.0 - progress));
    }

    if post_residual > 0 && bin_residual != bin_capacity {
        let scarcity_damp = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
        let pr = post_residual as f64;
        score += (0.05 * pr + 0.0018 * pr * pr) * scarcity_damp;
    }

    if post_residual >= 13 && post_residual <= 29 && next_item_size > 0 && post_residual < next_item_size && bin_residual != bin_capacity {
        let unus = 1.0 - (post_residual as f64 / next_item_size as f64);
        score += 7.0 * unus * (0.7 + 0.5 * progress);
    }

    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let tail = post_residual - next_item_size;
        if tail > 55 && tail < 100 {
            score += 3.0 * (1.0 - (tail as f64 - 55.0) / 45.0) * (0.5 + 0.5 * (1.0 - progress));
        } else if tail >= 60 {
            score += 2.0;
        }
    }

    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let chain_left = bin_residual - item_size - next_item_size;
        if chain_left <= 3 {
            score -= 10.0 + 6.0 * (1.0 - progress) + 3.0 / (fitting_bins_count as f64).max(1.0);
        }
    }

    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let size_factor = (item_size as f64 / 100.0).powf(1.5);
        score += pr * 0.045 * (1.0 - size_factor) * (1.0 - 0.3 * progress);
    }

    if post_residual >= 20 && post_residual <= 45 && bin_residual != bin_capacity {
        let tightness = (1.0 - (mean_residual / cap_f).min(1.0)).max(0.0);
        score -= 3.5 * tightness * (0.5 + 0.5 * (1.0 - progress));
    }

    if next_item_size > 35 && post_residual > 0 && post_residual < next_item_size && bin_residual != bin_capacity {
        let stranded = (next_item_size - post_residual) as f64 / next_item_size as f64;
        score += 5.0 * stranded * (1.0 - 0.4 * progress);
    }

    if post_residual >= 6 && post_residual <= 12 && bin_residual != bin_capacity {
        score += 2.5 + 3.0 * progress;
    }

    if post_residual > 0 && post_residual <= 20 && bin_residual != bin_capacity {
        score -= 3.0 * (1.0 - post_residual as f64 / 20.0) * (0.5 + 0.5 * progress);
    }

    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        let crowd = ((open_bins_count as f64 - 6.0).max(0.0) / 10.0).min(1.0);
        if pr <= 18.0 {
            score -= 2.0 * (1.0 - pr / 18.0) * crowd;
        } else if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0 * crowd * (1.0 - progress);
        }
    }

    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let tail = post_residual - next_item_size;
        if tail >= 25 && tail <= 50 {
            score -= 4.5 * (1.0 - (tail as f64 - 25.0).abs() / 25.0) * (0.6 + 0.4 * (1.0 - progress));
        }
    }

    if post_residual == 0 {
        let tightness = (1.0 - (mean_residual / cap_f).min(1.0)).max(0.0);
        score -= 4.0 * tightness;
    } else if slack >= 0 && slack <= 2 {
        let tightness = (1.0 - (mean_residual / cap_f).min(1.0)).max(0.0);
        score -= 2.5 * tightness * (1.0 - 0.5 * progress);
    }

    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let after_next = post_residual - next_item_size;
        if after_next >= 10 && after_next <= 45 {
            score -= 4.0 * (1.0 - after_next as f64 / 45.0) * (1.0 - 0.5 * progress);
        }
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 6.0 {
            score += 10.0 * (1.0 - miss / 6.0) * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    if post_residual > 0 && bin_residual != bin_capacity {
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        score += 0.12 * (post_residual as f64) * (0.6 + 0.8 * tightness);
    }

    if post_residual > 0 && post_residual <= 20 && bin_residual != bin_capacity {
        score -= 5.0 * (1.0 - post_residual as f64 / 20.0) * (1.0 - 0.4 * progress);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && open_bins_count > 10 {
        score += 1.5 * ((open_bins_count - 10) as f64).min(8.0) * 0.5;
    }

    if post_residual > 0 && bin_residual != bin_capacity {
        let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
        let pr = post_residual as f64;
        score += (0.09 * pr + 0.0022 * pr * pr) * (0.6 + 0.8 * tightness);
    }

    if post_residual > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        score += 0.035 * pr * (post_residual as f64 / cap_f) * (1.0 - 0.25 * progress);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && bin_residual != bin_capacity {
        let gap = (next_item_size - post_residual) as f64;
        if gap > 6.0 && gap <= 18.0 {
            score += 2.0 * (1.0 - gap / 18.0) * (0.6 + 0.4 * (1.0 - progress));
        } else if gap > 30.0 {
            score += 1.5;
        }
    }

    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let chain_left = bin_residual - item_size - next_item_size;
        if chain_left >= 8 && chain_left <= 20 {
