        // MUTATION (gen 42): two-step lookahead chain bonus — when the fresh
        // bin can absorb the item AND the next item AND still leave room for a
        // third step, reward opening only if the best open fit wastes more
        // than the chain slack; otherwise penalize to preserve compaction.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            let open_waste = bin_residual.saturating_sub(item_size);
            if fresh_left > 0 && open_waste > fresh_left + 12 {
                score -= 3.0 * (1.0 - progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual as i64 - next_item_size as i64) as f64;
        score -= 40.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
    } else if next_item_size > 0 {
        // post_residual too small for next item: dead space penalty
        score += 10.0 + (next_item_size - post_residual) as f64;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus: if this is the only bin that fits, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when current bin fits poorly
    if bin_residual == bin_capacity {
        let tight = mean_residual < item_size as f64 * 0.5;
        if tight {
            score -= 8.0;
        } else {
            score += 25.0;
        }
    }

    // Early in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    score
}

