            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if tightness > 0.6 && leftover > 50 {
                score += 8.0 * (tightness - 0.6) * 10.0;
            } else if tightness > 0.6 && leftover >= 25 && leftover <= 50 {
                score -= 5.0 * (tightness - 0.6) * 10.0;
            }
        }
        // Late-stream: penalize any fresh-bin leftover.
        if progress > 0.75 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size);
            if leftover > 0 {
                score += 3.0 + 0.08 * (leftover as f64) * (progress - 0.75) * 20.0;
            } else {
                score -= 6.0 * (progress - 0.75) * 10.0;
            }
        }
        // Small items late: keep them out of fresh bins.
        if item_size < 15 && progress > 0.5 && fitting_bins_count >= 1 {
            score += 15.0;
        }
        // Mid-band fresh leftovers (30..=55) are reusable.
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left >= 30 && fresh_left <= 55 {
                score -= 2.5 * (1.0 - ((fresh_left as f64 - 42.5).abs() / 12.5).min(1.0)) * (1.0 - 0.4 * progress);
            } else if fresh_left > 65 {
                score += 0.06 * ((fresh_left - 65) as f64).min(35.0) * (0.5 + 0.5 * progress);
            }
        }
        // Scarcity-locked chain continuity for fresh bins.
        if fitting_bins_count <= 2 && next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if fresh_left >= next_item_size {
                let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0);
                score -= 5.0 * scarcity * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION (gen 44): fresh-bin open-waste comparison — when the only
        // fitting open bin leaves a large waste but the fresh bin leaves a
        // reusable remainder, prefer opening (borrowed from best).
        if fitting_bins_count >= 1 && next_item_size > 0 {
            let open_after = bin_residual.saturating_sub(item_size);
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if open_after < next_item_size && fresh_left >= next_item_size + 10 {
                score -= 3.0 + 3.0 * (1.0 - progress);
            }
        }
        // MUTATION (gen 44): fresh-bin excess over mean residual — late-stream
        // guard against opening bins that strand more space than average.
        if progress > 0.45 && next_item_size > 0 {
            let leftover = bin_capacity.saturating_sub(item_size + next_item_size) as f64;
            let excess = leftover - mean_residual.max(0.0);
            if excess > 15.0 {
                score += 0.08 * (excess - 15.0).min(40.0);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual), with quadratic penalty on waste.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post_residual == next_item_size {
            // Perfect chain: this bin will be exactly filled next step.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits here: reward closeness of the chain fit.
            let gap = post - nxt;
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
            // Extra reward if gap is small relative to mean residual.
            if gap <= mean_residual {
                score -= 8.0;
            }
        } else {
            // Next item will NOT fit: penalize proportional to overflow.
            let overflow = nxt - post;
            score += 10.0 + 0.3 * overflow;
        }
    }

    // Penalize leaving dead space far below the smallest plausible item (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Slightly discourage proliferating bins when many are open and residual is large.
    if open_bins_count > 3 && post_residual as f64 > mean_residual {
        score += 3.0;
    }

    // Mild stream-progress bias: later in stream, prefer tighter packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.1;

    // New-bin candidate: make empty bins attractive only when nothing fits well.
    if bin_residual == bin_capacity {
        // Default new-bin score: moderate; beaten by any decent fit, beats bad fits.
        score += 20.0;
        if next_item_size > 0 && (bin_capacity as u32 - next_item_size) <= item_size.max(1) {
            // Opening a new bin lets next item pair nicely with current item.
            score -= 5.0;
        }
    }

    score
}

