            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            let center = 1.0 - ((post_residual as f64 - 32.5).abs() / 12.5).min(1.0);
            score -= 2.5 * center * (0.4 + 0.6 * (1.0 - tightness)) * (0.5 + 0.5 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post-residual nonlinearly.
    score -= 60.0 * (-post_residual as f64 / 12.0).exp();

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strong bonus to use it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else {
        // Mild penalty when many bins compete (spread usage).
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to waste.
            score += 5.0 * (1.0 - next_item_size as f64 / (post_residual as f64 + 1.0));
        }
    }

    // Global state coupling: prefer filling bins when mean residual is high.
    score -= 0.15 * mean_residual;

    // Prefer placing into already-open bins over opening new ones,
    // scaled by stream progression (early: explore new bins, late: consolidate).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 15.0 + 45.0 * progress;
        // But allow a new bin early when open bins are all tight.
        if open_bins_count > 0 && mean_residual < item_size as f64 {
            score -= 30.0 * (1.0 - progress);
        }
    } else {
        score -= 10.0 * progress;
    }

    // Mild penalty for accumulating many open bins early.
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // Item-size coupling: large items prefer the emptiest bins.
    if item_size > bin_capacity / 2 {
        score += 0.2 * (bin_capacity - bin_residual) as f64;
    }

    score
}

