    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = post * post / cap;                       // quadratic in post residual
    let progress_coupling = poly * (0.5 + progress);    // dead space penalized more later in stream
    let mut score = post + progress_coupling;

    // Reward tight fits (small post_residual) with smooth exponential shaping
    score -= 30.0 * (-(post / cap) * 4.0).exp();

    // Penalize when post_residual becomes too small to ever be useful (smooth sigmoid)
    let useless = 1.0 / (1.0 + (post / 10.0).exp());
    score += 20.0 * useless;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 12.0 * (1.0 - (post - next_item_size as f64) / cap);
    } else if next_item_size > 0 {
        score += 8.0;
    }

    // Mild preference for consolidating into fewer bins
    score += open_bins_count as f64 * 0.3;

    // Deviation from mean residual: prefer bins near/below mean (balance)
    score += 0.2 * (post - mean_residual).abs();

    // New-bin candidate: make it attractive only when item fits poorly everywhere else
    if bin_residual == bin_capacity {
        score = 40.0 + item * 0.5 - 10.0 * progress;
    }

    score
}

