            score -= (3.0 + 3.0 * (1.0 - progress)) * scarcity;
        }

        // gen 21: residual-dispersion dead-space guard
        if post_residual > 0 && bin_residual != bin_capacity && mean_residual > 0.45 * cap_f {
            let pr = post_residual as f64;
            score += 0.06 * pr * (0.4 + 0.6 * progress);
        }

        // gen 22: dead-space convexity escalation
        if post_residual > 0 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.00032 * pr * pr * pr * (0.5 + 0.7 * tightness);
        }

        // gen 22: open-bin compaction pull
        if post_residual > 0 && bin_residual != bin_capacity && fitting_bins_count >= 2 {
            let pr = post_residual as f64;
            let band = ((pr - mean_residual.max(0.0)) / cap_f).abs();
            score -= 2.0 * (1.0 - band.min(1.0)) * (0.4 + 0.6 * progress);
        }

        // gen 22: fresh-bin halo extension to ±6
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if d > 4 && d <= 6 {
                score -= (3.0 - 1.0 * (d - 4) as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // gen 22: late-stream waste-floor guard
        if post_residual > 0 && bin_residual != bin_capacity && progress > 0.66 && post_residual < next_item_size.max(20) {
            let unus = 1.0 - (post_residual as f64 / (next_item_size.max(20) as f64));
            score += 4.0 * unus * ((progress - 0.66) / 0.34).min(1.0);
        }

        // gen 23: dead-space convexity escalation
        if post_residual > 0 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.00045 * pr * pr * pr * (0.5 + 0.7 * tightness);
        }

        // gen 23: compaction pull strengthening
        if post_residual > 0 && bin_residual != bin_capacity && fitting_bins_count >= 2 {
            let pr = post_residual as f64;
            let band = ((pr - mean_residual.max(0.0)) / cap_f).abs();
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= (2.5 + 1.5 * scarcity) * (1.0 - band.min(1.0)) * (0.4 + 0.6 * progress);
        }

        // gen 23: fresh-bin halo extension to ±8
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if d > 6 && d <= 8 {
                score -= (2.0 - 0.75 * (d - 6) as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // gen 23: late-stream consolidation sharpening
        if post_residual > 0 && bin_residual != bin_capacity && progress > 0.60 && post_residual < next_item_size.max(20) {
            let unus = 1.0 - (post_residual as f64 / (next_item_size.max(20) as f64));
            score += 6.0 * unus * ((progress - 0.60) / 0.40).min(1.0);
        }

        // gen 23: residual-variance floor bonus
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 && bin_residual != bin_capacity {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= 3.5 * (1.0 - (post_residual - next_item_size) as f64 / 10.0) * scarcity * (0.5 + 0.5 * progress);
        }

        // MUTATION (gen 45): dead-space convexity continuation — raise the extra
        // cubic coefficient 0.00045 -> 0.00058, deepening the diagnosed
        // dead-space penalty on stranded mid/large residuals (momentum:
        // ContinueDirection on the cubic family).
        if post_residual > 0 && bin_residual != bin_capacity {
            let pr = post_residual as f64;
            let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
            score += 0.00058 * pr * pr * pr * (0.5 + 0.7 * tightness);
        }

        // MUTATION (gen 45): compaction pull reinforcement — the mean-residual
        // band homogenization is strengthened further (2.5+1.5s -> 3.2+2.0s)
        // and its progress ramp shifted earlier (0.4 -> 0.3 base), since
        // Sigma_res (0.2981) remains the diagnosed weakness.
        if post_residual > 0 && bin_residual != bin_capacity && fitting_bins_count >= 2 {
            let pr = post_residual as f64;
            let band = ((pr - mean_residual.max(0.0)) / cap_f).abs();
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= (3.2 + 2.0 * scarcity) * (1.0 - band.min(1.0)) * (0.3 + 0.7 * progress);
        }

        // MUTATION (gen 45): fresh-bin halo extension to ±10 — the widening
        // trend (±2 -> ±4 -> ±6 -> ±8) keeps capturing near-parity chain
        // continuations; extend with a shallow decay to ±10.
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size) as i64;
            let nx = next_item_size as i64;
            let d = (fresh_left - nx).abs();
            if d > 8 && d <= 10 {
                score -= (1.5 - 0.6 * (d - 8) as f64) * (0.5 + 0.5 * (1.0 - progress));
            }
        }

        // MUTATION (gen 45): late-stream consolidation sharpening — the
        // waste-floor guard is strengthened (6.0 -> 8.0) and its onset pulled
        // earlier (0.60 -> 0.55), forcing residual consolidation into fewer
        // usable slacks during the final stretch where the bin gap concentrates.
        if post_residual > 0 && bin_residual != bin_capacity && progress > 0.55 && post_residual < next_item_size.max(20) {
            let unus = 1.0 - (post_residual as f64 / (next_item_size.max(20) as f64));
            score += 8.0 * unus * ((progress - 0.55) / 0.45).min(1.0);
        }

        // MUTATION (gen 45): residual-variance floor bonus deepening — the
        // reusable-tail reward is strengthened (3.5 -> 4.5) and widened
        // (tail <= 10 -> tail <= 14), directly compressing residual dispersion.
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 14 && bin_residual != bin_capacity {
            let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
            score -= 4.5 * (1.0 - (post_residual - next_item_size) as f64 / 14.0) * scarcity * (0.5 + 0.5 * progress);
        }

        // MUTATION (gen 45): stranded-residual quadratic drag — new complementary
        // term: penalize placements that leave a post_residual just below the
        // next item (unusable sliver) with a smooth quadratic ramp, targeting
        // the dead-space ratio weakness without disturbing exact-fit families.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && bin_residual != bin_capacity {
            let miss = (next_item_size - post_residual) as f64;
            if miss <= 12.0 {
                let tightness = ((mean_residual / cap_f).max(0.0)).min(1.0);
                score += 0.09 * miss * miss * (0.4 + 0.6 * (1.0 - progress)) * (0.6 + 0.5 * tightness);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residues that are "useful" for future items.
    // Class A: post_residual divisible by 10 (aligns with 10-multiple item sizes).
    // Class B: post_residual in {1..9} (tiny dead space, nearly perfect).
    // Class C: awkward residues (11..19, 21..29 ... non-multiples) get penalized.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= (pr as f64) * 0.35; // clean residual, usable by grid items
        } else if pr < 10 {
            score -= 8.0; // negligible waste, effectively a near-perfect fit
        } else {
            // awkward residue: dead space risk grows with size of the awkward chunk
            let awkward = pr % 10;
            score += awkward as f64 * 1.5;
        }
    }

    // Integer-division thresholds on post_residual: classify leftover capacity bands.
    let band = pr / 20; // 0..=5
    score += match band {
        0 => -5.0,          // 0..19 : tight leftover, good
        1 => 2.0,           // 20..39
        2 => 5.0,           // 40..59
        3 => 8.0,           // 60..79
        4 => 11.0,          // 80..99 (only for new-bin candidate)
        _ => 0.0,
    };

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit_gap = post_residual - next_item_size;
        if next_fit_gap == 0 {
            score -= 400.0;
        } else if next_fit_gap % 10 == 0 {
            score -= 60.0;
        } else if next_fit_gap < 10 {
            score -= 40.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // next item won't fit here: this bin's leftover becomes dead space
        score += post_residual as f64 * 0.5;
    }

    // Last chance: only one bin can fit the item; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a bin is expensive unless the item is large
    // or no open bin fits well. Empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Base cost of a new bin.
        score += 120.0;
        // Large items justify a fresh bin (they leave little waste anyway).
        let frac = item_size as f64 / cap;
        if frac > 0.5 {
            score -= 90.0 * frac;
        }
        // If many bins already fit the item, prefer reusing one.
        if fitting_bins_count > 0 {
            score += 40.0 + 10.0 * (fitting_bins_count as f64).min(5.0);
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Mean-residual coupling: if this bin's residual is far above the mean,
    // it's a "loose" bin; prefer filling loose bins to consolidate.
    let res_f = bin_residual as f64;
    if res_f > mean_residual {
        score -= 0.15 * (res_f - mean_residual);
    } else {
        score += 0.10 * (mean_residual - res_f);
    }

    // Mild pressure to keep the number of open bins low.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
