        // usable slacks during the final stretch where the 45-bin gap
        // concentrates.
        if post_residual > 0 && bin_residual != bin_capacity && progress > 0.55 && post_residual < next_item_size.max(20) {
            let unus = 1.0 - (post_residual as f64 / (next_item_size.max(20) as f64));
            score += 8.5 * unus * ((progress - 0.55) / 0.45).min(1.0);
        }

        // MUTATION (gen 45): two-step lookahead chain reward — when placing
        // the item leaves post_residual that exactly accommodates the next
        // item AND the bin residual also chains, reward the tight triple
        // (item + next + residual alignment) to compress residual variance.
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next <= 14 {
                let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0).sqrt();
                score -= (4.0 + 3.0 * (1.0 - progress)) * (1.0 - after_next as f64 / 14.0) * scarcity;
            }
        }

        // MUTATION (gen 45): small-residual reusability bonus — open-bin
        // placements leaving a reusable 8-16 unit slack are mildly rewarded
        // since such slacks absorb the common small-item tail of the stream.
        if post_residual >= 8 && post_residual <= 16 && bin_residual != bin_capacity && progress > 0.35 {
            score -= 2.0 * (1.0 - ((post_residual as f64 - 12.0).abs() / 4.0).min(1.0)) * ((progress - 0.35) / 0.65).min(1.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing the bin exactly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if the next item fits into the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits here: reward proportionally to tightness of that fit.
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 200.0 + slack_after_next * 0.5;
        } else {
            // Dead space: post residual too small for next item -> penalize.
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 1.5;
            // Extra penalty if this dead space is small but useless (fragmentation).
            if post_residual < 10 {
                score += 50.0;
            }
        }
    }

    // Penalize leaving residual far from mean (keeps bin pool homogeneous).
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when current bin would waste a lot
    // or no good fit exists among open bins.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.9; // = 90, worse than most tight fits
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 50.0; // fresh bin accommodates next item too
        }
        if fitting_bins_count == 0 {
            score -= 500.0; // no open bin fits: new bin is necessary
        }
    }

    // Late in the stream: prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 30.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
