    // consolidated with crowd pressure to close bins early.
    if post_residual == 0 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // MUTATION (gen 46): near-miss refusal — graded penalty for stranding
    // 1..=4 unusable units, favoring placements that leave reusable tails.
    if post_residual >= 1 && post_residual <= 4 && bin_residual != bin_capacity {
        score += 3.0 * (1.0 - post_residual as f64 / 4.0) * (0.5 + 0.5 * progress);
    }

    // MUTATION (gen 46): mid-band compaction pull — tighten the 20..=60
    // residual band toward reuse, extending the roomy-reward family with a
    // progress-scaled bonus to compress residual variance.
    if post_residual >= 20 && post_residual <= 60 && bin_residual != bin_capacity {
        score -= 3.0 + 4.0 * (1.0 - progress);
    }

    // MUTATION (gen 46): large-slack hoarding penalty on crowded pools —
    // bins holding big slack while many bins are open get pushed to be used
    // now, reducing total open-bin count and dead space.
    if slack > 30 && open_bins_count > 10 && bin_residual != bin_capacity {
        score += 0.05 * ((slack - 30) as f64).min(50.0) * (0.5 + 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness: how well the item fills the bin (0..1)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;

    // Reward tight fits (minimize wasted space) more strongly over time.
    score -= 30.0 * tightness * (0.5 + progress);

    // Penalize large dead space after placement, scaled by remaining stream length.
    let dead_weight = (1.0 - progress) * 0.5 + 0.2;
    score += dead_weight * post_residual as f64 * 0.15;

    // Lookahead coupling: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = next_item_size as f64 / post_residual as f64;
        score -= 12.0 * chain_fit;
    } else if next_item_size > 0 {
        // Next item cannot use this bin's leftover; penalize proportionally.
        score += 6.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins whose residual is below the mean (consolidating waste),
    // penalize dipping into bins with above-average residual unless fit is tight.
    let residual_gap = bin_residual as f64 - mean_residual;
    score += 0.08 * residual_gap * (1.0 - tightness);

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit or when the current item is large.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening a new bin by default; less penalty for large items
        // or when many bins are already open (fragmentation relief).
        let size_relief = item_size as f64 / bin_capacity as f64;
        let crowd_relief = (open_bins_count as f64 / (open_bins_count as f64 + 8.0)) * 10.0;
        score += 35.0 - 20.0 * size_relief - crowd_relief;
        // Late in the stream, opening fresh bins is more acceptable (less future
        // to amortize dead space).
        score -= 15.0 * progress;
    }

    // Small bonus for keeping many moderately-filled bins balanced.
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0) * tightness;

    score
}

